export const CPP: Record<string, string> = {
 "01-matrix": "class Solution {\npublic:\n    vector<vector<int>> updateMatrix(vector<vector<int>>& mat) {\n        int R = mat.size(), C = mat[0].size();\n        vector<vector<int>> dist(R, vector<int>(C, -1));     // -1: not reached yet\n        queue<pair<int, int>> q;\n        for (int r = 0; r < R; r++)\n            for (int c = 0; c < C; c++)\n                if (mat[r][c] == 0) { dist[r][c] = 0; q.push({r, c}); }   // BFS from every 0 at once\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        while (!q.empty()) {\n            auto [r, c] = q.front(); q.pop();\n            for (int d = 0; d < 4; d++) {\n                int nr = r + dr[d], nc = c + dc[d];\n                if (nr >= 0 && nr < R && nc >= 0 && nc < C && dist[nr][nc] == -1) {\n                    dist[nr][nc] = dist[r][c] + 1;\n                    q.push({nr, nc});\n                }\n            }\n        }\n        return dist;\n    }\n};",
 "24-game": "class Solution {\n    bool solve(vector<double> nums) {\n        if (nums.size() == 1) return fabs(nums[0] - 24) < 1e-6;\n        int n = nums.size();\n        for (int i = 0; i < n; i++)\n            for (int j = 0; j < n; j++) {\n                if (i == j) continue;\n                vector<double> rest;          // every other number\n                for (int k = 0; k < n; k++)\n                    if (k != i && k != j) rest.push_back(nums[k]);\n                double a = nums[i], b = nums[j];\n                vector<double> options{a + b, a - b, a * b};\n                if (fabs(b) > 1e-6) options.push_back(a / b);\n                for (double x : options) {    // replace the pair by one result\n                    rest.push_back(x);\n                    if (solve(rest)) return true;\n                    rest.pop_back();\n                }\n            }\n        return false;\n    }\npublic:\n    bool judgePoint24(vector<int>& cards) { return solve(vector<double>(cards.begin(), cards.end())); }\n};",
 "3sum": "class Solution {\npublic:\n    vector<vector<int>> threeSum(vector<int>& nums) {\n        sort(nums.begin(), nums.end());\n        vector<vector<int>> out;\n        int n = nums.size();\n        for (int i = 0; i + 2 < n; i++) {\n            if (i && nums[i] == nums[i - 1]) continue;     // skip a repeated first number\n            int l = i + 1, r = n - 1;\n            while (l < r) {\n                int s = nums[i] + nums[l] + nums[r];\n                if (s < 0) l++;\n                else if (s > 0) r--;\n                else {\n                    out.push_back({nums[i], nums[l], nums[r]});\n                    l++;\n                    while (l < r && nums[l] == nums[l - 1]) l++;\n                    r--;\n                }\n            }\n        }\n        return out;\n    }\n};",
 "3sum-closest": "class Solution {\npublic:\n    int threeSumClosest(vector<int>& nums, int target) {\n        sort(nums.begin(), nums.end());\n        int best = nums[0] + nums[1] + nums[2];\n        for (int i = 0; i + 2 < (int)nums.size(); i++) {\n            int j = i + 1, k = nums.size() - 1;\n            while (j < k) {   // two pointers on the sorted rest\n                int s = nums[i] + nums[j] + nums[k];\n                if (abs(s - target) < abs(best - target)) best = s;\n                if (s < target) j++;\n                else if (s > target) k--;\n                else return s;   // exact hit\n            }\n        }\n        return best;\n    }\n};",
 "3sum-with-multiplicity": "class Solution {\npublic:\n    int threeSumMulti(vector<int>& arr, int target) {\n        const long long MOD = 1'000'000'007;\n        vector<long long> cnt(101, 0);\n        for (int x : arr) cnt[x]++;\n        long long ans = 0;\n        for (int x = 0; x <= 100; x++)\n            for (int y = x; y <= 100; y++) {\n                int z = target - x - y;\n                if (z < y || z > 100) continue;\n                if (x == y && y == z) ans += cnt[x] * (cnt[x] - 1) * (cnt[x] - 2) / 6;\n                else if (x == y) ans += cnt[x] * (cnt[x] - 1) / 2 * cnt[z];\n                else if (y == z) ans += cnt[x] * cnt[y] * (cnt[y] - 1) / 2;\n                else ans += cnt[x] * cnt[y] * cnt[z];\n                ans %= MOD;\n            }\n        return (int)ans;\n    }\n};",
 "4sum-ii": "class Solution {\npublic:\n    int fourSumCount(vector<int>& nums1, vector<int>& nums2, vector<int>& nums3, vector<int>& nums4) {\n        unordered_map<int, int> ab;   // every a + b and how often\n        for (int a : nums1)\n            for (int b : nums2) ab[a + b]++;\n        int total = 0;\n        for (int c : nums3)\n            for (int d : nums4) {\n                auto it = ab.find(-c - d);\n                if (it != ab.end()) total += it->second;\n            }\n        return total;\n    }\n};",
 "accounts-merge": "class Solution {\n    unordered_map<string, string> parent;\n    string find(string x) {\n        while (parent[x] != x) {\n            parent[x] = parent[parent[x]];                   // path halving\n            x = parent[x];\n        }\n        return x;\n    }\npublic:\n    vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {\n        unordered_map<string, string> owner;\n        for (auto& acc : accounts)\n            for (size_t i = 1; i < acc.size(); i++) {\n                if (!parent.count(acc[i])) parent[acc[i]] = acc[i];\n                owner[acc[i]] = acc[0];\n                parent[find(acc[i])] = find(acc[1]);         // join with the account's first email\n            }\n        unordered_map<string, vector<string>> groups;        // root -> its emails\n        for (auto& [e, p] : parent) groups[find(e)].push_back(e);\n        vector<vector<string>> out;\n        for (auto& [root, es] : groups) {\n            sort(es.begin(), es.end());\n            vector<string> row{owner[root]};\n            row.insert(row.end(), es.begin(), es.end());\n            out.push_back(row);\n        }\n        return out;\n    }\n};",
 "add-binary": "class Solution {\npublic:\n    string addBinary(string a, string b) {\n        int i = (int)a.size() - 1, j = (int)b.size() - 1, carry = 0;\n        string out;\n        while (i >= 0 || j >= 0 || carry) {\n            int s = carry;\n            if (i >= 0) s += a[i--] - '0';\n            if (j >= 0) s += b[j--] - '0';\n            out.push_back('0' + s % 2);\n            carry = s / 2;\n        }\n        reverse(out.begin(), out.end());                     // digits were built from the right\n        return out;\n    }\n};",
 "add-digits": "class Solution {\npublic:\n    int addDigits(int num) {\n        return num == 0 ? 0 : 1 + (num - 1) % 9;             // digital root\n    }\n};",
 "add-one-row-to-tree": "class Solution {\npublic:\n    TreeNode* addOneRow(TreeNode* root, int val, int depth) {\n        if (depth == 1) return new TreeNode(val, root, nullptr);   // old tree goes on the left\n        vector<TreeNode*> level{root};\n        for (int d = 0; d < depth - 2; d++) {                       // walk down to the row above the new one\n            vector<TreeNode*> next;\n            for (TreeNode* n : level)\n                for (TreeNode* c : {n->left, n->right})\n                    if (c) next.push_back(c);\n            level = next;\n        }\n        for (TreeNode* n : level) {\n            n->left = new TreeNode(val, n->left, nullptr);\n            n->right = new TreeNode(val, nullptr, n->right);\n        }\n        return root;\n    }\n};",
 "add-strings": "class Solution {\npublic:\n    string addStrings(string num1, string num2) {\n        int i = (int)num1.size() - 1, j = (int)num2.size() - 1, carry = 0;\n        string out;\n        while (i >= 0 || j >= 0 || carry) {\n            int s = carry;\n            if (i >= 0) s += num1[i--] - '0';\n            if (j >= 0) s += num2[j--] - '0';\n            out.push_back('0' + s % 10);\n            carry = s / 10;\n        }\n        reverse(out.begin(), out.end());\n        return out;\n    }\n};",
 "add-two-numbers": "class Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        ListNode dummy, *cur = &dummy;\n        int carry = 0;\n        while (l1 || l2 || carry) {                      // digits are stored lowest first\n            int total = carry + (l1 ? l1->val : 0) + (l2 ? l2->val : 0);\n            carry = total / 10;\n            cur->next = new ListNode(total % 10);\n            cur = cur->next;\n            l1 = l1 ? l1->next : nullptr;\n            l2 = l2 ? l2->next : nullptr;\n        }\n        return dummy.next;\n    }\n};",
 "add-two-numbers-ii": "class Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        vector<int> a, b;   // digits as stacks, so we can add from the back\n        for (; l1; l1 = l1->next) a.push_back(l1->val);\n        for (; l2; l2 = l2->next) b.push_back(l2->val);\n        ListNode* head = nullptr;\n        int carry = 0;\n        while (!a.empty() || !b.empty() || carry) {\n            int s = carry;\n            if (!a.empty()) { s += a.back(); a.pop_back(); }\n            if (!b.empty()) { s += b.back(); b.pop_back(); }\n            carry = s / 10;\n            head = new ListNode(s % 10, head);   // build the answer front first\n        }\n        return head;\n    }\n};",
 "adding-spaces-to-a-string": "class Solution {\npublic:\n    string addSpaces(string s, vector<int>& spaces) {\n        string out;\n        out.reserve(s.size() + spaces.size());\n        size_t j = 0;\n        for (int i = 0; i < (int)s.size(); i++) {\n            if (j < spaces.size() && spaces[j] == i) {   // a space goes before s[i]\n                out += ' ';\n                j++;\n            }\n            out += s[i];\n        }\n        return out;\n    }\n};",
 "all-ancestors-of-a-node-in-a-directed-acyclic-graph": "class Solution {\npublic:\n    vector<vector<int>> getAncestors(int n, vector<vector<int>>& edges) {\n        vector<vector<int>> g(n), anc(n);\n        for (auto& e : edges) g[e[0]].push_back(e[1]);\n        for (int s = 0; s < n; s++) {      // s is an ancestor of everything it reaches\n            vector<bool> seen(n, false);\n            vector<int> stack{s};\n            seen[s] = true;\n            while (!stack.empty()) {\n                int u = stack.back();\n                stack.pop_back();\n                for (int v : g[u])\n                    if (!seen[v]) {\n                        seen[v] = true;\n                        anc[v].push_back(s);   // s goes up in order, so lists stay sorted\n                        stack.push_back(v);\n                    }\n            }\n        }\n        return anc;\n    }\n};",
 "all-elements-in-two-binary-search-trees": "class Solution {\n    void inorder(TreeNode* node, vector<int>& out) {\n        if (!node) return;\n        inorder(node->left, out);\n        out.push_back(node->val);\n        inorder(node->right, out);\n    }\n\npublic:\n    vector<int> getAllElements(TreeNode* root1, TreeNode* root2) {\n        vector<int> a, b, out;\n        inorder(root1, a);   // a BST in order is sorted\n        inorder(root2, b);\n        size_t i = 0, j = 0;\n        while (i < a.size() || j < b.size()) {   // merge two sorted lists\n            if (j == b.size() || (i < a.size() && a[i] <= b[j])) out.push_back(a[i++]);\n            else out.push_back(b[j++]);\n        }\n        return out;\n    }\n};",
 "all-nodes-distance-k-in-binary-tree": "class Solution {\npublic:\n    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {\n        unordered_map<TreeNode*, TreeNode*> parent{{root, nullptr}};\n        vector<TreeNode*> st{root};\n        while (!st.empty()) {                              // record every node's parent\n            TreeNode* n = st.back(); st.pop_back();\n            for (TreeNode* c : {n->left, n->right})\n                if (c) { parent[c] = n; st.push_back(c); }\n        }\n        queue<TreeNode*> q;\n        q.push(target);\n        unordered_set<TreeNode*> seen{target};\n        for (int step = 0; step < k; step++) {             // BFS k rings out, through children and parent\n            for (int s = q.size(); s > 0; s--) {\n                TreeNode* n = q.front(); q.pop();\n                for (TreeNode* m : {n->left, n->right, parent[n]})\n                    if (m && !seen.count(m)) { seen.insert(m); q.push(m); }\n            }\n        }\n        vector<int> out;\n        for (; !q.empty(); q.pop()) out.push_back(q.front()->val);\n        return out;\n    }\n};",
 "all-oone-data-structure": "class AllOne {\n    struct Bucket {\n        int count;\n        unordered_set<string> keys;\n        Bucket *prev = nullptr, *next = nullptr;\n        Bucket(int c) : count(c) {}\n    };\n    Bucket *head, *tail;                    // sentinels, counts in increasing order between them\n    unordered_map<string, Bucket*> at;      // key -> its bucket\n\n    Bucket* addAfter(Bucket* b, int count) {\n        Bucket* nb = new Bucket(count);\n        nb->prev = b;\n        nb->next = b->next;\n        b->next->prev = nb;\n        b->next = nb;\n        return nb;\n    }\n\n    void drop(Bucket* b, const string& key) {\n        b->keys.erase(key);\n        if (b->keys.empty()) {   // unlink an empty bucket\n            b->prev->next = b->next;\n            b->next->prev = b->prev;\n            delete b;\n        }\n    }\n\npublic:\n    AllOne() : head(new Bucket(0)), tail(new Bucket(INT_MAX)) {\n        head->next = tail;\n        tail->prev = head;\n    }\n\n    void inc(string key) {\n        auto it = at.find(key);\n        Bucket* b = it == at.end() ? head : it->second;\n        Bucket* nxt = b->next->count == b->count + 1 ? b->next : addAfter(b, b->count + 1);\n        nxt->keys.insert(key);\n        at[key] = nxt;\n        if (b != head) drop(b, key);\n    }\n\n    void dec(string key) {\n        Bucket* b = at[key];\n        if (b->count == 1) {\n            at.erase(key);\n        } else {\n            Bucket* prv = b->prev->count == b->count - 1 ? b->prev : addAfter(b->prev, b->count - 1);\n            prv->keys.insert(key);\n            at[key] = prv;\n        }\n        drop(b, key);\n    }\n\n    string getMaxKey() {\n        return tail->prev != head ? *tail->prev->keys.begin() : \"\";\n    }\n\n    string getMinKey() {\n        return head->next != tail ? *head->next->keys.begin() : \"\";\n    }\n};",
 "all-paths-from-source-to-target": "class Solution {\npublic:\n    vector<vector<int>> allPathsSourceTarget(vector<vector<int>>& graph) {\n        vector<vector<int>> out;\n        int target = graph.size() - 1;\n        vector<int> path{0};\n        function<void(int)> go = [&](int u) {\n            if (u == target) { out.push_back(path); return; }\n            for (int v : graph[u]) {\n                path.push_back(v);\n                go(v);\n                path.pop_back();                           // the graph is a DAG, so no visited set\n            }\n        };\n        go(0);\n        return out;\n    }\n};",
 "angle-between-hands-of-a-clock": "class Solution {\npublic:\n    double angleClock(int hour, int minutes) {\n        double m = 6.0 * minutes;                       // minute hand: 6 degrees a minute\n        double h = 30.0 * (hour % 12) + 0.5 * minutes;  // hour hand also moves half a degree a minute\n        double d = fabs(h - m);\n        return min(d, 360 - d);\n    }\n};",
 "append-characters-to-string-to-make-subsequence": "class Solution {\npublic:\n    int appendCharacters(string s, string t) {\n        size_t j = 0;   // how much of t is already a subsequence of s\n        for (char c : s)\n            if (j < t.size() && c == t[j]) j++;\n        return t.size() - j;\n    }\n};",
 "apply-operations-to-maximize-score": "class Solution {\n    static const int MOD = 1e9 + 7;\n\n    static int primes(int x) {   // number of distinct prime factors\n        int c = 0;\n        for (int d = 2; d * d <= x; d++)\n            if (x % d == 0) {\n                c++;\n                while (x % d == 0) x /= d;\n            }\n        return c + (x > 1);\n    }\n\n    static long long power(long long b, long long e) {\n        long long r = 1;\n        for (b %= MOD; e; e >>= 1, b = b * b % MOD)\n            if (e & 1) r = r * b % MOD;\n        return r;\n    }\n\npublic:\n    int maximumScore(vector<int>& nums, int k) {\n        int n = nums.size();\n        vector<int> s(n);\n        for (int i = 0; i < n; i++) s[i] = primes(nums[i]);\n        // nums[i] wins every subarray in (left[i], right[i]) that contains i\n        vector<int> left(n, -1), right(n, n), st;\n        for (int i = 0; i < n; i++) {\n            while (!st.empty() && s[st.back()] < s[i]) {\n                right[st.back()] = i;\n                st.pop_back();\n            }\n            left[i] = st.empty() ? -1 : st.back();\n            st.push_back(i);\n        }\n        vector<int> order(n);\n        iota(order.begin(), order.end(), 0);\n        sort(order.begin(), order.end(), [&](int a, int b) { return nums[a] > nums[b]; });   // biggest factor first\n        long long ans = 1, left_k = k;\n        for (int i : order) {\n            long long take = min(left_k, (long long)(i - left[i]) * (right[i] - i));\n            ans = ans * power(nums[i], take) % MOD;\n            if ((left_k -= take) == 0) break;\n        }\n        return ans;\n    }\n};",
 "array-nesting": "class Solution {\npublic:\n    int arrayNesting(vector<int>& nums) {\n        vector<bool> seen(nums.size(), false);\n        int best = 0;\n        for (int s = 0; s < (int)nums.size(); s++) {\n            int i = s, length = 0;\n            while (!seen[i]) {          // walk the cycle once\n                seen[i] = true;\n                i = nums[i];\n                length++;\n            }\n            best = max(best, length);\n        }\n        return best;\n    }\n};",
 "array-of-doubled-pairs": "class Solution {\npublic:\n    bool canReorderDoubled(vector<int>& arr) {\n        unordered_map<int, int> c;\n        for (int x : arr) c[x]++;\n        vector<int> keys;\n        for (auto& [x, k] : c) keys.push_back(x);\n        sort(keys.begin(), keys.end(), [](int a, int b) { return abs(a) < abs(b); });   // smallest size first\n        for (int x : keys) {\n            if (c[x] > c[2 * x]) return false;   // every x needs its own 2x\n            c[2 * x] -= c[x];\n        }\n        return true;\n    }\n};",
 "assign-cookies": "class Solution {\npublic:\n    int findContentChildren(vector<int>& g, vector<int>& s) {\n        sort(g.begin(), g.end());\n        sort(s.begin(), s.end());\n        size_t child = 0;\n        for (int cookie : s)                                 // smallest cookie that fits the least greedy child\n            if (child < g.size() && cookie >= g[child]) child++;\n        return child;\n    }\n};",
 "asteroid-collision": "class Solution {\npublic:\n    vector<int> asteroidCollision(vector<int>& asteroids) {\n        vector<int> stack;\n        for (int a : asteroids) {\n            bool alive = true;\n            while (alive && a < 0 && !stack.empty() && stack.back() > 0) {   // a left-mover meets a right-mover\n                if (stack.back() < -a) { stack.pop_back(); continue; }     // the right-mover explodes\n                if (stack.back() == -a) stack.pop_back();                   // both explode\n                alive = false;\n            }\n            if (alive) stack.push_back(a);\n        }\n        return stack;\n    }\n};",
 "average-of-levels-in-binary-tree": "class Solution {\npublic:\n    vector<double> averageOfLevels(TreeNode* root) {\n        vector<double> out;\n        vector<TreeNode*> level{root};\n        while (!level.empty()) {\n            double sum = 0;                                  // double: node sums can pass int range\n            for (TreeNode* n : level) sum += n->val;\n            out.push_back(sum / level.size());\n            vector<TreeNode*> next;\n            for (TreeNode* n : level)\n                for (TreeNode* c : {n->left, n->right}) if (c) next.push_back(c);\n            level = next;\n        }\n        return out;\n    }\n};",
 "average-waiting-time": "class Solution {\npublic:\n    double averageWaitingTime(vector<vector<int>>& customers) {\n        long long t = 0, wait = 0;\n        for (auto& c : customers) {\n            t = max<long long>(t, c[0]) + c[1];\n            wait += t - c[0];\n        }\n        return (double)wait / customers.size();\n    }\n};",
 "backspace-string-compare": "class Solution {\n    // index of the next kept character at or before i, or -1\n    int next(const string& x, int i) {\n        int skip = 0;\n        for (; i >= 0; i--) {\n            if (x[i] == '#') skip++;\n            else if (skip) skip--;\n            else break;\n        }\n        return i;\n    }\n\npublic:\n    bool backspaceCompare(string s, string t) {\n        int i = s.size() - 1, j = t.size() - 1;\n        while (true) {                                   // walk both from the end, one kept character at a time\n            i = next(s, i); j = next(t, j);\n            if (i < 0 || j < 0) return i < 0 && j < 0;\n            if (s[i] != t[j]) return false;\n            i--; j--;\n        }\n    }\n};",
 "bag-of-tokens": "class Solution {\npublic:\n    int bagOfTokensScore(vector<int>& tokens, int power) {\n        sort(tokens.begin(), tokens.end());\n        int lo = 0, hi = (int)tokens.size() - 1, score = 0, best = 0;\n        while (lo <= hi) {\n            if (power >= tokens[lo]) {       // buy a point with the cheapest token\n                power -= tokens[lo++];\n                best = max(best, ++score);\n            } else if (score) {              // sell a point for the dearest token\n                power += tokens[hi--];\n                score--;\n            } else break;\n        }\n        return best;\n    }\n};",
 "balance-a-binary-search-tree": "class Solution {\npublic:\n    TreeNode* balanceBST(TreeNode* root) {\n        vector<int> vals;\n        function<void(TreeNode*)> inorder = [&](TreeNode* n) {\n            if (n) { inorder(n->left); vals.push_back(n->val); inorder(n->right); }\n        };\n        inorder(root);                                     // sorted values\n        function<TreeNode*(int, int)> build = [&](int lo, int hi) -> TreeNode* {\n            if (lo > hi) return nullptr;\n            int mid = (lo + hi) / 2;                       // middle value becomes the root\n            return new TreeNode(vals[mid], build(lo, mid - 1), build(mid + 1, hi));\n        };\n        return build(0, (int)vals.size() - 1);\n    }\n};",
 "balanced-binary-tree": "class Solution {\n    int height(TreeNode* node) {                           // -1 means unbalanced below\n        if (!node) return 0;\n        int a = height(node->left), b = height(node->right);\n        if (a < 0 || b < 0 || abs(a - b) > 1) return -1;\n        return 1 + max(a, b);\n    }\npublic:\n    bool isBalanced(TreeNode* root) { return height(root) >= 0; }\n};",
 "basic-calculator": "class Solution {\npublic:\n    int calculate(string s) {\n        long long res = 0, num = 0;\n        int sign = 1;\n        vector<pair<long long, int>> st;   // (result so far, sign before the bracket)\n        for (char c : s) {\n            if (isdigit(c)) {\n                num = num * 10 + (c - '0');\n            } else if (c == '+' || c == '-') {\n                res += sign * num;\n                num = 0;\n                sign = c == '+' ? 1 : -1;\n            } else if (c == '(') {\n                st.push_back({res, sign});\n                res = 0;\n                sign = 1;\n            } else if (c == ')') {\n                res += sign * num;\n                num = 0;\n                auto [prev, psign] = st.back();\n                st.pop_back();\n                res = prev + psign * res;   // fold the bracket into the outer sum\n            }\n        }\n        return res + sign * num;\n    }\n};",
 "basic-calculator-ii": "class Solution {\npublic:\n    int calculate(string s) {\n        vector<int> stack;   // terms to add up at the end\n        long long num = 0;\n        char op = '+';\n        s += '+';   // flushes the last number\n        for (char ch : s) {\n            if (isdigit(ch)) {\n                num = num * 10 + (ch - '0');\n            } else if (string(\"+-*/\").find(ch) != string::npos) {\n                if (op == '+') stack.push_back(num);\n                else if (op == '-') stack.push_back(-num);\n                else if (op == '*') stack.back() *= num;   // * and / bind to the previous term\n                else stack.back() /= num;                  // C++ division truncates toward zero\n                op = ch;\n                num = 0;\n            }\n        }\n        return accumulate(stack.begin(), stack.end(), 0);\n    }\n};",
 "beautiful-arrangement": "class Solution {\n    int n = 0;\n    vector<bool> used;\n    int place(int pos) {\n        if (pos > n) return 1;                               // every spot filled\n        int total = 0;\n        for (int x = 1; x <= n; x++)\n            if (!used[x] && (x % pos == 0 || pos % x == 0)) {\n                used[x] = true;\n                total += place(pos + 1);\n                used[x] = false;                             // undo and try the next number\n            }\n        return total;\n    }\npublic:\n    int countArrangement(int n) {\n        this->n = n;\n        used.assign(n + 1, false);\n        return place(1);\n    }\n};",
 "best-time-to-buy-and-sell-stock": "class Solution {\npublic:\n    int maxProfit(vector<int>& prices) {\n        int low = INT_MAX, best = 0;\n        for (int p : prices) {\n            low = min(low, p);                             // cheapest day so far\n            best = max(best, p - low);\n        }\n        return best;\n    }\n};",
 "best-time-to-buy-and-sell-stock-ii": "class Solution {\npublic:\n    int maxProfit(vector<int>& prices) {\n        int total = 0;\n        for (size_t i = 1; i < prices.size(); i++) total += max(0, prices[i] - prices[i - 1]);   // take every rise\n        return total;\n    }\n};",
 "best-time-to-buy-and-sell-stock-iii": "class Solution {\npublic:\n    int maxProfit(vector<int>& prices) {\n        int buy1 = INT_MIN, buy2 = INT_MIN, sell1 = 0, sell2 = 0;   // best cash after each step\n        for (int p : prices) {\n            buy1 = max(buy1, -p);\n            sell1 = max(sell1, buy1 + p);\n            buy2 = max(buy2, sell1 - p);\n            sell2 = max(sell2, buy2 + p);\n        }\n        return sell2;\n    }\n};",
 "best-time-to-buy-and-sell-stock-iv": "class Solution {\npublic:\n    int maxProfit(int k, vector<int>& prices) {\n        vector<int> buy(k + 1, INT_MIN), sell(k + 1, 0);     // best cash holding a stock / not, after t buys\n        for (int p : prices)\n            for (int t = 1; t <= k; t++) {\n                buy[t] = max(buy[t], sell[t - 1] - p);\n                sell[t] = max(sell[t], buy[t] + p);\n            }\n        return sell[k];\n    }\n};",
 "best-time-to-buy-and-sell-stock-with-cooldown": "class Solution {\npublic:\n    int maxProfit(vector<int>& prices) {\n        int hold = INT_MIN, sold = 0, rest = 0;              // holding, just sold, free to buy\n        for (int p : prices) {\n            int h = max(hold, rest - p), s = hold + p, r = max(rest, sold);\n            hold = h; sold = s; rest = r;\n        }\n        return max(sold, rest);\n    }\n};",
 "best-time-to-buy-and-sell-stock-with-transaction-fee": "class Solution {\npublic:\n    int maxProfit(vector<int>& prices, int fee) {\n        int cash = 0, hold = -prices[0];                     // best with no stock / with one\n        for (size_t i = 1; i < prices.size(); i++) {\n            int p = prices[i];\n            int c = max(cash, hold + p - fee), h = max(hold, cash - p);\n            cash = c; hold = h;\n        }\n        return cash;\n    }\n};",
 "binary-search": "class Solution {\npublic:\n    int search(vector<int>& nums, int target) {\n        int lo = 0, hi = nums.size() - 1;\n        while (lo <= hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (nums[mid] == target) return mid;\n            if (nums[mid] < target) lo = mid + 1;\n            else hi = mid - 1;\n        }\n        return -1;\n    }\n};",
 "binary-search-tree-iterator": "class BSTIterator {\n    stack<TreeNode*> st;\n    void push(TreeNode* node) {                              // walk down the left spine\n        for (; node; node = node->left) st.push(node);\n    }\npublic:\n    BSTIterator(TreeNode* root) { push(root); }\n\n    int next() {\n        TreeNode* node = st.top(); st.pop();\n        push(node->right);                                   // its right subtree comes next in order\n        return node->val;\n    }\n\n    bool hasNext() { return !st.empty(); }\n};",
 "binary-search-tree-to-greater-sum-tree": "class Solution {\npublic:\n    TreeNode* bstToGst(TreeNode* root) {\n        int total = 0;\n        function<void(TreeNode*)> go = [&](TreeNode* n) {\n            if (!n) return;\n            go(n->right);                                  // reverse inorder: largest values first\n            total += n->val;\n            n->val = total;\n            go(n->left);\n        };\n        go(root);\n        return root;\n    }\n};",
 "binary-subarrays-with-sum": "class Solution {\npublic:\n    int numSubarraysWithSum(vector<int>& nums, int goal) {\n        unordered_map<int, int> seen{{0, 1}};   // prefix sum -> how many times seen\n        int s = 0, ans = 0;\n        for (int x : nums) {\n            s += x;\n            if (auto it = seen.find(s - goal); it != seen.end()) ans += it->second;\n            seen[s]++;\n        }\n        return ans;\n    }\n};",
 "binary-tree-cameras": "class Solution {\n    int cams = 0;\n    // 0 = needs cover, 1 = has camera, 2 = covered\n    int dfs(TreeNode* node) {\n        if (!node) return 2;\n        int l = dfs(node->left), r = dfs(node->right);\n        if (l == 0 || r == 0) {   // a child is uncovered: put a camera here\n            cams++;\n            return 1;\n        }\n        return l == 1 || r == 1 ? 2 : 0;\n    }\n\npublic:\n    int minCameraCover(TreeNode* root) {\n        int rootState = dfs(root);\n        return cams + (rootState == 0);\n    }\n};",
 "binary-tree-coloring-game": "class Solution {\n    int x, l = 0, r = 0;   // sizes of x's left and right subtrees\n    int count(TreeNode* node) {\n        if (!node) return 0;\n        int a = count(node->left), b = count(node->right);\n        if (node->val == x) { l = a; r = b; }\n        return a + b + 1;\n    }\npublic:\n    bool btreeGameWinningMove(TreeNode* root, int n, int x) {\n        this->x = x;\n        count(root);\n        return max({l, r, n - 1 - l - r}) > n / 2;   // take the biggest of the three regions\n    }\n};",
 "binary-tree-inorder-traversal": "class Solution {\npublic:\n    vector<int> inorderTraversal(TreeNode* root) {\n        vector<int> out;\n        stack<TreeNode*> st;\n        TreeNode* node = root;\n        while (!st.empty() || node) {\n            while (node) { st.push(node); node = node->left; }   // go as far left as possible\n            node = st.top(); st.pop();\n            out.push_back(node->val);\n            node = node->right;\n        }\n        return out;\n    }\n};",
 "binary-tree-level-order-traversal": "class Solution {\npublic:\n    vector<vector<int>> levelOrder(TreeNode* root) {\n        if (!root) return {};\n        vector<vector<int>> out;\n        queue<TreeNode*> q;\n        q.push(root);\n        while (!q.empty()) {\n            vector<int> level;\n            for (int i = q.size(); i > 0; i--) {           // exactly the nodes of this level\n                TreeNode* node = q.front(); q.pop();\n                level.push_back(node->val);\n                if (node->left) q.push(node->left);\n                if (node->right) q.push(node->right);\n            }\n            out.push_back(level);\n        }\n        return out;\n    }\n};",
 "binary-tree-level-order-traversal-ii": "class Solution {\npublic:\n    vector<vector<int>> levelOrderBottom(TreeNode* root) {\n        if (!root) return {};\n        vector<vector<int>> out;\n        queue<TreeNode*> q;\n        q.push(root);\n        while (!q.empty()) {\n            vector<int> level;\n            for (int k = q.size(); k > 0; k--) {\n                TreeNode* n = q.front();\n                q.pop();\n                level.push_back(n->val);\n                if (n->left) q.push(n->left);\n                if (n->right) q.push(n->right);\n            }\n            out.push_back(level);\n        }\n        reverse(out.begin(), out.end());   // bottom level first\n        return out;\n    }\n};",
 "binary-tree-maximum-path-sum": "class Solution {\n    int best = INT_MIN;\n    int gain(TreeNode* node) {                             // best downward path starting here\n        if (!node) return 0;\n        int a = max(gain(node->left), 0), b = max(gain(node->right), 0);\n        best = max(best, node->val + a + b);               // path that bends at this node\n        return node->val + max(a, b);\n    }\npublic:\n    int maxPathSum(TreeNode* root) {\n        gain(root);\n        return best;\n    }\n};",
 "binary-tree-paths": "class Solution {\n    vector<string> out;\n    void dfs(TreeNode* node, string path) {\n        path += to_string(node->val);\n        if (!node->left && !node->right) { out.push_back(path); return; }   // a leaf ends a path\n        if (node->left) dfs(node->left, path + \"->\");\n        if (node->right) dfs(node->right, path + \"->\");\n    }\npublic:\n    vector<string> binaryTreePaths(TreeNode* root) {\n        dfs(root, \"\");\n        return out;\n    }\n};",
 "binary-tree-preorder-traversal": "class Solution {\npublic:\n    vector<int> preorderTraversal(TreeNode* root) {\n        vector<int> out;\n        vector<TreeNode*> st;\n        if (root) st.push_back(root);\n        while (!st.empty()) {\n            TreeNode* node = st.back(); st.pop_back();\n            out.push_back(node->val);\n            if (node->right) st.push_back(node->right);    // right first so left pops first\n            if (node->left) st.push_back(node->left);\n        }\n        return out;\n    }\n};",
 "binary-tree-pruning": "class Solution {\npublic:\n    TreeNode* pruneTree(TreeNode* root) {\n        if (!root) return nullptr;\n        root->left = pruneTree(root->left);\n        root->right = pruneTree(root->right);\n        if (!root->left && !root->right && root->val == 0) return nullptr;   // a 0 leaf after pruning goes too\n        return root;\n    }\n};",
 "binary-tree-right-side-view": "class Solution {\npublic:\n    vector<int> rightSideView(TreeNode* root) {\n        vector<int> out;\n        vector<TreeNode*> level;\n        if (root) level.push_back(root);\n        while (!level.empty()) {\n            out.push_back(level.back()->val);              // rightmost node of the level\n            vector<TreeNode*> next;\n            for (TreeNode* n : level)\n                for (TreeNode* c : {n->left, n->right})\n                    if (c) next.push_back(c);\n            level = next;\n        }\n        return out;\n    }\n};",
 "binary-tree-zigzag-level-order-traversal": "class Solution {\npublic:\n    vector<vector<int>> zigzagLevelOrder(TreeNode* root) {\n        vector<vector<int>> out;\n        vector<TreeNode*> level;\n        if (root) level.push_back(root);\n        bool flip = false;\n        while (!level.empty()) {\n            vector<int> vals;\n            for (TreeNode* n : level) vals.push_back(n->val);\n            if (flip) reverse(vals.begin(), vals.end());   // every other level right to left\n            out.push_back(vals);\n            flip = !flip;\n            vector<TreeNode*> next;\n            for (TreeNode* n : level)\n                for (TreeNode* c : {n->left, n->right})\n                    if (c) next.push_back(c);\n            level = next;\n        }\n        return out;\n    }\n};",
 "bitwise-and-of-numbers-range": "class Solution {\npublic:\n    int rangeBitwiseAnd(int left, int right) {\n        int shift = 0;\n        while (left != right) {   // strip bits until only the common prefix is left\n            left >>= 1;\n            right >>= 1;\n            shift++;\n        }\n        return left << shift;\n    }\n};",
 "boats-to-save-people": "class Solution {\npublic:\n    int numRescueBoats(vector<int>& people, int limit) {\n        sort(people.begin(), people.end());\n        int i = 0, j = (int)people.size() - 1, boats = 0;\n        while (i <= j) {\n            if (people[i] + people[j] <= limit) i++;         // lightest rides with the heaviest if they fit\n            j--;\n            boats++;\n        }\n        return boats;\n    }\n};",
 "broken-calculator": "class Solution {\npublic:\n    int brokenCalc(int startValue, int target) {\n        int steps = 0;\n        while (target > startValue) {   // work backwards: halve when even, else add one\n            target = target % 2 == 0 ? target / 2 : target + 1;\n            steps++;\n        }\n        return steps + startValue - target;\n    }\n};",
 "burst-balloons": "class Solution {\npublic:\n    int maxCoins(vector<int>& nums) {\n        vector<int> a = {1};                         // pad with a 1 on each side\n        a.insert(a.end(), nums.begin(), nums.end());\n        a.push_back(1);\n        int n = a.size();\n        vector<vector<int>> dp(n, vector<int>(n, 0));    // dp[i][j]: best for balloons strictly between i and j\n        for (int gap = 2; gap < n; gap++)\n            for (int i = 0; i + gap < n; i++) {\n                int j = i + gap;\n                for (int k = i + 1; k < j; k++)          // k is the last balloon burst between i and j\n                    dp[i][j] = max(dp[i][j], dp[i][k] + a[i] * a[k] * a[j] + dp[k][j]);\n            }\n        return dp[0][n - 1];\n    }\n};",
 "bus-routes": "class Solution {\npublic:\n    int numBusesToDestination(vector<vector<int>>& routes, int source, int target) {\n        if (source == target) return 0;\n        unordered_map<int, vector<int>> buses;   // stop -> buses through it\n        for (int b = 0; b < (int)routes.size(); b++)\n            for (int s : routes[b]) buses[s].push_back(b);\n        queue<pair<int, int>> q;   // (stop, buses taken)\n        q.push({source, 0});\n        unordered_set<int> used, seen{source};\n        while (!q.empty()) {\n            auto [s, d] = q.front();\n            q.pop();\n            for (int b : buses[s]) {\n                if (!used.insert(b).second) continue;   // each bus is ridden once\n                for (int t : routes[b]) {\n                    if (t == target) return d + 1;\n                    if (seen.insert(t).second) q.push({t, d + 1});\n                }\n            }\n        }\n        return -1;\n    }\n};",
 "camelcase-matching": "class Solution {\npublic:\n    vector<bool> camelMatch(vector<string>& queries, string pattern) {\n        vector<bool> out;\n        for (auto& q : queries) {\n            size_t j = 0;\n            bool ok = true;\n            for (char ch : q) {\n                if (j < pattern.size() && ch == pattern[j]) j++;\n                else if (isupper(ch)) { ok = false; break; }   // an extra capital cannot be inserted\n            }\n            out.push_back(ok && j == pattern.size());\n        }\n        return out;\n    }\n};",
 "candy": "class Solution {\npublic:\n    int candy(vector<int>& ratings) {\n        int n = ratings.size();\n        vector<int> c(n, 1);\n        for (int i = 1; i < n; i++)                      // left neighbour rule\n            if (ratings[i] > ratings[i - 1]) c[i] = c[i - 1] + 1;\n        for (int i = n - 2; i >= 0; i--)                 // right neighbour rule, keep the larger\n            if (ratings[i] > ratings[i + 1]) c[i] = max(c[i], c[i + 1] + 1);\n        return accumulate(c.begin(), c.end(), 0);\n    }\n};",
 "car-fleet-ii": "class Solution {\npublic:\n    vector<double> getCollisionTimes(vector<vector<int>>& cars) {\n        int n = cars.size();\n        vector<double> ans(n, -1.0);\n        vector<int> stack;   // cars ahead that this car might hit\n        for (int i = n - 1; i >= 0; i--) {\n            int p = cars[i][0], s = cars[i][1];\n            while (!stack.empty()) {\n                int j = stack.back(), pj = cars[j][0], sj = cars[j][1];\n                // too slow to catch j, or j merges into a fleet before we arrive\n                if (s <= sj || (ans[j] > 0 && (double)(pj - p) / (s - sj) >= ans[j])) {\n                    stack.pop_back();\n                } else {\n                    ans[i] = (double)(pj - p) / (s - sj);\n                    break;\n                }\n            }\n            stack.push_back(i);\n        }\n        return ans;\n    }\n};",
 "car-pooling": "class Solution {\npublic:\n    bool carPooling(vector<vector<int>>& trips, int capacity) {\n        vector<int> diff(1001, 0);\n        for (auto& t : trips) {\n            diff[t[1]] += t[0];                            // passengers get on\n            diff[t[2]] -= t[0];                            // and off\n        }\n        int load = 0;\n        for (int d : diff) {\n            load += d;\n            if (load > capacity) return false;\n        }\n        return true;\n    }\n};",
 "cf:binary search": "// smallest time t in which the machines make at least k items\nlong long solve(vector<int> a, long long k) {\n    long long lo = 1, hi = *min_element(a.begin(), a.end()) * k;   // the fastest machine alone is surely enough\n    while (lo < hi) {\n        long long mid = (lo + hi) / 2, made = 0;\n        for (int x : a) made += mid / x;\n        if (made >= k) hi = mid;\n        else lo = mid + 1;\n    }\n    return lo;\n}",
 "cf:bitmasks": "// is there a non-empty subset of a that sums to target?\nstring solve(vector<int> a, int target) {\n    int n = a.size();\n    for (int mask = 1; mask < (1 << n); mask++) {          // each mask is one subset\n        long long total = 0;\n        for (int i = 0; i < n; i++)\n            if (mask >> i & 1) total += a[i];\n        if (total == target) return \"YES\";\n    }\n    return \"NO\";\n}",
 "cf:brute force": "// pairs i < j with a[i] + a[j] divisible by k\nlong long solve(vector<int> a, int k) {\n    long long count = 0;\n    for (size_t i = 0; i < a.size(); i++)\n        for (size_t j = i + 1; j < a.size(); j++)\n            if ((a[i] + a[j]) % k == 0) count++;\n    return count;\n}",
 "cf:constructive algorithms": "// a permutation of 1..n where neighbours differ by at least 2, or [-1]\nvector<int> solve(int n) {\n    if (n == 1) return {1};\n    if (n < 4) return {-1};\n    vector<int> out;\n    for (int x = 2; x <= n; x += 2) out.push_back(x);      // evens first, then odds\n    for (int x = 1; x <= n; x += 2) out.push_back(x);\n    return out;\n}",
 "cf:data structures": "// number of groups after each link (union-find)\nvector<int> solve(int n, vector<pair<int, int>> links) {\n    vector<int> parent(n);\n    iota(parent.begin(), parent.end(), 0);\n    auto find = [&](int x) {\n        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }   // path halving\n        return x;\n    };\n    int groups = n;\n    vector<int> out;\n    for (auto [a, b] : links) {\n        int ra = find(a), rb = find(b);\n        if (ra != rb) { parent[ra] = rb; groups--; }\n        out.push_back(groups);\n    }\n    return out;\n}",
 "cf:dp": "// frog: least total cost to reach the last stone, jumping 1 or 2\nint solve(vector<int> h) {\n    int n = h.size();\n    vector<int> best(n, 0);\n    for (int i = 1; i < n; i++) {\n        best[i] = best[i - 1] + abs(h[i] - h[i - 1]);\n        if (i > 1) best[i] = min(best[i], best[i - 2] + abs(h[i] - h[i - 2]));\n    }\n    return best[n - 1];\n}",
 "cf:graphs": "// shortest number of edges from 0 to n - 1, or -1\nint solve(int n, vector<pair<int, int>> edges) {\n    vector<vector<int>> adj(n);\n    for (auto [u, v] : edges) { adj[u].push_back(v); adj[v].push_back(u); }\n    vector<int> dist(n, -1);\n    queue<int> q; q.push(0); dist[0] = 0;\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        for (int v : adj[u]) if (dist[v] < 0) { dist[v] = dist[u] + 1; q.push(v); }\n    }\n    return dist[n - 1];\n}",
 "cf:greedy": "// at most k swaps of a[i] with b[j] to maximise sum(a)\nlong long solve(vector<int> a, vector<int> b, int k) {\n    sort(a.begin(), a.end());                              // smallest of a\n    sort(b.rbegin(), b.rend());                            // against largest of b\n    for (int i = 0; i < min(k, (int)a.size()); i++) {\n        if (b[i] <= a[i]) break;\n        a[i] = b[i];\n    }\n    return accumulate(a.begin(), a.end(), 0LL);\n}",
 "cf:implementation": "// first step at which the walk revisits a point, or -1\nint solve(string s) {\n    map<char, pair<int, int>> moves{{'U', {0, 1}}, {'D', {0, -1}}, {'L', {-1, 0}}, {'R', {1, 0}}};\n    int x = 0, y = 0;\n    set<pair<int, int>> seen{{0, 0}};\n    for (int step = 1; step <= (int)s.size(); step++) {\n        x += moves[s[step - 1]].first;\n        y += moves[s[step - 1]].second;\n        if (!seen.insert({x, y}).second) return step;      // already visited\n    }\n    return -1;\n}",
 "cf:math": "// numbers in 1..n divisible by a or b (inclusion-exclusion)\nlong long solve(long long n, long long a, long long b) {\n    long long lcm = a / gcd(a, b) * b;                     // divide first to avoid overflow\n    return n / a + n / b - n / lcm;\n}",
 "cf:number theory": "// number of divisors of n, from its prime factorisation\nlong long solve(long long n) {\n    long long ways = 1;\n    for (long long d = 2; d * d <= n; d++) {\n        int e = 0;\n        while (n % d == 0) { n /= d; e++; }\n        ways *= e + 1;\n    }\n    return n > 1 ? ways * 2 : ways;                        // a prime left over adds exponent 1\n}",
 "cf:sortings": "// smallest max - min over any k elements\nint solve(vector<int> a, int k) {\n    sort(a.begin(), a.end());\n    int best = INT_MAX;\n    for (size_t i = 0; i + k - 1 < a.size(); i++)          // the best k are neighbours once sorted\n        best = min(best, a[i + k - 1] - a[i]);\n    return best;\n}",
 "cf:strings": "// length of the longest proper prefix that is also a suffix (prefix function)\nint solve(string s) {\n    vector<int> pi(s.size(), 0);\n    for (size_t i = 1; i < s.size(); i++) {\n        int j = pi[i - 1];\n        while (j && s[i] != s[j]) j = pi[j - 1];\n        if (s[i] == s[j]) j++;\n        pi[i] = j;\n    }\n    return pi.back();\n}",
 "cf:two pointers": "// longest window with sum at most s\nint solve(vector<int> a, long long s) {\n    int best = 0, l = 0;\n    long long total = 0;\n    for (int r = 0; r < (int)a.size(); r++) {\n        total += a[r];\n        while (total > s) total -= a[l++];                 // shrink from the left\n        best = max(best, r - l + 1);\n    }\n    return best;\n}",
 "cheapest-flights-within-k-stops": "class Solution {\npublic:\n    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {\n        const int INF = INT_MAX;\n        vector<int> cost(n, INF);\n        cost[src] = 0;\n        for (int round = 0; round <= k; round++) {       // k stops means at most k + 1 flights\n            vector<int> nxt = cost;                      // relax from last round's costs only\n            for (auto& f : flights) {\n                int u = f[0], v = f[1], w = f[2];\n                if (cost[u] != INF && cost[u] + w < nxt[v]) nxt[v] = cost[u] + w;\n            }\n            cost = nxt;\n        }\n        return cost[dst] == INF ? -1 : cost[dst];\n    }\n};",
 "check-if-all-the-integers-in-a-range-are-covered": "class Solution {\npublic:\n    bool isCovered(vector<vector<int>>& ranges, int left, int right) {\n        vector<int> diff(52, 0);\n        for (auto& r : ranges) { diff[r[0]]++; diff[r[1] + 1]--; }\n        int cover = 0;\n        for (int x = 1; x <= right; x++) {\n            cover += diff[x];                              // how many ranges cover x\n            if (x >= left && cover == 0) return false;\n        }\n        return true;\n    }\n};",
 "cherry-pickup": "class Solution {\npublic:\n    int cherryPickup(vector<vector<int>>& grid) {\n        int n = grid.size();\n        const int NEG = INT_MIN;   // unreachable\n        // two walkers move together; after t steps walker k is at (rk, t - rk)\n        vector<vector<int>> dp(n, vector<int>(n, NEG));\n        dp[0][0] = grid[0][0];\n        for (int t = 1; t < 2 * n - 1; t++) {\n            vector<vector<int>> nxt(n, vector<int>(n, NEG));\n            for (int r1 = max(0, t - n + 1); r1 < min(n, t + 1); r1++)\n                for (int r2 = max(0, t - n + 1); r2 < min(n, t + 1); r2++) {\n                    int c1 = t - r1, c2 = t - r2;\n                    if (grid[r1][c1] < 0 || grid[r2][c2] < 0) continue;\n                    int best = NEG;\n                    for (int a : {r1 - 1, r1})\n                        for (int b : {r2 - 1, r2})\n                            if (a >= 0 && b >= 0) best = max(best, dp[a][b]);\n                    if (best == NEG) continue;\n                    int gain = grid[r1][c1] + (r1 != r2 ? grid[r2][c2] : 0);   // same cell counts once\n                    nxt[r1][r2] = best + gain;\n                }\n            dp = nxt;\n        }\n        return max(0, dp[n - 1][n - 1]);\n    }\n};",
 "climbing-stairs": "class Solution {\npublic:\n    int climbStairs(int n) {\n        int a = 1, b = 1;                                    // ways to reach the last two steps\n        for (int i = 0; i < n - 1; i++) {\n            int c = a + b;\n            a = b;\n            b = c;\n        }\n        return b;\n    }\n};",
 "clone-graph": "class Node {\npublic:\n    int val;\n    vector<Node*> neighbors;\n    Node() { val = 0; neighbors = vector<Node*>(); }\n    Node(int _val) { val = _val; neighbors = vector<Node*>(); }\n    Node(int _val, vector<Node*> _neighbors) { val = _val; neighbors = _neighbors; }\n};\n\nclass Solution {\npublic:\n    Node* cloneGraph(Node* node) {\n        if (!node) return nullptr;\n        unordered_map<Node*, Node*> copies = {{node, new Node(node->val)}};   // original to copy\n        vector<Node*> stack = {node};\n        while (!stack.empty()) {\n            Node* u = stack.back(); stack.pop_back();\n            for (Node* v : u->neighbors) {\n                if (!copies.count(v)) {                  // first visit: make its copy\n                    copies[v] = new Node(v->val);\n                    stack.push_back(v);\n                }\n                copies[u]->neighbors.push_back(copies[v]);\n            }\n        }\n        return copies[node];\n    }\n};",
 "coin-change": "class Solution {\npublic:\n    int coinChange(vector<int>& coins, int amount) {\n        int INF = amount + 1;                                // more coins than any real answer\n        vector<int> dp(amount + 1, INF);\n        dp[0] = 0;\n        for (int a = 1; a <= amount; a++)\n            for (int c : coins)\n                if (c <= a && dp[a - c] + 1 < dp[a]) dp[a] = dp[a - c] + 1;\n        return dp[amount] <= amount ? dp[amount] : -1;\n    }\n};",
 "coin-change-ii": "class Solution {\npublic:\n    int change(int amount, vector<int>& coins) {\n        // unsigned: middle cells can pass int range on LeetCode's tests; the answer itself fits\n        vector<unsigned long long> dp(amount + 1, 0);\n        dp[0] = 1;\n        for (int c : coins)                                  // coins outside: each combination counted once\n            for (int a = c; a <= amount; a++) dp[a] += dp[a - c];\n        return (int)dp[amount];\n    }\n};",
 "combination-sum": "class Solution {\n    vector<vector<int>> out;\n    vector<int> path;\n\n    void dfs(vector<int>& candidates, int start, int remain) {\n        if (remain == 0) { out.push_back(path); return; }\n        for (int i = start; i < (int)candidates.size(); i++) {\n            int c = candidates[i];\n            if (c > remain) break;                       // sorted, so the rest are too big as well\n            path.push_back(c);\n            dfs(candidates, i, remain - c);              // i, not i + 1: c can be reused\n            path.pop_back();\n        }\n    }\n\npublic:\n    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {\n        sort(candidates.begin(), candidates.end());\n        dfs(candidates, 0, target);\n        return out;\n    }\n};",
 "combination-sum-iii": "class Solution {\npublic:\n    vector<vector<int>> combinationSum3(int k, int n) {\n        vector<vector<int>> out;\n        vector<int> path;\n        function<void(int, int)> go = [&](int start, int rem) {\n            if ((int)path.size() == k) {\n                if (rem == 0) out.push_back(path);\n                return;\n            }\n            for (int d = start; d <= 9; d++) {\n                if (d > rem) break;                        // digits only grow, so stop early\n                path.push_back(d);\n                go(d + 1, rem - d);\n                path.pop_back();\n            }\n        };\n        go(1, n);\n        return out;\n    }\n};",
 "combinations": "class Solution {\n    vector<vector<int>> out;\n    vector<int> path;\n\n    void dfs(int n, int k, int start) {\n        if ((int)path.size() == k) { out.push_back(path); return; }\n        for (int x = start; x <= n - (k - (int)path.size()) + 1; x++) {   // leave room for the rest\n            path.push_back(x);\n            dfs(n, k, x + 1);\n            path.pop_back();\n        }\n    }\n\npublic:\n    vector<vector<int>> combine(int n, int k) {\n        dfs(n, k, 1);\n        return out;\n    }\n};",
 "compare-version-numbers": "class Solution {\n    vector<int> parts(const string& v) {\n        vector<int> out;\n        stringstream ss(v);\n        string p;\n        while (getline(ss, p, '.')) out.push_back(stoi(p));   // stoi drops leading zeros\n        return out;\n    }\n\npublic:\n    int compareVersion(string version1, string version2) {\n        auto a = parts(version1), b = parts(version2);\n        for (size_t i = 0; i < max(a.size(), b.size()); i++) {\n            int x = i < a.size() ? a[i] : 0, y = i < b.size() ? b[i] : 0;   // a missing part counts as 0\n            if (x != y) return x > y ? 1 : -1;\n        }\n        return 0;\n    }\n};",
 "complete-binary-tree-inserter": "class CBTInserter {\n    vector<TreeNode*> a;                               // nodes in level order: parent of i is (i - 1) / 2\npublic:\n    CBTInserter(TreeNode* root) {\n        a.push_back(root);\n        for (size_t i = 0; i < a.size(); i++) {\n            if (a[i]->left) a.push_back(a[i]->left);\n            if (a[i]->right) a.push_back(a[i]->right);\n        }\n    }\n\n    int insert(int val) {\n        TreeNode* node = new TreeNode(val);\n        TreeNode* p = a[(a.size() - 1) / 2];           // parent of the next free slot\n        if (!p->left) p->left = node;\n        else p->right = node;\n        a.push_back(node);\n        return p->val;\n    }\n\n    TreeNode* get_root() { return a[0]; }\n};",
 "concatenated-words": "class Solution {\npublic:\n    vector<string> findAllConcatenatedWordsInADict(vector<string>& words) {\n        unordered_set<string> vocab(words.begin(), words.end());\n        // can w be split into at least two words of the list?\n        auto can = [&](const string& w) -> bool {\n            int n = w.size();\n            vector<bool> dp(n + 1, false);\n            dp[0] = true;\n            for (int i = 1; i <= n; i++)\n                for (int j = 0; j < i; j++)\n                    if (dp[j] && !(j == 0 && i == n) && vocab.count(w.substr(j, i - j))) { dp[i] = true; break; }\n            return dp[n];\n        };\n        vector<string> out;\n        for (auto& w : words) if (!w.empty() && can(w)) out.push_back(w);\n        return out;\n    }\n};",
 "construct-binary-search-tree-from-preorder-traversal": "class Solution {\npublic:\n    TreeNode* bstFromPreorder(vector<int>& preorder) {\n        size_t i = 0;\n        function<TreeNode*(int)> build = [&](int hi) -> TreeNode* {\n            if (i == preorder.size() || preorder[i] > hi) return nullptr;   // next value belongs higher up\n            TreeNode* node = new TreeNode(preorder[i++]);\n            node->left = build(node->val);\n            node->right = build(hi);\n            return node;\n        };\n        return build(INT_MAX);\n    }\n};",
 "construct-binary-tree-from-inorder-and-postorder-traversal": "class Solution {\n    unordered_map<int, int> at;                              // value -> index in inorder\n    vector<int> post;\n    TreeNode* go(int lo, int hi) {\n        if (lo > hi) return nullptr;\n        int v = post.back(); post.pop_back();                // postorder from the end gives roots\n        TreeNode* node = new TreeNode(v);\n        node->right = go(at[v] + 1, hi);                     // right first, since we read backwards\n        node->left = go(lo, at[v] - 1);\n        return node;\n    }\npublic:\n    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {\n        for (int i = 0; i < (int)inorder.size(); i++) at[inorder[i]] = i;\n        post = postorder;\n        return go(0, (int)inorder.size() - 1);\n    }\n};",
 "construct-binary-tree-from-preorder-and-inorder-traversal": "class Solution {\n    unordered_map<int, int> at;                              // value -> index in inorder\n    int next = 0;                                            // next root in preorder\n    TreeNode* go(const vector<int>& preorder, int lo, int hi) {\n        if (lo > hi) return nullptr;\n        int v = preorder[next++];\n        TreeNode* node = new TreeNode(v);\n        node->left = go(preorder, lo, at[v] - 1);\n        node->right = go(preorder, at[v] + 1, hi);\n        return node;\n    }\npublic:\n    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {\n        for (int i = 0; i < (int)inorder.size(); i++) at[inorder[i]] = i;\n        return go(preorder, 0, (int)inorder.size() - 1);\n    }\n};",
 "construct-binary-tree-from-preorder-and-postorder-traversal": "class Solution {\npublic:\n    TreeNode* constructFromPrePost(vector<int>& preorder, vector<int>& postorder) {\n        unordered_map<int, int> at;\n        for (int i = 0; i < (int)postorder.size(); i++) at[postorder[i]] = i;\n        // preorder[a..b], postorder starting at c\n        function<TreeNode*(int, int, int)> build = [&](int a, int b, int c) -> TreeNode* {\n            if (a > b) return nullptr;\n            TreeNode* root = new TreeNode(preorder[a]);\n            if (a == b) return root;\n            int size = at[preorder[a + 1]] - c + 1;        // left subtree size\n            root->left = build(a + 1, a + size, c);\n            root->right = build(a + size + 1, b, c + size);\n            return root;\n        };\n        return build(0, (int)preorder.size() - 1, 0);\n    }\n};",
 "construct-k-palindrome-strings": "class Solution {\npublic:\n    bool canConstruct(string s, int k) {\n        int cnt[26] = {};\n        for (char c : s) cnt[c - 'a']++;\n        int odd = 0;\n        for (int v : cnt) odd += v % 2;   // each odd count needs its own palindrome centre\n        return odd <= k && k <= (int)s.size();\n    }\n};",
 "construct-smallest-number-from-di-string": "class Solution {\npublic:\n    string smallestNumber(string pattern) {\n        string out, st;\n        for (int i = 0; i <= (int)pattern.size(); i++) {\n            st.push_back('1' + i);\n            if (i == (int)pattern.size() || pattern[i] == 'I') {   // a rise: flush the run reversed\n                while (!st.empty()) { out.push_back(st.back()); st.pop_back(); }\n            }\n        }\n        return out;\n    }\n};",
 "container-with-most-water": "class Solution {\npublic:\n    int maxArea(vector<int>& height) {\n        int l = 0, r = height.size() - 1, best = 0;\n        while (l < r) {\n            best = max(best, (r - l) * min(height[l], height[r]));\n            if (height[l] < height[r]) l++;                // move the shorter wall\n            else r--;\n        }\n        return best;\n    }\n};",
 "contains-duplicate": "class Solution {\npublic:\n    bool containsDuplicate(vector<int>& nums) {\n        unordered_set<int> seen;\n        for (int x : nums)\n            if (!seen.insert(x).second) return true;       // already there\n        return false;\n    }\n};",
 "contains-duplicate-iii": "class Solution {\n    static long long floorDiv(long long a, long long b) { return a / b - (a % b != 0 && (a < 0) != (b < 0)); }\npublic:\n    bool containsNearbyAlmostDuplicate(vector<int>& nums, int indexDiff, int valueDiff) {\n        long long w = (long long)valueDiff + 1;          // bucket width\n        unordered_map<long long, long long> buckets;     // bucket id -> the value in it\n        for (int i = 0; i < (int)nums.size(); i++) {\n            long long x = nums[i], b = floorDiv(x, w);\n            if (buckets.count(b)) return true;          // same bucket: close enough\n            if (buckets.count(b - 1) && x - buckets[b - 1] <= valueDiff) return true;\n            if (buckets.count(b + 1) && buckets[b + 1] - x <= valueDiff) return true;\n            buckets[b] = x;\n            if (i >= indexDiff) buckets.erase(floorDiv(nums[i - indexDiff], w));   // keep the window\n        }\n        return false;\n    }\n};",
 "contiguous-array": "class Solution {\npublic:\n    int findMaxLength(vector<int>& nums) {\n        unordered_map<int, int> first{{0, -1}};   // running score -> first index\n        int s = 0, best = 0;\n        for (int i = 0; i < (int)nums.size(); i++) {\n            s += nums[i] ? 1 : -1;\n            if (auto it = first.find(s); it != first.end()) best = max(best, i - it->second);\n            else first[s] = i;\n        }\n        return best;\n    }\n};",
 "continuous-subarray-sum": "class Solution {\npublic:\n    bool checkSubarraySum(vector<int>& nums, int k) {\n        unordered_map<int, int> first{{0, -1}};            // first index of each remainder\n        int run = 0;\n        for (int i = 0; i < (int)nums.size(); i++) {\n            run = (run + nums[i]) % k;\n            auto it = first.find(run);\n            if (it != first.end()) {\n                if (i - it->second >= 2) return true;\n            } else first[run] = i;\n        }\n        return false;\n    }\n};",
 "continuous-subarrays": "class Solution {\npublic:\n    long long continuousSubarrays(vector<int>& nums) {\n        deque<int> mx, mn;   // indices, values decreasing / increasing\n        int L = 0;\n        long long ans = 0;\n        for (int R = 0; R < (int)nums.size(); R++) {\n            int x = nums[R];\n            while (!mx.empty() && nums[mx.back()] <= x) mx.pop_back();\n            while (!mn.empty() && nums[mn.back()] >= x) mn.pop_back();\n            mx.push_back(R); mn.push_back(R);\n            while (nums[mx.front()] - nums[mn.front()] > 2) {   // shrink until max - min <= 2\n                L++;\n                if (mx.front() < L) mx.pop_front();\n                if (mn.front() < L) mn.pop_front();\n            }\n            ans += R - L + 1;   // every subarray ending at R that starts in [L, R]\n        }\n        return ans;\n    }\n};",
 "convert-bst-to-greater-tree": "class Solution {\n    int total = 0;\n    void go(TreeNode* node) {                                // reverse inorder: largest first\n        if (!node) return;\n        go(node->right);\n        total += node->val;\n        node->val = total;\n        go(node->left);\n    }\npublic:\n    TreeNode* convertBST(TreeNode* root) {\n        go(root);\n        return root;\n    }\n};",
 "convert-sorted-array-to-binary-search-tree": "class Solution {\n    TreeNode* go(const vector<int>& nums, int lo, int hi) {\n        if (lo > hi) return nullptr;\n        int mid = (lo + hi) / 2;                             // middle value as root keeps it balanced\n        TreeNode* node = new TreeNode(nums[mid]);\n        node->left = go(nums, lo, mid - 1);\n        node->right = go(nums, mid + 1, hi);\n        return node;\n    }\npublic:\n    TreeNode* sortedArrayToBST(vector<int>& nums) {\n        return go(nums, 0, (int)nums.size() - 1);\n    }\n};",
 "convert-sorted-list-to-binary-search-tree": "class Solution {\npublic:\n    TreeNode* sortedListToBST(ListNode* head) {\n        vector<int> vals;\n        for (; head; head = head->next) vals.push_back(head->val);\n        function<TreeNode*(int, int)> build = [&](int lo, int hi) -> TreeNode* {\n            if (lo > hi) return nullptr;\n            int mid = (lo + hi) / 2;                       // middle value as root keeps it balanced\n            TreeNode* node = new TreeNode(vals[mid]);\n            node->left = build(lo, mid - 1);\n            node->right = build(mid + 1, hi);\n            return node;\n        };\n        return build(0, (int)vals.size() - 1);\n    }\n};",
 "copy-list-with-random-pointer": "class Node {\npublic:\n    int val;\n    Node* next;\n    Node* random;\n    Node(int _val) { val = _val; next = NULL; random = NULL; }\n};\n\nclass Solution {\npublic:\n    Node* copyRandomList(Node* head) {\n        unordered_map<Node*, Node*> copy = {{nullptr, nullptr}};   // original to copy\n        for (Node* cur = head; cur; cur = cur->next) copy[cur] = new Node(cur->val);\n        for (Node* cur = head; cur; cur = cur->next) {   // second pass: every copy now exists\n            copy[cur]->next = copy[cur->next];\n            copy[cur]->random = copy[cur->random];\n        }\n        return copy[head];\n    }\n};",
 "corporate-flight-bookings": "class Solution {\npublic:\n    vector<int> corpFlightBookings(vector<vector<int>>& bookings, int n) {\n        vector<int> diff(n + 1, 0);\n        for (auto& b : bookings) {\n            diff[b[0] - 1] += b[2];\n            diff[b[1]] -= b[2];\n        }\n        vector<int> out(n);\n        partial_sum(diff.begin(), diff.begin() + n, out.begin());   // running total\n        return out;\n    }\n};",
 "count-all-possible-routes": "class Solution {\npublic:\n    int countRoutes(vector<int>& locations, int start, int finish, int fuel) {\n        const int MOD = 1e9 + 7;\n        int n = locations.size();\n        vector<vector<int>> memo(n, vector<int>(fuel + 1, -1));\n        // routes from city to finish with f fuel left\n        function<int(int, int)> ways = [&](int city, int f) {\n            int& res = memo[city][f];\n            if (res >= 0) return res;\n            long long total = city == finish;   // stopping here counts as a route\n            for (int nxt = 0; nxt < n; nxt++) {\n                int cost = abs(locations[nxt] - locations[city]);\n                if (nxt != city && cost <= f) total += ways(nxt, f - cost);\n            }\n            return res = total % MOD;\n        };\n        return ways(start, fuel);\n    }\n};",
 "count-and-say": "class Solution {\npublic:\n    string countAndSay(int n) {\n        string s = \"1\";\n        for (int step = 1; step < n; step++) {\n            string out;\n            for (size_t i = 0; i < s.size(); ) {\n                size_t j = i;\n                while (j < s.size() && s[j] == s[i]) j++;  // a run of equal digits\n                out += to_string(j - i) + s[i];\n                i = j;\n            }\n            s = out;\n        }\n        return s;\n    }\n};",
 "count-complete-tree-nodes": "class Solution {\npublic:\n    int countNodes(TreeNode* root) {\n        if (!root) return 0;\n        int lh = 0, rh = 0;\n        for (TreeNode* l = root; l; l = l->left) lh++;\n        for (TreeNode* r = root; r; r = r->right) rh++;\n        if (lh == rh) return (1 << lh) - 1;                // perfect tree: no need to look inside\n        return 1 + countNodes(root->left) + countNodes(root->right);\n    }\n};",
 "count-good-numbers": "class Solution {\n    static constexpr long long MOD = 1'000'000'007;\n    long long power(long long b, long long e) {              // fast power mod MOD\n        long long r = 1;\n        for (b %= MOD; e; e >>= 1, b = b * b % MOD)\n            if (e & 1) r = r * b % MOD;\n        return r;\n    }\npublic:\n    int countGoodNumbers(long long n) {\n        // 5 even digits for each even index, 4 primes for each odd index\n        return (int)(power(5, (n + 1) / 2) * power(4, n / 2) % MOD);\n    }\n};",
 "count-nodes-equal-to-average-of-subtree": "class Solution {\n    int ans = 0;\n    pair<int, int> go(TreeNode* node) {   // (sum, count) of the subtree\n        if (!node) return {0, 0};\n        auto [ls, lc] = go(node->left);\n        auto [rs, rc] = go(node->right);\n        int s = ls + rs + node->val, c = lc + rc + 1;\n        if (s / c == node->val) ans++;\n        return {s, c};\n    }\npublic:\n    int averageOfSubtree(TreeNode* root) {\n        go(root);\n        return ans;\n    }\n};",
 "count-number-of-bad-pairs": "class Solution {\npublic:\n    long long countBadPairs(vector<int>& nums) {\n        unordered_map<int, long long> seen;   // x - i equal means a good pair\n        long long good = 0;\n        for (int i = 0; i < (int)nums.size(); i++) good += seen[nums[i] - i]++;\n        long long n = nums.size();\n        return n * (n - 1) / 2 - good;\n    }\n};",
 "count-number-of-nice-subarrays": "class Solution {\npublic:\n    int numberOfSubarrays(vector<int>& nums, int k) {\n        unordered_map<int, int> seen{{0, 1}};   // count of odd numbers so far -> how often\n        int s = 0, ans = 0;\n        for (int x : nums) {\n            s += x & 1;\n            if (auto it = seen.find(s - k); it != seen.end()) ans += it->second;\n            seen[s]++;\n        }\n        return ans;\n    }\n};",
 "count-numbers-with-unique-digits": "class Solution {\npublic:\n    int countNumbersWithUniqueDigits(int n) {\n        int total = 1, ways = 9;\n        for (int L = 1; L <= n; L++) {\n            total += ways;\n            ways *= 10 - L;\n        }\n        return total;\n    }\n};",
 "count-of-range-sum": "class Solution {\n    vector<long long> pre;\n    int lower, upper;\n\n    // counts pairs i < j in pre[lo, hi) with lower <= pre[j] - pre[i] <= upper, then sorts the range\n    int sortCount(int lo, int hi) {\n        if (hi - lo <= 1) return 0;\n        int mid = (lo + hi) / 2;\n        int cnt = sortCount(lo, mid) + sortCount(mid, hi);\n        int a = mid, b = mid;\n        for (int i = lo; i < mid; i++) {   // both halves sorted: a and b only move forward\n            while (a < hi && pre[a] - pre[i] < lower) a++;\n            while (b < hi && pre[b] - pre[i] <= upper) b++;\n            cnt += b - a;\n        }\n        inplace_merge(pre.begin() + lo, pre.begin() + mid, pre.begin() + hi);\n        return cnt;\n    }\n\npublic:\n    int countRangeSum(vector<int>& nums, int lower, int upper) {\n        this->lower = lower;\n        this->upper = upper;\n        pre = {0};\n        for (int x : nums) pre.push_back(pre.back() + x);\n        return sortCount(0, pre.size());\n    }\n};",
 "count-of-smaller-numbers-after-self": "class Solution {\npublic:\n    vector<int> countSmaller(vector<int>& nums) {\n        vector<int> vals = nums;   // compress values to ranks 1..m\n        sort(vals.begin(), vals.end());\n        vals.erase(unique(vals.begin(), vals.end()), vals.end());\n        vector<int> bit(vals.size() + 1, 0);\n        vector<int> out;\n        for (int i = nums.size() - 1; i >= 0; i--) {\n            int rank = lower_bound(vals.begin(), vals.end(), nums[i]) - vals.begin() + 1;\n            int s = 0;\n            for (int r = rank - 1; r > 0; r -= r & -r) s += bit[r];   // how many smaller seen so far\n            out.push_back(s);\n            for (int r = rank; r < (int)bit.size(); r += r & -r) bit[r]++;\n        }\n        reverse(out.begin(), out.end());\n        return out;\n    }\n};",
 "count-pairs-with-xor-in-a-range": "class Solution {\n    static constexpr int B = 15;\n    vector<array<int, 3>> trie = {{0, 0, 0}};           // children for bit 0 and 1, then how many numbers pass\n\n    void insert(int x) {\n        int cur = 0;\n        for (int b = B - 1; b >= 0; b--) {\n            int bit = (x >> b) & 1;\n            if (!trie[cur][bit]) { trie.push_back({0, 0, 0}); trie[cur][bit] = trie.size() - 1; }\n            cur = trie[cur][bit];\n            trie[cur][2]++;\n        }\n    }\n\n    int less(int x, int limit) {                         // numbers y in the trie with x ^ y < limit\n        int cur = 0, total = 0;\n        for (int b = B - 1; b >= 0; b--) {\n            int xb = (x >> b) & 1, lb = (limit >> b) & 1;\n            if (lb) {\n                int same = trie[cur][xb];                // this bit of x ^ y is 0 < 1: all of them count\n                if (same) total += trie[same][2];\n                cur = trie[cur][1 - xb];\n            } else {\n                cur = trie[cur][xb];\n            }\n            if (!cur) break;\n        }\n        return total;\n    }\n\npublic:\n    int countPairs(vector<int>& nums, int low, int high) {\n        int ans = 0;\n        for (int x : nums) {\n            ans += less(x, high + 1) - less(x, low);     // pairs with an earlier number\n            insert(x);\n        }\n        return ans;\n    }\n};",
 "count-primes": "class Solution {\npublic:\n    int countPrimes(int n) {\n        if (n < 3) return 0;\n        vector<bool> isP(n, true);\n        isP[0] = isP[1] = false;\n        for (long long p = 2; p * p < n; p++)\n            if (isP[p])\n                for (long long m = p * p; m < n; m += p) isP[m] = false;   // smaller multiples already crossed\n        return (int)count(isP.begin(), isP.end(), true);\n    }\n};",
 "count-servers-that-communicate": "class Solution {\npublic:\n    int countServers(vector<vector<int>>& grid) {\n        int m = grid.size(), n = grid[0].size();\n        vector<int> rows(m, 0), cols(n, 0);\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++) { rows[i] += grid[i][j]; cols[j] += grid[i][j]; }\n        int ans = 0;\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++)\n                if (grid[i][j] && (rows[i] > 1 || cols[j] > 1)) ans++;   // shares a row or column\n        return ans;\n    }\n};",
 "count-sorted-vowel-strings": "class Solution {\npublic:\n    int countVowelStrings(int n) {\n        int dp[5] = {1, 1, 1, 1, 1};   // dp[v]: strings that start with vowel v\n        for (int k = 0; k < n - 1; k++)\n            for (int v = 3; v >= 0; v--) dp[v] += dp[v + 1];\n        return accumulate(dp, dp + 5, 0);\n    }\n};",
 "count-special-integers": "class Solution {\n    static long long perm(int m, int r) {     // ways to fill r positions from m unused digits\n        long long out = 1;\n        for (int t = 0; t < r; t++) out *= m - t;\n        return out;\n    }\npublic:\n    int countSpecialNumbers(int n) {\n        string s = to_string(n);\n        int L = s.size();\n        long long total = 0;\n        for (int m = 1; m < L; m++) total += 9 * perm(9, m - 1);\n        bool used[10] = {};\n        for (int i = 0; i < L; i++) {\n            int d = s[i] - '0';\n            for (int x = i == 0 ? 1 : 0; x < d; x++)\n                if (!used[x]) total += perm(9 - i, L - i - 1);\n            if (used[d]) return total;\n            used[d] = true;\n        }\n        return total + 1;\n    }\n};",
 "count-square-submatrices-with-all-ones": "class Solution {\npublic:\n    int countSquares(vector<vector<int>>& matrix) {\n        int R = matrix.size(), C = matrix[0].size(), total = 0;\n        vector<vector<int>> dp(R + 1, vector<int>(C + 1, 0));   // dp: largest square ending here\n        for (int i = 0; i < R; i++)\n            for (int j = 0; j < C; j++)\n                if (matrix[i][j]) {\n                    dp[i + 1][j + 1] = 1 + min({dp[i][j + 1], dp[i + 1][j], dp[i][j]});\n                    total += dp[i + 1][j + 1];\n                }\n        return total;\n    }\n};",
 "count-subarrays-where-max-element-appears-at-least-k-times": "class Solution {\npublic:\n    long long countSubarrays(vector<int>& nums, int k) {\n        int mx = *max_element(nums.begin(), nums.end());\n        long long ans = 0;\n        int left = 0, cnt = 0;\n        for (int x : nums) {\n            if (x == mx) cnt++;\n            while (cnt >= k) {            // shrink until the window has fewer than k\n                if (nums[left] == mx) cnt--;\n                left++;\n            }\n            ans += left;                  // starts 0..left-1 all reach k copies\n        }\n        return ans;\n    }\n};",
 "count-subarrays-with-fixed-bounds": "class Solution {\npublic:\n    long long countSubarrays(vector<int>& nums, int minK, int maxK) {\n        int bad = -1, lo = -1, hi = -1;   // last index out of range, last minK, last maxK\n        long long ans = 0;\n        for (int i = 0; i < (int)nums.size(); i++) {\n            int x = nums[i];\n            if (x < minK || x > maxK) bad = i;\n            if (x == minK) lo = i;\n            if (x == maxK) hi = i;\n            ans += max(0, min(lo, hi) - bad);   // valid starts for subarrays ending at i\n        }\n        return ans;\n    }\n};",
 "count-submatrices-with-all-ones": "class Solution {\npublic:\n    int numSubmat(vector<vector<int>>& mat) {\n        int n = mat[0].size(), ans = 0;\n        vector<int> h(n, 0);   // run of ones ending at this row, per column\n        for (auto& row : mat) {\n            for (int j = 0; j < n; j++) h[j] = row[j] ? h[j] + 1 : 0;\n            for (int j = 0; j < n; j++) {\n                int low = h[j];\n                for (int k = j; k >= 0; k--) {   // rectangles with bottom-right corner at j\n                    low = min(low, h[k]);\n                    if (!low) break;\n                    ans += low;\n                }\n            }\n        }\n        return ans;\n    }\n};",
 "count-the-number-of-complete-components": "class Solution {\npublic:\n    int countCompleteComponents(int n, vector<vector<int>>& edges) {\n        vector<vector<int>> g(n);\n        for (auto& e : edges) {\n            g[e[0]].push_back(e[1]);\n            g[e[1]].push_back(e[0]);\n        }\n        vector<bool> seen(n, false);\n        int ans = 0;\n        for (int s = 0; s < n; s++) {\n            if (seen[s]) continue;\n            seen[s] = true;\n            vector<int> comp, stack{s};\n            while (!stack.empty()) {\n                int u = stack.back();\n                stack.pop_back();\n                comp.push_back(u);\n                for (int v : g[u])\n                    if (!seen[v]) {\n                        seen[v] = true;\n                        stack.push_back(v);\n                    }\n            }\n            // complete: every node links to all the others\n            if (all_of(comp.begin(), comp.end(), [&](int u) { return g[u].size() == comp.size() - 1; })) ans++;\n        }\n        return ans;\n    }\n};",
 "count-the-number-of-fair-pairs": "class Solution {\npublic:\n    long long countFairPairs(vector<int>& nums, int lower, int upper) {\n        sort(nums.begin(), nums.end());\n        // pairs with sum <= x, by two pointers\n        auto count = [&](long long x) {\n            long long c = 0;\n            int L = 0, R = nums.size() - 1;\n            while (L < R) {\n                if ((long long)nums[L] + nums[R] <= x) {\n                    c += R - L;      // nums[L] pairs with everything up to R\n                    L++;\n                } else R--;\n            }\n            return c;\n        };\n        return count(upper) - count((long long)lower - 1);\n    }\n};",
 "count-the-number-of-good-subarrays": "class Solution {\npublic:\n    long long countGood(vector<int>& nums, int k) {\n        unordered_map<int, int> cnt;\n        long long pairs = 0, ans = 0;\n        int L = 0;\n        for (int x : nums) {\n            pairs += cnt[x]++;            // x pairs with every earlier copy\n            while (pairs >= k) {          // shrink while the window is still good\n                pairs -= --cnt[nums[L]];\n                L++;\n            }\n            ans += L;                     // starts 0..L-1 all give a good subarray\n        }\n        return ans;\n    }\n};",
 "count-triplets-that-can-form-two-arrays-of-equal-xor": "class Solution {\npublic:\n    int countTriplets(vector<int>& arr) {\n        int n = arr.size();\n        vector<int> X(n + 1, 0);   // X[i] = xor of arr[0..i-1]\n        for (int i = 0; i < n; i++) X[i + 1] = X[i] ^ arr[i];\n        int ans = 0;\n        for (int i = 0; i < n; i++)\n            for (int k = i + 1; k < n; k++)\n                if (X[i] == X[k + 1]) ans += k - i;   // any j in (i, k] works\n        return ans;\n    }\n};",
 "count-unguarded-cells-in-the-grid": "class Solution {\npublic:\n    int countUnguarded(int m, int n, vector<vector<int>>& guards, vector<vector<int>>& walls) {\n        vector<vector<int>> g(m, vector<int>(n, 0));   // 0 free, 1 guarded, 2 guard or wall\n        for (auto& p : guards) g[p[0]][p[1]] = 2;\n        for (auto& p : walls) g[p[0]][p[1]] = 2;\n        const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        for (auto& p : guards)\n            for (int d = 0; d < 4; d++)   // look along each direction until blocked\n                for (int y = p[0] + dr[d], x = p[1] + dc[d]; y >= 0 && y < m && x >= 0 && x < n && g[y][x] != 2; y += dr[d], x += dc[d])\n                    g[y][x] = 1;\n        int free = 0;\n        for (auto& row : g) free += count(row.begin(), row.end(), 0);\n        return free;\n    }\n};",
 "count-unreachable-pairs-of-nodes-in-an-undirected-graph": "class Solution {\n    vector<int> parent;\n    int find(int x) {\n        while (parent[x] != x) {\n            parent[x] = parent[parent[x]];\n            x = parent[x];\n        }\n        return x;\n    }\npublic:\n    long long countPairs(int n, vector<vector<int>>& edges) {\n        parent.resize(n);\n        iota(parent.begin(), parent.end(), 0);\n        for (auto& e : edges) parent[find(e[0])] = find(e[1]);\n        unordered_map<int, long long> size;\n        for (int x = 0; x < n; x++) size[find(x)]++;\n        long long ans = 0, seen = 0;\n        for (auto& [root, s] : size) {   // pairs with a node in an earlier component\n            ans += s * seen;\n            seen += s;\n        }\n        return ans;\n    }\n};",
 "count-vowel-strings-in-ranges": "class Solution {\npublic:\n    vector<int> vowelStrings(vector<string>& words, vector<vector<int>>& queries) {\n        auto vowel = [](char c) { return string(\"aeiou\").find(c) != string::npos; };\n        vector<int> pre{0};          // pre[i] = good words among the first i\n        for (auto& w : words) pre.push_back(pre.back() + (vowel(w.front()) && vowel(w.back())));\n        vector<int> out;\n        for (auto& q : queries) out.push_back(pre[q[1] + 1] - pre[q[0]]);\n        return out;\n    }\n};",
 "counting-bits": "class Solution {\npublic:\n    vector<int> countBits(int n) {\n        vector<int> ans(n + 1, 0);\n        for (int i = 1; i <= n; i++) ans[i] = ans[i >> 1] + (i & 1);   // drop the last bit, add it back\n        return ans;\n    }\n};",
 "couples-holding-hands": "class Solution {\npublic:\n    int minSwapsCouples(vector<int>& row) {\n        vector<int> pos(row.size());\n        for (int i = 0; i < (int)row.size(); i++) pos[row[i]] = i;\n        int swaps = 0;\n        for (int i = 0; i < (int)row.size(); i += 2) {\n            int partner = row[i] ^ 1;   // couples are (0,1), (2,3), ...\n            if (row[i + 1] != partner) {\n                int j = pos[partner];   // bring the partner next to row[i]\n                swap(row[i + 1], row[j]);\n                pos[row[j]] = j;\n                pos[partner] = i + 1;\n                swaps++;\n            }\n        }\n        return swaps;\n    }\n};",
 "course-schedule": "class Solution {\npublic:\n    bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {\n        vector<vector<int>> adj(numCourses);\n        vector<int> indeg(numCourses, 0);\n        for (auto& p : prerequisites) { adj[p[1]].push_back(p[0]); indeg[p[0]]++; }\n        queue<int> q;\n        for (int i = 0; i < numCourses; i++) if (indeg[i] == 0) q.push(i);\n        int taken = 0;\n        while (!q.empty()) {\n            int u = q.front(); q.pop();\n            taken++;\n            for (int v : adj[u]) if (--indeg[v] == 0) q.push(v);   // last prerequisite done\n        }\n        return taken == numCourses;\n    }\n};",
 "course-schedule-ii": "class Solution {\npublic:\n    vector<int> findOrder(int numCourses, vector<vector<int>>& prerequisites) {\n        vector<vector<int>> adj(numCourses);\n        vector<int> indeg(numCourses, 0);\n        for (auto& p : prerequisites) { adj[p[1]].push_back(p[0]); indeg[p[0]]++; }\n        queue<int> q;\n        for (int i = 0; i < numCourses; i++) if (indeg[i] == 0) q.push(i);\n        vector<int> order;\n        while (!q.empty()) {\n            int u = q.front(); q.pop();\n            order.push_back(u);\n            for (int v : adj[u]) if (--indeg[v] == 0) q.push(v);\n        }\n        if ((int)order.size() != numCourses) return {};  // a cycle left some courses unreachable\n        return order;\n    }\n};",
 "course-schedule-iii": "class Solution {\npublic:\n    int scheduleCourse(vector<vector<int>>& courses) {\n        sort(courses.begin(), courses.end(), [](auto& a, auto& b) { return a[1] < b[1]; });   // earliest deadline first\n        priority_queue<int> heap;   // durations taken, longest on top\n        int t = 0;\n        for (auto& c : courses) {\n            t += c[0];\n            heap.push(c[0]);\n            if (t > c[1]) {   // over the deadline: drop the longest course so far\n                t -= heap.top();\n                heap.pop();\n            }\n        }\n        return heap.size();\n    }\n};",
 "cousins-in-binary-tree-ii": "class Solution {\npublic:\n    TreeNode* replaceValueInTree(TreeNode* root) {\n        root->val = 0;\n        vector<TreeNode*> level{root};\n        while (!level.empty()) {\n            vector<TreeNode*> next;\n            long long total = 0;                        // sum of the next level\n            for (auto* n : level)\n                for (auto* c : {n->left, n->right})\n                    if (c) { next.push_back(c); total += c->val; }\n            for (auto* n : level) {\n                int kids = (n->left ? n->left->val : 0) + (n->right ? n->right->val : 0);\n                for (auto* c : {n->left, n->right})\n                    if (c) c->val = total - kids;       // everyone on the level but the siblings\n            }\n            level = next;\n        }\n        return root;\n    }\n};",
 "cracking-the-safe": "class Solution {\npublic:\n    string crackSafe(int n, int k) {\n        string start(n - 1, '0'), out;\n        unordered_map<string, int> left;                     // node -> digits not yet typed from it\n        vector<pair<string, char>> st = {{start, 0}};\n        while (!st.empty()) {\n            string node = st.back().first;\n            if (!left.count(node)) left[node] = k;\n            if (left[node]) {\n                char d = '0' + --left[node];\n                st.push_back({(node + d).substr(1), d});\n            } else {\n                if (st.back().second) out += st.back().second;\n                st.pop_back();\n            }\n        }\n        reverse(out.begin(), out.end());\n        return start + out;\n    }\n};",
 "create-binary-tree-from-descriptions": "class Solution {\npublic:\n    TreeNode* createBinaryTree(vector<vector<int>>& descriptions) {\n        unordered_map<int, TreeNode*> nodes;\n        unordered_set<int> kids;\n        auto get = [&](int v) {\n            auto& node = nodes[v];\n            if (!node) node = new TreeNode(v);\n            return node;\n        };\n        for (auto& d : descriptions) {\n            TreeNode *a = get(d[0]), *b = get(d[1]);\n            (d[2] ? a->left : a->right) = b;\n            kids.insert(d[1]);\n        }\n        for (auto& d : descriptions)\n            if (!kids.count(d[0])) return nodes[d[0]];   // the root is nobody's child\n        return nullptr;\n    }\n};",
 "critical-connections-in-a-network": "class Solution {\n    vector<vector<int>> g, out;\n    vector<int> tin, low;\n    int t = 0;\n\n    void dfs(int u, int parent) {\n        tin[u] = low[u] = t++;\n        for (int v : g[u]) {\n            if (v == parent) continue;\n            if (tin[v] == -1) {\n                dfs(v, u);\n                low[u] = min(low[u], low[v]);\n                if (low[v] > tin[u]) out.push_back({u, v});   // v cannot reach u or above without this edge\n            } else {\n                low[u] = min(low[u], tin[v]);\n            }\n        }\n    }\n\npublic:\n    vector<vector<int>> criticalConnections(int n, vector<vector<int>>& connections) {\n        g.assign(n, {});\n        for (auto& c : connections) {\n            g[c[0]].push_back(c[1]);\n            g[c[1]].push_back(c[0]);\n        }\n        tin.assign(n, -1);\n        low.assign(n, 0);\n        dfs(0, -1);\n        return out;\n    }\n};",
 "custom-sort-string": "class Solution {\npublic:\n    string customSortString(string order, string s) {\n        int cnt[26] = {};\n        for (char c : s) cnt[c - 'a']++;\n        string out;\n        for (char c : order) { out.append(cnt[c - 'a'], c); cnt[c - 'a'] = 0; }   // ordered letters first\n        for (int i = 0; i < 26; i++) out.append(cnt[i], 'a' + i);                // then the rest\n        return out;\n    }\n};",
 "daily-temperatures": "class Solution {\npublic:\n    vector<int> dailyTemperatures(vector<int>& temperatures) {\n        vector<int> ans(temperatures.size(), 0);\n        vector<int> stack;                               // days still waiting for a warmer one\n        for (int i = 0; i < (int)temperatures.size(); i++) {\n            while (!stack.empty() && temperatures[stack.back()] < temperatures[i]) {\n                ans[stack.back()] = i - stack.back();\n                stack.pop_back();\n            }\n            stack.push_back(i);\n        }\n        return ans;\n    }\n};",
 "decode-string": "class Solution {\npublic:\n    string decodeString(string s) {\n        vector<pair<string, int>> stack;                 // (text before the bracket, its repeat count)\n        string cur;\n        int num = 0;\n        for (char ch : s) {\n            if (isdigit(ch)) num = num * 10 + (ch - '0');\n            else if (ch == '[') { stack.push_back({cur, num}); cur = \"\"; num = 0; }\n            else if (ch == ']') {\n                auto [prev, k] = stack.back(); stack.pop_back();\n                string rep;\n                while (k--) rep += cur;\n                cur = prev + rep;\n            }\n            else cur += ch;\n        }\n        return cur;\n    }\n};",
 "decode-ways": "class Solution {\npublic:\n    int numDecodings(string s) {\n        int prev = 1, cur = s[0] != '0';                     // ways up to i-2 and i-1\n        for (size_t i = 1; i < s.size(); i++) {\n            int nxt = 0;\n            if (s[i] != '0') nxt += cur;                     // one-digit code\n            int two = (s[i - 1] - '0') * 10 + (s[i] - '0');\n            if (10 <= two && two <= 26) nxt += prev;         // two-digit code\n            prev = cur;\n            cur = nxt;\n        }\n        return cur;\n    }\n};",
 "decode-xored-permutation": "class Solution {\npublic:\n    vector<int> decode(vector<int>& encoded) {\n        int n = (int)encoded.size() + 1, total = 0, rest = 0;\n        for (int i = 1; i <= n; i++) total ^= i;             // XOR of the whole permutation\n        for (int i = 1; i < n - 1; i += 2) rest ^= encoded[i];   // XOR of every element but the first\n        vector<int> perm{total ^ rest};\n        for (int e : encoded) perm.push_back(perm.back() ^ e);\n        return perm;\n    }\n};",
 "decoded-string-at-index": "class Solution {\npublic:\n    string decodeAtIndex(string s, int k) {\n        long long size = 0;\n        int i = 0;\n        // decoded length, stopping once it reaches k (the full length can pass 2^63)\n        for (; i < (int)s.size(); i++) {\n            size = isdigit(s[i]) ? size * (s[i] - '0') : size + 1;\n            if (size >= k) break;\n        }\n        for (; i >= 0; i--) {                 // walk back, folding k into the shorter string\n            char ch = s[i];\n            k %= size;\n            if (k == 0 && isalpha(ch)) return string(1, ch);\n            size = isdigit(ch) ? size / (ch - '0') : size - 1;\n        }\n        return \"\";\n    }\n};",
 "deepest-leaves-sum": "class Solution {\npublic:\n    int deepestLeavesSum(TreeNode* root) {\n        vector<TreeNode*> level{root};\n        while (true) {\n            vector<TreeNode*> next;\n            for (TreeNode* n : level)\n                for (TreeNode* c : {n->left, n->right})\n                    if (c) next.push_back(c);\n            if (next.empty()) {                            // this was the deepest level\n                int sum = 0;\n                for (TreeNode* n : level) sum += n->val;\n                return sum;\n            }\n            level = next;\n        }\n    }\n};",
 "delete-leaves-with-a-given-value": "class Solution {\npublic:\n    TreeNode* removeLeafNodes(TreeNode* root, int target) {\n        if (!root) return nullptr;\n        root->left = removeLeafNodes(root->left, target);      // children first, so new leaves get checked\n        root->right = removeLeafNodes(root->right, target);\n        if (!root->left && !root->right && root->val == target) return nullptr;\n        return root;\n    }\n};",
 "delete-node-in-a-bst": "class Solution {\npublic:\n    TreeNode* deleteNode(TreeNode* root, int key) {\n        if (!root) return nullptr;\n        if (key < root->val) root->left = deleteNode(root->left, key);\n        else if (key > root->val) root->right = deleteNode(root->right, key);\n        else {\n            if (!root->left) return root->right;             // zero or one child: lift the other side\n            if (!root->right) return root->left;\n            TreeNode* s = root->right;                       // two children: take the inorder successor\n            while (s->left) s = s->left;\n            root->val = s->val;\n            root->right = deleteNode(root->right, s->val);\n        }\n        return root;\n    }\n};",
 "delete-nodes-and-return-forest": "class Solution {\n    unordered_set<int> kill;\n    vector<TreeNode*> out;\n\n    TreeNode* dfs(TreeNode* node, bool parentGone) {\n        if (!node) return nullptr;\n        bool gone = kill.count(node->val);\n        if (parentGone && !gone) out.push_back(node);   // a kept node under a deleted one starts a tree\n        node->left = dfs(node->left, gone);\n        node->right = dfs(node->right, gone);\n        return gone ? nullptr : node;\n    }\n\npublic:\n    vector<TreeNode*> delNodes(TreeNode* root, vector<int>& to_delete) {\n        kill = unordered_set<int>(to_delete.begin(), to_delete.end());\n        dfs(root, true);\n        return out;\n    }\n};",
 "delete-operation-for-two-strings": "class Solution {\npublic:\n    int minDistance(string word1, string word2) {\n        int m = word1.size(), n = word2.size();\n        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));   // LCS lengths\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++)\n                dp[i + 1][j + 1] = word1[i] == word2[j] ? dp[i][j] + 1 : max(dp[i][j + 1], dp[i + 1][j]);\n        return m + n - 2 * dp[m][n];                         // delete everything outside the LCS\n    }\n};",
 "delete-the-middle-node-of-a-linked-list": "class Solution {\npublic:\n    ListNode* deleteMiddle(ListNode* head) {\n        if (!head->next) return nullptr;\n        ListNode *slow = head, *fast = head->next->next;   // fast starts ahead so slow stops before the middle\n        while (fast && fast->next) {\n            slow = slow->next;\n            fast = fast->next->next;\n        }\n        slow->next = slow->next->next;\n        return head;\n    }\n};",
 "design-a-food-rating-system": "class FoodRatings {\n    unordered_map<string, pair<string, int>> info;   // food -> (cuisine, current rating)\n    // per cuisine: (-rating, food), so the top is the best rating, then the smallest name\n    unordered_map<string, priority_queue<pair<int, string>, vector<pair<int, string>>, greater<>>> heaps;\npublic:\n    FoodRatings(vector<string>& foods, vector<string>& cuisines, vector<int>& ratings) {\n        for (size_t i = 0; i < foods.size(); i++) {\n            info[foods[i]] = {cuisines[i], ratings[i]};\n            heaps[cuisines[i]].push({-ratings[i], foods[i]});\n        }\n    }\n\n    void changeRating(string food, int newRating) {\n        auto& [c, r] = info[food];\n        r = newRating;\n        heaps[c].push({-newRating, food});   // the old entry stays and goes stale\n    }\n\n    string highestRated(string cuisine) {\n        auto& h = heaps[cuisine];\n        while (-h.top().first != info[h.top().second].second) h.pop();   // drop stale entries\n        return h.top().second;\n    }\n};",
 "design-a-stack-with-increment-operation": "class CustomStack {\n    int n;\n    vector<int> st, inc;                               // inc[i]: amount still to add to st[0..i]\npublic:\n    CustomStack(int maxSize) : n(maxSize) {}\n\n    void push(int x) {\n        if ((int)st.size() < n) { st.push_back(x); inc.push_back(0); }\n    }\n\n    int pop() {\n        if (st.empty()) return -1;\n        int add = inc.back(); inc.pop_back();\n        if (!inc.empty()) inc.back() += add;           // pass the pending add down one place\n        int x = st.back(); st.pop_back();\n        return x + add;\n    }\n\n    void increment(int k, int val) {\n        if (!st.empty()) inc[min(k, (int)st.size()) - 1] += val;   // lazy: mark only the top affected slot\n    }\n};",
 "design-add-and-search-words-data-structure": "class WordDictionary {\n    struct TrieNode {\n        TrieNode* kids[26] = {};\n        bool end = false;\n    };\n    TrieNode* root = new TrieNode();\n\n    bool dfs(TrieNode* node, const string& word, int i) {\n        if (i == (int)word.size()) return node->end;\n        if (word[i] == '.') {                            // a dot tries every child\n            for (TrieNode* kid : node->kids)\n                if (kid && dfs(kid, word, i + 1)) return true;\n            return false;\n        }\n        TrieNode* kid = node->kids[word[i] - 'a'];\n        return kid && dfs(kid, word, i + 1);\n    }\n\npublic:\n    WordDictionary() {}\n\n    void addWord(string word) {\n        TrieNode* node = root;\n        for (char ch : word) {\n            if (!node->kids[ch - 'a']) node->kids[ch - 'a'] = new TrieNode();\n            node = node->kids[ch - 'a'];\n        }\n        node->end = true;\n    }\n\n    bool search(string word) { return dfs(root, word, 0); }\n};",
 "design-browser-history": "class BrowserHistory {\n    vector<string> pages;\n    int cur = 0, end = 0;\n\npublic:\n    BrowserHistory(string homepage) : pages{homepage} {}\n\n    void visit(string url) {\n        cur++;\n        if (cur == (int)pages.size()) pages.push_back(url);\n        else pages[cur] = url;\n        end = cur;                            // forward pages are gone\n    }\n\n    string back(int steps) {\n        cur = max(0, cur - steps);\n        return pages[cur];\n    }\n\n    string forward(int steps) {\n        cur = min(end, cur + steps);\n        return pages[cur];\n    }\n};",
 "design-circular-deque": "class MyCircularDeque {\n    vector<int> a;\n    int k, head = 0, size = 0;\npublic:\n    MyCircularDeque(int k) : a(k), k(k) {}\n\n    bool insertFront(int value) {\n        if (size == k) return false;\n        head = (head - 1 + k) % k;   // step back, wrapping round\n        a[head] = value;\n        size++;\n        return true;\n    }\n\n    bool insertLast(int value) {\n        if (size == k) return false;\n        a[(head + size) % k] = value;\n        size++;\n        return true;\n    }\n\n    bool deleteFront() {\n        if (!size) return false;\n        head = (head + 1) % k;\n        size--;\n        return true;\n    }\n\n    bool deleteLast() {\n        if (!size) return false;\n        size--;\n        return true;\n    }\n\n    int getFront() { return size ? a[head] : -1; }\n    int getRear() { return size ? a[(head + size - 1) % k] : -1; }\n    bool isEmpty() { return size == 0; }\n    bool isFull() { return size == k; }\n};",
 "design-graph-with-shortest-path-calculator": "class Graph {\n    vector<vector<pair<int, int>>> g;   // node -> (neighbour, weight)\npublic:\n    Graph(int n, vector<vector<int>>& edges) : g(n) {\n        for (auto& e : edges) addEdge(e);\n    }\n\n    void addEdge(vector<int> edge) {\n        g[edge[0]].push_back({edge[1], edge[2]});\n    }\n\n    int shortestPath(int node1, int node2) {   // Dijkstra\n        vector<int> dist(g.size(), INT_MAX);\n        dist[node1] = 0;\n        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> h;\n        h.push({0, node1});\n        while (!h.empty()) {\n            auto [d, u] = h.top(); h.pop();\n            if (u == node2) return d;\n            if (d > dist[u]) continue;       // stale entry\n            for (auto [v, w] : g[u])\n                if (d + w < dist[v]) { dist[v] = d + w; h.push({d + w, v}); }\n        }\n        return -1;\n    }\n};",
 "determine-if-two-strings-are-close": "class Solution {\npublic:\n    bool closeStrings(string word1, string word2) {\n        array<int, 26> a{}, b{};\n        for (char c : word1) a[c - 'a']++;\n        for (char c : word2) b[c - 'a']++;\n        for (int i = 0; i < 26; i++)\n            if ((a[i] > 0) != (b[i] > 0)) return false;   // same set of letters\n        sort(a.begin(), a.end());\n        sort(b.begin(), b.end());\n        return a == b;                                     // same multiset of counts\n    }\n};",
 "diagonal-traverse": "class Solution {\npublic:\n    vector<int> findDiagonalOrder(vector<vector<int>>& mat) {\n        int m = mat.size(), n = mat[0].size();\n        vector<int> out;\n        for (int d = 0; d < m + n - 1; d++) {\n            vector<int> diag;                              // cells with i + j == d, top to bottom\n            for (int i = max(0, d - n + 1); i <= min(d, m - 1); i++) diag.push_back(mat[i][d - i]);\n            if (d % 2 == 0) reverse(diag.begin(), diag.end());   // even diagonals go up\n            out.insert(out.end(), diag.begin(), diag.end());\n        }\n        return out;\n    }\n};",
 "diagonal-traverse-ii": "class Solution {\npublic:\n    vector<int> findDiagonalOrder(vector<vector<int>>& nums) {\n        map<int, vector<int>> groups;   // i + j names an anti-diagonal\n        for (int i = nums.size() - 1; i >= 0; i--)   // bottom rows first, so each diagonal reads upward\n            for (int j = 0; j < (int)nums[i].size(); j++) groups[i + j].push_back(nums[i][j]);\n        vector<int> out;\n        for (auto& [d, v] : groups) out.insert(out.end(), v.begin(), v.end());\n        return out;\n    }\n};",
 "diameter-of-binary-tree": "class Solution {\n    int best = 0;\n    int height(TreeNode* node) {\n        if (!node) return 0;\n        int a = height(node->left), b = height(node->right);\n        best = max(best, a + b);                           // longest path through this node\n        return 1 + max(a, b);\n    }\npublic:\n    int diameterOfBinaryTree(TreeNode* root) {\n        height(root);\n        return best;\n    }\n};",
 "difference-between-ones-and-zeros-in-row-and-column": "class Solution {\npublic:\n    vector<vector<int>> onesMinusZeros(vector<vector<int>>& grid) {\n        int m = grid.size(), n = grid[0].size();\n        vector<int> r(m, 0), c(n, 0);   // ones in each row and column\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++) { r[i] += grid[i][j]; c[j] += grid[i][j]; }\n        vector<vector<int>> out(m, vector<int>(n));\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++) out[i][j] = 2 * r[i] + 2 * c[j] - m - n;\n        return out;\n    }\n};",
 "different-ways-to-add-parentheses": "class Solution {\n    unordered_map<string, vector<int>> memo;\npublic:\n    vector<int> diffWaysToCompute(string expression) {\n        auto it = memo.find(expression);\n        if (it != memo.end()) return it->second;\n        vector<int> out;\n        for (size_t i = 0; i < expression.size(); i++) {\n            char ch = expression[i];\n            if (ch != '+' && ch != '-' && ch != '*') continue;\n            // ch is the last operator applied: every left result with every right result\n            for (int a : diffWaysToCompute(expression.substr(0, i)))\n                for (int b : diffWaysToCompute(expression.substr(i + 1)))\n                    out.push_back(ch == '+' ? a + b : ch == '-' ? a - b : a * b);\n        }\n        if (out.empty()) out.push_back(stoi(expression));   // just a number\n        return memo[expression] = out;\n    }\n};",
 "distant-barcodes": "class Solution {\npublic:\n    vector<int> rearrangeBarcodes(vector<int>& barcodes) {\n        unordered_map<int, int> cnt;\n        for (int b : barcodes) cnt[b]++;\n        vector<pair<int, int>> byCount;   // (count, value)\n        for (auto& [v, c] : cnt) byCount.push_back({c, v});\n        sort(byCount.rbegin(), byCount.rend());   // most common first\n        vector<int> order;\n        for (auto [c, v] : byCount) order.insert(order.end(), c, v);\n        int n = barcodes.size(), half = (n + 1) / 2;\n        vector<int> out(n);\n        for (int i = 0; i < n; i++)               // first half on even slots, the rest on odd slots\n            out[i < half ? 2 * i : 2 * (i - half) + 1] = order[i];\n        return out;\n    }\n};",
 "distinct-subsequences": "class Solution {\npublic:\n    int numDistinct(string s, string t) {\n        // unsigned: middle cells can pass int range on LeetCode's tests; the answer itself fits\n        vector<unsigned long long> dp(t.size() + 1, 0);\n        dp[0] = 1;\n        for (char ch : s)\n            for (size_t i = t.size(); i > 0; i--)            // backwards so each s char is used once\n                if (t[i - 1] == ch) dp[i] += dp[i - 1];\n        return (int)dp[t.size()];\n    }\n};",
 "distribute-coins-in-binary-tree": "class Solution {\n    int moves = 0;\n    // coins this subtree sends up to its parent (negative: it needs coins)\n    int excess(TreeNode* node) {\n        if (!node) return 0;\n        int e = excess(node->left) + excess(node->right) + node->val - 1;\n        moves += abs(e);   // every extra or missing coin crosses the edge above\n        return e;\n    }\npublic:\n    int distributeCoins(TreeNode* root) {\n        excess(root);\n        return moves;\n    }\n};",
 "divide-intervals-into-minimum-number-of-groups": "class Solution {\npublic:\n    int minGroups(vector<vector<int>>& intervals) {\n        sort(intervals.begin(), intervals.end());\n        priority_queue<int, vector<int>, greater<>> ends;   // end of each group's last interval\n        for (auto& iv : intervals) {\n            if (!ends.empty() && ends.top() < iv[0]) ends.pop();   // reuse the group that ends first\n            ends.push(iv[1]);\n        }\n        return ends.size();\n    }\n};",
 "divide-two-integers": "class Solution {\npublic:\n    int divide(int dividend, int divisor) {\n        if (dividend == INT_MIN && divisor == -1) return INT_MAX;   // the only overflow\n        bool neg = (dividend < 0) != (divisor < 0);\n        long long a = llabs((long long)dividend), b = llabs((long long)divisor), q = 0;\n        while (a >= b) {\n            long long t = b, m = 1;\n            while (a >= t << 1) { t <<= 1; m <<= 1; }        // biggest doubling of b that fits\n            a -= t;\n            q += m;\n        }\n        return (int)(neg ? -q : q);\n    }\n};",
 "double-a-number-represented-as-a-linked-list": "class Solution {\npublic:\n    ListNode* doubleIt(ListNode* head) {\n        if (head->val >= 5) head = new ListNode(0, head);   // the carry needs a new first digit\n        for (ListNode* c = head; c; c = c->next) {\n            c->val = c->val * 2 % 10;\n            if (c->next && c->next->val >= 5) c->val++;       // carry in from the next digit\n        }\n        return head;\n    }\n};",
 "dungeon-game": "class Solution {\npublic:\n    int calculateMinimumHP(vector<vector<int>>& dungeon) {\n        int R = dungeon.size(), C = dungeon[0].size();\n        vector<vector<int>> dp(R + 1, vector<int>(C + 1, INT_MAX));   // health needed on entering (i, j)\n        dp[R][C - 1] = dp[R - 1][C] = 1;\n        for (int i = R - 1; i >= 0; i--)\n            for (int j = C - 1; j >= 0; j--) {\n                int need = min(dp[i + 1][j], dp[i][j + 1]) - dungeon[i][j];\n                dp[i][j] = max(1, need);\n            }\n        return dp[0][0];\n    }\n};",
 "edit-distance": "class Solution {\npublic:\n    int minDistance(string word1, string word2) {\n        int m = word1.size(), n = word2.size();\n        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));\n        for (int i = 0; i <= m; i++) dp[i][0] = i;           // delete all of word1's prefix\n        for (int j = 0; j <= n; j++) dp[0][j] = j;           // insert all of word2's prefix\n        for (int i = 1; i <= m; i++)\n            for (int j = 1; j <= n; j++)\n                if (word1[i - 1] == word2[j - 1]) dp[i][j] = dp[i - 1][j - 1];\n                else dp[i][j] = 1 + min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});\n        return dp[m][n];\n    }\n};",
 "equal-row-and-column-pairs": "class Solution {\npublic:\n    int equalPairs(vector<vector<int>>& grid) {\n        int n = grid.size();\n        map<vector<int>, int> rows;\n        for (auto& r : grid) rows[r]++;\n        int ans = 0;\n        for (int j = 0; j < n; j++) {\n            vector<int> col(n);\n            for (int i = 0; i < n; i++) col[i] = grid[i][j];\n            auto it = rows.find(col);\n            if (it != rows.end()) ans += it->second;   // every row equal to this column\n        }\n        return ans;\n    }\n};",
 "equal-sum-arrays-with-minimum-number-of-operations": "class Solution {\npublic:\n    int minOperations(vector<int>& nums1, vector<int>& nums2) {\n        int s1 = accumulate(nums1.begin(), nums1.end(), 0), s2 = accumulate(nums2.begin(), nums2.end(), 0);\n        vector<int>* a = &nums1, *b = &nums2;\n        if (s1 > s2) { swap(a, b); swap(s1, s2); }   // make a the smaller sum\n        int diff = s2 - s1;\n        if (diff == 0) return 0;\n        vector<int> gains;                           // how much one change can close the gap\n        for (int x : *a) gains.push_back(6 - x);\n        for (int x : *b) gains.push_back(x - 1);\n        sort(gains.rbegin(), gains.rend());\n        for (int ops = 0; ops < (int)gains.size(); ops++) {\n            diff -= gains[ops];\n            if (diff <= 0) return ops + 1;\n        }\n        return -1;\n    }\n};",
 "evaluate-division": "class Solution {\n    unordered_map<string, vector<pair<string, double>>> g;\n\n    double ratio(const string& x, const string& y, unordered_set<string>& seen) {\n        if (x == y) return 1.0;\n        seen.insert(x);\n        for (auto& [z, v] : g[x])\n            if (!seen.count(z)) {\n                double r = ratio(z, y, seen);\n                if (r != -1.0) return v * r;             // found a path through z\n            }\n        return -1.0;\n    }\n\npublic:\n    vector<double> calcEquation(vector<vector<string>>& equations, vector<double>& values, vector<vector<string>>& queries) {\n        for (size_t i = 0; i < equations.size(); i++) {\n            auto& a = equations[i][0]; auto& b = equations[i][1];\n            g[a].push_back({b, values[i]});\n            g[b].push_back({a, 1 / values[i]});\n        }\n        vector<double> out;\n        for (auto& q : queries) {\n            unordered_set<string> seen;\n            out.push_back(g.count(q[0]) && g.count(q[1]) ? ratio(q[0], q[1], seen) : -1.0);\n        }\n        return out;\n    }\n};",
 "evaluate-reverse-polish-notation": "class Solution {\npublic:\n    int evalRPN(vector<string>& tokens) {\n        vector<long long> stack;\n        for (auto& t : tokens) {\n            if (t == \"+\" || t == \"-\" || t == \"*\" || t == \"/\") {\n                long long b = stack.back(); stack.pop_back();\n                long long a = stack.back(); stack.pop_back();\n                if (t == \"+\") stack.push_back(a + b);\n                else if (t == \"-\") stack.push_back(a - b);\n                else if (t == \"*\") stack.push_back(a * b);\n                else stack.push_back(a / b);             // C++ division already truncates toward zero\n            } else {\n                stack.push_back(stoll(t));\n            }\n        }\n        return stack[0];\n    }\n};",
 "evaluate-the-bracket-pairs-of-a-string": "class Solution {\npublic:\n    string evaluate(string s, vector<vector<string>>& knowledge) {\n        unordered_map<string, string> k;\n        for (auto& kv : knowledge) k[kv[0]] = kv[1];\n        string out;\n        for (size_t i = 0; i < s.size();) {\n            if (s[i] == '(') {\n                size_t j = s.find(')', i);\n                auto it = k.find(s.substr(i + 1, j - i - 1));\n                out += it == k.end() ? \"?\" : it->second;\n                i = j + 1;\n            } else out += s[i++];\n        }\n        return out;\n    }\n};",
 "even-odd-tree": "class Solution {\npublic:\n    bool isEvenOddTree(TreeNode* root) {\n        queue<TreeNode*> q;\n        q.push(root);\n        for (int level = 0; !q.empty(); level++) {\n            optional<int> prev;\n            for (int k = q.size(); k > 0; k--) {\n                TreeNode* node = q.front(); q.pop();\n                int v = node->val;\n                if (level % 2 == 0) {   // even level: odd values, strictly increasing\n                    if (v % 2 == 0 || (prev && v <= *prev)) return false;\n                } else {                // odd level: even values, strictly decreasing\n                    if (v % 2 == 1 || (prev && v >= *prev)) return false;\n                }\n                prev = v;\n                if (node->left) q.push(node->left);\n                if (node->right) q.push(node->right);\n            }\n        }\n        return true;\n    }\n};",
 "excel-sheet-column-number": "class Solution {\npublic:\n    int titleToNumber(string columnTitle) {\n        long long n = 0;\n        for (char ch : columnTitle) n = n * 26 + (ch - 'A' + 1);   // base 26 with digits 1 to 26\n        return (int)n;\n    }\n};",
 "excel-sheet-column-title": "class Solution {\npublic:\n    string convertToTitle(int columnNumber) {\n        int n = columnNumber;\n        string out;\n        while (n) {\n            n--;                                             // shift 1..26 down to 0..25\n            out.push_back('A' + n % 26);\n            n /= 26;\n        }\n        reverse(out.begin(), out.end());\n        return out;\n    }\n};",
 "filling-bookcase-shelves": "class Solution {\npublic:\n    int minHeightShelves(vector<vector<int>>& books, int shelfWidth) {\n        int n = books.size();\n        vector<int> dp(n + 1, INT_MAX);   // dp[i] = least height for the first i books\n        dp[0] = 0;\n        for (int i = 1; i <= n; i++) {\n            int w = 0, h = 0;\n            for (int j = i; j > 0; j--) {     // books j..i on the last shelf\n                w += books[j - 1][0];\n                if (w > shelfWidth) break;\n                h = max(h, books[j - 1][1]);\n                dp[i] = min(dp[i], dp[j - 1] + h);\n            }\n        }\n        return dp[n];\n    }\n};",
 "find-all-anagrams-in-a-string": "class Solution {\npublic:\n    vector<int> findAnagrams(string s, string p) {\n        int k = p.size();\n        array<int, 26> need{}, win{};\n        for (char ch : p) need[ch - 'a']++;\n        vector<int> out;\n        for (int i = 0; i < (int)s.size(); i++) {\n            win[s[i] - 'a']++;\n            if (i >= k) win[s[i - k] - 'a']--;           // slide the window of length k\n            if (win == need) out.push_back(i - k + 1);\n        }\n        return out;\n    }\n};",
 "find-all-duplicates-in-an-array": "class Solution {\npublic:\n    vector<int> findDuplicates(vector<int>& nums) {\n        vector<int> out;\n        for (int x : nums) {\n            int i = abs(x) - 1;\n            if (nums[i] < 0) out.push_back(abs(x));   // already flipped: seen before\n            else nums[i] = -nums[i];                  // mark value i + 1 as seen\n        }\n        return out;\n    }\n};",
 "find-all-groups-of-farmland": "class Solution {\npublic:\n    vector<vector<int>> findFarmland(vector<vector<int>>& land) {\n        int m = land.size(), n = land[0].size();\n        vector<vector<int>> out;\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++)\n                if (land[i][j] && (i == 0 || !land[i - 1][j]) && (j == 0 || !land[i][j - 1])) {   // top left corner\n                    int r = i, c = j;\n                    while (r + 1 < m && land[r + 1][j]) r++;\n                    while (c + 1 < n && land[i][c + 1]) c++;\n                    out.push_back({i, j, r, c});\n                }\n        return out;\n    }\n};",
 "find-all-lonely-numbers-in-the-array": "class Solution {\npublic:\n    vector<int> findLonely(vector<int>& nums) {\n        unordered_map<int, int> cnt;\n        for (int x : nums) cnt[x]++;\n        vector<int> out;\n        for (int x : nums)\n            if (cnt[x] == 1 && !cnt.count(x - 1) && !cnt.count(x + 1)) out.push_back(x);\n        return out;\n    }\n};",
 "find-all-numbers-disappeared-in-an-array": "class Solution {\npublic:\n    vector<int> findDisappearedNumbers(vector<int>& nums) {\n        for (int x : nums) {\n            int i = abs(x) - 1;\n            nums[i] = -abs(nums[i]);                       // mark value i + 1 as seen\n        }\n        vector<int> out;\n        for (int i = 0; i < (int)nums.size(); i++)\n            if (nums[i] > 0) out.push_back(i + 1);\n        return out;\n    }\n};",
 "find-all-people-with-secret": "class Solution {\npublic:\n    vector<int> findAllPeople(int n, vector<vector<int>>& meetings, int firstPerson) {\n        vector<int> p(n);\n        iota(p.begin(), p.end(), 0);\n        auto find = [&](int x) {\n            while (p[x] != x) {\n                p[x] = p[p[x]];\n                x = p[x];\n            }\n            return x;\n        };\n        p[firstPerson] = 0;\n        sort(meetings.begin(), meetings.end(), [](auto& a, auto& b) { return a[2] < b[2]; });\n        for (size_t i = 0; i < meetings.size();) {\n            size_t j = i;\n            while (j < meetings.size() && meetings[j][2] == meetings[i][2]) j++;\n            for (size_t k = i; k < j; k++) p[find(meetings[k][0])] = find(meetings[k][1]);   // join everyone meeting at this time\n            for (size_t k = i; k < j; k++)\n                for (int z : {meetings[k][0], meetings[k][1]})\n                    if (find(z) != find(0)) p[z] = z;   // did not learn the secret: undo the join\n            i = j;\n        }\n        vector<int> out;\n        for (int k = 0; k < n; k++)\n            if (find(k) == find(0)) out.push_back(k);\n        return out;\n    }\n};",
 "find-all-possible-recipes-from-given-supplies": "class Solution {\npublic:\n    vector<string> findAllRecipes(vector<string>& recipes, vector<vector<string>>& ingredients, vector<string>& supplies) {\n        unordered_map<string, int> need;               // ingredients a recipe still lacks\n        unordered_map<string, vector<string>> users;   // ingredient -> recipes that use it\n        for (size_t i = 0; i < recipes.size(); i++) {\n            need[recipes[i]] = ingredients[i].size();\n            for (const string& x : ingredients[i]) users[x].push_back(recipes[i]);\n        }\n        queue<string> q;\n        for (const string& s : supplies) q.push(s);\n        vector<string> out;\n        while (!q.empty()) {                           // Kahn's topological order\n            string x = q.front(); q.pop();\n            for (const string& r : users[x])\n                if (--need[r] == 0) { out.push_back(r); q.push(r); }   // a made recipe is a new supply\n        }\n        return out;\n    }\n};",
 "find-and-replace-pattern": "class Solution {\n    // each letter becomes the order in which it first appears: \"abb\" -> 0 1 1\n    vector<int> shape(const string& w) {\n        unordered_map<char, int> first;\n        vector<int> out;\n        for (char c : w) {\n            auto it = first.try_emplace(c, first.size()).first;\n            out.push_back(it->second);\n        }\n        return out;\n    }\n\npublic:\n    vector<string> findAndReplacePattern(vector<string>& words, string pattern) {\n        vector<int> p = shape(pattern);\n        vector<string> out;\n        for (auto& w : words)\n            if (shape(w) == p) out.push_back(w);\n        return out;\n    }\n};",
 "find-critical-and-pseudo-critical-edges-in-minimum-spanning-tree": "class Solution {\n    int n;\n    vector<vector<int>> edges;\n    vector<int> order;\n\n    // MST weight skipping one edge or forcing one in first; INT_MAX if the graph stays split\n    int mst(int skip = -1, int force = -1) {\n        vector<int> parent(n);\n        iota(parent.begin(), parent.end(), 0);\n        auto find = [&](int x) {\n            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }\n            return x;\n        };\n        int total = 0, joined = 0;\n        if (force >= 0) {\n            parent[find(edges[force][0])] = find(edges[force][1]);\n            total = edges[force][2]; joined = 1;\n        }\n        for (int i : order) {\n            if (i == skip) continue;\n            int ra = find(edges[i][0]), rb = find(edges[i][1]);\n            if (ra != rb) { parent[ra] = rb; total += edges[i][2]; joined++; }\n        }\n        return joined == n - 1 ? total : INT_MAX;\n    }\n\npublic:\n    vector<vector<int>> findCriticalAndPseudoCriticalEdges(int n, vector<vector<int>>& edges) {\n        this->n = n; this->edges = edges;\n        order.resize(edges.size());\n        iota(order.begin(), order.end(), 0);\n        stable_sort(order.begin(), order.end(), [&](int a, int b) { return edges[a][2] < edges[b][2]; });\n        int base = mst();\n        vector<int> critical, pseudo;\n        for (int i = 0; i < (int)edges.size(); i++) {\n            if (mst(i) > base) critical.push_back(i);           // without it the MST costs more\n            else if (mst(-1, i) == base) pseudo.push_back(i);   // some MST can use it\n        }\n        return {critical, pseudo};\n    }\n};",
 "find-elements-in-a-contaminated-binary-tree": "class FindElements {\n    unordered_set<int> seen;\npublic:\n    FindElements(TreeNode* root) {\n        vector<pair<TreeNode*, int>> stack{{root, 0}};\n        while (!stack.empty()) {\n            auto [node, v] = stack.back(); stack.pop_back();\n            if (!node) continue;\n            node->val = v;   // recover the value\n            seen.insert(v);\n            stack.push_back({node->left, 2 * v + 1});\n            stack.push_back({node->right, 2 * v + 2});\n        }\n    }\n\n    bool find(int target) {\n        return seen.count(target);\n    }\n};",
 "find-eventual-safe-states": "class Solution {\n    vector<int> state;                                   // 0 unseen, 1 on the path, 2 safe\n\n    bool safe(vector<vector<int>>& graph, int u) {\n        if (state[u]) return state[u] == 2;\n        state[u] = 1;\n        bool ok = true;\n        for (int v : graph[u]) if (!safe(graph, v)) { ok = false; break; }\n        if (ok) state[u] = 2;\n        return state[u] == 2;\n    }\n\npublic:\n    vector<int> eventualSafeNodes(vector<vector<int>>& graph) {\n        state.assign(graph.size(), 0);\n        vector<int> out;\n        for (int u = 0; u < (int)graph.size(); u++) if (safe(graph, u)) out.push_back(u);\n        return out;\n    }\n};",
 "find-first-and-last-position-of-element-in-sorted-array": "class Solution {\npublic:\n    vector<int> searchRange(vector<int>& nums, int target) {\n        int lo = lower_bound(nums.begin(), nums.end(), target) - nums.begin();\n        if (lo == (int)nums.size() || nums[lo] != target) return {-1, -1};\n        int hi = upper_bound(nums.begin(), nums.end(), target) - nums.begin() - 1;   // last copy\n        return {lo, hi};\n    }\n};",
 "find-greatest-common-divisor-of-array": "class Solution {\npublic:\n    int findGCD(vector<int>& nums) {\n        int a = *max_element(nums.begin(), nums.end()), b = *min_element(nums.begin(), nums.end());\n        while (b) {                                          // Euclid\n            int r = a % b;\n            a = b;\n            b = r;\n        }\n        return a;\n    }\n};",
 "find-if-path-exists-in-graph": "class Solution {\npublic:\n    bool validPath(int n, vector<vector<int>>& edges, int source, int destination) {\n        vector<vector<int>> adj(n);\n        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }\n        vector<bool> seen(n, false);\n        queue<int> q; q.push(source); seen[source] = true;\n        while (!q.empty()) {\n            int u = q.front(); q.pop();\n            if (u == destination) return true;\n            for (int v : adj[u]) if (!seen[v]) { seen[v] = true; q.push(v); }\n        }\n        return false;\n    }\n};",
 "find-k-closest-elements": "class Solution {\npublic:\n    vector<int> findClosestElements(vector<int>& arr, int k, int x) {\n        int lo = 0, hi = arr.size() - k;                   // binary search the window's left edge\n        while (lo < hi) {\n            int mid = (lo + hi) / 2;\n            if (x - arr[mid] > arr[mid + k] - x) lo = mid + 1;\n            else hi = mid;\n        }\n        return vector<int>(arr.begin() + lo, arr.begin() + lo + k);\n    }\n};",
 "find-k-pairs-with-smallest-sums": "class Solution {\npublic:\n    vector<vector<int>> kSmallestPairs(vector<int>& nums1, vector<int>& nums2, int k) {\n        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> h;   // (sum, i, j)\n        for (int i = 0; i < min(k, (int)nums1.size()); i++) h.push({nums1[i] + nums2[0], i, 0});\n        vector<vector<int>> out;\n        while (!h.empty() && (int)out.size() < k) {\n            auto [s, i, j] = h.top(); h.pop();\n            out.push_back({nums1[i], nums2[j]});\n            if (j + 1 < (int)nums2.size()) h.push({nums1[i] + nums2[j + 1], i, j + 1});   // next pair in row i\n        }\n        return out;\n    }\n};",
 "find-k-th-smallest-pair-distance": "class Solution {\npublic:\n    int smallestDistancePair(vector<int>& nums, int k) {\n        sort(nums.begin(), nums.end());\n        int lo = 0, hi = nums.back() - nums[0];\n        while (lo < hi) {\n            int mid = (lo + hi) / 2;\n            long long cnt = 0;\n            for (int l = 0, r = 0; r < (int)nums.size(); r++) {\n                while (nums[r] - nums[l] > mid) l++;\n                cnt += r - l;            // pairs ending at r with distance <= mid\n            }\n            if (cnt >= k) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "find-kth-bit-in-nth-binary-string": "class Solution {\npublic:\n    char findKthBit(int n, int k) {\n        bool flip = false;\n        while (n > 1) {\n            int mid = 1 << (n - 1);                      // length of S(n) is 2^n - 1\n            if (k == mid) return flip ? '0' : '1';\n            if (k > mid) { k = 2 * mid - k; flip = !flip; }\n            n--;\n        }\n        return flip ? '1' : '0';\n    }\n};",
 "find-largest-value-in-each-tree-row": "class Solution {\npublic:\n    vector<int> largestValues(TreeNode* root) {\n        vector<int> out;\n        queue<TreeNode*> q;\n        if (root) q.push(root);\n        while (!q.empty()) {\n            int best = INT_MIN;\n            for (int k = q.size(); k > 0; k--) {   // one row at a time\n                TreeNode* node = q.front(); q.pop();\n                best = max(best, node->val);\n                if (node->left) q.push(node->left);\n                if (node->right) q.push(node->right);\n            }\n            out.push_back(best);\n        }\n        return out;\n    }\n};",
 "find-longest-awesome-substring": "class Solution {\npublic:\n    int longestAwesome(string s) {\n        vector<int> first(1 << 10, INT_MAX);   // first index where each parity mask appeared\n        first[0] = -1;\n        int mask = 0, best = 0;\n        for (int i = 0; i < (int)s.size(); i++) {\n            mask ^= 1 << (s[i] - '0');\n            if (first[mask] != INT_MAX) best = max(best, i - first[mask]);   // all counts even\n            else first[mask] = i;\n            for (int d = 0; d < 10; d++) {                                   // one odd count\n                int m = mask ^ (1 << d);\n                if (first[m] != INT_MAX) best = max(best, i - first[m]);\n            }\n        }\n        return best;\n    }\n};",
 "find-longest-special-substring-that-occurs-thrice-i": "class Solution {\npublic:\n    int maximumLength(string s) {\n        vector<int> runs[26];   // lengths of each letter's runs\n        for (int i = 0; i < (int)s.size();) {\n            int j = i;\n            while (j < (int)s.size() && s[j] == s[i]) j++;\n            runs[s[i] - 'a'].push_back(j - i);\n            i = j;\n        }\n        int best = -1;\n        for (auto& lens : runs) {\n            if (lens.empty()) continue;   // letter not in s\n            lens.push_back(0);\n            lens.push_back(0);\n            sort(lens.rbegin(), lens.rend());\n            int a = lens[0], b = lens[1], c = lens[2];   // three longest runs\n            best = max({best, a - 2, min(a - 1, b), c});\n        }\n        return best > 0 ? best : -1;\n    }\n};",
 "find-median-from-data-stream": "class MedianFinder {\n    priority_queue<int> lo;                              // smaller half, max-heap\n    priority_queue<int, vector<int>, greater<int>> hi;   // larger half, min-heap\n\npublic:\n    MedianFinder() {}\n\n    void addNum(int num) {\n        lo.push(num);\n        hi.push(lo.top()); lo.pop();                     // the largest of the small half moves up\n        if (hi.size() > lo.size()) { lo.push(hi.top()); hi.pop(); }   // lo keeps the extra one\n    }\n\n    double findMedian() {\n        if (lo.size() > hi.size()) return lo.top();\n        return (lo.top() + (double)hi.top()) / 2;\n    }\n};",
 "find-minimum-in-rotated-sorted-array": "class Solution {\npublic:\n    int findMin(vector<int>& nums) {\n        int lo = 0, hi = nums.size() - 1;\n        while (lo < hi) {\n            int mid = (lo + hi) / 2;\n            if (nums[mid] > nums[hi]) lo = mid + 1;        // the drop is to the right\n            else hi = mid;\n        }\n        return nums[lo];\n    }\n};",
 "find-minimum-in-rotated-sorted-array-ii": "class Solution {\npublic:\n    int findMin(vector<int>& nums) {\n        int lo = 0, hi = nums.size() - 1;\n        while (lo < hi) {\n            int mid = (lo + hi) / 2;\n            if (nums[mid] > nums[hi]) lo = mid + 1;   // the drop is to the right of mid\n            else if (nums[mid] < nums[hi]) hi = mid;\n            else hi--;                                // equal: hi can go, mid keeps its value\n        }\n        return nums[lo];\n    }\n};",
 "find-original-array-from-doubled-array": "class Solution {\npublic:\n    vector<int> findOriginalArray(vector<int>& changed) {\n        if (changed.size() % 2) return {};\n        unordered_map<int, int> cnt;\n        for (int x : changed) cnt[x]++;\n        sort(changed.begin(), changed.end());\n        vector<int> out;\n        for (int x : changed) {\n            if (cnt[x] == 0) continue;                       // already used as a double\n            if (cnt[2 * x] == 0 || (x == 0 && cnt[0] < 2)) return {};\n            cnt[x]--;\n            cnt[2 * x]--;\n            out.push_back(x);\n        }\n        return out;\n    }\n};",
 "find-peak-element": "class Solution {\npublic:\n    int findPeakElement(vector<int>& nums) {\n        int lo = 0, hi = nums.size() - 1;\n        while (lo < hi) {\n            int mid = (lo + hi) / 2;\n            if (nums[mid] < nums[mid + 1]) lo = mid + 1;   // uphill to the right: a peak is there\n            else hi = mid;\n        }\n        return lo;\n    }\n};",
 "find-pivot-index": "class Solution {\npublic:\n    int pivotIndex(vector<int>& nums) {\n        int total = accumulate(nums.begin(), nums.end(), 0), left = 0;\n        for (int i = 0; i < (int)nums.size(); i++) {\n            if (left == total - left - nums[i]) return i;  // left sum equals right sum\n            left += nums[i];\n        }\n        return -1;\n    }\n};",
 "find-players-with-zero-or-one-losses": "class Solution {\npublic:\n    vector<vector<int>> findWinners(vector<vector<int>>& matches) {\n        map<int, int> losses;   // every player -> losses, sorted by player\n        for (auto& m : matches) { losses[m[0]] += 0; losses[m[1]]++; }\n        vector<vector<int>> out(2);\n        for (auto [p, l] : losses)\n            if (l <= 1) out[l].push_back(p);\n        return out;\n    }\n};",
 "find-right-interval": "class Solution {\npublic:\n    vector<int> findRightInterval(vector<vector<int>>& intervals) {\n        vector<pair<int, int>> starts;   // (start, index), sorted\n        for (int i = 0; i < (int)intervals.size(); i++) starts.push_back({intervals[i][0], i});\n        sort(starts.begin(), starts.end());\n        vector<int> out;\n        for (auto& iv : intervals) {\n            auto it = lower_bound(starts.begin(), starts.end(), pair{iv[1], INT_MIN});   // first start >= end\n            out.push_back(it != starts.end() ? it->second : -1);\n        }\n        return out;\n    }\n};",
 "find-the-city-with-the-smallest-number-of-neighbors-at-a-threshold-distance": "class Solution {\npublic:\n    int findTheCity(int n, vector<vector<int>>& edges, int distanceThreshold) {\n        const int INF = 1e9;\n        vector<vector<int>> d(n, vector<int>(n, INF));\n        for (int i = 0; i < n; i++) d[i][i] = 0;\n        for (auto& e : edges) d[e[0]][e[1]] = d[e[1]][e[0]] = e[2];\n        for (int k = 0; k < n; k++)                     // Floyd-Warshall\n            for (int i = 0; i < n; i++)\n                for (int j = 0; j < n; j++)\n                    if (d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];\n        int best = n + 1, city = -1;\n        for (int i = 0; i < n; i++) {\n            int c = 0;\n            for (int j = 0; j < n; j++) c += d[i][j] <= distanceThreshold;\n            if (c <= best) { best = c; city = i; }      // <= keeps the largest index on ties\n        }\n        return city;\n    }\n};",
 "find-the-difference": "class Solution {\npublic:\n    char findTheDifference(string s, string t) {\n        int x = 0;\n        for (char ch : s + t) x ^= ch;                       // pairs cancel, the extra letter stays\n        return (char)x;\n    }\n};",
 "find-the-duplicate-number": "class Solution {\npublic:\n    int findDuplicate(vector<int>& nums) {\n        int slow = nums[0], fast = nums[0];\n        do {                                               // i -> nums[i] is a list with a cycle\n            slow = nums[slow];\n            fast = nums[nums[fast]];\n        } while (slow != fast);\n        slow = nums[0];\n        while (slow != fast) {                             // they meet at the cycle entrance\n            slow = nums[slow];\n            fast = nums[fast];\n        }\n        return slow;\n    }\n};",
 "find-the-index-of-the-first-occurrence-in-a-string": "class Solution {\npublic:\n    int strStr(string haystack, string needle) {\n        int m = needle.size();\n        vector<int> lps(m, 0);                           // longest proper prefix that is also a suffix\n        for (int i = 1, k = 0; i < m; i++) {\n            while (k && needle[i] != needle[k]) k = lps[k - 1];\n            if (needle[i] == needle[k]) k++;\n            lps[i] = k;\n        }\n        for (int i = 0, k = 0; i < (int)haystack.size(); i++) {\n            while (k && haystack[i] != needle[k]) k = lps[k - 1];   // fall back without moving i\n            if (haystack[i] == needle[k]) k++;\n            if (k == m) return i - k + 1;\n        }\n        return -1;\n    }\n};",
 "find-the-longest-substring-containing-vowels-in-even-counts": "class Solution {\npublic:\n    int findTheLongestSubstring(string s) {\n        const string vowels = \"aeiou\";\n        vector<int> first(32, -2);   // parity mask -> first index, -2 = not seen\n        first[0] = -1;\n        int mask = 0, best = 0;\n        for (int i = 0; i < (int)s.size(); i++) {\n            auto p = vowels.find(s[i]);\n            if (p != string::npos) mask ^= 1 << p;\n            if (first[mask] != -2) best = max(best, i - first[mask]);   // same parity: even counts between\n            else first[mask] = i;\n        }\n        return best;\n    }\n};",
 "find-the-minimum-and-maximum-number-of-nodes-between-critical-points": "class Solution {\npublic:\n    vector<int> nodesBetweenCriticalPoints(ListNode* head) {\n        int first = -1, last = -1, best = INT_MAX;\n        ListNode *prev = head, *cur = head->next;\n        for (int i = 1; cur->next; i++) {\n            int nxt = cur->next->val;\n            bool peak = prev->val < cur->val && cur->val > nxt;\n            bool valley = prev->val > cur->val && cur->val < nxt;\n            if (peak || valley) {\n                if (first == -1) first = i;\n                else best = min(best, i - last);       // closest pair is always adjacent\n                last = i;\n            }\n            prev = cur;\n            cur = cur->next;\n        }\n        if (first == last) return {-1, -1};           // fewer than two critical points\n        return {best, last - first};\n    }\n};",
 "find-the-original-array-of-prefix-xor": "class Solution {\npublic:\n    vector<int> findArray(vector<int>& pref) {\n        vector<int> out{pref[0]};\n        for (int i = 1; i < (int)pref.size(); i++) out.push_back(pref[i] ^ pref[i - 1]);   // xor cancels the shared prefix\n        return out;\n    }\n};",
 "find-the-safest-path-in-a-grid": "class Solution {\npublic:\n    int maximumSafenessFactor(vector<vector<int>>& grid) {\n        int n = grid.size();\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        vector<vector<int>> dist(n, vector<int>(n, -1));\n        queue<pair<int, int>> q;\n        for (int r = 0; r < n; r++)\n            for (int c = 0; c < n; c++)\n                if (grid[r][c]) { dist[r][c] = 0; q.push({r, c}); }\n        while (!q.empty()) {                           // multi-source BFS: distance to the nearest thief\n            auto [r, c] = q.front(); q.pop();\n            for (int d = 0; d < 4; d++) {\n                int nr = r + dr[d], nc = c + dc[d];\n                if (nr >= 0 && nr < n && nc >= 0 && nc < n && dist[nr][nc] == -1) {\n                    dist[nr][nc] = dist[r][c] + 1;\n                    q.push({nr, nc});\n                }\n            }\n        }\n        priority_queue<tuple<int, int, int>> heap;     // (safeness so far, r, c), safest first\n        heap.push({dist[0][0], 0, 0});\n        vector<vector<bool>> seen(n, vector<bool>(n, false));\n        seen[0][0] = true;\n        while (!heap.empty()) {\n            auto [s, r, c] = heap.top(); heap.pop();\n            if (r == n - 1 && c == n - 1) return s;\n            for (int d = 0; d < 4; d++) {\n                int nr = r + dr[d], nc = c + dc[d];\n                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !seen[nr][nc]) {\n                    seen[nr][nc] = true;\n                    heap.push({min(s, dist[nr][nc]), nr, nc});   // a path is as safe as its worst cell\n                }\n            }\n        }\n        return 0;\n    }\n};",
 "find-the-smallest-divisor-given-a-threshold": "class Solution {\npublic:\n    int smallestDivisor(vector<int>& nums, int threshold) {\n        int lo = 1, hi = *max_element(nums.begin(), nums.end());\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            long long s = 0;\n            for (int x : nums) s += (x + mid - 1) / mid;   // ceiling division\n            if (s <= threshold) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "find-the-winner-of-the-circular-game": "class Solution {\npublic:\n    int findTheWinner(int n, int k) {\n        int w = 0;   // winner index with 1 friend\n        for (int i = 2; i <= n; i++) w = (w + k) % i;\n        return w + 1;\n    }\n};",
 "find-triangular-sum-of-an-array": "class Solution {\npublic:\n    int triangularSum(vector<int>& nums) {\n        for (int len = nums.size(); len > 1; len--)        // each pass makes one shorter row\n            for (int i = 0; i + 1 < len; i++) nums[i] = (nums[i] + nums[i + 1]) % 10;\n        return nums[0];\n    }\n};",
 "find-two-non-overlapping-sub-arrays-each-with-target-sum": "class Solution {\npublic:\n    int minSumOfLengths(vector<int>& arr, int target) {\n        const int INF = INT_MAX / 2;\n        int n = arr.size();\n        vector<int> best(n, INF);        // best[r] = shortest window ending at or before r\n        int ans = INF, shortest = INF, l = 0, s = 0;\n        for (int r = 0; r < n; r++) {\n            s += arr[r];\n            while (s > target) s -= arr[l++];\n            if (s == target) {\n                if (l > 0 && best[l - 1] < INF) ans = min(ans, best[l - 1] + r - l + 1);\n                shortest = min(shortest, r - l + 1);\n            }\n            best[r] = shortest;\n        }\n        return ans == INF ? -1 : ans;\n    }\n};",
 "find-valid-matrix-given-row-and-column-sums": "class Solution {\npublic:\n    vector<vector<int>> restoreMatrix(vector<int>& rowSum, vector<int>& colSum) {\n        vector<vector<int>> out(rowSum.size(), vector<int>(colSum.size(), 0));\n        for (size_t i = 0; i < rowSum.size(); i++)\n            for (size_t j = 0; j < colSum.size(); j++) {\n                int v = min(rowSum[i], colSum[j]);   // put as much as both allow\n                out[i][j] = v;\n                rowSum[i] -= v;\n                colSum[j] -= v;\n            }\n        return out;\n    }\n};",
 "first-missing-positive": "class Solution {\npublic:\n    int firstMissingPositive(vector<int>& nums) {\n        int n = nums.size();\n        for (int i = 0; i < n; i++)\n            while (0 < nums[i] && nums[i] <= n && nums[nums[i] - 1] != nums[i])\n                swap(nums[i], nums[nums[i] - 1]);          // put value v at index v - 1\n        for (int i = 0; i < n; i++)\n            if (nums[i] != i + 1) return i + 1;\n        return n + 1;\n    }\n};",
 "first-unique-character-in-a-string": "class Solution {\npublic:\n    int firstUniqChar(string s) {\n        int count[26] = {};\n        for (char ch : s) count[ch - 'a']++;\n        for (int i = 0; i < (int)s.size(); i++)\n            if (count[s[i] - 'a'] == 1) return i;\n        return -1;\n    }\n};",
 "flatten-a-multilevel-doubly-linked-list": "class Node {\npublic:\n    int val;\n    Node* prev;\n    Node* next;\n    Node* child;\n};\n\nclass Solution {\npublic:\n    Node* flatten(Node* head) {\n        if (!head) return head;\n        vector<Node*> st{head};\n        Node* prev = nullptr;\n        while (!st.empty()) {\n            Node* node = st.back(); st.pop_back();\n            if (prev) { prev->next = node; node->prev = prev; }\n            if (node->next) st.push_back(node->next);  // pushed first, so the child comes out first\n            if (node->child) { st.push_back(node->child); node->child = nullptr; }\n            prev = node;\n        }\n        return head;\n    }\n};",
 "flatten-binary-tree-to-linked-list": "class Solution {\npublic:\n    void flatten(TreeNode* root) {\n        for (TreeNode* node = root; node; node = node->right) {\n            if (node->left) {\n                TreeNode* pre = node->left;\n                while (pre->right) pre = pre->right;   // last node of the left subtree\n                pre->right = node->right;\n                node->right = node->left;\n                node->left = nullptr;\n            }\n        }\n    }\n};",
 "flip-columns-for-maximum-number-of-equal-rows": "class Solution {\npublic:\n    int maxEqualRowsAfterFlips(vector<vector<int>>& matrix) {\n        map<vector<int>, int> c;   // row normalised so it starts with 0 -> count\n        int best = 0;\n        for (auto& row : matrix) {\n            vector<int> key;\n            for (int x : row) key.push_back(x ^ row[0]);\n            best = max(best, ++c[key]);\n        }\n        return best;\n    }\n};",
 "flood-fill": "class Solution {\n    void fill(vector<vector<int>>& image, int r, int c, int old, int color) {\n        if (r < 0 || r >= (int)image.size() || c < 0 || c >= (int)image[0].size() || image[r][c] != old) return;\n        image[r][c] = color;\n        fill(image, r + 1, c, old, color);\n        fill(image, r - 1, c, old, color);\n        fill(image, r, c + 1, old, color);\n        fill(image, r, c - 1, old, color);\n    }\n\npublic:\n    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {\n        int old = image[sr][sc];\n        if (old == color) return image;                  // nothing to change, and avoids looping forever\n        fill(image, sr, sc, old, color);\n        return image;\n    }\n};",
 "flower-planting-with-no-adjacent": "class Solution {\npublic:\n    vector<int> gardenNoAdj(int n, vector<vector<int>>& paths) {\n        vector<vector<int>> adj(n);\n        for (auto& p : paths) { adj[p[0] - 1].push_back(p[1] - 1); adj[p[1] - 1].push_back(p[0] - 1); }\n        vector<int> ans(n, 0);\n        for (int u = 0; u < n; u++) {\n            bool taken[5] = {};\n            for (int v : adj[u]) taken[ans[v]] = true;\n            for (int c = 1; c <= 4; c++) if (!taken[c]) { ans[u] = c; break; }   // at most 3 neighbours, so one is free\n        }\n        return ans;\n    }\n};",
 "frog-jump-ii": "class Solution {\npublic:\n    int maxJump(vector<int>& stones) {\n        int best = stones[1] - stones[0];\n        for (int i = 2; i < (int)stones.size(); i++)\n            best = max(best, stones[i] - stones[i - 2]);   // go on every other stone, come back on the rest\n        return best;\n    }\n};",
 "fruit-into-baskets": "class Solution {\npublic:\n    int totalFruit(vector<int>& fruits) {\n        unordered_map<int, int> count;                     // fruit kinds in the window\n        int l = 0, best = 0;\n        for (int r = 0; r < (int)fruits.size(); r++) {\n            count[fruits[r]]++;\n            while (count.size() > 2) {                     // too many kinds: shrink\n                if (--count[fruits[l]] == 0) count.erase(fruits[l]);\n                l++;\n            }\n            best = max(best, r - l + 1);\n        }\n        return best;\n    }\n};",
 "furthest-building-you-can-reach": "class Solution {\npublic:\n    int furthestBuilding(vector<int>& heights, int bricks, int ladders) {\n        priority_queue<int, vector<int>, greater<int>> heap;   // climbs covered by ladders\n        for (int i = 0; i + 1 < (int)heights.size(); i++) {\n            int d = heights[i + 1] - heights[i];\n            if (d <= 0) continue;\n            heap.push(d);\n            if ((int)heap.size() > ladders) {    // the smallest climb uses bricks instead\n                bricks -= heap.top();\n                heap.pop();\n                if (bricks < 0) return i;\n            }\n        }\n        return heights.size() - 1;\n    }\n};",
 "game-of-life": "class Solution {\npublic:\n    void gameOfLife(vector<vector<int>>& board) {\n        int m = board.size(), n = board[0].size();\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++) {\n                int live = -(board[i][j] & 1);   // bit 0 = now, bit 1 = next\n                for (int x = max(0, i - 1); x < min(m, i + 2); x++)\n                    for (int y = max(0, j - 1); y < min(n, j + 2); y++) live += board[x][y] & 1;\n                if (live == 3 || (live == 2 && (board[i][j] & 1))) board[i][j] |= 2;\n            }\n        for (auto& row : board)\n            for (int& v : row) v >>= 1;   // next becomes now\n    }\n};",
 "gas-station": "class Solution {\npublic:\n    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {\n        if (accumulate(gas.begin(), gas.end(), 0) < accumulate(cost.begin(), cost.end(), 0)) return -1;\n        int start = 0, tank = 0;\n        for (int i = 0; i < (int)gas.size(); i++) {\n            tank += gas[i] - cost[i];\n            if (tank < 0) { start = i + 1; tank = 0; }  // no station up to i can be the start\n        }\n        return start;\n    }\n};",
 "get-equal-substrings-within-budget": "class Solution {\npublic:\n    int equalSubstring(string s, string t, int maxCost) {\n        int L = 0, cost = 0, best = 0;\n        for (int R = 0; R < (int)s.size(); R++) {\n            cost += abs(s[R] - t[R]);\n            while (cost > maxCost) {   // over budget: drop from the left\n                cost -= abs(s[L] - t[L]);\n                L++;\n            }\n            best = max(best, R - L + 1);\n        }\n        return best;\n    }\n};",
 "greatest-common-divisor-of-strings": "class Solution {\npublic:\n    string gcdOfStrings(string str1, string str2) {\n        if (str1 + str2 != str2 + str1) return \"\";           // no common repeating unit\n        return str1.substr(0, gcd(str1.size(), str2.size()));\n    }\n};",
 "group-anagrams": "class Solution {\npublic:\n    vector<vector<string>> groupAnagrams(vector<string>& strs) {\n        unordered_map<string, vector<string>> groups;    // sorted letters is the key\n        for (auto& w : strs) {\n            string key = w;\n            sort(key.begin(), key.end());\n            groups[key].push_back(w);\n        }\n        vector<vector<string>> out;\n        for (auto& [key, g] : groups) out.push_back(g);\n        return out;\n    }\n};",
 "grumpy-bookstore-owner": "class Solution {\npublic:\n    int maxSatisfied(vector<int>& customers, vector<int>& grumpy, int minutes) {\n        int n = customers.size(), base = 0, gain = 0, best = 0;\n        for (int i = 0; i < n; i++) if (!grumpy[i]) base += customers[i];   // happy anyway\n        for (int i = 0; i < n; i++) {\n            gain += customers[i] * grumpy[i];                               // window of saved customers\n            if (i >= minutes) gain -= customers[i - minutes] * grumpy[i - minutes];\n            best = max(best, gain);\n        }\n        return base + best;\n    }\n};",
 "hamming-distance": "class Solution {\npublic:\n    int hammingDistance(int x, int y) {\n        return __builtin_popcount(x ^ y);                    // bits that differ\n    }\n};",
 "hand-of-straights": "class Solution {\npublic:\n    bool isNStraightHand(vector<int>& hand, int groupSize) {\n        map<int, int> cnt;                               // sorted by card value\n        for (int x : hand) cnt[x]++;\n        for (auto& [x, k] : cnt) {\n            if (!k) continue;\n            int need = k;                                // every group starting at x\n            for (int y = x; y < x + groupSize; y++) {\n                auto it = cnt.find(y);\n                if (it == cnt.end() || it->second < need) return false;\n                it->second -= need;\n            }\n        }\n        return true;\n    }\n};",
 "happy-number": "class Solution {\npublic:\n    bool isHappy(int n) {\n        unordered_set<int> seen;\n        while (n != 1 && !seen.count(n)) {                   // a repeat means a cycle without 1\n            seen.insert(n);\n            int s = 0;\n            for (; n; n /= 10) s += (n % 10) * (n % 10);\n            n = s;\n        }\n        return n == 1;\n    }\n};",
 "house-robber": "class Solution {\npublic:\n    int rob(vector<int>& nums) {\n        int prev = 0, cur = 0;                               // best up to i-2 and i-1\n        for (int x : nums) {\n            int nxt = max(cur, prev + x);                    // skip this house or rob it\n            prev = cur;\n            cur = nxt;\n        }\n        return cur;\n    }\n};",
 "house-robber-ii": "class Solution {\n    int line(vector<int>::const_iterator b, vector<int>::const_iterator e) {\n        int prev = 0, cur = 0;\n        for (; b != e; ++b) {\n            int nxt = max(cur, prev + *b);\n            prev = cur;\n            cur = nxt;\n        }\n        return cur;\n    }\npublic:\n    int rob(vector<int>& nums) {\n        if (nums.size() == 1) return nums[0];\n        // first and last are neighbours: drop one of them\n        return max(line(nums.begin(), nums.end() - 1), line(nums.begin() + 1, nums.end()));\n    }\n};",
 "house-robber-iii": "class Solution {\n    pair<int, int> go(TreeNode* node) {                  // (best if we rob node, best if we skip it)\n        if (!node) return {0, 0};\n        auto l = go(node->left), r = go(node->right);\n        int take = node->val + l.second + r.second;\n        int skip = max(l.first, l.second) + max(r.first, r.second);\n        return {take, skip};\n    }\n\npublic:\n    int rob(TreeNode* root) {\n        auto [take, skip] = go(root);\n        return max(take, skip);\n    }\n};",
 "implement-magic-dictionary": "class MagicDictionary {\n    unordered_set<string> words;\n    unordered_map<string, int> pat;   // \"h*llo\" -> how many words fit it\npublic:\n    MagicDictionary() {}\n\n    void buildDict(vector<string> dictionary) {\n        words = unordered_set<string>(dictionary.begin(), dictionary.end());\n        pat.clear();\n        for (auto& w : dictionary)\n            for (size_t i = 0; i < w.size(); i++) pat[w.substr(0, i) + \"*\" + w.substr(i + 1)]++;\n    }\n\n    bool search(string searchWord) {\n        for (size_t i = 0; i < searchWord.size(); i++) {\n            auto it = pat.find(searchWord.substr(0, i) + \"*\" + searchWord.substr(i + 1));\n            int c = it == pat.end() ? 0 : it->second;\n            // another word fits, or the one word that fits is not searchWord itself\n            if (c > 1 || (c == 1 && !words.count(searchWord))) return true;\n        }\n        return false;\n    }\n};",
 "implement-queue-using-stacks": "class MyQueue {\n    stack<int> in, out;                                  // push onto in, pop from out\n\n    void move() {                                        // refill out only when it is empty\n        if (out.empty())\n            while (!in.empty()) { out.push(in.top()); in.pop(); }\n    }\n\npublic:\n    MyQueue() {}\n\n    void push(int x) { in.push(x); }\n\n    int pop() {\n        move();\n        int x = out.top();\n        out.pop();\n        return x;\n    }\n\n    int peek() {\n        move();\n        return out.top();\n    }\n\n    bool empty() { return in.empty() && out.empty(); }\n};",
 "implement-trie-prefix-tree": "class Trie {\n    struct TrieNode {\n        TrieNode* kids[26] = {};\n        bool end = false;                                // a word ends here\n    };\n    TrieNode* root = new TrieNode();\n\n    TrieNode* walk(const string& s) {                    // node for s, or nullptr if no word starts with s\n        TrieNode* node = root;\n        for (char ch : s) {\n            node = node->kids[ch - 'a'];\n            if (!node) return nullptr;\n        }\n        return node;\n    }\n\npublic:\n    Trie() {}\n\n    void insert(string word) {\n        TrieNode* node = root;\n        for (char ch : word) {\n            if (!node->kids[ch - 'a']) node->kids[ch - 'a'] = new TrieNode();\n            node = node->kids[ch - 'a'];\n        }\n        node->end = true;\n    }\n\n    bool search(string word) {\n        TrieNode* node = walk(word);\n        return node && node->end;\n    }\n\n    bool startsWith(string prefix) { return walk(prefix) != nullptr; }\n};",
 "increasing-triplet-subsequence": "class Solution {\npublic:\n    bool increasingTriplet(vector<int>& nums) {\n        long long first = LLONG_MAX, second = LLONG_MAX;   // smallest end of length-1 and length-2 runs\n        for (int x : nums) {\n            if (x <= first) first = x;\n            else if (x <= second) second = x;\n            else return true;\n        }\n        return false;\n    }\n};",
 "insert-delete-getrandom-o1-duplicates-allowed": "class RandomizedCollection {\n    vector<int> vals;\n    unordered_map<int, unordered_set<int>> pos;   // value -> indexes in vals\npublic:\n    RandomizedCollection() {}\n\n    bool insert(int val) {\n        pos[val].insert(vals.size());\n        vals.push_back(val);\n        return pos[val].size() == 1;\n    }\n\n    bool remove(int val) {\n        auto& p = pos[val];\n        if (p.empty()) return false;\n        int i = *p.begin(), last = vals.back();\n        p.erase(p.begin());\n        vals[i] = last;                   // move the last value into the hole\n        pos[last].insert(i);\n        pos[last].erase(vals.size() - 1);\n        vals.pop_back();\n        return true;\n    }\n\n    int getRandom() { return vals[rand() % vals.size()]; }\n};",
 "insert-greatest-common-divisors-in-linked-list": "class Solution {\npublic:\n    ListNode* insertGreatestCommonDivisors(ListNode* head) {\n        for (ListNode* node = head; node->next; node = node->next->next)   // skip the new node\n            node->next = new ListNode(gcd(node->val, node->next->val), node->next);\n        return head;\n    }\n};",
 "insert-interval": "class Solution {\npublic:\n    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {\n        vector<vector<int>> out;\n        int i = 0, n = intervals.size();\n        int s = newInterval[0], e = newInterval[1];\n        while (i < n && intervals[i][1] < s) out.push_back(intervals[i++]);   // entirely before\n        while (i < n && intervals[i][0] <= e) {                                // overlapping: merge\n            s = min(s, intervals[i][0]);\n            e = max(e, intervals[i][1]);\n            i++;\n        }\n        out.push_back({s, e});\n        while (i < n) out.push_back(intervals[i++]);                           // entirely after\n        return out;\n    }\n};",
 "insert-into-a-binary-search-tree": "class Solution {\npublic:\n    TreeNode* insertIntoBST(TreeNode* root, int val) {\n        if (!root) return new TreeNode(val);                 // the empty spot it belongs in\n        if (val < root->val) root->left = insertIntoBST(root->left, val);\n        else root->right = insertIntoBST(root->right, val);\n        return root;\n    }\n};",
 "integer-to-english-words": "class Solution {\n    const vector<string> ONES = {\"\", \"One\", \"Two\", \"Three\", \"Four\", \"Five\", \"Six\", \"Seven\", \"Eight\", \"Nine\", \"Ten\",\n                                 \"Eleven\", \"Twelve\", \"Thirteen\", \"Fourteen\", \"Fifteen\", \"Sixteen\", \"Seventeen\", \"Eighteen\", \"Nineteen\"};\n    const vector<string> TENS = {\"\", \"\", \"Twenty\", \"Thirty\", \"Forty\", \"Fifty\", \"Sixty\", \"Seventy\", \"Eighty\", \"Ninety\"};\n\n    void three(int n, vector<string>& out) {             // words for 1 to 999\n        if (n >= 100) { out.push_back(ONES[n / 100]); out.push_back(\"Hundred\"); n %= 100; }\n        if (n >= 20) { out.push_back(TENS[n / 10]); n %= 10; }\n        if (n) out.push_back(ONES[n]);\n    }\n\npublic:\n    string numberToWords(int num) {\n        if (num == 0) return \"Zero\";\n        vector<string> words;\n        pair<int, string> scales[] = {{1000000000, \"Billion\"}, {1000000, \"Million\"}, {1000, \"Thousand\"}, {1, \"\"}};\n        for (auto& [scale, name] : scales)\n            if (num >= scale) {\n                three(num / scale, words);\n                if (!name.empty()) words.push_back(name);\n                num %= scale;\n            }\n        string out;\n        for (auto& w : words) out += (out.empty() ? \"\" : \" \") + w;\n        return out;\n    }\n};",
 "interleaving-string": "class Solution {\npublic:\n    bool isInterleave(string s1, string s2, string s3) {\n        int m = s1.size(), n = s2.size();\n        if (m + n != (int)s3.size()) return false;\n        vector<vector<bool>> dp(m + 1, vector<bool>(n + 1, false));   // dp[i][j]: s1[:i] and s2[:j] make s3[:i+j]\n        dp[0][0] = true;\n        for (int i = 0; i <= m; i++)\n            for (int j = 0; j <= n; j++) {\n                if (i && s1[i - 1] == s3[i + j - 1] && dp[i - 1][j]) dp[i][j] = true;\n                if (j && s2[j - 1] == s3[i + j - 1] && dp[i][j - 1]) dp[i][j] = true;\n            }\n        return dp[m][n];\n    }\n};",
 "intersection-of-two-linked-lists": "class Solution {\npublic:\n    ListNode* getIntersectionNode(ListNode* headA, ListNode* headB) {\n        ListNode *a = headA, *b = headB;\n        while (a != b) {                                 // each walks A then B, so both cover the same length\n            a = a ? a->next : headB;\n            b = b ? b->next : headA;\n        }\n        return a;\n    }\n};",
 "interval-list-intersections": "class Solution {\npublic:\n    vector<vector<int>> intervalIntersection(vector<vector<int>>& firstList, vector<vector<int>>& secondList) {\n        auto &A = firstList, &B = secondList;\n        vector<vector<int>> out;\n        size_t i = 0, j = 0;\n        while (i < A.size() && j < B.size()) {\n            int lo = max(A[i][0], B[j][0]), hi = min(A[i][1], B[j][1]);\n            if (lo <= hi) out.push_back({lo, hi});\n            if (A[i][1] < B[j][1]) i++;   // the one that ends first is done\n            else j++;\n        }\n        return out;\n    }\n};",
 "invert-binary-tree": "class Solution {\npublic:\n    TreeNode* invertTree(TreeNode* root) {\n        if (root) {\n            TreeNode* left = invertTree(root->right);      // swap the inverted subtrees\n            root->right = invertTree(root->left);\n            root->left = left;\n        }\n        return root;\n    }\n};",
 "is-graph-bipartite": "class Solution {\npublic:\n    bool isBipartite(vector<vector<int>>& graph) {\n        vector<int> color(graph.size(), -1);\n        for (int s = 0; s < (int)graph.size(); s++) {\n            if (color[s] != -1) continue;\n            color[s] = 0;\n            vector<int> st = {s};\n            while (!st.empty()) {\n                int u = st.back(); st.pop_back();\n                for (int v : graph[u]) {\n                    if (color[v] == -1) { color[v] = color[u] ^ 1; st.push_back(v); }\n                    else if (color[v] == color[u]) return false;   // an edge inside one side\n                }\n            }\n        }\n        return true;\n    }\n};",
 "island-perimeter": "class Solution {\npublic:\n    int islandPerimeter(vector<vector<int>>& grid) {\n        int total = 0;\n        for (int r = 0; r < (int)grid.size(); r++)\n            for (int c = 0; c < (int)grid[r].size(); c++)\n                if (grid[r][c]) {\n                    total += 4;\n                    if (r && grid[r - 1][c]) total -= 2;   // shared edge with the cell above\n                    if (c && grid[r][c - 1]) total -= 2;   // shared edge with the cell to the left\n                }\n        return total;\n    }\n};",
 "isomorphic-strings": "class Solution {\npublic:\n    bool isIsomorphic(string s, string t) {\n        int st[256], ts[256];                            // char maps both ways, -1 for unset\n        fill(st, st + 256, -1);\n        fill(ts, ts + 256, -1);\n        for (size_t i = 0; i < s.size(); i++) {\n            unsigned char a = s[i], b = t[i];\n            if (st[a] == -1) st[a] = b;\n            if (ts[b] == -1) ts[b] = a;\n            if (st[a] != b || ts[b] != a) return false;\n        }\n        return true;\n    }\n};",
 "iterator-for-combination": "class CombinationIterator {\n    string chars;\n    vector<int> idx;       // indexes of the next combination, in order\n    bool more = true;\npublic:\n    CombinationIterator(string characters, int combinationLength) : chars(characters), idx(combinationLength) {\n        iota(idx.begin(), idx.end(), 0);   // the first combination is the first k letters\n    }\n\n    string next() {\n        string out;\n        for (int i : idx) out += chars[i];\n        // advance: bump the rightmost index that still has room, then reset those after it\n        int k = idx.size(), n = chars.size(), i = k - 1;\n        while (i >= 0 && idx[i] == n - k + i) i--;\n        if (i < 0) more = false;\n        else {\n            idx[i]++;\n            for (int j = i + 1; j < k; j++) idx[j] = idx[j - 1] + 1;\n        }\n        return out;\n    }\n\n    bool hasNext() { return more; }\n};",
 "jump-game": "class Solution {\npublic:\n    bool canJump(vector<int>& nums) {\n        int reach = 0;\n        for (int i = 0; i < (int)nums.size(); i++) {\n            if (i > reach) return false;                 // cannot get here\n            reach = max(reach, i + nums[i]);\n        }\n        return true;\n    }\n};",
 "jump-game-ii": "class Solution {\npublic:\n    int jump(vector<int>& nums) {\n        int jumps = 0, end = 0, far = 0;\n        for (int i = 0; i + 1 < (int)nums.size(); i++) {\n            far = max(far, i + nums[i]);\n            if (i == end) { jumps++; end = far; }        // this jump's range is used up\n        }\n        return jumps;\n    }\n};",
 "jump-game-iii": "class Solution {\npublic:\n    bool canReach(vector<int>& arr, int start) {\n        int n = arr.size();\n        vector<bool> seen(n, false);\n        vector<int> stack{start};\n        while (!stack.empty()) {\n            int i = stack.back(); stack.pop_back();\n            if (arr[i] == 0) return true;\n            seen[i] = true;\n            for (int j : {i + arr[i], i - arr[i]})\n                if (0 <= j && j < n && !seen[j]) stack.push_back(j);\n        }\n        return false;\n    }\n};",
 "jump-game-iv": "class Solution {\npublic:\n    int minJumps(vector<int>& arr) {\n        int n = arr.size();\n        unordered_map<int, vector<int>> same;   // value -> indices holding it\n        for (int i = 0; i < n; i++) same[arr[i]].push_back(i);\n        vector<int> dist(n, -1);\n        dist[0] = 0;\n        queue<int> q; q.push(0);\n        while (!q.empty()) {\n            int i = q.front(); q.pop();\n            if (i == n - 1) return dist[i];\n            vector<int> next;\n            if (auto it = same.find(arr[i]); it != same.end()) {\n                next = move(it->second);\n                same.erase(it);                 // each value's group is used once\n            }\n            next.push_back(i - 1);\n            next.push_back(i + 1);\n            for (int j : next)\n                if (0 <= j && j < n && dist[j] < 0) { dist[j] = dist[i] + 1; q.push(j); }\n        }\n        return -1;\n    }\n};",
 "jump-game-vi": "class Solution {\npublic:\n    int maxResult(vector<int>& nums, int k) {\n        int n = nums.size();\n        vector<int> dp(n);\n        dp[0] = nums[0];\n        deque<int> dq{0};                     // indices, dp values falling front to back\n        for (int i = 1; i < n; i++) {\n            if (dq.front() < i - k) dq.pop_front();\n            dp[i] = nums[i] + dp[dq.front()];\n            while (!dq.empty() && dp[dq.back()] <= dp[i]) dq.pop_back();\n            dq.push_back(i);\n        }\n        return dp[n - 1];\n    }\n};",
 "k-closest-points-to-origin": "class Solution {\npublic:\n    vector<vector<int>> kClosest(vector<vector<int>>& points, int k) {\n        priority_queue<tuple<int, int, int>> h;            // max-heap on distance keeps the k closest\n        for (auto& p : points) {\n            h.push({p[0] * p[0] + p[1] * p[1], p[0], p[1]});\n            if ((int)h.size() > k) h.pop();                // drop the farthest\n        }\n        vector<vector<int>> out;\n        for (; !h.empty(); h.pop()) out.push_back({get<1>(h.top()), get<2>(h.top())});\n        return out;\n    }\n};",
 "k-radius-subarray-averages": "class Solution {\npublic:\n    vector<int> getAverages(vector<int>& nums, int k) {\n        long long w = 2LL * k + 1, s = 0;   // window size, window sum\n        vector<int> out(nums.size(), -1);\n        for (int i = 0; i < (int)nums.size(); i++) {\n            s += nums[i];\n            if (i >= w) s -= nums[i - w];\n            if (i >= w - 1) out[i - k] = s / w;\n        }\n        return out;\n    }\n};",
 "k-similar-strings": "class Solution {\npublic:\n    int kSimilarity(string s1, string s2) {\n        queue<string> q;\n        q.push(s1);\n        unordered_set<string> seen{s1};\n        for (int steps = 0;; steps++) {          // BFS, one swap per level\n            for (int k = q.size(); k > 0; k--) {\n                string s = q.front();\n                q.pop();\n                if (s == s2) return steps;\n                int i = 0;\n                while (s[i] == s2[i]) i++;       // first wrong position\n                for (int j = i + 1; j < (int)s.size(); j++)\n                    if (s[j] == s2[i] && s[j] != s2[j]) {   // a swap that fixes position i\n                        string t = s;\n                        swap(t[i], t[j]);\n                        if (seen.insert(t).second) q.push(t);\n                    }\n            }\n        }\n    }\n};",
 "k-th-smallest-prime-fraction": "class Solution {\npublic:\n    vector<int> kthSmallestPrimeFraction(vector<int>& arr, int k) {\n        // (value, numerator index, denominator index); one row per denominator\n        priority_queue<tuple<double, int, int>, vector<tuple<double, int, int>>, greater<>> heap;\n        for (int j = 1; j < (int)arr.size(); j++) heap.push({(double)arr[0] / arr[j], 0, j});\n        for (int t = 0; t < k - 1; t++) {\n            auto [v, i, j] = heap.top();\n            heap.pop();\n            if (i + 1 < j) heap.push({(double)arr[i + 1] / arr[j], i + 1, j});\n        }\n        auto [v, i, j] = heap.top();\n        return {arr[i], arr[j]};\n    }\n};",
 "k-th-symbol-in-grammar": "class Solution {\npublic:\n    int kthGrammar(int n, int k) {\n        if (n == 1) return 0;\n        int parent = kthGrammar(n - 1, (k + 1) / 2);\n        return k % 2 == 1 ? parent : 1 - parent;   // left child copies, right child flips\n    }\n};",
 "keys-and-rooms": "class Solution {\npublic:\n    bool canVisitAllRooms(vector<vector<int>>& rooms) {\n        vector<bool> seen(rooms.size(), false);\n        seen[0] = true;\n        vector<int> stack{0};\n        int count = 1;\n        while (!stack.empty()) {\n            int r = stack.back();\n            stack.pop_back();\n            for (int key : rooms[r])\n                if (!seen[key]) {\n                    seen[key] = true;\n                    count++;\n                    stack.push_back(key);\n                }\n        }\n        return count == (int)rooms.size();\n    }\n};",
 "koko-eating-bananas": "class Solution {\npublic:\n    int minEatingSpeed(vector<int>& piles, int h) {\n        int lo = 1, hi = *max_element(piles.begin(), piles.end());\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            long long hours = 0;\n            for (int p : piles) hours += (p + (long long)mid - 1) / mid;   // ceil(p / mid)\n            if (hours <= h) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "kth-ancestor-of-a-tree-node": "class TreeAncestor {\n    vector<vector<int>> up;                                  // up[j][v] = 2^j-th ancestor of v, or -1\npublic:\n    TreeAncestor(int n, vector<int>& parent) {\n        up.push_back(parent);\n        for (int j = 1; (1 << j) <= n; j++) {\n            vector<int>& prev = up.back();\n            vector<int> row(n);\n            for (int v = 0; v < n; v++) row[v] = prev[v] == -1 ? -1 : prev[prev[v]];\n            up.push_back(row);\n        }\n    }\n\n    int getKthAncestor(int node, int k) {\n        for (int j = 0; k && node != -1; j++, k >>= 1)\n            if (k & 1) node = up[j][node];\n        return node;\n    }\n};",
 "kth-largest-element-in-a-stream": "class KthLargest {\n    int k;\n    priority_queue<int, vector<int>, greater<int>> heap;   // the k largest so far; the top is the k-th\n\npublic:\n    KthLargest(int k, vector<int>& nums) : k(k) {\n        for (int x : nums) add(x);\n    }\n\n    int add(int val) {\n        heap.push(val);\n        if ((int)heap.size() > k) heap.pop();            // drop the smallest\n        return heap.top();\n    }\n};",
 "kth-largest-element-in-an-array": "class Solution {\npublic:\n    int findKthLargest(vector<int>& nums, int k) {\n        priority_queue<int, vector<int>, greater<int>> h;  // min-heap of the k largest\n        for (int x : nums) {\n            h.push(x);\n            if ((int)h.size() > k) h.pop();\n        }\n        return h.top();\n    }\n};",
 "kth-largest-sum-in-a-binary-tree": "class Solution {\npublic:\n    long long kthLargestLevelSum(TreeNode* root, int k) {\n        vector<long long> sums;\n        queue<TreeNode*> q;\n        q.push(root);\n        while (!q.empty()) {                           // BFS, one level per round\n            long long s = 0;\n            for (int i = q.size(); i > 0; i--) {\n                TreeNode* n = q.front(); q.pop();\n                s += n->val;\n                if (n->left) q.push(n->left);\n                if (n->right) q.push(n->right);\n            }\n            sums.push_back(s);\n        }\n        if ((int)sums.size() < k) return -1;\n        sort(sums.rbegin(), sums.rend());\n        return sums[k - 1];\n    }\n};",
 "kth-smallest-element-in-a-bst": "class Solution {\npublic:\n    int kthSmallest(TreeNode* root, int k) {\n        stack<TreeNode*> st;\n        TreeNode* node = root;\n        while (true) {                                       // iterative inorder\n            for (; node; node = node->left) st.push(node);\n            node = st.top(); st.pop();\n            if (--k == 0) return node->val;\n            node = node->right;\n        }\n    }\n};",
 "kth-smallest-element-in-a-sorted-matrix": "class Solution {\npublic:\n    int kthSmallest(vector<vector<int>>& matrix, int k) {\n        int n = matrix.size();\n        auto count = [&](int x) {   // how many values are <= x, walking a staircase\n            int c = 0, j = n - 1;\n            for (auto& row : matrix) {\n                while (j >= 0 && row[j] > x) j--;\n                c += j + 1;\n            }\n            return c;\n        };\n        int lo = matrix[0][0], hi = matrix[n - 1][n - 1];\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (count(mid) >= k) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "kth-smallest-number-in-multiplication-table": "class Solution {\npublic:\n    int findKthNumber(int m, int n, int k) {\n        int lo = 1, hi = m * n;\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            int cnt = 0;\n            for (int i = 1; i <= m; i++) cnt += min(mid / i, n);   // values <= mid in row i\n            if (cnt >= k) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "largest-component-size-by-common-factor": "class Solution {\n    unordered_map<int, int> parent;\n    int find(int x) {\n        if (!parent.count(x)) parent[x] = x;\n        while (parent[x] != x) {\n            parent[x] = parent[parent[x]];\n            x = parent[x];\n        }\n        return x;\n    }\n    void unite(int a, int b) { parent[find(a)] = find(b); }\npublic:\n    int largestComponentSize(vector<int>& nums) {\n        for (int x : nums) {\n            int y = x;\n            for (int p = 2; p * p <= y; p++) {\n                if (y % p == 0) {\n                    unite(x, -p);          // primes stored as negative keys\n                    while (y % p == 0) y /= p;\n                }\n            }\n            if (y > 1) unite(x, -y);\n        }\n        unordered_map<int, int> size;\n        int best = 0;\n        for (int x : nums) best = max(best, ++size[find(x)]);\n        return best;\n    }\n};",
 "largest-divisible-subset": "class Solution {\npublic:\n    vector<int> largestDivisibleSubset(vector<int>& nums) {\n        sort(nums.begin(), nums.end());\n        int n = nums.size();\n        vector<int> size(n, 1), prev(n, -1);   // longest chain ending at i, and the link back\n        for (int i = 0; i < n; i++)\n            for (int j = 0; j < i; j++)\n                if (nums[i] % nums[j] == 0 && size[j] + 1 > size[i]) {\n                    size[i] = size[j] + 1;\n                    prev[i] = j;\n                }\n        int i = max_element(size.begin(), size.end()) - size.begin();\n        vector<int> out;\n        for (; i != -1; i = prev[i]) out.push_back(nums[i]);\n        reverse(out.begin(), out.end());\n        return out;\n    }\n};",
 "largest-number": "class Solution {\npublic:\n    string largestNumber(vector<int>& nums) {\n        vector<string> s;\n        for (int x : nums) s.push_back(to_string(x));\n        sort(s.begin(), s.end(), [](const string& a, const string& b) { return a + b > b + a; });   // a goes first if ab beats ba\n        if (s[0] == \"0\") return \"0\";\n        string out;\n        for (auto& x : s) out += x;\n        return out;\n    }\n};",
 "largest-rectangle-in-histogram": "class Solution {\npublic:\n    int largestRectangleArea(vector<int>& heights) {\n        vector<int> stack;                               // indexes with increasing heights\n        int best = 0, n = heights.size();\n        for (int i = 0; i <= n; i++) {\n            int h = i < n ? heights[i] : 0;              // a 0 at the end flushes the stack\n            while (!stack.empty() && heights[stack.back()] > h) {\n                int top = stack.back(); stack.pop_back();\n                int left = stack.empty() ? 0 : stack.back() + 1;\n                best = max(best, heights[top] * (i - left));   // widest bar of height heights[top]\n            }\n            stack.push_back(i);\n        }\n        return best;\n    }\n};",
 "largest-submatrix-with-rearrangements": "class Solution {\npublic:\n    int largestSubmatrix(vector<vector<int>>& matrix) {\n        int n = matrix[0].size(), best = 0;\n        vector<int> h(n, 0);\n        for (auto& row : matrix) {\n            for (int j = 0; j < n; j++) h[j] = row[j] ? h[j] + 1 : 0;   // run of 1s ending here\n            vector<int> s = h;\n            sort(s.rbegin(), s.rend());\n            for (int w = 1; w <= n; w++) best = max(best, w * s[w - 1]);\n        }\n        return best;\n    }\n};",
 "last-day-where-you-can-still-cross": "class Solution {\n    vector<int> parent;\n    int find(int x) {\n        while (parent[x] != x) {\n            parent[x] = parent[parent[x]];\n            x = parent[x];\n        }\n        return x;\n    }\npublic:\n    int latestDayToCross(int row, int col, vector<vector<int>>& cells) {\n        int n = row * col, TOP = n, BOT = n + 1;   // two virtual nodes for the top and bottom rows\n        parent.resize(n + 2);\n        iota(parent.begin(), parent.end(), 0);\n        vector<vector<bool>> land(row, vector<bool>(col, false));\n        const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        for (int d = cells.size() - 1; d >= 0; d--) {   // add land back, last day first\n            int r = cells[d][0] - 1, c = cells[d][1] - 1;\n            land[r][c] = true;\n            int u = r * col + c;\n            if (r == 0) parent[find(u)] = find(TOP);\n            if (r == row - 1) parent[find(u)] = find(BOT);\n            for (int k = 0; k < 4; k++) {\n                int nr = r + dr[k], nc = c + dc[k];\n                if (nr >= 0 && nr < row && nc >= 0 && nc < col && land[nr][nc]) parent[find(u)] = find(nr * col + nc);\n            }\n            if (find(TOP) == find(BOT)) return d;\n        }\n        return 0;\n    }\n};",
 "last-stone-weight": "class Solution {\npublic:\n    int lastStoneWeight(vector<int>& stones) {\n        priority_queue<int> heap(stones.begin(), stones.end());   // max-heap\n        while (heap.size() > 1) {\n            int y = heap.top(); heap.pop();\n            int x = heap.top(); heap.pop();\n            if (y != x) heap.push(y - x);\n        }\n        return heap.empty() ? 0 : heap.top();\n    }\n};",
 "last-stone-weight-ii": "class Solution {\npublic:\n    int lastStoneWeightII(vector<int>& stones) {\n        int total = accumulate(stones.begin(), stones.end(), 0);\n        set<int> reach{0};                                   // subset sums up to total / 2\n        for (int x : stones) {\n            vector<int> add;\n            for (int s : reach) if (s + x <= total / 2) add.push_back(s + x);\n            reach.insert(add.begin(), add.end());\n        }\n        return total - 2 * *reach.rbegin();                  // closest split to two equal piles\n    }\n};",
 "lemonade-change": "class Solution {\npublic:\n    bool lemonadeChange(vector<int>& bills) {\n        int five = 0, ten = 0;\n        for (int b : bills) {\n            if (b == 5) five++;\n            else if (b == 10) {\n                if (!five) return false;\n                five--; ten++;\n            }\n            else if (ten && five) { ten--; five--; }     // prefer giving a 10, keep the 5s\n            else if (five >= 3) five -= 3;\n            else return false;\n        }\n        return true;\n    }\n};",
 "length-of-last-word": "class Solution {\npublic:\n    int lengthOfLastWord(string s) {\n        int i = s.size() - 1;\n        while (s[i] == ' ') i--;                         // skip trailing spaces\n        int j = i;\n        while (j >= 0 && s[j] != ' ') j--;\n        return i - j;\n    }\n};",
 "length-of-longest-subarray-with-at-most-k-frequency": "class Solution {\npublic:\n    int maxSubarrayLength(vector<int>& nums, int k) {\n        unordered_map<int, int> count;\n        int left = 0, best = 0;\n        for (int right = 0; right < (int)nums.size(); right++) {\n            int x = nums[right];\n            count[x]++;\n            while (count[x] > k) count[nums[left++]]--;   // shrink until x is allowed again\n            best = max(best, right - left + 1);\n        }\n        return best;\n    }\n};",
 "letter-case-permutation": "class Solution {\npublic:\n    vector<string> letterCasePermutation(string s) {\n        vector<string> out{\"\"};\n        for (char c : s) {\n            vector<string> next;\n            for (auto& p : out) {\n                if (isalpha(c)) {   // a letter doubles the list\n                    next.push_back(p + (char)tolower(c));\n                    next.push_back(p + (char)toupper(c));\n                } else {\n                    next.push_back(p + c);\n                }\n            }\n            out = next;\n        }\n        return out;\n    }\n};",
 "lexicographical-numbers": "class Solution {\npublic:\n    vector<int> lexicalOrder(int n) {\n        vector<int> out;\n        int x = 1;\n        for (int k = 0; k < n; k++) {\n            out.push_back(x);\n            if ((long long)x * 10 <= n) {\n                x *= 10;   // go one digit deeper\n            } else {\n                while (x % 10 == 9 || x + 1 > n) x /= 10;   // climb back up\n                x++;\n            }\n        }\n        return out;\n    }\n};",
 "lexicographically-smallest-equivalent-string": "class Solution {\n    int parent[26];\n    int find(int x) {\n        while (parent[x] != x) {\n            parent[x] = parent[parent[x]];\n            x = parent[x];\n        }\n        return x;\n    }\npublic:\n    string smallestEquivalentString(string s1, string s2, string baseStr) {\n        iota(parent, parent + 26, 0);\n        for (size_t i = 0; i < s1.size(); i++) {\n            int ra = find(s1[i] - 'a'), rb = find(s2[i] - 'a');\n            if (ra != rb) parent[max(ra, rb)] = min(ra, rb);   // the smaller letter is the root\n        }\n        for (char& c : baseStr) c = 'a' + find(c - 'a');\n        return baseStr;\n    }\n};",
 "lfu-cache": "class LFUCache {\n    int cap, minFreq = 0;\n    unordered_map<int, pair<int, int>> key;               // key -> (value, uses)\n    unordered_map<int, list<int>> bucket;                 // uses -> keys, oldest first\n    unordered_map<int, list<int>::iterator> where;        // key -> its place in its bucket\n\n    void touch(int k) {\n        auto& [val, f] = key[k];\n        bucket[f].erase(where[k]);\n        if (bucket[f].empty()) {\n            bucket.erase(f);\n            if (minFreq == f) minFreq = f + 1;\n        }\n        f++;\n        bucket[f].push_back(k);\n        where[k] = prev(bucket[f].end());\n    }\n\npublic:\n    LFUCache(int capacity) : cap(capacity) {}\n\n    int get(int k) {\n        if (!key.count(k)) return -1;\n        touch(k);\n        return key[k].first;\n    }\n\n    void put(int k, int value) {\n        if (cap == 0) return;\n        if (key.count(k)) {\n            key[k].first = value;\n            touch(k);\n            return;\n        }\n        if ((int)key.size() == cap) {\n            int old = bucket[minFreq].front();\n            bucket[minFreq].pop_front();\n            if (bucket[minFreq].empty()) bucket.erase(minFreq);\n            key.erase(old);\n            where.erase(old);\n        }\n        key[k] = {value, 1};\n        bucket[1].push_back(k);\n        where[k] = prev(bucket[1].end());\n        minFreq = 1;\n    }\n};",
 "linked-list-cycle": "class Solution {\npublic:\n    bool hasCycle(ListNode* head) {\n        ListNode *slow = head, *fast = head;\n        while (fast && fast->next) {\n            slow = slow->next;\n            fast = fast->next->next;\n            if (slow == fast) return true;               // the fast pointer lapped the slow one\n        }\n        return false;\n    }\n};",
 "linked-list-cycle-ii": "class Solution {\npublic:\n    ListNode* detectCycle(ListNode* head) {\n        ListNode *slow = head, *fast = head;\n        while (fast && fast->next) {\n            slow = slow->next;\n            fast = fast->next->next;\n            if (slow == fast) {\n                // head and the meeting point are the same distance from the cycle start\n                slow = head;\n                while (slow != fast) {\n                    slow = slow->next;\n                    fast = fast->next;\n                }\n                return slow;\n            }\n        }\n        return nullptr;\n    }\n};",
 "longest-common-prefix": "class Solution {\npublic:\n    string longestCommonPrefix(vector<string>& strs) {\n        size_t shortest = strs[0].size();\n        for (auto& s : strs) shortest = min(shortest, s.size());\n        for (size_t i = 0; i < shortest; i++)            // compare column by column\n            for (auto& s : strs)\n                if (s[i] != strs[0][i]) return strs[0].substr(0, i);\n        return strs[0].substr(0, shortest);\n    }\n};",
 "longest-common-subsequence": "class Solution {\npublic:\n    int longestCommonSubsequence(string text1, string text2) {\n        int m = text1.size(), n = text2.size();\n        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++)\n                dp[i + 1][j + 1] = text1[i] == text2[j] ? dp[i][j] + 1 : max(dp[i][j + 1], dp[i + 1][j]);\n        return dp[m][n];\n    }\n};",
 "longest-consecutive-sequence": "class Solution {\npublic:\n    int longestConsecutive(vector<int>& nums) {\n        unordered_set<int> s(nums.begin(), nums.end());\n        int best = 0;\n        for (int x : s)\n            if (!s.count(x - 1)) {                         // x starts a run\n                int y = x;\n                while (s.count(y + 1)) y++;\n                best = max(best, y - x + 1);\n            }\n        return best;\n    }\n};",
 "longest-continuous-subarray-with-absolute-diff-less-than-or-equal-to-limit": "class Solution {\npublic:\n    int longestSubarray(vector<int>& nums, int limit) {\n        deque<int> mx, mn;   // values, decreasing / increasing\n        int L = 0, best = 0;\n        for (int R = 0; R < (int)nums.size(); R++) {\n            int x = nums[R];\n            while (!mx.empty() && mx.back() < x) mx.pop_back();\n            while (!mn.empty() && mn.back() > x) mn.pop_back();\n            mx.push_back(x); mn.push_back(x);\n            if (mx.front() - mn.front() > limit) {   // slide the window by one\n                if (mx.front() == nums[L]) mx.pop_front();\n                if (mn.front() == nums[L]) mn.pop_front();\n                L++;\n            }\n            best = max(best, R - L + 1);\n        }\n        return best;\n    }\n};",
 "longest-cycle-in-a-graph": "class Solution {\npublic:\n    int longestCycle(vector<int>& edges) {\n        int n = edges.size();\n        vector<int> stamp(n, 0);   // time each node was first visited\n        int t = 1, best = -1;\n        for (int s = 0; s < n; s++) {\n            if (stamp[s]) continue;\n            int first = t, u = s;\n            while (u != -1 && !stamp[u]) {\n                stamp[u] = t++;\n                u = edges[u];\n            }\n            if (u != -1 && stamp[u] >= first) best = max(best, t - stamp[u]);   // met this walk again\n        }\n        return best;\n    }\n};",
 "longest-duplicate-substring": "class Solution {\n    using u64 = unsigned long long;\n    static constexpr u64 MOD = (1ULL << 61) - 1, B = 131;\n    static u64 mul(u64 a, u64 b) { return (unsigned __int128)a * b % MOD; }   // 128-bit product, no overflow\n\n    // start of a repeated substring of length L, or -1\n    int dup(const string& s, int L) {\n        u64 h = 0, p = 1;\n        for (int k = 0; k < L; k++) p = mul(p, B);   // B^L, the weight of the char leaving the window\n        unordered_map<u64, vector<int>> seen;\n        for (int i = 0; i < (int)s.size(); i++) {\n            h = (mul(h, B) + (unsigned char)s[i]) % MOD;\n            if (i >= L) h = (h + MOD - mul((unsigned char)s[i - L], p)) % MOD;\n            if (i >= L - 1) {\n                int st = i - L + 1;\n                auto& bucket = seen[h];\n                for (int j : bucket)\n                    if (s.compare(j, L, s, st, L) == 0) return st;   // confirm, hashes can collide\n                bucket.push_back(st);\n            }\n        }\n        return -1;\n    }\n\npublic:\n    string longestDupSubstring(string s) {\n        int lo = 1, hi = s.size() - 1;\n        string best;\n        while (lo <= hi) {   // a repeat of length L means one of every shorter length too\n            int mid = (lo + hi) / 2, st = dup(s, mid);\n            if (st >= 0) { best = s.substr(st, mid); lo = mid + 1; }\n            else hi = mid - 1;\n        }\n        return best;\n    }\n};",
 "longest-ideal-subsequence": "class Solution {\npublic:\n    int longestIdealString(string s, int k) {\n        array<int, 26> dp{};   // dp[c] = longest ideal subsequence ending in letter c\n        for (char ch : s) {\n            int c = ch - 'a';\n            int best = 0;\n            for (int d = max(0, c - k); d <= min(25, c + k); d++) best = max(best, dp[d]);\n            dp[c] = best + 1;\n        }\n        return *max_element(dp.begin(), dp.end());\n    }\n};",
 "longest-increasing-subsequence": "class Solution {\npublic:\n    int lengthOfLIS(vector<int>& nums) {\n        vector<int> tails;                                   // tails[k]: smallest tail of a run of length k+1\n        for (int x : nums) {\n            auto it = lower_bound(tails.begin(), tails.end(), x);\n            if (it == tails.end()) tails.push_back(x);\n            else *it = x;\n        }\n        return tails.size();\n    }\n};",
 "longest-mountain-in-array": "class Solution {\npublic:\n    int longestMountain(vector<int>& arr) {\n        int best = 0, up = 0, down = 0;\n        for (int i = 1; i < (int)arr.size(); i++) {\n            if ((down && arr[i] > arr[i - 1]) || arr[i] == arr[i - 1]) up = down = 0;   // a new mountain starts\n            if (arr[i] > arr[i - 1]) up++;\n            else if (arr[i] < arr[i - 1]) down++;\n            if (up && down) best = max(best, up + down + 1);\n        }\n        return best;\n    }\n};",
 "longest-nice-subarray": "class Solution {\npublic:\n    int longestNiceSubarray(vector<int>& nums) {\n        int used = 0, L = 0, best = 0;   // used = OR of the window\n        for (int R = 0; R < (int)nums.size(); R++) {\n            int x = nums[R];\n            while (used & x) {           // a shared bit: drop from the left\n                used ^= nums[L];\n                L++;\n            }\n            used |= x;\n            best = max(best, R - L + 1);\n        }\n        return best;\n    }\n};",
 "longest-palindrome-by-concatenating-two-letter-words": "class Solution {\npublic:\n    int longestPalindrome(vector<string>& words) {\n        unordered_map<string, int> cnt;\n        for (auto& w : words) cnt[w]++;\n        int ans = 0;\n        bool center = false;\n        for (auto& [w, k] : cnt) {\n            if (w[0] == w[1]) {\n                ans += k / 2 * 4;          // pairs of \"gg\" go on both sides\n                if (k % 2) center = true;  // one left over can sit in the middle\n            } else {\n                string r(w.rbegin(), w.rend());\n                if (w < r && cnt.count(r)) ans += min(k, cnt[r]) * 4;\n            }\n        }\n        return ans + (center ? 2 : 0);\n    }\n};",
 "longest-palindromic-subsequence": "class Solution {\npublic:\n    int longestPalindromeSubseq(string s) {\n        int n = s.size();\n        vector<vector<int>> dp(n, vector<int>(n, 0));    // dp[i][j]: answer for s[i..j]\n        for (int i = n - 1; i >= 0; i--) {\n            dp[i][i] = 1;\n            for (int j = i + 1; j < n; j++)\n                dp[i][j] = s[i] == s[j] ? dp[i + 1][j - 1] + 2 : max(dp[i + 1][j], dp[i][j - 1]);\n        }\n        return dp[0][n - 1];\n    }\n};",
 "longest-palindromic-substring": "class Solution {\npublic:\n    string longestPalindrome(string s) {\n        int n = s.size(), bestL = 0, bestLen = 0;\n        for (int c = 0; c < n; c++)\n            for (auto [l, r] : {pair{c, c}, pair{c, c + 1}}) {   // odd and even centres\n                while (l >= 0 && r < n && s[l] == s[r]) { l--; r++; }\n                if (r - l - 1 > bestLen) { bestLen = r - l - 1; bestL = l + 1; }\n            }\n        return s.substr(bestL, bestLen);\n    }\n};",
 "longest-path-with-different-adjacent-characters": "class Solution {\npublic:\n    int longestPath(vector<int>& parent, string s) {\n        int n = parent.size();\n        vector<vector<int>> kids(n);\n        for (int i = 1; i < n; i++) kids[parent[i]].push_back(i);\n        vector<int> order{0};                                    // BFS order, parents first\n        for (size_t i = 0; i < order.size(); i++)\n            for (int v : kids[order[i]]) order.push_back(v);\n        vector<int> down(n, 1);\n        int best = 1;\n        for (int k = n - 1; k >= 0; k--) {\n            int u = order[k], a = 0, b = 0;                      // two longest legs\n            for (int v : kids[u]) {\n                if (s[v] == s[u]) continue;\n                if (down[v] > a) { b = a; a = down[v]; }\n                else if (down[v] > b) b = down[v];\n            }\n            down[u] = 1 + a;\n            best = max(best, 1 + a + b);\n        }\n        return best;\n    }\n};",
 "longest-repeating-character-replacement": "class Solution {\npublic:\n    int characterReplacement(string s, int k) {\n        int count[26] = {};\n        int best = 0, maxf = 0, l = 0;\n        for (int r = 0; r < (int)s.size(); r++) {\n            maxf = max(maxf, ++count[s[r] - 'A']);\n            if (r - l + 1 - maxf > k) { count[s[l] - 'A']--; l++; }   // too many to replace: slide\n            best = max(best, r - l + 1);\n        }\n        return best;\n    }\n};",
 "longest-subarray-with-maximum-bitwise-and": "class Solution {\npublic:\n    int longestSubarray(vector<int>& nums) {\n        int mx = *max_element(nums.begin(), nums.end());\n        int best = 0, run = 0;\n        for (int x : nums) {\n            run = x == mx ? run + 1 : 0;   // longest run of the maximum\n            best = max(best, run);\n        }\n        return best;\n    }\n};",
 "longest-substring-with-at-least-k-repeating-characters": "class Solution {\npublic:\n    int longestSubstring(string s, int k) {\n        if ((int)s.size() < k) return 0;\n        int cnt[26] = {};\n        for (char c : s) cnt[c - 'a']++;\n        for (char c : s)\n            if (cnt[c - 'a'] < k) {   // c can never be in the answer: split around it\n                int best = 0;\n                string part;\n                stringstream ss(s);\n                while (getline(ss, part, c)) best = max(best, longestSubstring(part, k));\n                return best;\n            }\n        return s.size();\n    }\n};",
 "longest-substring-without-repeating-characters": "class Solution {\npublic:\n    int lengthOfLongestSubstring(string s) {\n        unordered_map<char, int> last;                     // last index of each character\n        int l = 0, best = 0;\n        for (int r = 0; r < (int)s.size(); r++) {\n            auto it = last.find(s[r]);\n            if (it != last.end() && it->second >= l) l = it->second + 1;   // jump past the repeat\n            last[s[r]] = r;\n            best = max(best, r - l + 1);\n        }\n        return best;\n    }\n};",
 "longest-univalue-path": "class Solution {\npublic:\n    int longestUnivaluePath(TreeNode* root) {\n        int best = 0;\n        // longest same-value arm going down from node\n        function<int(TreeNode*)> arm = [&](TreeNode* node) {\n            if (!node) return 0;\n            int l = arm(node->left), r = arm(node->right);\n            l = node->left && node->left->val == node->val ? l + 1 : 0;\n            r = node->right && node->right->val == node->val ? r + 1 : 0;\n            best = max(best, l + r);                   // a path may bend here\n            return max(l, r);\n        };\n        arm(root);\n        return best;\n    }\n};",
 "longest-valid-parentheses": "class Solution {\npublic:\n    int longestValidParentheses(string s) {\n        vector<int> st{-1};          // bottom: index just before the current valid run\n        int best = 0;\n        for (int i = 0; i < (int)s.size(); i++) {\n            if (s[i] == '(') st.push_back(i);\n            else {\n                st.pop_back();\n                if (st.empty()) st.push_back(i);   // unmatched ')' starts a new base\n                else best = max(best, i - st.back());\n            }\n        }\n        return best;\n    }\n};",
 "longest-well-performing-interval": "class Solution {\npublic:\n    int longestWPI(vector<int>& hours) {\n        unordered_map<int, int> first;   // prefix score -> first index it appeared\n        int s = 0, best = 0;\n        for (int i = 0; i < (int)hours.size(); i++) {\n            s += hours[i] > 8 ? 1 : -1;\n            if (s > 0) best = i + 1;\n            else if (auto it = first.find(s - 1); it != first.end()) best = max(best, i - it->second);\n            first.emplace(s, i);         // keeps the earliest index only\n        }\n        return best;\n    }\n};",
 "longest-word-in-dictionary": "class Solution {\npublic:\n    string longestWord(vector<string>& words) {\n        sort(words.begin(), words.end());                // a word comes after all its prefixes\n        unordered_set<string> built = {\"\"};\n        string best;\n        for (auto& w : words)\n            if (built.count(w.substr(0, w.size() - 1))) {\n                built.insert(w);\n                if (w.size() > best.size()) best = w;\n            }\n        return best;\n    }\n};",
 "lowest-common-ancestor-of-a-binary-search-tree": "class Solution {\npublic:\n    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n        TreeNode* node = root;\n        while (node) {\n            if (p->val < node->val && q->val < node->val) node = node->left;         // both on the left\n            else if (p->val > node->val && q->val > node->val) node = node->right;   // both on the right\n            else return node;                                // they split here\n        }\n        return nullptr;\n    }\n};",
 "lowest-common-ancestor-of-a-binary-tree": "class Solution {\npublic:\n    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n        if (!root || root == p || root == q) return root;\n        TreeNode* L = lowestCommonAncestor(root->left, p, q);\n        TreeNode* R = lowestCommonAncestor(root->right, p, q);\n        if (L && R) return root;   // p and q are on different sides\n        return L ? L : R;\n    }\n};",
 "lru-cache": "class LRUCache {\n    struct Node {\n        int key, val;\n        Node *prev = nullptr, *next = nullptr;\n    };\n    int cap;\n    unordered_map<int, Node*> map;\n    Node head{0, 0}, tail{0, 0};\n\n    void unlink(Node* node) {\n        node->prev->next = node->next;\n        node->next->prev = node->prev;\n    }\n    void pushFront(Node* node) {\n        node->prev = &head;\n        node->next = head.next;\n        head.next->prev = node;\n        head.next = node;\n    }\n\npublic:\n    LRUCache(int capacity) : cap(capacity) {\n        head.next = &tail;\n        tail.prev = &head;\n    }\n    ~LRUCache() {\n        for (auto& [k, node] : map) delete node;\n    }\n\n    int get(int key) {\n        auto it = map.find(key);\n        if (it == map.end()) return -1;\n        unlink(it->second);\n        pushFront(it->second);\n        return it->second->val;\n    }\n\n    void put(int key, int value) {\n        auto it = map.find(key);\n        if (it != map.end()) {\n            it->second->val = value;\n            unlink(it->second);\n            pushFront(it->second);\n            return;\n        }\n        Node* node = new Node{key, value};\n        map[key] = node;\n        pushFront(node);\n        if ((int)map.size() > cap) {\n            Node* lru = tail.prev;\n            unlink(lru);\n            map.erase(lru->key);\n            delete lru;\n        }\n    }\n};",
 "magnetic-force-between-two-balls": "class Solution {\npublic:\n    int maxDistance(vector<int>& position, int m) {\n        sort(position.begin(), position.end());\n        auto fits = [&](int d) {                 // can m balls be at least d apart?\n            int count = 1, last = position[0];\n            for (size_t i = 1; i < position.size(); i++)\n                if (position[i] - last >= d) { count++; last = position[i]; }\n            return count >= m;\n        };\n        int lo = 1, hi = position.back() - position[0];\n        while (lo < hi) {\n            int mid = lo + (hi - lo + 1) / 2;    // round up so lo = mid moves\n            if (fits(mid)) lo = mid;\n            else hi = mid - 1;\n        }\n        return lo;\n    }\n};",
 "majority-element": "class Solution {\npublic:\n    int majorityElement(vector<int>& nums) {\n        int cand = 0, count = 0;\n        for (int x : nums) {\n            if (count == 0) cand = x;                      // Boyer-Moore vote\n            count += x == cand ? 1 : -1;\n        }\n        return cand;\n    }\n};",
 "majority-element-ii": "class Solution {\npublic:\n    vector<int> majorityElement(vector<int>& nums) {\n        optional<int> c1, c2;   // two candidates (Boyer-Moore voting)\n        int n1 = 0, n2 = 0;\n        for (int x : nums) {\n            if (c1 == x) n1++;\n            else if (c2 == x) n2++;\n            else if (n1 == 0) { c1 = x; n1 = 1; }\n            else if (n2 == 0) { c2 = x; n2 = 1; }\n            else { n1--; n2--; }\n        }\n        vector<int> out;\n        for (auto c : {c1, c2})   // confirm with a real count\n            if (c && count(nums.begin(), nums.end(), *c) > (int)nums.size() / 3) out.push_back(*c);\n        return out;\n    }\n};",
 "make-string-a-subsequence-using-cyclic-increments": "class Solution {\npublic:\n    bool canMakeSubsequence(string str1, string str2) {\n        size_t j = 0;\n        for (char c : str1) {\n            char next = (c - 'a' + 1) % 26 + 'a';   // c after one cyclic increment\n            if (j < str2.size() && (c == str2[j] || next == str2[j])) j++;\n        }\n        return j == str2.size();\n    }\n};",
 "make-sum-divisible-by-p": "class Solution {\npublic:\n    int minSubarray(vector<int>& nums, int p) {\n        long long total = 0;\n        for (int x : nums) total += x;\n        int r = total % p;\n        if (r == 0) return 0;\n        int n = nums.size(), cur = 0, best = n;\n        unordered_map<int, int> last{{0, -1}};   // prefix remainder -> latest index\n        for (int i = 0; i < n; i++) {\n            cur = (cur + nums[i]) % p;\n            if (auto it = last.find(((cur - r) % p + p) % p); it != last.end())\n                best = min(best, i - it->second);\n            last[cur] = i;\n        }\n        return best < n ? best : -1;\n    }\n};",
 "making-a-large-island": "class Solution {\npublic:\n    int largestIsland(vector<vector<int>>& grid) {\n        int n = grid.size(), label = 2;\n        unordered_map<int, int> size;            // island label -> its area\n        const int dy[] = {1, -1, 0, 0}, dx[] = {0, 0, 1, -1};\n        for (int r = 0; r < n; r++)\n            for (int c = 0; c < n; c++) {\n                if (grid[r][c] != 1) continue;\n                grid[r][c] = label;               // flood fill with a new label\n                vector<pair<int, int>> stack{{r, c}};\n                int cnt = 0;\n                while (!stack.empty()) {\n                    auto [y, x] = stack.back();\n                    stack.pop_back();\n                    cnt++;\n                    for (int d = 0; d < 4; d++) {\n                        int ny = y + dy[d], nx = x + dx[d];\n                        if (ny >= 0 && ny < n && nx >= 0 && nx < n && grid[ny][nx] == 1) {\n                            grid[ny][nx] = label;\n                            stack.push_back({ny, nx});\n                        }\n                    }\n                }\n                size[label++] = cnt;\n            }\n        int best = 0;\n        for (auto& [l, s] : size) best = max(best, s);\n        for (int r = 0; r < n; r++)\n            for (int c = 0; c < n; c++) {\n                if (grid[r][c] != 0) continue;\n                set<int> ids;                     // distinct islands touching this water cell\n                for (int d = 0; d < 4; d++) {\n                    int y = r + dy[d], x = c + dx[d];\n                    if (y >= 0 && y < n && x >= 0 && x < n && grid[y][x] > 1) ids.insert(grid[y][x]);\n                }\n                int total = 1;\n                for (int i : ids) total += size[i];\n                best = max(best, total);\n            }\n        return best;\n    }\n};",
 "map-sum-pairs": "class MapSum {\n    struct Node {\n        unordered_map<char, Node*> next;\n        int sum = 0;   // total value of keys through this node\n    };\n    Node root;\n    unordered_map<string, int> vals;\n\npublic:\n    MapSum() {}\n\n    void insert(string key, int val) {\n        int delta = val - vals[key];   // an existing key only adds the change\n        vals[key] = val;\n        Node* node = &root;\n        for (char c : key) {\n            Node*& nxt = node->next[c];\n            if (!nxt) nxt = new Node();\n            node = nxt;\n            node->sum += delta;\n        }\n    }\n\n    int sum(string prefix) {\n        Node* node = &root;\n        for (char c : prefix) {\n            auto it = node->next.find(c);\n            if (it == node->next.end()) return 0;\n            node = it->second;\n        }\n        return node->sum;\n    }\n};",
 "matrix-block-sum": "class Solution {\npublic:\n    vector<vector<int>> matrixBlockSum(vector<vector<int>>& mat, int k) {\n        int m = mat.size(), n = mat[0].size();\n        vector<vector<int>> P(m + 1, vector<int>(n + 1, 0));   // P[i][j] = sum of mat[0..i-1][0..j-1]\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++) P[i + 1][j + 1] = mat[i][j] + P[i][j + 1] + P[i + 1][j] - P[i][j];\n        vector<vector<int>> out(m, vector<int>(n));\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++) {\n                int r1 = max(0, i - k), c1 = max(0, j - k);           // block clipped to the grid\n                int r2 = min(m, i + k + 1), c2 = min(n, j + k + 1);\n                out[i][j] = P[r2][c2] - P[r1][c2] - P[r2][c1] + P[r1][c1];\n            }\n        return out;\n    }\n};",
 "max-area-of-island": "class Solution {\n    int area(vector<vector<int>>& grid, int r, int c) {\n        if (r < 0 || r >= (int)grid.size() || c < 0 || c >= (int)grid[0].size() || grid[r][c] != 1) return 0;\n        grid[r][c] = 0;                                  // sink it so it is counted once\n        return 1 + area(grid, r + 1, c) + area(grid, r - 1, c) + area(grid, r, c + 1) + area(grid, r, c - 1);\n    }\n\npublic:\n    int maxAreaOfIsland(vector<vector<int>>& grid) {\n        int best = 0;\n        for (int r = 0; r < (int)grid.size(); r++)\n            for (int c = 0; c < (int)grid[0].size(); c++) best = max(best, area(grid, r, c));\n        return best;\n    }\n};",
 "max-chunks-to-make-sorted": "class Solution {\npublic:\n    int maxChunksToSorted(vector<int>& arr) {\n        int mx = 0, ans = 0;\n        for (int i = 0; i < (int)arr.size(); i++) {\n            mx = max(mx, arr[i]);\n            if (mx == i) ans++;   // everything so far fits in 0..i\n        }\n        return ans;\n    }\n};",
 "max-consecutive-ones-iii": "class Solution {\npublic:\n    int longestOnes(vector<int>& nums, int k) {\n        int L = 0, zeros = 0, best = 0;\n        for (int R = 0; R < (int)nums.size(); R++) {\n            zeros += nums[R] == 0;\n            while (zeros > k) {          // too many flips: drop from the left\n                zeros -= nums[L] == 0;\n                L++;\n            }\n            best = max(best, R - L + 1);\n        }\n        return best;\n    }\n};",
 "max-number-of-k-sum-pairs": "class Solution {\npublic:\n    int maxOperations(vector<int>& nums, int k) {\n        sort(nums.begin(), nums.end());\n        int i = 0, j = nums.size() - 1, ops = 0;\n        while (i < j) {\n            long long s = (long long)nums[i] + nums[j];\n            if (s == k) { ops++; i++; j--; }\n            else if (s < k) i++;   // need a bigger sum\n            else j--;\n        }\n        return ops;\n    }\n};",
 "max-sum-of-a-pair-with-equal-sum-of-digits": "class Solution {\npublic:\n    int maximumSum(vector<int>& nums) {\n        unordered_map<int, int> best;   // digit sum -> largest number seen with it\n        int ans = -1;\n        for (int x : nums) {\n            int d = 0;\n            for (int y = x; y; y /= 10) d += y % 10;\n            auto it = best.find(d);\n            if (it != best.end()) {\n                ans = max(ans, it->second + x);\n                it->second = max(it->second, x);\n            } else {\n                best[d] = x;\n            }\n        }\n        return ans;\n    }\n};",
 "maximal-square": "class Solution {\npublic:\n    int maximalSquare(vector<vector<char>>& matrix) {\n        int R = matrix.size(), C = matrix[0].size(), best = 0;\n        vector<vector<int>> dp(R + 1, vector<int>(C + 1, 0));   // side of the largest square ending at (i, j)\n        for (int i = 0; i < R; i++)\n            for (int j = 0; j < C; j++)\n                if (matrix[i][j] == '1') {\n                    dp[i + 1][j + 1] = 1 + min({dp[i][j], dp[i][j + 1], dp[i + 1][j]});\n                    best = max(best, dp[i + 1][j + 1]);\n                }\n        return best * best;\n    }\n};",
 "maximize-distance-to-closest-person": "class Solution {\npublic:\n    int maxDistToClosest(vector<int>& seats) {\n        int prev = -1, best = 0;\n        for (int i = 0; i < (int)seats.size(); i++)\n            if (seats[i]) {\n                best = prev < 0 ? i : max(best, (i - prev) / 2);   // leading gap, or middle of a gap\n                prev = i;\n            }\n        return max(best, (int)seats.size() - 1 - prev);   // trailing gap\n    }\n};",
 "maximize-happiness-of-selected-children": "class Solution {\npublic:\n    long long maximumHappinessSum(vector<int>& happiness, int k) {\n        sort(happiness.rbegin(), happiness.rend());   // happiest first\n        long long total = 0;\n        for (int i = 0; i < k; i++) total += max(happiness[i] - i, 0);   // each earlier pick costs 1\n        return total;\n    }\n};",
 "maximize-the-confusion-of-an-exam": "class Solution {\npublic:\n    int maxConsecutiveAnswers(string answerKey, int k) {\n        int t = 0, f = 0, left = 0, best = 0;\n        for (int right = 0; right < (int)answerKey.size(); right++) {\n            (answerKey[right] == 'T' ? t : f)++;\n            while (min(t, f) > k) {              // too many of the minority answer to flip\n                (answerKey[left] == 'T' ? t : f)--;\n                left++;\n            }\n            best = max(best, right - left + 1);\n        }\n        return best;\n    }\n};",
 "maximum-area-of-a-piece-of-cake-after-horizontal-and-vertical-cuts": "class Solution {\n    long long widest(vector<int>& cuts, int size) {\n        sort(cuts.begin(), cuts.end());\n        int best = max(cuts[0], size - cuts.back());   // pieces at the two edges\n        for (size_t i = 1; i < cuts.size(); i++) best = max(best, cuts[i] - cuts[i - 1]);\n        return best;\n    }\npublic:\n    int maxArea(int h, int w, vector<int>& horizontalCuts, vector<int>& verticalCuts) {\n        return widest(horizontalCuts, h) * widest(verticalCuts, w) % 1'000'000'007;\n    }\n};",
 "maximum-average-subarray-i": "class Solution {\npublic:\n    double findMaxAverage(vector<int>& nums, int k) {\n        int s = accumulate(nums.begin(), nums.begin() + k, 0), best = s;\n        for (int i = k; i < (int)nums.size(); i++) {\n            s += nums[i] - nums[i - k];                    // slide the window by one\n            best = max(best, s);\n        }\n        return (double)best / k;\n    }\n};",
 "maximum-bags-with-full-capacity-of-rocks": "class Solution {\npublic:\n    int maximumBags(vector<int>& capacity, vector<int>& rocks, int additionalRocks) {\n        vector<int> gaps;\n        for (size_t i = 0; i < capacity.size(); i++) gaps.push_back(capacity[i] - rocks[i]);\n        sort(gaps.begin(), gaps.end());   // fill the nearly full bags first\n        int full = 0;\n        for (int gap : gaps) {\n            if (gap > additionalRocks) break;\n            additionalRocks -= gap;\n            full++;\n        }\n        return full;\n    }\n};",
 "maximum-binary-tree": "class Solution {\n    TreeNode* build(vector<int>& nums, int lo, int hi) {   // nums[lo..hi)\n        if (lo >= hi) return nullptr;\n        int i = max_element(nums.begin() + lo, nums.begin() + hi) - nums.begin();   // the maximum is the root\n        return new TreeNode(nums[i], build(nums, lo, i), build(nums, i + 1, hi));\n    }\npublic:\n    TreeNode* constructMaximumBinaryTree(vector<int>& nums) {\n        return build(nums, 0, nums.size());\n    }\n};",
 "maximum-candies-allocated-to-k-children": "class Solution {\npublic:\n    int maximumCandies(vector<int>& candies, long long k) {\n        int lo = 0, hi = *max_element(candies.begin(), candies.end());\n        while (lo < hi) {\n            int mid = lo + (hi - lo + 1) / 2;\n            long long piles = 0;\n            for (int c : candies) piles += c / mid;   // piles of size mid we can make\n            if (piles >= k) lo = mid;\n            else hi = mid - 1;\n        }\n        return lo;\n    }\n};",
 "maximum-depth-of-binary-tree": "class Solution {\npublic:\n    int maxDepth(TreeNode* root) {\n        if (!root) return 0;\n        return 1 + max(maxDepth(root->left), maxDepth(root->right));\n    }\n};",
 "maximum-difference-between-node-and-ancestor": "class Solution {\npublic:\n    int maxAncestorDiff(TreeNode* root) {\n        // carry the smallest and largest value on the path down\n        function<int(TreeNode*, int, int)> go = [&](TreeNode* node, int lo, int hi) {\n            if (!node) return hi - lo;\n            lo = min(lo, node->val);\n            hi = max(hi, node->val);\n            return max(go(node->left, lo, hi), go(node->right, lo, hi));\n        };\n        return go(root, root->val, root->val);\n    }\n};",
 "maximum-employees-to-be-invited-to-a-meeting": "class Solution {\npublic:\n    int maximumInvitations(vector<int>& favorite) {\n        int n = favorite.size();\n        vector<int> indeg(n, 0), chain(n, 0);\n        for (int f : favorite) indeg[f]++;\n        queue<int> q;\n        for (int i = 0; i < n; i++) if (!indeg[i]) q.push(i);\n        while (!q.empty()) {                                 // peel the trees hanging into the cycles\n            int u = q.front(); q.pop();\n            int v = favorite[u];\n            chain[v] = max(chain[v], chain[u] + 1);\n            if (--indeg[v] == 0) q.push(v);\n        }\n        int big = 0, pairs = 0;\n        for (int i = 0; i < n; i++) {\n            if (!indeg[i]) continue;\n            int len = 0;\n            for (int j = i; indeg[j]; j = favorite[j]) { indeg[j] = 0; len++; }\n            if (len == 2) pairs += 2 + chain[i] + chain[favorite[i]];\n            else big = max(big, len);\n        }\n        return max(big, pairs);\n    }\n};",
 "maximum-erasure-value": "class Solution {\npublic:\n    int maximumUniqueSubarray(vector<int>& nums) {\n        unordered_set<int> seen;\n        int left = 0, cur = 0, best = 0;\n        for (int x : nums) {\n            while (seen.count(x)) {   // shrink until x is unique in the window\n                seen.erase(nums[left]);\n                cur -= nums[left++];\n            }\n            seen.insert(x);\n            cur += x;\n            best = max(best, cur);\n        }\n        return best;\n    }\n};",
 "maximum-frequency-stack": "class FreqStack {\n    unordered_map<int, int> freq;                        // value to its count\n    unordered_map<int, vector<int>> group;               // count to the values pushed at that count, in order\n    int top = 0;                                         // highest count right now\n\npublic:\n    FreqStack() {}\n\n    void push(int val) {\n        int f = ++freq[val];\n        top = max(top, f);\n        group[f].push_back(val);\n    }\n\n    int pop() {\n        int val = group[top].back();                     // most frequent, latest pushed among ties\n        group[top].pop_back();\n        freq[val]--;\n        if (group[top].empty()) top--;\n        return val;\n    }\n};",
 "maximum-fruits-harvested-after-at-most-k-steps": "class Solution {\npublic:\n    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {\n        int best = 0, total = 0, l = 0, n = fruits.size();\n        for (auto& f : fruits) {\n            int pr = f[0];\n            total += f[1];\n            while (l < n) {\n                int pl = fruits[l][0];\n                // the window [pl, pr] is reachable: walk it once plus the shorter way to one end\n                if (pl > pr || (pr - pl) + min(abs(startPos - pl), abs(pr - startPos)) <= k) break;\n                total -= fruits[l++][1];\n            }\n            best = max(best, total);\n        }\n        return best;\n    }\n};",
 "maximum-gap": "class Solution {\npublic:\n    int maximumGap(vector<int>& nums) {\n        int n = nums.size();\n        auto [lo_it, hi_it] = minmax_element(nums.begin(), nums.end());\n        int lo = *lo_it, hi = *hi_it;\n        if (n < 2 || lo == hi) return 0;\n        int size = max(1, (hi - lo) / (n - 1));   // the answer is at least this, so no gap hides inside a bucket\n        int m = (hi - lo) / size + 1;\n        vector<int> bmin(m, INT_MAX), bmax(m, INT_MIN);\n        for (int x : nums) {\n            int b = (x - lo) / size;\n            bmin[b] = min(bmin[b], x);\n            bmax[b] = max(bmax[b], x);\n        }\n        int best = 0, prev = lo;\n        for (int b = 0; b < m; b++) {\n            if (bmin[b] == INT_MAX) continue;      // empty bucket\n            best = max(best, bmin[b] - prev);      // gap between neighbouring buckets\n            prev = bmax[b];\n        }\n        return best;\n    }\n};",
 "maximum-genetic-difference-query": "class Solution {\n    static constexpr int B = 18;\n    vector<array<int, 3>> trie = {{0, 0, 0}};           // children for bit 0 and 1, then a count\n\n    void update(int x, int d) {\n        int cur = 0;\n        for (int b = B - 1; b >= 0; b--) {\n            int bit = (x >> b) & 1;\n            if (!trie[cur][bit]) { trie.push_back({0, 0, 0}); trie[cur][bit] = trie.size() - 1; }\n            cur = trie[cur][bit];\n            trie[cur][2] += d;\n        }\n    }\n\n    int best(int x) {                                    // largest x ^ y over the values on the path\n        int cur = 0, res = 0;\n        for (int b = B - 1; b >= 0; b--) {\n            int want = 1 - ((x >> b) & 1);\n            int nxt = trie[cur][want];\n            if (nxt && trie[nxt][2]) { res |= 1 << b; cur = nxt; }\n            else cur = trie[cur][1 - want];\n        }\n        return res;\n    }\n\npublic:\n    vector<int> maxGeneticDifference(vector<int>& parents, vector<vector<int>>& queries) {\n        int n = parents.size(), root = -1;\n        vector<vector<int>> kids(n);\n        for (int v = 0; v < n; v++) {\n            if (parents[v] == -1) root = v;\n            else kids[parents[v]].push_back(v);\n        }\n        vector<vector<pair<int, int>>> at(n);           // queries asked at each node\n        for (int k = 0; k < (int)queries.size(); k++) at[queries[k][0]].push_back({queries[k][1], k});\n        vector<int> ans(queries.size(), 0);\n        vector<pair<int, bool>> stack = {{root, false}};  // iterative DFS: the trie holds the root-to-v path\n        while (!stack.empty()) {\n            auto [v, leaving] = stack.back(); stack.pop_back();\n            if (leaving) { update(v, -1); continue; }\n            update(v, 1);\n            for (auto [val, k] : at[v]) ans[k] = best(val);\n            stack.push_back({v, true});\n            for (int c : kids[v]) stack.push_back({c, false});\n        }\n        return ans;\n    }\n};",
 "maximum-length-of-a-concatenated-string-with-unique-characters": "class Solution {\npublic:\n    int maxLength(vector<string>& arr) {\n        vector<pair<int, int>> combos{{0, 0}};               // (letter mask, length) of each unique concatenation\n        for (const string& w : arr) {\n            int m = 0;\n            bool dup = false;\n            for (char ch : w) {\n                int b = 1 << (ch - 'a');\n                if (m & b) { dup = true; break; }            // the word repeats a letter itself\n                m |= b;\n            }\n            if (dup) continue;\n            size_t size = combos.size();\n            for (size_t i = 0; i < size; i++)\n                if (!(combos[i].first & m)) combos.push_back({combos[i].first | m, combos[i].second + (int)w.size()});\n        }\n        int best = 0;\n        for (auto& [mask, n] : combos) best = max(best, n);\n        return best;\n    }\n};",
 "maximum-length-of-pair-chain": "class Solution {\npublic:\n    int findLongestChain(vector<vector<int>>& pairs) {\n        sort(pairs.begin(), pairs.end(), [](auto& a, auto& b) { return a[1] < b[1]; });   // earliest end first\n        long long end = LLONG_MIN;\n        int count = 0;\n        for (auto& p : pairs)\n            if (p[0] > end) { end = p[1]; count++; }\n        return count;\n    }\n};",
 "maximum-length-of-repeated-subarray": "class Solution {\npublic:\n    int findLength(vector<int>& nums1, vector<int>& nums2) {\n        int m = nums1.size(), n = nums2.size(), best = 0;\n        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));   // common run ending at i-1, j-1\n        for (int i = 1; i <= m; i++)\n            for (int j = 1; j <= n; j++)\n                if (nums1[i - 1] == nums2[j - 1]) {\n                    dp[i][j] = dp[i - 1][j - 1] + 1;\n                    best = max(best, dp[i][j]);\n                }\n        return best;\n    }\n};",
 "maximum-level-sum-of-a-binary-tree": "class Solution {\npublic:\n    int maxLevelSum(TreeNode* root) {\n        long long best = LLONG_MIN;\n        int ans = 1, level = 1;\n        vector<TreeNode*> row{root};\n        while (!row.empty()) {\n            long long s = 0;\n            for (auto* n : row) s += n->val;\n            if (s > best) { best = s; ans = level; }   // strict: keep the smallest level\n            vector<TreeNode*> next;\n            for (auto* n : row) {\n                if (n->left) next.push_back(n->left);\n                if (n->right) next.push_back(n->right);\n            }\n            row = next;\n            level++;\n        }\n        return ans;\n    }\n};",
 "maximum-non-negative-product-in-a-matrix": "class Solution {\npublic:\n    int maxProductPath(vector<vector<int>>& grid) {\n        int m = grid.size(), n = grid[0].size();\n        // the largest and smallest product reaching each cell (a negative can flip them)\n        vector<vector<long long>> hi(m, vector<long long>(n)), lo(m, vector<long long>(n));\n        for (int r = 0; r < m; r++)\n            for (int c = 0; c < n; c++) {\n                long long v = grid[r][c];\n                if (r == 0 && c == 0) {\n                    hi[r][c] = lo[r][c] = v;\n                    continue;\n                }\n                vector<long long> prev;\n                if (r) prev.insert(prev.end(), {hi[r - 1][c], lo[r - 1][c]});\n                if (c) prev.insert(prev.end(), {hi[r][c - 1], lo[r][c - 1]});\n                long long a = LLONG_MIN, b = LLONG_MAX;\n                for (long long p : prev) {\n                    a = max(a, p * v);\n                    b = min(b, p * v);\n                }\n                hi[r][c] = a;\n                lo[r][c] = b;\n            }\n        long long best = hi[m - 1][n - 1];\n        return best >= 0 ? best % 1000000007 : -1;\n    }\n};",
 "maximum-number-of-events-that-can-be-attended": "class Solution {\npublic:\n    int maxEvents(vector<vector<int>>& events) {\n        sort(events.begin(), events.end());\n        priority_queue<int, vector<int>, greater<int>> heap;   // end days of open events\n        int i = 0, n = events.size(), day = 0, ans = 0;\n        while (i < n || !heap.empty()) {\n            if (heap.empty()) day = max(day, events[i][0]);   // jump to the next start\n            while (i < n && events[i][0] <= day) heap.push(events[i++][1]);\n            heap.pop();   // attend the one that ends first\n            ans++;\n            day++;\n            while (!heap.empty() && heap.top() < day) heap.pop();   // drop events already over\n        }\n        return ans;\n    }\n};",
 "maximum-number-of-integers-to-choose-from-a-range-i": "class Solution {\npublic:\n    int maxCount(vector<int>& banned, int n, int maxSum) {\n        unordered_set<int> ban(banned.begin(), banned.end());\n        int count = 0;\n        long long total = 0;\n        for (int x = 1; x <= n; x++) {   // smallest numbers first\n            if (ban.count(x)) continue;\n            if (total + x > maxSum) break;\n            total += x;\n            count++;\n        }\n        return count;\n    }\n};",
 "maximum-number-of-k-divisible-components": "class Solution {\n    vector<vector<int>> g;\n    int count = 0;\n    // sum of the part of u's subtree still attached to u\n    long long dfs(int u, int parent, vector<int>& values, int k) {\n        long long s = values[u];\n        for (int v : g[u])\n            if (v != parent) s += dfs(v, u, values, k);\n        if (s % k == 0) {      // cut it off as its own component\n            count++;\n            return 0;\n        }\n        return s;\n    }\npublic:\n    int maxKDivisibleComponents(int n, vector<vector<int>>& edges, vector<int>& values, int k) {\n        g.assign(n, {});\n        for (auto& e : edges) {\n            g[e[0]].push_back(e[1]);\n            g[e[1]].push_back(e[0]);\n        }\n        dfs(0, -1, values, k);\n        return count;\n    }\n};",
 "maximum-product-of-splitted-binary-tree": "class Solution {\npublic:\n    int maxProduct(TreeNode* root) {\n        vector<long long> sums;                        // sum of every subtree\n        function<long long(TreeNode*)> s = [&](TreeNode* node) -> long long {\n            if (!node) return 0;\n            long long t = node->val + s(node->left) + s(node->right);\n            sums.push_back(t);\n            return t;\n        };\n        long long total = s(root), best = 0;\n        for (long long x : sums) best = max(best, x * (total - x));   // cut above this subtree\n        return best % 1000000007;                      // take the max first, then the modulo\n    }\n};",
 "maximum-product-of-word-lengths": "class Solution {\npublic:\n    int maxProduct(vector<string>& words) {\n        int n = words.size();\n        vector<int> masks(n, 0);   // bit c set if the word has letter c\n        for (int i = 0; i < n; i++)\n            for (char c : words[i]) masks[i] |= 1 << (c - 'a');\n        int best = 0;\n        for (int i = 0; i < n; i++)\n            for (int j = i + 1; j < n; j++)\n                if ((masks[i] & masks[j]) == 0)   // no shared letter\n                    best = max(best, (int)(words[i].size() * words[j].size()));\n        return best;\n    }\n};",
 "maximum-product-subarray": "class Solution {\npublic:\n    int maxProduct(vector<int>& nums) {\n        long long hi = nums[0], lo = nums[0], best = nums[0];   // largest and smallest product ending here\n        for (size_t i = 1; i < nums.size(); i++) {\n            long long x = nums[i];\n            if (x < 0) swap(hi, lo);                       // a negative flips them\n            hi = max(x, hi * x);\n            lo = min(x, lo * x);\n            best = max(best, hi);\n        }\n        return best;\n    }\n};",
 "maximum-running-time-of-n-computers": "class Solution {\npublic:\n    long long maxRunTime(int n, vector<int>& batteries) {\n        long long lo = 0, hi = accumulate(batteries.begin(), batteries.end(), 0LL) / n;\n        while (lo < hi) {\n            long long mid = (lo + hi + 1) / 2, power = 0;\n            for (int b : batteries) power += min<long long>(b, mid);   // a battery helps at most mid minutes\n            if (power >= n * mid) lo = mid;\n            else hi = mid - 1;\n        }\n        return lo;\n    }\n};",
 "maximum-score-from-removing-substrings": "class Solution {\n    // remove every \"ab\" (a then b) with a stack, scoring pts each\n    int strip(string& s, char a, char b, int pts) {\n        string st;\n        int got = 0;\n        for (char ch : s) {\n            if (!st.empty() && st.back() == a && ch == b) {\n                st.pop_back();\n                got += pts;\n            } else st += ch;\n        }\n        s = st;\n        return got;\n    }\npublic:\n    int maximumGain(string s, int x, int y) {\n        if (x >= y) return strip(s, 'a', 'b', x) + strip(s, 'b', 'a', y);   // the dearer pair first\n        return strip(s, 'b', 'a', y) + strip(s, 'a', 'b', x);\n    }\n};",
 "maximum-score-of-a-good-subarray": "class Solution {\npublic:\n    int maximumScore(vector<int>& nums, int k) {\n        int n = nums.size(), i = k, j = k;\n        int low = nums[k], best = nums[k];\n        while (i > 0 || j < n - 1) {\n            // grow towards the bigger neighbour so the minimum drops as slowly as possible\n            if (i == 0 || (j < n - 1 && nums[j + 1] > nums[i - 1])) low = min(low, nums[++j]);\n            else low = min(low, nums[--i]);\n            best = max(best, low * (j - i + 1));\n        }\n        return best;\n    }\n};",
 "maximum-split-of-positive-even-integers": "class Solution {\npublic:\n    vector<long long> maximumEvenSplit(long long finalSum) {\n        if (finalSum % 2) return {};\n        vector<long long> out;\n        for (long long x = 2; finalSum >= x; x += 2) {   // take 2, 4, 6, ... while they fit\n            out.push_back(x);\n            finalSum -= x;\n        }\n        out.back() += finalSum;   // the rest goes on the biggest, keeping all distinct\n        return out;\n    }\n};",
 "maximum-subarray": "class Solution {\npublic:\n    int maxSubArray(vector<int>& nums) {\n        int run = nums[0], best = nums[0];\n        for (size_t i = 1; i < nums.size(); i++) {\n            run = max(nums[i], run + nums[i]);             // extend or start fresh\n            best = max(best, run);\n        }\n        return best;\n    }\n};",
 "maximum-subarray-sum-with-length-divisible-by-k": "class Solution {\npublic:\n    long long maxSubarraySum(vector<int>& nums, int k) {\n        vector<long long> low(k, LLONG_MAX);   // smallest prefix sum at each length mod k\n        low[0] = 0;\n        long long s = 0, best = LLONG_MIN;\n        for (int j = 1; j <= (int)nums.size(); j++) {\n            s += nums[j - 1];\n            int r = j % k;\n            if (low[r] != LLONG_MAX) best = max(best, s - low[r]);   // same remainder: length divisible by k\n            low[r] = min(low[r], s);\n        }\n        return best;\n    }\n};",
 "maximum-sum-circular-subarray": "class Solution {\npublic:\n    int maxSubarraySumCircular(vector<int>& nums) {\n        int curMax = 0, curMin = 0, bestMax = nums[0], bestMin = nums[0], total = 0;\n        for (int x : nums) {\n            curMax = max(x, curMax + x);\n            bestMax = max(bestMax, curMax);\n            curMin = min(x, curMin + x);\n            bestMin = min(bestMin, curMin);\n            total += x;\n        }\n        // wrapping around = total minus the smallest middle part; all negative means no wrap\n        return bestMax < 0 ? bestMax : max(bestMax, total - bestMin);\n    }\n};",
 "maximum-swap": "class Solution {\npublic:\n    int maximumSwap(int num) {\n        string d = to_string(num);\n        int last[10];\n        fill(last, last + 10, -1);\n        for (int i = 0; i < (int)d.size(); i++) last[d[i] - '0'] = i;   // last place of each digit\n        for (int i = 0; i < (int)d.size(); i++)\n            for (int big = 9; big > d[i] - '0'; big--)\n                if (last[big] > i) {                     // a bigger digit later on: swap it forward\n                    swap(d[i], d[last[big]]);\n                    return stoi(d);\n                }\n        return num;\n    }\n};",
 "maximum-tastiness-of-candy-basket": "class Solution {\npublic:\n    int maximumTastiness(vector<int>& price, int k) {\n        sort(price.begin(), price.end());\n        // can we pick k candies with every gap >= gap? take greedily from the left\n        auto ok = [&](int gap) {\n            int cnt = 1, last = price[0];\n            for (int p : price)\n                if (p - last >= gap) { cnt++; last = p; }\n            return cnt >= k;\n        };\n        int lo = 0, hi = (price.back() - price[0]) / (k - 1);\n        while (lo < hi) {\n            int mid = lo + (hi - lo + 1) / 2;\n            if (ok(mid)) lo = mid;\n            else hi = mid - 1;\n        }\n        return lo;\n    }\n};",
 "maximum-total-damage-with-spell-casting": "class Solution {\npublic:\n    long long maximumTotalDamage(vector<int>& power) {\n        map<int, long long> cnt;\n        for (int p : power) cnt[p]++;\n        vector<pair<int, long long>> vals(cnt.begin(), cnt.end());   // sorted distinct values\n        vector<long long> dp(vals.size() + 1, 0);                    // dp[i] = best using the first i values\n        size_t j = 0;\n        for (size_t i = 0; i < vals.size(); i++) {\n            auto [v, c] = vals[i];\n            while (vals[j].first < v - 2) j++;          // vals[..j) can sit next to v\n            dp[i + 1] = max(dp[i], dp[j] + v * c);\n        }\n        return dp.back();\n    }\n};",
 "maximum-twin-sum-of-a-linked-list": "class Solution {\npublic:\n    int pairSum(ListNode* head) {\n        ListNode *slow = head, *fast = head;\n        while (fast && fast->next) { slow = slow->next; fast = fast->next->next; }   // slow reaches the middle\n        ListNode* prev = nullptr;\n        while (slow) {                                   // reverse the second half\n            ListNode* nxt = slow->next;\n            slow->next = prev;\n            prev = slow;\n            slow = nxt;\n        }\n        int best = 0;\n        for (; prev; head = head->next, prev = prev->next) best = max(best, head->val + prev->val);\n        return best;\n    }\n};",
 "maximum-units-on-a-truck": "class Solution {\npublic:\n    int maximumUnits(vector<vector<int>>& boxTypes, int truckSize) {\n        sort(boxTypes.begin(), boxTypes.end(), [](auto& a, auto& b) { return a[1] > b[1]; });   // most units first\n        int total = 0;\n        for (auto& b : boxTypes) {\n            int take = min(b[0], truckSize);\n            total += take * b[1];\n            truckSize -= take;\n            if (!truckSize) break;\n        }\n        return total;\n    }\n};",
 "maximum-value-at-a-given-index-in-a-bounded-array": "class Solution {\npublic:\n    int maxValue(int n, int index, int maxSum) {\n        auto side = [](long long v, long long length) -> long long {   // v-1, v-2, ... over length cells, min 1\n            if (v - 1 >= length) return (2 * v - 1 - length) * length / 2;\n            return v * (v - 1) / 2 + (length - (v - 1));\n        };\n        auto cost = [&](long long v) { return v + side(v, index) + side(v, n - index - 1); };\n        int lo = 1, hi = maxSum;\n        while (lo < hi) {\n            int mid = lo + (hi - lo + 1) / 2;\n            if (cost(mid) <= maxSum) lo = mid;\n            else hi = mid - 1;\n        }\n        return lo;\n    }\n};",
 "maximum-white-tiles-covered-by-a-carpet": "class Solution {\npublic:\n    int maximumWhiteTiles(vector<vector<int>>& tiles, int carpetLen) {\n        sort(tiles.begin(), tiles.end());\n        int n = tiles.size(), best = 0, cover = 0, j = 0;\n        for (int i = 0; i < n; i++) {\n            int s = tiles[i][0], e = tiles[i][1];\n            int end = s + carpetLen;                   // carpet starts at s, covers [s, end)\n            while (j < n && tiles[j][1] < end) {       // tiles fully under the carpet\n                cover += tiles[j][1] - tiles[j][0] + 1;\n                j++;\n            }\n            int part = j < n ? max(0, end - tiles[j][0]) : 0;   // part of the next tile\n            best = max(best, cover + part);\n            if (best >= carpetLen) return carpetLen;\n            cover -= e - s + 1;                        // tile i leaves the window\n        }\n        return best;\n    }\n};",
 "maximum-width-of-binary-tree": "class Solution {\npublic:\n    int widthOfBinaryTree(TreeNode* root) {\n        unsigned long long best = 0;\n        vector<pair<TreeNode*, unsigned long long>> level{{root, 0}};   // node and its heap index\n        while (!level.empty()) {\n            unsigned long long first = level[0].second;\n            best = max(best, level.back().second - first + 1);\n            vector<pair<TreeNode*, unsigned long long>> next;\n            for (auto [node, i] : level) {\n                i -= first;                                  // renumber from 0 so indices stay small\n                if (node->left) next.push_back({node->left, 2 * i});\n                if (node->right) next.push_back({node->right, 2 * i + 1});\n            }\n            level = next;\n        }\n        return (int)best;\n    }\n};",
 "maximum-width-ramp": "class Solution {\npublic:\n    int maxWidthRamp(vector<int>& nums) {\n        vector<int> st;   // indices of a strictly decreasing run of prefix minimums\n        for (int i = 0; i < (int)nums.size(); i++)\n            if (st.empty() || nums[st.back()] > nums[i]) st.push_back(i);\n        int best = 0;\n        for (int j = nums.size() - 1; j >= 0; j--)\n            while (!st.empty() && nums[st.back()] <= nums[j]) {\n                best = max(best, j - st.back());\n                st.pop_back();\n            }\n        return best;\n    }\n};",
 "maximum-xor-of-two-numbers-in-an-array": "class Solution {\npublic:\n    int findMaximumXOR(vector<int>& nums) {\n        int mx = *max_element(nums.begin(), nums.end()), bits = 0;\n        while (mx >> bits) bits++;   // bit length of the largest number\n        int ans = 0;\n        for (int b = bits - 1; b >= 0; b--) {\n            ans <<= 1;\n            unordered_set<int> prefixes;\n            for (int x : nums) prefixes.insert(x >> b);\n            int cand = ans | 1;   // try to set this bit\n            for (int p : prefixes)\n                if (prefixes.count(cand ^ p)) { ans = cand; break; }\n        }\n        return ans;\n    }\n};",
 "maximum-xor-with-an-element-from-array": "class Solution {\npublic:\n    vector<int> maximizeXor(vector<int>& nums, vector<vector<int>>& queries) {\n        sort(nums.begin(), nums.end());\n        vector<int> order(queries.size());\n        iota(order.begin(), order.end(), 0);\n        stable_sort(order.begin(), order.end(), [&](int a, int b) { return queries[a][1] < queries[b][1]; });   // by limit m\n        vector<array<int, 2>> trie = {{0, 0}};          // binary trie; 0 means no child\n        vector<int> ans(queries.size(), -1);\n        size_t i = 0;\n        for (int k : order) {\n            int x = queries[k][0], m = queries[k][1];\n            for (; i < nums.size() && nums[i] <= m; i++) {   // add every number allowed for this query\n                int node = 0;\n                for (int b = 29; b >= 0; b--) {\n                    int bit = (nums[i] >> b) & 1;\n                    if (!trie[node][bit]) { trie.push_back({0, 0}); trie[node][bit] = trie.size() - 1; }\n                    node = trie[node][bit];\n                }\n            }\n            if (i == 0) continue;                        // nothing is small enough\n            int node = 0, best = 0;\n            for (int b = 29; b >= 0; b--) {\n                int bit = (x >> b) & 1;\n                if (trie[node][1 - bit]) { best |= 1 << b; node = trie[node][1 - bit]; }   // take the opposite bit\n                else node = trie[node][bit];\n            }\n            ans[k] = best;\n        }\n        return ans;\n    }\n};",
 "meeting-rooms-iii": "class Solution {\npublic:\n    int mostBooked(int n, vector<vector<int>>& meetings) {\n        priority_queue<int, vector<int>, greater<int>> free;                    // room numbers\n        for (int r = 0; r < n; r++) free.push(r);\n        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> busy;  // (end, room)\n        vector<int> count(n, 0);\n        sort(meetings.begin(), meetings.end());\n        for (auto& m : meetings) {\n            long long s = m[0], e = m[1];\n            while (!busy.empty() && busy.top().first <= s) {   // rooms that are free by now\n                free.push(busy.top().second);\n                busy.pop();\n            }\n            int r;\n            if (!free.empty()) {\n                r = free.top();\n                free.pop();\n                busy.push({e, r});\n            } else {                                           // wait for the first room to free up\n                auto [end, room] = busy.top();\n                busy.pop();\n                r = room;\n                busy.push({end + e - s, r});\n            }\n            count[r]++;\n        }\n        return max_element(count.begin(), count.end()) - count.begin();\n    }\n};",
 "merge-in-between-linked-lists": "class Solution {\npublic:\n    ListNode* mergeInBetween(ListNode* list1, int a, int b, ListNode* list2) {\n        ListNode* before = list1;\n        for (int i = 0; i < a - 1; i++) before = before->next;      // node a - 1\n        ListNode* after = before;\n        for (int i = 0; i < b - a + 2; i++) after = after->next;    // node b + 1\n        before->next = list2;\n        while (list2->next) list2 = list2->next;\n        list2->next = after;\n        return list1;\n    }\n};",
 "merge-intervals": "class Solution {\npublic:\n    vector<vector<int>> merge(vector<vector<int>>& intervals) {\n        sort(intervals.begin(), intervals.end());\n        vector<vector<int>> out;\n        for (auto& iv : intervals) {\n            if (!out.empty() && iv[0] <= out.back()[1]) out.back()[1] = max(out.back()[1], iv[1]);   // overlaps the last one\n            else out.push_back(iv);\n        }\n        return out;\n    }\n};",
 "merge-k-sorted-lists": "class Solution {\npublic:\n    ListNode* mergeKLists(vector<ListNode*>& lists) {\n        // (value, list index, node): the index breaks ties so nodes are never compared\n        using Item = tuple<int, int, ListNode*>;\n        priority_queue<Item, vector<Item>, greater<Item>> heap;\n        for (int i = 0; i < (int)lists.size(); i++) if (lists[i]) heap.push({lists[i]->val, i, lists[i]});\n        ListNode dummy, *tail = &dummy;\n        while (!heap.empty()) {\n            auto [v, i, node] = heap.top(); heap.pop();  // smallest head of all lists\n            tail->next = node;\n            tail = node;\n            if (node->next) heap.push({node->next->val, i, node->next});\n        }\n        return dummy.next;\n    }\n};",
 "merge-two-sorted-lists": "class Solution {\npublic:\n    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {\n        ListNode dummy, *tail = &dummy;\n        while (list1 && list2) {\n            if (list1->val <= list2->val) { tail->next = list1; list1 = list1->next; }   // take the smaller head\n            else { tail->next = list2; list2 = list2->next; }\n            tail = tail->next;\n        }\n        tail->next = list1 ? list1 : list2;              // attach whatever is left\n        return dummy.next;\n    }\n};",
 "middle-of-the-linked-list": "class Solution {\npublic:\n    ListNode* middleNode(ListNode* head) {\n        ListNode *slow = head, *fast = head;\n        while (fast && fast->next) {          // fast moves two steps for each step of slow\n            slow = slow->next;\n            fast = fast->next->next;\n        }\n        return slow;\n    }\n};",
 "min-cost-climbing-stairs": "class Solution {\npublic:\n    int minCostClimbingStairs(vector<int>& cost) {\n        int a = cost[0], b = cost[1];                        // cheapest way to stand on the last two steps\n        for (size_t i = 2; i < cost.size(); i++) {\n            int c = cost[i] + min(a, b);\n            a = b;\n            b = c;\n        }\n        return min(a, b);\n    }\n};",
 "min-cost-to-connect-all-points": "class Solution {\npublic:\n    int minCostConnectPoints(vector<vector<int>>& points) {\n        int n = points.size(), total = 0;\n        vector<int> dist(n, INT_MAX);                    // cheapest edge from the tree to each point\n        vector<bool> used(n, false);\n        dist[0] = 0;\n        for (int step = 0; step < n; step++) {\n            int u = -1;\n            for (int i = 0; i < n; i++)                  // closest point not yet in the tree\n                if (!used[i] && (u == -1 || dist[i] < dist[u])) u = i;\n            used[u] = true;\n            total += dist[u];\n            for (int v = 0; v < n; v++)\n                if (!used[v]) {\n                    int d = abs(points[u][0] - points[v][0]) + abs(points[u][1] - points[v][1]);\n                    dist[v] = min(dist[v], d);\n                }\n        }\n        return total;\n    }\n};",
 "min-stack": "class MinStack {\n    vector<pair<int, int>> st;                // (value, smallest value at or below it)\npublic:\n    MinStack() {}\n\n    void push(int val) {\n        int low = st.empty() ? val : min(val, st.back().second);\n        st.push_back({val, low});\n    }\n\n    void pop() { st.pop_back(); }\n\n    int top() { return st.back().first; }\n\n    int getMin() { return st.back().second; }\n};",
 "minimize-hamming-distance-after-swap-operations": "class Solution {\npublic:\n    int minimumHammingDistance(vector<int>& source, vector<int>& target, vector<vector<int>>& allowedSwaps) {\n        vector<int> parent(source.size());\n        iota(parent.begin(), parent.end(), 0);\n        auto find = [&](int x) {\n            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }   // path halving\n            return x;\n        };\n        for (auto& s : allowedSwaps) parent[find(s[0])] = find(s[1]);   // positions that can swap form groups\n        unordered_map<int, unordered_map<int, int>> have;  // group -> value counts from source\n        for (int i = 0; i < (int)source.size(); i++) have[find(i)][source[i]]++;\n        int ans = 0;\n        for (int i = 0; i < (int)target.size(); i++) {\n            int& c = have[find(i)][target[i]];\n            if (c > 0) c--;\n            else ans++;                                // no matching value left in this group\n        }\n        return ans;\n    }\n};",
 "minimize-xor": "class Solution {\npublic:\n    int minimizeXor(int num1, int num2) {\n        int need = __builtin_popcount(num2), x = 0;\n        for (int b = 30; b >= 0 && need; b--)          // cancel num1's high bits first\n            if (num1 >> b & 1) { x |= 1 << b; need--; }\n        for (int b = 0; b <= 30 && need; b++)          // then fill the lowest free bits\n            if (!(x >> b & 1)) { x |= 1 << b; need--; }\n        return x;\n    }\n};",
 "minimized-maximum-of-products-distributed-to-any-store": "class Solution {\npublic:\n    int minimizedMaximum(int n, vector<int>& quantities) {\n        int lo = 1, hi = *max_element(quantities.begin(), quantities.end());\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            long long stores = 0;\n            for (int q : quantities) stores += (q + mid - 1) / mid;   // stores this product needs\n            if (stores <= n) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "minimum-absolute-difference-between-elements-with-constraint": "class Solution {\npublic:\n    int minAbsoluteDifference(vector<int>& nums, int x) {\n        multiset<int> seen;   // values at least x positions back\n        int best = INT_MAX;\n        for (int i = x; i < (int)nums.size(); i++) {\n            seen.insert(nums[i - x]);\n            auto it = seen.lower_bound(nums[i]);\n            if (it != seen.end()) best = min(best, *it - nums[i]);              // closest above\n            if (it != seen.begin()) best = min(best, nums[i] - *prev(it));      // closest below\n        }\n        return best;\n    }\n};",
 "minimum-absolute-sum-difference": "class Solution {\npublic:\n    int minAbsoluteSumDiff(vector<int>& nums1, vector<int>& nums2) {\n        vector<int> s = nums1;\n        sort(s.begin(), s.end());\n        long long total = 0;\n        int gain = 0;\n        for (size_t i = 0; i < nums1.size(); i++) {\n            int a = nums1[i], b = nums2[i], d = abs(a - b);\n            total += d;\n            auto it = lower_bound(s.begin(), s.end(), b);   // closest value in nums1 to b\n            int best = d;\n            if (it != s.end()) best = min(best, *it - b);\n            if (it != s.begin()) best = min(best, b - *prev(it));\n            gain = max(gain, d - best);                     // best single replacement\n        }\n        return (total - gain) % 1'000'000'007;\n    }\n};",
 "minimum-add-to-make-parentheses-valid": "class Solution {\npublic:\n    int minAddToMakeValid(string s) {\n        int open = 0, add = 0;\n        for (char ch : s) {\n            if (ch == '(') open++;\n            else if (open) open--;\n            else add++;            // a ')' with nothing to close\n        }\n        return add + open;         // plus every '(' left open\n    }\n};",
 "minimum-average-difference": "class Solution {\npublic:\n    int minimumAverageDifference(vector<int>& nums) {\n        long long n = nums.size(), total = accumulate(nums.begin(), nums.end(), 0LL), pre = 0, best = LLONG_MAX;\n        int ans = 0;\n        for (int i = 0; i < n; i++) {\n            pre += nums[i];\n            long long left = pre / (i + 1);\n            long long right = i < n - 1 ? (total - pre) / (n - i - 1) : 0;\n            if (llabs(left - right) < best) {\n                best = llabs(left - right);\n                ans = i;\n            }\n        }\n        return ans;\n    }\n};",
 "minimum-cost-homecoming-of-a-robot-in-a-grid": "class Solution {\npublic:\n    int minCost(vector<int>& startPos, vector<int>& homePos, vector<int>& rowCosts, vector<int>& colCosts) {\n        int r0 = startPos[0], c0 = startPos[1], r1 = homePos[0], c1 = homePos[1];\n        int cost = 0;\n        // every row and column between start and home is entered once, whatever the path\n        if (r1 >= r0) for (int r = r0 + 1; r <= r1; r++) cost += rowCosts[r];\n        else for (int r = r1; r < r0; r++) cost += rowCosts[r];\n        if (c1 >= c0) for (int c = c0 + 1; c <= c1; c++) cost += colCosts[c];\n        else for (int c = c1; c < c0; c++) cost += colCosts[c];\n        return cost;\n    }\n};",
 "minimum-cost-of-a-path-with-special-roads": "class Solution {\npublic:\n    int minimumCost(vector<int>& start, vector<int>& target, vector<vector<int>>& specialRoads) {\n        int tx = target[0], ty = target[1];\n        map<pair<int, int>, int> dist{{{start[0], start[1]}, 0}};\n        set<pair<int, int>> done;\n        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> pq;\n        pq.push({0, start[0], start[1]});\n        int best = abs(tx - start[0]) + abs(ty - start[1]);\n        while (!pq.empty()) {                     // Dijkstra over road ends\n            auto [d, x, y] = pq.top();\n            pq.pop();\n            if (!done.insert({x, y}).second) continue;\n            best = min(best, d + abs(tx - x) + abs(ty - y));   // walk straight to the target\n            for (auto& r : specialRoads) {\n                int nd = d + abs(r[0] - x) + abs(r[1] - y) + r[4];\n                auto it = dist.find({r[2], r[3]});\n                if (it == dist.end() || nd < it->second) {\n                    dist[{r[2], r[3]}] = nd;\n                    pq.push({nd, r[2], r[3]});\n                }\n            }\n        }\n        return best;\n    }\n};",
 "minimum-cost-to-convert-string-i": "class Solution {\npublic:\n    long long minimumCost(string source, string target, vector<char>& original, vector<char>& changed, vector<int>& cost) {\n        const long long INF = LLONG_MAX / 4;\n        vector<vector<long long>> d(26, vector<long long>(26, INF));\n        for (int i = 0; i < 26; i++) d[i][i] = 0;\n        for (size_t i = 0; i < original.size(); i++) {\n            int u = original[i] - 'a', v = changed[i] - 'a';\n            d[u][v] = min(d[u][v], (long long)cost[i]);\n        }\n        for (int k = 0; k < 26; k++)   // Floyd-Warshall over the 26 letters\n            for (int i = 0; i < 26; i++)\n                for (int j = 0; j < 26; j++) d[i][j] = min(d[i][j], d[i][k] + d[k][j]);\n        long long total = 0;\n        for (size_t i = 0; i < source.size(); i++) {\n            long long c = d[source[i] - 'a'][target[i] - 'a'];\n            if (c >= INF) return -1;\n            total += c;\n        }\n        return total;\n    }\n};",
 "minimum-cost-to-cut-a-stick": "class Solution {\npublic:\n    int minCost(int n, vector<int>& cuts) {\n        vector<int> c = {0};\n        vector<int> s = cuts;\n        sort(s.begin(), s.end());\n        c.insert(c.end(), s.begin(), s.end());\n        c.push_back(n);\n        int m = c.size();\n        vector<vector<int>> dp(m, vector<int>(m, 0));    // dp[i][j]: cost to make every cut between c[i] and c[j]\n        for (int gap = 2; gap < m; gap++)\n            for (int i = 0; i + gap < m; i++) {\n                int j = i + gap, best = INT_MAX;\n                for (int k = i + 1; k < j; k++) best = min(best, dp[i][k] + dp[k][j]);   // k is the first cut\n                dp[i][j] = c[j] - c[i] + best;\n            }\n        return dp[0][m - 1];\n    }\n};",
 "minimum-cost-to-hire-k-workers": "class Solution {\npublic:\n    double mincostToHireWorkers(vector<int>& quality, vector<int>& wage, int k) {\n        vector<pair<double, int>> workers;               // (wage per unit of quality, quality)\n        for (size_t i = 0; i < quality.size(); i++) workers.push_back({(double)wage[i] / quality[i], quality[i]});\n        sort(workers.begin(), workers.end());\n        priority_queue<int> heap;                        // the k smallest qualities so far\n        long long total = 0;\n        double best = 1e18;\n        for (auto [ratio, q] : workers) {\n            heap.push(q);\n            total += q;\n            if ((int)heap.size() > k) { total -= heap.top(); heap.pop(); }\n            if ((int)heap.size() == k) best = min(best, ratio * total);   // this worker sets the pay rate\n        }\n        return best;\n    }\n};",
 "minimum-cost-to-make-array-equal": "class Solution {\npublic:\n    long long minCost(vector<int>& nums, vector<int>& cost) {\n        int n = nums.size();\n        vector<pair<int, int>> pairs(n);\n        for (int i = 0; i < n; i++) pairs[i] = {nums[i], cost[i]};\n        sort(pairs.begin(), pairs.end());\n        long long total = accumulate(cost.begin(), cost.end(), 0LL);\n        long long half = (total + 1) / 2, acc = 0;\n        int target = 0;\n        for (auto [x, c] : pairs) {          // weighted median\n            acc += c;\n            if (acc >= half) { target = x; break; }\n        }\n        long long ans = 0;\n        for (int i = 0; i < n; i++) ans += (long long)abs(nums[i] - target) * cost[i];\n        return ans;\n    }\n};",
 "minimum-cost-to-make-at-least-one-valid-path-in-a-grid": "class Solution {\npublic:\n    int minCost(vector<vector<int>>& grid) {\n        int m = grid.size(), n = grid[0].size();\n        int dr[] = {0, 0, 1, -1}, dc[] = {1, -1, 0, 0};       // signs 1 right, 2 left, 3 down, 4 up\n        vector<vector<int>> dist(m, vector<int>(n, INT_MAX));\n        deque<array<int, 3>> dq;\n        dist[0][0] = 0;\n        dq.push_back({0, 0, 0});\n        while (!dq.empty()) {\n            auto [d, r, c] = dq.front(); dq.pop_front();\n            if (d > dist[r][c]) continue;\n            if (r == m - 1 && c == n - 1) return d;\n            for (int k = 0; k < 4; k++) {\n                int nr = r + dr[k], nc = c + dc[k];\n                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;\n                int w = grid[r][c] == k + 1 ? 0 : 1;\n                if (d + w < dist[nr][nc]) {\n                    dist[nr][nc] = d + w;\n                    if (w) dq.push_back({d + 1, nr, nc});\n                    else dq.push_front({d, nr, nc});\n                }\n            }\n        }\n        return dist[m - 1][n - 1];\n    }\n};",
 "minimum-deletions-to-make-array-beautiful": "class Solution {\npublic:\n    int minDeletion(vector<int>& nums) {\n        int deleted = 0, kept = 0;\n        for (int i = 0; i < (int)nums.size(); i++) {\n            if (kept % 2 == 1 && nums[i] == nums[i - 1]) deleted++;   // would break the pair\n            else kept++;\n        }\n        return deleted + kept % 2;   // an odd length drops the last one\n    }\n};",
 "minimum-depth-of-binary-tree": "class Solution {\npublic:\n    int minDepth(TreeNode* root) {\n        if (!root) return 0;\n        queue<pair<TreeNode*, int>> q;\n        q.push({root, 1});\n        while (!q.empty()) {\n            auto [node, d] = q.front(); q.pop();\n            if (!node->left && !node->right) return d;     // BFS: the first leaf is the shallowest\n            if (node->left) q.push({node->left, d + 1});\n            if (node->right) q.push({node->right, d + 1});\n        }\n        return 0;\n    }\n};",
 "minimum-difference-between-largest-and-smallest-value-in-three-moves": "class Solution {\npublic:\n    int minDifference(vector<int>& nums) {\n        int n = nums.size();\n        if (n <= 4) return 0;\n        sort(nums.begin(), nums.end());\n        int best = INT_MAX;\n        for (int i = 0; i < 4; i++) best = min(best, nums[n - 4 + i] - nums[i]);   // drop i small, 3 - i big\n        return best;\n    }\n};",
 "minimum-domino-rotations-for-equal-row": "class Solution {\npublic:\n    int minDominoRotations(vector<int>& tops, vector<int>& bottoms) {\n        int best = INT_MAX;\n        for (int v : {tops[0], bottoms[0]}) {   // the row must use one of the first domino's values\n            int rotTop = 0, rotBottom = 0;\n            bool ok = true;\n            for (size_t i = 0; i < tops.size(); i++) {\n                if (tops[i] != v && bottoms[i] != v) { ok = false; break; }\n                if (tops[i] != v) rotTop++;\n                if (bottoms[i] != v) rotBottom++;\n            }\n            if (ok) best = min({best, rotTop, rotBottom});\n        }\n        return best == INT_MAX ? -1 : best;\n    }\n};",
 "minimum-edge-weight-equilibrium-queries-in-a-tree": "class Solution {\npublic:\n    vector<int> minOperationsQueries(int n, vector<vector<int>>& edges, vector<vector<int>>& queries) {\n        vector<vector<pair<int, int>>> g(n);\n        for (auto& e : edges) { g[e[0]].push_back({e[1], e[2]}); g[e[1]].push_back({e[0], e[2]}); }\n        int LOG = 1;\n        while ((1 << LOG) <= n) LOG++;\n        vector<vector<int>> up(LOG, vector<int>(n, 0));\n        vector<int> depth(n, 0);\n        vector<array<int, 27>> cnt(n);                       // cnt[v][w] = edges of weight w from the root to v\n        cnt[0].fill(0);\n        vector<bool> seen(n, false);\n        seen[0] = true;\n        vector<int> st = {0};\n        while (!st.empty()) {\n            int u = st.back(); st.pop_back();\n            for (auto [v, w] : g[u])\n                if (!seen[v]) {\n                    seen[v] = true;\n                    up[0][v] = u; depth[v] = depth[u] + 1;\n                    cnt[v] = cnt[u]; cnt[v][w]++;\n                    st.push_back(v);\n                }\n        }\n        for (int j = 1; j < LOG; j++)\n            for (int v = 0; v < n; v++) up[j][v] = up[j - 1][up[j - 1][v]];\n        auto lca = [&](int a, int b) {\n            if (depth[a] < depth[b]) swap(a, b);\n            int d = depth[a] - depth[b];\n            for (int j = 0; j < LOG; j++) if (d >> j & 1) a = up[j][a];\n            if (a == b) return a;\n            for (int j = LOG - 1; j >= 0; j--)\n                if (up[j][a] != up[j][b]) { a = up[j][a]; b = up[j][b]; }\n            return up[0][a];\n        };\n        vector<int> out;\n        for (auto& q : queries) {\n            int a = q[0], b = q[1], l = lca(a, b), total = 0, best = 0;\n            for (int w = 1; w <= 26; w++) {\n                int c = cnt[a][w] + cnt[b][w] - 2 * cnt[l][w];\n                total += c; best = max(best, c);\n            }\n            out.push_back(total - best);\n        }\n        return out;\n    }\n};",
 "minimum-flips-to-make-a-or-b-equal-to-c": "class Solution {\npublic:\n    int minFlips(int a, int b, int c) {\n        int ans = 0;\n        while (a || b || c) {\n            int x = a & 1, y = b & 1, z = c & 1;\n            ans += z == 0 ? x + y : 1 - (x | y);   // clear both, or set one\n            a >>= 1;\n            b >>= 1;\n            c >>= 1;\n        }\n        return ans;\n    }\n};",
 "minimum-genetic-mutation": "class Solution {\npublic:\n    int minMutation(string startGene, string endGene, vector<string>& bank) {\n        unordered_set<string> pool(bank.begin(), bank.end()), seen{startGene};\n        queue<pair<string, int>> q;\n        q.push({startGene, 0});\n        while (!q.empty()) {\n            auto [g, d] = q.front();\n            q.pop();\n            if (g == endGene) return d;\n            for (size_t i = 0; i < g.size(); i++)\n                for (char ch : string(\"ACGT\")) {\n                    string n = g;\n                    n[i] = ch;                       // one letter changed\n                    if (pool.count(n) && !seen.count(n)) {\n                        seen.insert(n);\n                        q.push({n, d + 1});\n                    }\n                }\n        }\n        return -1;\n    }\n};",
 "minimum-height-trees": "class Solution {\npublic:\n    vector<int> findMinHeightTrees(int n, vector<vector<int>>& edges) {\n        if (n == 1) return {0};\n        vector<unordered_set<int>> g(n);\n        for (auto& e : edges) {\n            g[e[0]].insert(e[1]);\n            g[e[1]].insert(e[0]);\n        }\n        vector<int> leaves;\n        for (int i = 0; i < n; i++)\n            if (g[i].size() == 1) leaves.push_back(i);\n        int left = n;\n        while (left > 2) {   // peel leaves layer by layer; the last one or two are the centres\n            left -= leaves.size();\n            vector<int> nxt;\n            for (int x : leaves) {\n                int y = *g[x].begin();\n                g[x].clear();\n                g[y].erase(x);\n                if (g[y].size() == 1) nxt.push_back(y);\n            }\n            leaves = nxt;\n        }\n        return leaves;\n    }\n};",
 "minimum-increment-to-make-array-unique": "class Solution {\npublic:\n    int minIncrementForUnique(vector<int>& nums) {\n        sort(nums.begin(), nums.end());\n        long long moves = 0, need = 0;   // need = smallest value still free\n        for (int x : nums) {\n            need = max(need, (long long)x);\n            moves += need - x;\n            need++;\n        }\n        return moves;\n    }\n};",
 "minimum-index-of-a-valid-split": "class Solution {\npublic:\n    int minimumIndex(vector<int>& nums) {\n        int cand = 0, cnt = 0;\n        for (int x : nums) {                  // Boyer-Moore vote\n            if (cnt == 0) cand = x;\n            cnt += x == cand ? 1 : -1;\n        }\n        int n = nums.size(), total = count(nums.begin(), nums.end(), cand), left = 0;\n        for (int i = 0; i + 1 < n; i++) {\n            left += nums[i] == cand;\n            if (left * 2 > i + 1 && (total - left) * 2 > n - i - 1) return i;\n        }\n        return -1;\n    }\n};",
 "minimum-interval-to-include-each-query": "class Solution {\npublic:\n    vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {\n        sort(intervals.begin(), intervals.end());\n        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> heap;   // (size, right end), smallest first\n        map<int, int> best;\n        size_t i = 0;\n        for (int q : set<int>(queries.begin(), queries.end())) {\n            while (i < intervals.size() && intervals[i][0] <= q) {   // every interval that starts by q\n                int l = intervals[i][0], r = intervals[i][1];\n                heap.push({r - l + 1, r});\n                i++;\n            }\n            while (!heap.empty() && heap.top().second < q) heap.pop();   // drop intervals that ended before q\n            best[q] = heap.empty() ? -1 : heap.top().first;\n        }\n        vector<int> out;\n        for (int q : queries) out.push_back(best[q]);\n        return out;\n    }\n};",
 "minimum-limit-of-balls-in-a-bag": "class Solution {\npublic:\n    int minimumSize(vector<int>& nums, int maxOperations) {\n        int lo = 1, hi = *max_element(nums.begin(), nums.end());\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            long long ops = 0;\n            for (int x : nums) ops += (x - 1) / mid;   // splits to get every bag <= mid\n            if (ops <= maxOperations) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "minimum-number-of-arrows-to-burst-balloons": "class Solution {\npublic:\n    int findMinArrowShots(vector<vector<int>>& points) {\n        sort(points.begin(), points.end(), [](auto& a, auto& b) { return a[1] < b[1]; });   // by end\n        int arrows = 0;\n        long long x = LLONG_MIN;   // where the last arrow went\n        for (auto& p : points)\n            if (p[0] > x) {   // this balloon starts after the last arrow: shoot at its end\n                arrows++;\n                x = p[1];\n            }\n        return arrows;\n    }\n};",
 "minimum-number-of-days-to-disconnect-island": "class Solution {\n    int m, n, timer = 0;\n    bool cut = false;\n    vector<vector<int>> disc, low;\n\n    void dfs(vector<vector<int>>& grid, int r, int c, int pr, int pc) {\n        disc[r][c] = low[r][c] = timer++;\n        int children = 0;\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        for (int k = 0; k < 4; k++) {\n            int nr = r + dr[k], nc = c + dc[k];\n            if (nr < 0 || nr >= m || nc < 0 || nc >= n || !grid[nr][nc]) continue;\n            if (disc[nr][nc] < 0) {\n                children++;\n                dfs(grid, nr, nc, r, c);\n                low[r][c] = min(low[r][c], low[nr][nc]);\n                if (pr >= 0 && low[nr][nc] >= disc[r][c]) cut = true;   // nothing below (nr, nc) climbs above (r, c)\n            } else if (nr != pr || nc != pc) {\n                low[r][c] = min(low[r][c], disc[nr][nc]);\n            }\n        }\n        if (pr < 0 && children > 1) cut = true;\n    }\n\npublic:\n    int minDays(vector<vector<int>>& grid) {\n        m = grid.size(); n = grid[0].size();\n        disc.assign(m, vector<int>(n, -1)); low.assign(m, vector<int>(n, 0));\n        int land = 0, sr = -1, sc = -1;\n        for (int r = 0; r < m; r++)\n            for (int c = 0; c < n; c++)\n                if (grid[r][c]) { land++; if (sr < 0) { sr = r; sc = c; } }\n        if (!land) return 0;\n        dfs(grid, sr, sc, -1, -1);\n        if (timer < land) return 0;\n        if (land == 1 || cut) return 1;\n        return 2;\n    }\n};",
 "minimum-number-of-days-to-make-m-bouquets": "class Solution {\npublic:\n    int minDays(vector<int>& bloomDay, int m, int k) {\n        if ((long long)m * k > (long long)bloomDay.size()) return -1;\n        auto ok = [&](int d) {   // can we make m bouquets by day d?\n            int made = 0, run = 0;\n            for (int b : bloomDay) {\n                run = b <= d ? run + 1 : 0;\n                if (run == k) { made++; run = 0; }\n            }\n            return made >= m;\n        };\n        int lo = *min_element(bloomDay.begin(), bloomDay.end()), hi = *max_element(bloomDay.begin(), bloomDay.end());\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (ok(mid)) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "minimum-number-of-flips-to-convert-binary-matrix-to-zero-matrix": "class Solution {\npublic:\n    int minFlips(vector<vector<int>>& mat) {\n        int m = mat.size(), n = mat[0].size();\n        int start = 0;\n        for (int r = 0; r < m; r++)\n            for (int c = 0; c < n; c++) start |= mat[r][c] << (r * n + c);   // the grid as a bitmask\n        vector<int> flips;                                                      // mask each cell toggles\n        const int dy[] = {0, 1, -1, 0, 0}, dx[] = {0, 0, 0, 1, -1};\n        for (int r = 0; r < m; r++)\n            for (int c = 0; c < n; c++) {\n                int f = 0;\n                for (int d = 0; d < 5; d++) {\n                    int y = r + dy[d], x = c + dx[d];\n                    if (y >= 0 && y < m && x >= 0 && x < n) f |= 1 << (y * n + x);\n                }\n                flips.push_back(f);\n            }\n        unordered_map<int, int> dist{{start, 0}};\n        queue<int> q;\n        q.push(start);\n        while (!q.empty()) {                    // BFS over grid states\n            int s = q.front();\n            q.pop();\n            if (s == 0) return dist[s];\n            for (int f : flips) {\n                int t = s ^ f;\n                if (!dist.count(t)) {\n                    dist[t] = dist[s] + 1;\n                    q.push(t);\n                }\n            }\n        }\n        return -1;\n    }\n};",
 "minimum-number-of-k-consecutive-bit-flips": "class Solution {\npublic:\n    int minKBitFlips(vector<int>& nums, int k) {\n        int n = nums.size(), cur = 0, ans = 0;   // cur: parity of flips covering i\n        vector<int> started(n, 0);\n        for (int i = 0; i < n; i++) {\n            if (i >= k) cur ^= started[i - k];   // a flip that no longer reaches i\n            if ((nums[i] ^ cur) == 0) {          // still 0: start a flip here\n                if (i + k > n) return -1;\n                started[i] = 1;\n                cur ^= 1;\n                ans++;\n            }\n        }\n        return ans;\n    }\n};",
 "minimum-number-of-operations-to-make-all-array-elements-equal-to-1": "class Solution {\npublic:\n    int minOperations(vector<int>& nums) {\n        int n = nums.size(), ones = count(nums.begin(), nums.end(), 1);\n        if (ones) return n - ones;   // each 1 spreads to a neighbour in one step\n        int best = INT_MAX;\n        for (int i = 0; i < n; i++) {\n            int g = nums[i];\n            for (int j = i + 1; j < n; j++) {\n                g = gcd(g, nums[j]);\n                if (g == 1) { best = min(best, j - i); break; }   // shortest window with gcd 1\n            }\n        }\n        return best == INT_MAX ? -1 : best + n - 1;\n    }\n};",
 "minimum-number-of-operations-to-make-array-continuous": "class Solution {\npublic:\n    int minOperations(vector<int>& nums) {\n        int n = nums.size();\n        vector<int> a = nums;\n        sort(a.begin(), a.end());\n        a.erase(unique(a.begin(), a.end()), a.end());   // distinct values, sorted\n        int best = 0, j = 0;\n        for (int i = 0; i < (int)a.size(); i++) {\n            while (j < (int)a.size() && a[j] < (long long)a[i] + n) j++;   // values that fit in [a[i], a[i] + n)\n            best = max(best, j - i);\n        }\n        return n - best;\n    }\n};",
 "minimum-number-of-operations-to-make-array-empty": "class Solution {\npublic:\n    int minOperations(vector<int>& nums) {\n        unordered_map<int, int> cnt;\n        for (int x : nums) cnt[x]++;\n        int ops = 0;\n        for (auto& [v, c] : cnt) {\n            if (c == 1) return -1;\n            ops += (c + 2) / 3;   // as many triples as possible, pairs for the rest\n        }\n        return ops;\n    }\n};",
 "minimum-number-of-operations-to-move-all-balls-to-each-box": "class Solution {\npublic:\n    vector<int> minOperations(string boxes) {\n        int n = boxes.size();\n        vector<int> out(n, 0);\n        for (int pass = 0; pass < 2; pass++) {   // left to right, then right to left\n            int balls = 0, moves = 0;\n            for (int k = 0; k < n; k++) {\n                int i = pass == 0 ? k : n - 1 - k;\n                out[i] += moves;\n                balls += boxes[i] == '1';\n                moves += balls;                  // every ball so far moves one more step\n            }\n        }\n        return out;\n    }\n};",
 "minimum-number-of-pushes-to-type-word-ii": "class Solution {\npublic:\n    int minimumPushes(string word) {\n        vector<int> freq(26, 0);\n        for (char c : word) freq[c - 'a']++;\n        sort(freq.rbegin(), freq.rend());   // commonest letters get the first press\n        int total = 0;\n        for (int i = 0; i < 26; i++) total += freq[i] * (i / 8 + 1);   // 8 keys per press level\n        return total;\n    }\n};",
 "minimum-number-of-refueling-stops": "class Solution {\npublic:\n    int minRefuelStops(int target, int startFuel, vector<vector<int>>& stations) {\n        priority_queue<int> heap;   // fuel of stations we passed, biggest on top\n        long long fuel = startFuel;\n        int stops = 0, i = 0;\n        while (fuel < target) {\n            while (i < (int)stations.size() && stations[i][0] <= fuel) heap.push(stations[i++][1]);\n            if (heap.empty()) return -1;\n            fuel += heap.top();   // stop at the best station we could have reached\n            heap.pop();\n            stops++;\n        }\n        return stops;\n    }\n};",
 "minimum-number-of-steps-to-make-two-strings-anagram": "class Solution {\npublic:\n    int minSteps(string s, string t) {\n        int need[26] = {};\n        for (char c : s) need[c - 'a']++;\n        for (char c : t) need[c - 'a']--;\n        int steps = 0;\n        for (int k : need) if (k > 0) steps += k;   // letters t is short of\n        return steps;\n    }\n};",
 "minimum-number-of-taps-to-open-to-water-a-garden": "class Solution {\npublic:\n    int minTaps(int n, vector<int>& ranges) {\n        vector<int> reach(n + 1, 0);                     // furthest point a tap starting at lo can water\n        for (int i = 0; i <= n; i++) {\n            int lo = max(0, i - ranges[i]);\n            reach[lo] = max(reach[lo], i + ranges[i]);\n        }\n        int taps = 0, end = 0, far = 0;\n        for (int i = 0; i < n; i++) {\n            far = max(far, reach[i]);\n            if (i == end) {\n                if (far <= i) return -1;                 // a gap nothing covers\n                taps++;\n                end = far;\n            }\n        }\n        return taps;\n    }\n};",
 "minimum-number-of-work-sessions-to-finish-the-tasks": "class Solution {\npublic:\n    int minSessions(vector<int>& tasks, int sessionTime) {\n        int n = tasks.size();\n        vector<pair<int, int>> dp(1 << n, {n + 1, 0});   // per set of done tasks: (sessions, time used in the last)\n        dp[0] = {1, 0};\n        for (int mask = 0; mask < (1 << n); mask++) {\n            auto [s, used] = dp[mask];\n            for (int i = 0; i < n; i++)\n                if (!(mask >> i & 1)) {\n                    int t = tasks[i];\n                    pair<int, int> nxt = used + t <= sessionTime ? pair{s, used + t} : pair{s + 1, t};\n                    int m2 = mask | 1 << i;\n                    dp[m2] = min(dp[m2], nxt);\n                }\n        }\n        return dp.back().first;\n    }\n};",
 "minimum-obstacle-removal-to-reach-corner": "class Solution {\npublic:\n    int minimumObstacles(vector<vector<int>>& grid) {\n        int m = grid.size(), n = grid[0].size();\n        vector<vector<int>> dist(m, vector<int>(n, INT_MAX));\n        dist[0][0] = 0;\n        deque<pair<int, int>> dq{{0, 0}};\n        const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        while (!dq.empty()) {                  // 0-1 BFS\n            auto [r, c] = dq.front();\n            dq.pop_front();\n            for (int k = 0; k < 4; k++) {\n                int nr = r + dr[k], nc = c + dc[k];\n                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;\n                int nd = dist[r][c] + grid[nr][nc];\n                if (nd < dist[nr][nc]) {\n                    dist[nr][nc] = nd;\n                    if (grid[nr][nc]) dq.push_back({nr, nc});   // costs 1: to the back\n                    else dq.push_front({nr, nc});               // free: to the front\n                }\n            }\n        }\n        return dist[m - 1][n - 1];\n    }\n};",
 "minimum-operations-to-make-a-subsequence": "class Solution {\npublic:\n    int minOperations(vector<int>& target, vector<int>& arr) {\n        unordered_map<int, int> pos;   // target values are distinct\n        for (int i = 0; i < (int)target.size(); i++) pos[target[i]] = i;\n        vector<int> tails;   // longest increasing subsequence of positions\n        for (int x : arr) {\n            auto it = pos.find(x);\n            if (it == pos.end()) continue;\n            auto k = lower_bound(tails.begin(), tails.end(), it->second);\n            if (k == tails.end()) tails.push_back(it->second);\n            else *k = it->second;\n        }\n        return target.size() - tails.size();\n    }\n};",
 "minimum-operations-to-make-a-uni-value-grid": "class Solution {\npublic:\n    int minOperations(vector<vector<int>>& grid, int x) {\n        vector<int> vals;\n        for (auto& row : grid) vals.insert(vals.end(), row.begin(), row.end());\n        sort(vals.begin(), vals.end());\n        for (int v : vals) if ((v - vals[0]) % x) return -1;   // all must share a remainder\n        int mid = vals[vals.size() / 2];                       // the median minimises the moves\n        int ops = 0;\n        for (int v : vals) ops += abs(v - mid) / x;\n        return ops;\n    }\n};",
 "minimum-operations-to-make-array-equal": "class Solution {\npublic:\n    int minOperations(int n) { return n * n / 4; }   // sum of the gaps above the middle\n};",
 "minimum-path-sum": "class Solution {\npublic:\n    int minPathSum(vector<vector<int>>& grid) {\n        int R = grid.size(), C = grid[0].size();\n        vector<int> dp(C, INT_MAX);                      // one row of best sums\n        dp[0] = 0;\n        for (int i = 0; i < R; i++) {\n            dp[0] += grid[i][0];\n            for (int j = 1; j < C; j++) dp[j] = grid[i][j] + min(dp[j], dp[j - 1]);\n        }\n        return dp[C - 1];\n    }\n};",
 "minimum-remove-to-make-valid-parentheses": "class Solution {\npublic:\n    string minRemoveToMakeValid(string s) {\n        vector<bool> drop(s.size(), false);\n        vector<int> st;                                // indexes of unmatched '('\n        for (int i = 0; i < (int)s.size(); i++) {\n            if (s[i] == '(') st.push_back(i);\n            else if (s[i] == ')') {\n                if (!st.empty()) st.pop_back();\n                else drop[i] = true;                   // ')' with nothing to close\n            }\n        }\n        for (int i : st) drop[i] = true;               // '(' never closed\n        string out;\n        for (int i = 0; i < (int)s.size(); i++) if (!drop[i]) out += s[i];\n        return out;\n    }\n};",
 "minimum-rounds-to-complete-all-tasks": "class Solution {\npublic:\n    int minimumRounds(vector<int>& tasks) {\n        unordered_map<int, int> cnt;\n        for (int t : tasks) cnt[t]++;\n        int ans = 0;\n        for (auto& [t, c] : cnt) {\n            if (c == 1) return -1;\n            ans += (c + 2) / 3;     // as many 3s as possible, a 2 or two to finish\n        }\n        return ans;\n    }\n};",
 "minimum-score-after-removals-on-a-tree": "class Solution {\n    vector<vector<int>> adj;\n    vector<int> xr, tin, tout;\n    int t = 0;\n    void dfs(int u, int p) {\n        tin[u] = t++;\n        for (int v : adj[u])\n            if (v != p) {\n                dfs(v, u);\n                xr[u] ^= xr[v];         // xor of the whole subtree\n            }\n        tout[u] = t;\n    }\n    bool anc(int a, int b) { return tin[a] <= tin[b] && tin[b] < tout[a]; }   // a is above b\npublic:\n    int minimumScore(vector<int>& nums, vector<vector<int>>& edges) {\n        int n = nums.size();\n        adj.assign(n, {});\n        for (auto& e : edges) {\n            adj[e[0]].push_back(e[1]);\n            adj[e[1]].push_back(e[0]);\n        }\n        xr = nums;\n        tin.assign(n, 0);\n        tout.assign(n, 0);\n        dfs(0, -1);\n        int total = xr[0], best = INT_MAX;\n        // cut the edges above nodes i and j\n        for (int i = 1; i < n; i++)\n            for (int j = i + 1; j < n; j++) {\n                int a, b, c;\n                if (anc(i, j)) { a = xr[j]; b = xr[i] ^ xr[j]; c = total ^ xr[i]; }\n                else if (anc(j, i)) { a = xr[i]; b = xr[j] ^ xr[i]; c = total ^ xr[j]; }\n                else { a = xr[i]; b = xr[j]; c = total ^ xr[i] ^ xr[j]; }\n                best = min(best, max({a, b, c}) - min({a, b, c}));\n            }\n        return best;\n    }\n};",
 "minimum-sideway-jumps": "class Solution {\npublic:\n    int minSideJumps(vector<int>& obstacles) {\n        const int INF = INT_MAX / 2;\n        array<int, 3> dp{1, 0, 1};       // fewest jumps to stand in each lane\n        for (size_t i = 1; i < obstacles.size(); i++) {\n            int o = obstacles[i];\n            if (o) dp[o - 1] = INF;\n            int best = *min_element(dp.begin(), dp.end());\n            for (int lane = 0; lane < 3; lane++)\n                if (lane != o - 1) dp[lane] = min(dp[lane], best + 1);   // jump over from the best lane\n        }\n        return *min_element(dp.begin(), dp.end());\n    }\n};",
 "minimum-size-subarray-sum": "class Solution {\npublic:\n    int minSubArrayLen(int target, vector<int>& nums) {\n        int n = nums.size(), l = 0, s = 0, best = n + 1;\n        for (int r = 0; r < n; r++) {\n            s += nums[r];\n            while (s >= target) {                          // shrink while still enough\n                best = min(best, r - l + 1);\n                s -= nums[l++];\n            }\n        }\n        return best <= n ? best : 0;\n    }\n};",
 "minimum-speed-to-arrive-on-time": "class Solution {\npublic:\n    int minSpeedOnTime(vector<int>& dist, double hour) {\n        int n = dist.size();\n        if (hour <= n - 1) return -1;   // every train but the last takes a whole hour at least\n        auto time = [&](int v) {\n            long long whole = 0;\n            for (int i = 0; i + 1 < n; i++) whole += (dist[i] + v - 1) / v;   // wait for the next whole hour\n            return whole + (double)dist[n - 1] / v;\n        };\n        int lo = 1, hi = 10'000'000;\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (time(mid) <= hour) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "minimum-suffix-flips": "class Solution {\npublic:\n    int minFlips(string target) {\n        int flips = 0;\n        char cur = '0';\n        for (char c : target)\n            if (c != cur) { flips++; cur = c; }   // each change of bit needs one flip\n        return flips;\n    }\n};",
 "minimum-sum-of-squared-difference": "class Solution {\npublic:\n    long long minSumSquareDiff(vector<int>& nums1, vector<int>& nums2, int k1, int k2) {\n        vector<long long> d;\n        for (size_t i = 0; i < nums1.size(); i++) d.push_back(abs(nums1[i] - nums2[i]));\n        sort(d.rbegin(), d.rend());\n        long long k = (long long)k1 + k2;\n        if (accumulate(d.begin(), d.end(), 0LL) <= k) return 0;\n        d.push_back(0);\n        long long i = 0;                 // d[0..i] are all levelled to d[i]\n        while ((i + 1) * (d[i] - d[i + 1]) <= k) {\n            k -= (i + 1) * (d[i] - d[i + 1]);\n            i++;\n        }\n        long long q = k / (i + 1), r = k % (i + 1);\n        long long level = d[i] - q;      // r of them go one lower still\n        long long ans = r * (level - 1) * (level - 1) + (i + 1 - r) * level * level;\n        for (size_t j = i + 1; j < d.size(); j++) ans += d[j] * d[j];\n        return ans;\n    }\n};",
 "minimum-swaps-to-arrange-a-binary-grid": "class Solution {\npublic:\n    int minSwaps(vector<vector<int>>& grid) {\n        int n = grid.size();\n        vector<int> tz;                          // trailing zeros of each row\n        for (auto& row : grid) {\n            int z = 0;\n            while (z < n && row[n - 1 - z] == 0) z++;\n            tz.push_back(z);\n        }\n        int swaps = 0;\n        for (int i = 0; i < n; i++) {\n            int need = n - 1 - i, j = i;\n            while (j < n && tz[j] < need) j++;   // nearest row below that fits\n            if (j == n) return -1;\n            int v = tz[j];\n            tz.erase(tz.begin() + j);            // bubble it up to row i\n            tz.insert(tz.begin() + i, v);\n            swaps += j - i;\n        }\n        return swaps;\n    }\n};",
 "minimum-time-difference": "class Solution {\npublic:\n    int findMinDifference(vector<string>& timePoints) {\n        vector<int> m;\n        for (auto& t : timePoints) m.push_back(stoi(t.substr(0, 2)) * 60 + stoi(t.substr(3)));\n        sort(m.begin(), m.end());\n        int best = m[0] + 1440 - m.back();   // wrap past midnight\n        for (size_t i = 1; i < m.size(); i++) best = min(best, m[i] - m[i - 1]);\n        return best;\n    }\n};",
 "minimum-time-to-complete-trips": "class Solution {\npublic:\n    long long minimumTime(vector<int>& time, int totalTrips) {\n        long long lo = 1, hi = (long long)*min_element(time.begin(), time.end()) * totalTrips;\n        while (lo < hi) {\n            long long mid = lo + (hi - lo) / 2, trips = 0;\n            for (int t : time) trips += mid / t;\n            if (trips >= totalTrips) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "minimum-time-to-repair-cars": "class Solution {\n    static long long isqrt(long long x) {\n        long long s = sqrtl((long double)x);\n        while (s * s > x) s--;\n        while ((s + 1) * (s + 1) <= x) s++;\n        return s;\n    }\npublic:\n    long long repairCars(vector<int>& ranks, int cars) {\n        long long lo = 1, hi = (long long)*min_element(ranks.begin(), ranks.end()) * cars * cars;\n        while (lo < hi) {\n            long long mid = lo + (hi - lo) / 2;\n            long long fixed = 0;\n            for (int r : ranks) fixed += isqrt(mid / r);   // r * c^2 <= mid\n            if (fixed >= cars) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n};",
 "minimum-weighted-subgraph-with-the-required-paths": "class Solution {\n    using Graph = vector<vector<pair<int, int>>>;\n    static constexpr long long INF = LLONG_MAX / 4;\n    vector<long long> dijkstra(int src, const Graph& adj) {\n        vector<long long> dist(adj.size(), INF);\n        dist[src] = 0;\n        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> heap;\n        heap.push({0, src});\n        while (!heap.empty()) {\n            auto [d, u] = heap.top();\n            heap.pop();\n            if (d > dist[u]) continue;\n            for (auto [v, w] : adj[u])\n                if (d + w < dist[v]) {\n                    dist[v] = d + w;\n                    heap.push({dist[v], v});\n                }\n        }\n        return dist;\n    }\npublic:\n    long long minimumWeight(int n, vector<vector<int>>& edges, int src1, int src2, int dest) {\n        Graph fwd(n), rev(n);\n        for (auto& e : edges) {\n            fwd[e[0]].push_back({e[1], e[2]});\n            rev[e[1]].push_back({e[0], e[2]});\n        }\n        auto a = dijkstra(src1, fwd), b = dijkstra(src2, fwd), c = dijkstra(dest, rev);\n        long long best = INF;\n        for (int i = 0; i < n; i++) best = min(best, a[i] + b[i] + c[i]);   // the paths meet at i\n        return best >= INF ? -1 : best;\n    }\n};",
 "minimum-window-substring": "class Solution {\npublic:\n    string minWindow(string s, string t) {\n        int need[128] = {};\n        for (char ch : t) need[(unsigned char)ch]++;\n        int missing = t.size(), l = 0, bestL = 0, bestR = -1;\n        for (int r = 0; r < (int)s.size(); r++) {\n            if (need[(unsigned char)s[r]]-- > 0) missing--;          // this char was still needed\n            while (missing == 0) {                                    // window covers t: shrink from the left\n                if (bestR < 0 || r - l < bestR - bestL) { bestL = l; bestR = r; }\n                if (++need[(unsigned char)s[l]] > 0) missing++;\n                l++;\n            }\n        }\n        return bestR < 0 ? \"\" : s.substr(bestL, bestR - bestL + 1);\n    }\n};",
 "missing-number": "class Solution {\npublic:\n    int missingNumber(vector<int>& nums) {\n        int x = nums.size();\n        for (int i = 0; i < (int)nums.size(); i++) x ^= i ^ nums[i];   // every present number cancels its index\n        return x;\n    }\n};",
 "most-frequent-subtree-sum": "class Solution {\n    unordered_map<int, int> freq;\n    int best = 0;\n    int sum(TreeNode* t) {\n        if (!t) return 0;\n        int s = t->val + sum(t->left) + sum(t->right);\n        best = max(best, ++freq[s]);\n        return s;\n    }\npublic:\n    vector<int> findFrequentTreeSum(TreeNode* root) {\n        sum(root);\n        vector<int> ans;\n        for (auto& [s, c] : freq) if (c == best) ans.push_back(s);\n        return ans;\n    }\n};",
 "most-profit-assigning-work": "class Solution {\npublic:\n    int maxProfitAssignment(vector<int>& difficulty, vector<int>& profit, vector<int>& worker) {\n        vector<pair<int, int>> jobs;\n        for (size_t i = 0; i < difficulty.size(); i++) jobs.push_back({difficulty[i], profit[i]});\n        sort(jobs.begin(), jobs.end());\n        sort(worker.begin(), worker.end());\n        int best = 0, total = 0;\n        size_t i = 0;\n        for (int w : worker) {\n            while (i < jobs.size() && jobs[i].first <= w) best = max(best, jobs[i++].second);   // best job so far\n            total += best;\n        }\n        return total;\n    }\n};",
 "most-stones-removed-with-same-row-or-column": "class Solution {\npublic:\n    int removeStones(vector<vector<int>>& stones) {\n        unordered_map<int, int> parent;                // rows as r, columns as ~c so they never clash\n        function<int(int)> find = [&](int x) {\n            parent.emplace(x, x);\n            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }\n            return x;\n        };\n        for (auto& s : stones) {\n            int a = find(s[0]), b = find(~s[1]);\n            parent[a] = b;                             // a stone joins its row and its column\n        }\n        vector<int> keys;\n        for (auto& [x, _] : parent) keys.push_back(x);\n        unordered_set<int> groups;\n        for (int x : keys) groups.insert(find(x));\n        return stones.size() - groups.size();          // each group keeps one stone\n    }\n};",
 "move-pieces-to-obtain-a-string": "class Solution {\npublic:\n    bool canChange(string start, string target) {\n        int n = start.size(), i = 0, j = 0;\n        while (true) {\n            while (i < n && start[i] == '_') i++;\n            while (j < n && target[j] == '_') j++;\n            if (i == n || j == n) return i == n && j == n;\n            if (start[i] != target[j]) return false;      // pieces cannot pass each other\n            if (start[i] == 'L' && i < j) return false;   // L only moves left\n            if (start[i] == 'R' && i > j) return false;   // R only moves right\n            i++;\n            j++;\n        }\n    }\n};",
 "move-zeroes": "class Solution {\npublic:\n    void moveZeroes(vector<int>& nums) {\n        int w = 0;                                         // next slot for a non-zero\n        for (int r = 0; r < (int)nums.size(); r++)\n            if (nums[r] != 0) swap(nums[w++], nums[r]);\n    }\n};",
 "multiply-strings": "class Solution {\npublic:\n    string multiply(string num1, string num2) {\n        int m = num1.size(), n = num2.size();\n        vector<int> res(m + n, 0);\n        for (int i = m - 1; i >= 0; i--)\n            for (int j = n - 1; j >= 0; j--) {\n                int p = (num1[i] - '0') * (num2[j] - '0') + res[i + j + 1];\n                res[i + j + 1] = p % 10;          // digit stays here\n                res[i + j] += p / 10;             // carry moves one place left\n            }\n        string out;\n        for (int d : res) if (!(out.empty() && d == 0)) out += char('0' + d);   // skip leading zeros\n        return out.empty() ? \"0\" : out;\n    }\n};",
 "my-calendar-i": "class MyCalendar {\n    vector<int> starts, ends;   // bookings sorted by start\npublic:\n    MyCalendar() {}\n\n    bool book(int start, int end) {\n        int i = upper_bound(starts.begin(), starts.end(), start) - starts.begin();\n        if (i && ends[i - 1] > start) return false;                  // overlaps the booking before\n        if (i < (int)starts.size() && starts[i] < end) return false; // overlaps the booking after\n        starts.insert(starts.begin() + i, start);\n        ends.insert(ends.begin() + i, end);\n        return true;\n    }\n};",
 "my-calendar-ii": "class MyCalendarTwo {\n    vector<pair<int, int>> booked, overlaps;   // overlaps: ranges already booked twice\n\npublic:\n    MyCalendarTwo() {}\n\n    bool book(int start, int end) {\n        for (auto [s, e] : overlaps)\n            if (start < e && s < end) return false;   // would be a triple booking\n        for (auto [s, e] : booked)\n            if (start < e && s < end) overlaps.push_back({max(s, start), min(e, end)});\n        booked.push_back({start, end});\n        return true;\n    }\n};",
 "my-calendar-iii": "class MyCalendarThree {\n    map<int, int> delta;   // +1 where a booking starts, -1 where it ends\npublic:\n    MyCalendarThree() {}\n\n    int book(int startTime, int endTime) {\n        delta[startTime]++;\n        delta[endTime]--;\n        int best = 0, cur = 0;\n        for (auto& [t, d] : delta) {   // sweep in time order\n            cur += d;\n            best = max(best, cur);\n        }\n        return best;\n    }\n};",
 "n-ary-tree-level-order-traversal": "class Node {\npublic:\n    int val;\n    vector<Node*> children;\n\n    Node() {}\n\n    Node(int _val) {\n        val = _val;\n    }\n\n    Node(int _val, vector<Node*> _children) {\n        val = _val;\n        children = _children;\n    }\n};\n\nclass Solution {\npublic:\n    vector<vector<int>> levelOrder(Node* root) {\n        vector<vector<int>> out;\n        vector<Node*> level;\n        if (root) level.push_back(root);\n        while (!level.empty()) {\n            vector<int> vals;\n            vector<Node*> next;\n            for (Node* n : level) {\n                vals.push_back(n->val);\n                next.insert(next.end(), n->children.begin(), n->children.end());\n            }\n            out.push_back(vals);\n            level = move(next);\n        }\n        return out;\n    }\n};",
 "n-queens": "class Solution {\npublic:\n    vector<vector<string>> solveNQueens(int n) {\n        vector<vector<string>> out;\n        vector<bool> cols(n), d1(2 * n), d2(2 * n);       // used columns and diagonals (r - c + n, r + c)\n        vector<string> board(n, string(n, '.'));\n        function<void(int)> place = [&](int r) {\n            if (r == n) { out.push_back(board); return; }\n            for (int c = 0; c < n; c++) {\n                if (cols[c] || d1[r - c + n] || d2[r + c]) continue;\n                cols[c] = d1[r - c + n] = d2[r + c] = true;\n                board[r][c] = 'Q';\n                place(r + 1);\n                board[r][c] = '.';                         // undo before trying the next column\n                cols[c] = d1[r - c + n] = d2[r + c] = false;\n            }\n        };\n        place(0);\n        return out;\n    }\n};",
 "n-th-tribonacci-number": "class Solution {\npublic:\n    int tribonacci(int n) {\n        long long a = 0, b = 1, c = 1;             // c runs two terms ahead, so it can pass int\n        for (int i = 0; i < n; i++) {\n            long long next = a + b + c;\n            a = b; b = c; c = next;\n        }\n        return a;\n    }\n};",
 "nearest-exit-from-entrance-in-maze": "class Solution {\npublic:\n    int nearestExit(vector<vector<char>>& maze, vector<int>& entrance) {\n        int R = maze.size(), C = maze[0].size();\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        queue<tuple<int, int, int>> q;                 // (row, col, steps)\n        q.push({entrance[0], entrance[1], 0});\n        maze[entrance[0]][entrance[1]] = '+';          // mark visited by walling it off\n        while (!q.empty()) {\n            auto [r, c, d] = q.front(); q.pop();\n            for (int k = 0; k < 4; k++) {\n                int nr = r + dr[k], nc = c + dc[k];\n                if (nr >= 0 && nr < R && nc >= 0 && nc < C && maze[nr][nc] == '.') {\n                    if (nr == 0 || nr == R - 1 || nc == 0 || nc == C - 1) return d + 1;   // first border cell\n                    maze[nr][nc] = '+';\n                    q.push({nr, nc, d + 1});\n                }\n            }\n        }\n        return -1;\n    }\n};",
 "network-delay-time": "class Solution {\npublic:\n    int networkDelayTime(vector<vector<int>>& times, int n, int k) {\n        vector<vector<pair<int, int>>> adj(n + 1);\n        for (auto& t : times) adj[t[0]].push_back({t[1], t[2]});\n        vector<int> dist(n + 1, -1);                     // -1 means not settled yet\n        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> heap;\n        heap.push({0, k});\n        int settled = 0, last = 0;\n        while (!heap.empty()) {\n            auto [d, u] = heap.top(); heap.pop();\n            if (dist[u] != -1) continue;                 // already reached by a shorter path\n            dist[u] = d; settled++; last = max(last, d);\n            for (auto [v, w] : adj[u]) if (dist[v] == -1) heap.push({d + w, v});\n        }\n        return settled == n ? last : -1;\n    }\n};",
 "next-greater-element-i": "class Solution {\npublic:\n    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {\n        unordered_map<int, int> nxt;\n        vector<int> st;                                    // values still waiting for a bigger one\n        for (int x : nums2) {\n            while (!st.empty() && st.back() < x) { nxt[st.back()] = x; st.pop_back(); }\n            st.push_back(x);\n        }\n        vector<int> out;\n        for (int x : nums1) out.push_back(nxt.count(x) ? nxt[x] : -1);\n        return out;\n    }\n};",
 "next-greater-element-ii": "class Solution {\npublic:\n    vector<int> nextGreaterElements(vector<int>& nums) {\n        int n = nums.size();\n        vector<int> res(n, -1), st;   // st: indices still waiting for a greater value\n        for (int i = 0; i < 2 * n; i++) {   // two passes simulate the wrap-around\n            int x = nums[i % n];\n            while (!st.empty() && nums[st.back()] < x) {\n                res[st.back()] = x;\n                st.pop_back();\n            }\n            if (i < n) st.push_back(i);\n        }\n        return res;\n    }\n};",
 "next-greater-element-iii": "class Solution {\npublic:\n    int nextGreaterElement(int n) {\n        string d = to_string(n);\n        int i = d.size() - 2;\n        while (i >= 0 && d[i] >= d[i + 1]) i--;   // first digit from the right that can grow\n        if (i < 0) return -1;\n        int j = d.size() - 1;\n        while (d[j] <= d[i]) j--;                 // smallest digit to its right that is bigger\n        swap(d[i], d[j]);\n        reverse(d.begin() + i + 1, d.end());      // smallest tail\n        long long v = stoll(d);\n        return v <= INT_MAX ? v : -1;\n    }\n};",
 "next-greater-node-in-linked-list": "class Solution {\npublic:\n    vector<int> nextLargerNodes(ListNode* head) {\n        vector<int> vals;\n        for (; head; head = head->next) vals.push_back(head->val);\n        vector<int> ans(vals.size(), 0);\n        stack<int> st;                                   // indexes still waiting for a larger value\n        for (int i = 0; i < (int)vals.size(); i++) {\n            while (!st.empty() && vals[st.top()] < vals[i]) { ans[st.top()] = vals[i]; st.pop(); }\n            st.push(i);\n        }\n        return ans;\n    }\n};",
 "next-permutation": "class Solution {\npublic:\n    void nextPermutation(vector<int>& nums) {\n        int i = nums.size() - 2;\n        while (i >= 0 && nums[i] >= nums[i + 1]) i--;      // rightmost ascent\n        if (i >= 0) {\n            int j = nums.size() - 1;\n            while (nums[j] <= nums[i]) j--;                // smallest bigger value to its right\n            swap(nums[i], nums[j]);\n        }\n        reverse(nums.begin() + i + 1, nums.end());\n    }\n};",
 "non-decreasing-subsequences": "class Solution {\n    vector<vector<int>> out;\n    vector<int> path;\n    void go(const vector<int>& nums, int start) {\n        if (path.size() > 1) out.push_back(path);\n        unordered_set<int> used;                 // values already tried at this depth\n        for (int i = start; i < (int)nums.size(); i++) {\n            if (used.count(nums[i]) || (!path.empty() && nums[i] < path.back())) continue;\n            used.insert(nums[i]);\n            path.push_back(nums[i]);\n            go(nums, i + 1);\n            path.pop_back();\n        }\n    }\npublic:\n    vector<vector<int>> findSubsequences(vector<int>& nums) {\n        go(nums, 0);\n        return out;\n    }\n};",
 "non-negative-integers-without-consecutive-ones": "class Solution {\npublic:\n    int findIntegers(int n) {\n        int fib[32] = {1, 2};                 // fib[k] = k-bit strings with no two adjacent 1s\n        for (int k = 2; k < 32; k++) fib[k] = fib[k - 1] + fib[k - 2];\n        int total = 0;\n        bool prev = false;\n        for (int b = 30; b >= 0; b--) {\n            if (!(n >> b & 1)) { prev = false; continue; }\n            total += fib[b];                  // a 0 here leaves b free bits\n            if (prev) return total;\n            prev = true;\n        }\n        return total + 1;\n    }\n};",
 "non-overlapping-intervals": "class Solution {\npublic:\n    int eraseOverlapIntervals(vector<vector<int>>& intervals) {\n        sort(intervals.begin(), intervals.end(), [](auto& a, auto& b) { return a[1] < b[1]; });   // earliest end first\n        long long end = LLONG_MIN;\n        int removed = 0;\n        for (auto& iv : intervals) {\n            if (iv[0] >= end) end = iv[1];\n            else removed++;\n        }\n        return removed;\n    }\n};",
 "nth-magical-number": "class Solution {\npublic:\n    int nthMagicalNumber(int n, int a, int b) {\n        long long lcm = (long long)a / gcd(a, b) * b;\n        long long lo = 1, hi = (long long)n * min(a, b);\n        while (lo < hi) {\n            long long mid = lo + (hi - lo) / 2;\n            if (mid / a + mid / b - mid / lcm >= n) hi = mid;   // magical numbers <= mid\n            else lo = mid + 1;\n        }\n        return lo % 1000000007;\n    }\n};",
 "number-of-1-bits": "class Solution {\npublic:\n    int hammingWeight(int n) {\n        int count = 0;\n        while (n) {\n            n &= n - 1;                                      // clears the lowest set bit\n            count++;\n        }\n        return count;\n    }\n};",
 "number-of-digit-one": "class Solution {\npublic:\n    int countDigitOne(int n) {\n        string s = to_string(n);\n        int L = s.size();\n        long long total = 0, ones = 0;        // ones = 1s in n's prefix so far\n        for (int i = 0; i < L; i++) {\n            int d = s[i] - '0', r = L - i - 1;\n            long long p = 1;\n            for (int t = 0; t < r; t++) p *= 10;\n            for (int x = 0; x < d; x++)       // x below n's digit: the last r digits are free\n                total += (ones + (x == 1)) * p + r * p / 10;\n            ones += d == 1;\n        }\n        return total + ones;\n    }\n};",
 "number-of-flowers-in-full-bloom": "class Solution {\npublic:\n    vector<int> fullBloomFlowers(vector<vector<int>>& flowers, vector<int>& people) {\n        vector<int> starts, ends;\n        for (auto& f : flowers) { starts.push_back(f[0]); ends.push_back(f[1]); }\n        sort(starts.begin(), starts.end());\n        sort(ends.begin(), ends.end());\n        vector<int> out;\n        for (int t : people)   // started by t, minus ended before t\n            out.push_back((upper_bound(starts.begin(), starts.end(), t) - starts.begin()) - (lower_bound(ends.begin(), ends.end(), t) - ends.begin()));\n        return out;\n    }\n};",
 "number-of-good-leaf-nodes-pairs": "class Solution {\npublic:\n    int countPairs(TreeNode* root, int distance) {\n        int ans = 0;\n        // distances from node down to each leaf below it, only those still under distance\n        function<vector<int>(TreeNode*)> dfs = [&](TreeNode* node) -> vector<int> {\n            if (!node) return {};\n            if (!node->left && !node->right) return {1};\n            vector<int> L = dfs(node->left), R = dfs(node->right);\n            for (int a : L)\n                for (int b : R)\n                    if (a + b <= distance) ans++;      // pairs that meet at this node\n            vector<int> up;\n            for (auto* side : {&L, &R})\n                for (int d : *side)\n                    if (d + 1 < distance) up.push_back(d + 1);\n            return up;\n        };\n        dfs(root);\n        return ans;\n    }\n};",
 "number-of-good-ways-to-split-a-string": "class Solution {\npublic:\n    int numSplits(string s) {\n        int n = s.size();\n        vector<int> left(n), right(n + 1, 0);   // distinct letters in s[..i] and in s[i..]\n        set<char> seen;\n        for (int i = 0; i < n; i++) {\n            seen.insert(s[i]);\n            left[i] = seen.size();\n        }\n        seen.clear();\n        for (int i = n - 1; i >= 0; i--) {\n            seen.insert(s[i]);\n            right[i] = seen.size();\n        }\n        int ans = 0;\n        for (int i = 0; i + 1 < n; i++) ans += left[i] == right[i + 1];\n        return ans;\n    }\n};",
 "number-of-islands": "class Solution {\n    void sink(vector<vector<char>>& grid, int r, int c) {\n        if (r < 0 || r >= (int)grid.size() || c < 0 || c >= (int)grid[0].size() || grid[r][c] != '1') return;\n        grid[r][c] = '0';\n        sink(grid, r + 1, c); sink(grid, r - 1, c); sink(grid, r, c + 1); sink(grid, r, c - 1);\n    }\n\npublic:\n    int numIslands(vector<vector<char>>& grid) {\n        int count = 0;\n        for (int r = 0; r < (int)grid.size(); r++)\n            for (int c = 0; c < (int)grid[0].size(); c++)\n                if (grid[r][c] == '1') { count++; sink(grid, r, c); }   // a new island: sink all of it\n        return count;\n    }\n};",
 "number-of-laser-beams-in-a-bank": "class Solution {\npublic:\n    int numberOfBeams(vector<string>& bank) {\n        int prev = 0, ans = 0;\n        for (auto& row : bank) {\n            int c = count(row.begin(), row.end(), '1');\n            if (c) {                 // empty rows are skipped\n                ans += prev * c;\n                prev = c;\n            }\n        }\n        return ans;\n    }\n};",
 "number-of-longest-increasing-subsequence": "class Solution {\npublic:\n    int findNumberOfLIS(vector<int>& nums) {\n        int n = nums.size();\n        vector<int> length(n, 1), count(n, 1);               // longest run ending at i, and how many\n        for (int i = 0; i < n; i++)\n            for (int j = 0; j < i; j++)\n                if (nums[j] < nums[i]) {\n                    if (length[j] + 1 > length[i]) { length[i] = length[j] + 1; count[i] = count[j]; }\n                    else if (length[j] + 1 == length[i]) count[i] += count[j];\n                }\n        int best = *max_element(length.begin(), length.end()), total = 0;\n        for (int i = 0; i < n; i++) if (length[i] == best) total += count[i];\n        return total;\n    }\n};",
 "number-of-operations-to-make-network-connected": "class Solution {\npublic:\n    int makeConnected(int n, vector<vector<int>>& connections) {\n        if ((int)connections.size() < n - 1) return -1;   // not enough cables\n        vector<int> parent(n);\n        iota(parent.begin(), parent.end(), 0);\n        auto find = [&](int x) {\n            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }   // path halving\n            return x;\n        };\n        int comps = n;\n        for (auto& c : connections) {\n            int ra = find(c[0]), rb = find(c[1]);\n            if (ra != rb) { parent[ra] = rb; comps--; }\n        }\n        return comps - 1;   // one cable joins two components\n    }\n};",
 "number-of-provinces": "class Solution {\npublic:\n    int findCircleNum(vector<vector<int>>& isConnected) {\n        int n = isConnected.size();\n        vector<bool> seen(n, false);\n        function<void(int)> dfs = [&](int u) {\n            seen[u] = true;\n            for (int v = 0; v < n; v++)\n                if (isConnected[u][v] && !seen[v]) dfs(v);\n        };\n        int provinces = 0;\n        for (int u = 0; u < n; u++)\n            if (!seen[u]) {   // a new city starts a new province\n                provinces++;\n                dfs(u);\n            }\n        return provinces;\n    }\n};",
 "number-of-smooth-descent-periods-of-a-stock": "class Solution {\npublic:\n    long long getDescentPeriods(vector<int>& prices) {\n        long long ans = 0, run = 0;\n        for (size_t i = 0; i < prices.size(); i++) {\n            run = (i && prices[i - 1] - prices[i] == 1) ? run + 1 : 1;   // periods ending at i\n            ans += run;\n        }\n        return ans;\n    }\n};",
 "number-of-steps-to-reduce-a-number-in-binary-representation-to-one": "class Solution {\npublic:\n    int numSteps(string s) {\n        int steps = 0, carry = 0;\n        for (int i = s.size() - 1; i > 0; i--) {\n            int bit = (s[i] - '0') + carry;\n            if (bit == 1) {        // odd: add 1 (carry on) and then halve\n                steps += 2;\n                carry = 1;\n            } else steps += 1;     // even: just halve\n        }\n        return steps + carry;\n    }\n};",
 "number-of-subarrays-with-bounded-maximum": "class Solution {\npublic:\n    int numSubarrayBoundedMax(vector<int>& nums, int left, int right) {\n        int bad = -1, good = -1, ans = 0;   // last index above right, last index in range\n        for (int i = 0; i < (int)nums.size(); i++) {\n            int x = nums[i];\n            if (x > right) bad = i;\n            if (left <= x && x <= right) good = i;\n            ans += max(0, good - bad);      // starts after bad that still include good\n        }\n        return ans;\n    }\n};",
 "number-of-submatrices-that-sum-to-target": "class Solution {\npublic:\n    int numSubmatrixSumTarget(vector<vector<int>>& matrix, int target) {\n        int m = matrix.size(), n = matrix[0].size(), ans = 0;\n        for (int top = 0; top < m; top++) {\n            vector<int> col(n, 0);   // column sums of rows top..bot\n            for (int bot = top; bot < m; bot++) {\n                for (int j = 0; j < n; j++) col[j] += matrix[bot][j];\n                unordered_map<int, int> seen{{0, 1}};   // then subarray sum equals target on col\n                int s = 0;\n                for (int x : col) {\n                    s += x;\n                    if (auto it = seen.find(s - target); it != seen.end()) ans += it->second;\n                    seen[s]++;\n                }\n            }\n        }\n        return ans;\n    }\n};",
 "number-of-substrings-containing-all-three-characters": "class Solution {\npublic:\n    int numberOfSubstrings(string s) {\n        int last[3] = {-1, -1, -1};   // latest index of a, b, c\n        int ans = 0;\n        for (int i = 0; i < (int)s.size(); i++) {\n            last[s[i] - 'a'] = i;\n            ans += min({last[0], last[1], last[2]}) + 1;   // starts that still include all three\n        }\n        return ans;\n    }\n};",
 "number-of-substrings-with-only-1s": "class Solution {\npublic:\n    int numSub(string s) {\n        const long long MOD = 1'000'000'007;\n        long long run = 0, total = 0;\n        for (char ch : s) {\n            run = ch == '1' ? run + 1 : 0;\n            total += run;            // substrings of ones ending here\n        }\n        return total % MOD;\n    }\n};",
 "number-of-valid-words-for-each-puzzle": "class Solution {\n    static int mask(const string& w, size_t from = 0) {\n        int m = 0;\n        for (size_t i = from; i < w.size(); i++) m |= 1 << (w[i] - 'a');\n        return m;\n    }\npublic:\n    vector<int> findNumOfValidWords(vector<string>& words, vector<string>& puzzles) {\n        unordered_map<int, int> count;           // letter set -> words with exactly that set\n        for (auto& w : words) count[mask(w)]++;\n        vector<int> out;\n        for (auto& p : puzzles) {\n            int first = 1 << (p[0] - 'a'), rest = mask(p, 1), total = 0;\n            for (int sub = rest;; sub = (sub - 1) & rest) {   // every subset of the other 6 letters\n                auto it = count.find(sub | first);\n                if (it != count.end()) total += it->second;\n                if (sub == 0) break;\n            }\n            out.push_back(total);\n        }\n        return out;\n    }\n};",
 "number-of-ways-to-arrive-at-destination": "class Solution {\npublic:\n    int countPaths(int n, vector<vector<int>>& roads) {\n        const int MOD = 1e9 + 7;\n        vector<vector<pair<int, int>>> g(n);\n        for (auto& r : roads) {\n            g[r[0]].push_back({r[1], r[2]});\n            g[r[1]].push_back({r[0], r[2]});\n        }\n        vector<long long> dist(n, LLONG_MAX);\n        vector<int> ways(n, 0);\n        dist[0] = 0;\n        ways[0] = 1;\n        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;\n        pq.push({0, 0});\n        while (!pq.empty()) {\n            auto [d, u] = pq.top();\n            pq.pop();\n            if (d > dist[u]) continue;   // stale entry\n            for (auto [v, t] : g[u]) {\n                long long nd = d + t;\n                if (nd < dist[v]) {   // a shorter way: its count replaces the old one\n                    dist[v] = nd;\n                    ways[v] = ways[u];\n                    pq.push({nd, v});\n                } else if (nd == dist[v]) {   // another shortest way\n                    ways[v] = (ways[v] + ways[u]) % MOD;\n                }\n            }\n        }\n        return ways[n - 1];\n    }\n};",
 "number-of-ways-to-split-a-string": "class Solution {\npublic:\n    int numWays(string s) {\n        const long long MOD = 1'000'000'007;\n        long long n = s.size();\n        vector<long long> pos;                            // indexes of the ones\n        for (int i = 0; i < n; i++) if (s[i] == '1') pos.push_back(i);\n        long long ones = pos.size();\n        if (ones % 3) return 0;\n        if (ones == 0) return (n - 1) * (n - 2) / 2 % MOD;  // choose 2 of the n - 1 cut positions\n        long long t = ones / 3;\n        return (pos[t] - pos[t - 1]) * (pos[2 * t] - pos[2 * t - 1]) % MOD;\n    }\n};",
 "number-of-ways-to-split-array": "class Solution {\npublic:\n    int waysToSplitArray(vector<int>& nums) {\n        long long total = accumulate(nums.begin(), nums.end(), 0LL), left = 0;\n        int ways = 0;\n        for (size_t i = 0; i + 1 < nums.size(); i++) {\n            left += nums[i];\n            if (left >= total - left) ways++;\n        }\n        return ways;\n    }\n};",
 "number-of-wonderful-substrings": "class Solution {\npublic:\n    long long wonderfulSubstrings(string word) {\n        vector<long long> cnt(1024, 0);   // parity mask of a prefix -> how many\n        cnt[0] = 1;\n        int mask = 0;\n        long long ans = 0;\n        for (char ch : word) {\n            mask ^= 1 << (ch - 'a');\n            ans += cnt[mask];                                     // all letters even\n            for (int b = 0; b < 10; b++) ans += cnt[mask ^ (1 << b)];   // exactly one odd\n            cnt[mask]++;\n        }\n        return ans;\n    }\n};",
 "numbers-at-most-n-given-digit-set": "class Solution {\npublic:\n    int atMostNGivenDigitSet(vector<string>& digits, int n) {\n        string s = to_string(n);\n        int L = s.size(), k = digits.size();\n        vector<long long> pw(L + 1, 1);\n        for (int i = 1; i <= L; i++) pw[i] = pw[i - 1] * k;\n        long long total = 0;\n        for (int len = 1; len < L; len++) total += pw[len];   // shorter numbers are all below n\n        for (int i = 0; i < L; i++) {\n            int below = 0;\n            bool inSet = false;\n            for (auto& d : digits) {\n                below += d[0] < s[i];\n                inSet |= d[0] == s[i];\n            }\n            total += below * pw[L - i - 1];\n            if (!inSet) return total;\n        }\n        return total + 1;\n    }\n};",
 "online-stock-span": "class StockSpanner {\n    vector<pair<int, int>> st;                 // (price, span), prices strictly falling\npublic:\n    StockSpanner() {}\n\n    int next(int price) {\n        int span = 1;\n        while (!st.empty() && st.back().first <= price) {   // absorb every smaller or equal day\n            span += st.back().second;\n            st.pop_back();\n        }\n        st.push_back({price, span});\n        return span;\n    }\n};",
 "pacific-atlantic-water-flow": "class Solution {\npublic:\n    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {\n        int R = heights.size(), C = heights[0].size();\n        // every cell reachable by walking uphill from the given ocean edge\n        auto climb = [&](vector<pair<int, int>> stack) {\n            vector<vector<bool>> seen(R, vector<bool>(C, false));\n            for (auto [r, c] : stack) seen[r][c] = true;\n            int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n            while (!stack.empty()) {\n                auto [r, c] = stack.back(); stack.pop_back();\n                for (int d = 0; d < 4; d++) {\n                    int nr = r + dr[d], nc = c + dc[d];\n                    if (nr >= 0 && nr < R && nc >= 0 && nc < C && !seen[nr][nc] && heights[nr][nc] >= heights[r][c]) {\n                        seen[nr][nc] = true;\n                        stack.push_back({nr, nc});\n                    }\n                }\n            }\n            return seen;\n        };\n        vector<pair<int, int>> pacStart, atlStart;\n        for (int r = 0; r < R; r++) { pacStart.push_back({r, 0}); atlStart.push_back({r, C - 1}); }\n        for (int c = 0; c < C; c++) { pacStart.push_back({0, c}); atlStart.push_back({R - 1, c}); }\n        auto pac = climb(pacStart), atl = climb(atlStart);\n        vector<vector<int>> out;\n        for (int r = 0; r < R; r++)\n            for (int c = 0; c < C; c++)\n                if (pac[r][c] && atl[r][c]) out.push_back({r, c});\n        return out;\n    }\n};",
 "pairs-of-songs-with-total-durations-divisible-by-60": "class Solution {\npublic:\n    int numPairsDivisibleBy60(vector<int>& time) {\n        int cnt[60] = {}, ans = 0;\n        for (int t : time) {\n            ans += cnt[(60 - t % 60) % 60];   // earlier songs that complete this one\n            cnt[t % 60]++;\n        }\n        return ans;\n    }\n};",
 "palindrome-linked-list": "class Solution {\npublic:\n    bool isPalindrome(ListNode* head) {\n        ListNode *slow = head, *fast = head;\n        while (fast && fast->next) { slow = slow->next; fast = fast->next->next; }\n        ListNode* prev = nullptr;\n        while (slow) {                              // reverse the second half\n            ListNode* nxt = slow->next;\n            slow->next = prev;\n            prev = slow;\n            slow = nxt;\n        }\n        while (prev) {                              // compare it with the first half\n            if (prev->val != head->val) return false;\n            prev = prev->next;\n            head = head->next;\n        }\n        return true;\n    }\n};",
 "palindrome-number": "class Solution {\npublic:\n    bool isPalindrome(int x) {\n        if (x < 0 || (x % 10 == 0 && x != 0)) return false;\n        int rev = 0;\n        while (x > rev) {                                    // reverse only the back half\n            rev = rev * 10 + x % 10;\n            x /= 10;\n        }\n        return x == rev || x == rev / 10;                    // odd length: drop the middle digit\n    }\n};",
 "palindrome-pairs": "class Solution {\n    static bool isPal(const string& s) { return equal(s.begin(), s.begin() + s.size() / 2, s.rbegin()); }\n\npublic:\n    vector<vector<int>> palindromePairs(vector<string>& words) {\n        unordered_map<string, int> idx;   // reversed word -> its index\n        for (int i = 0; i < (int)words.size(); i++) idx[string(words[i].rbegin(), words[i].rend())] = i;\n        vector<vector<int>> out;\n        for (int i = 0; i < (int)words.size(); i++) {\n            const string& w = words[i];\n            for (int k = 0; k <= (int)w.size(); k++) {\n                string pre = w.substr(0, k), suf = w.substr(k);\n                // palindrome prefix: put the reverse of the suffix in front\n                if (isPal(pre)) {\n                    auto it = idx.find(suf);\n                    if (it != idx.end() && it->second != i) out.push_back({it->second, i});\n                }\n                // palindrome suffix: put the reverse of the prefix after (k < len avoids counting a pair twice)\n                if (k != (int)w.size() && isPal(suf)) {\n                    auto it = idx.find(pre);\n                    if (it != idx.end() && it->second != i) out.push_back({i, it->second});\n                }\n            }\n        }\n        return out;\n    }\n};",
 "palindrome-partitioning": "class Solution {\npublic:\n    vector<vector<string>> partition(string s) {\n        vector<vector<string>> out;\n        vector<string> path;\n        function<void(int)> dfs = [&](int i) {\n            if (i == (int)s.size()) { out.push_back(path); return; }\n            for (int j = i + 1; j <= (int)s.size(); j++) {\n                string piece = s.substr(i, j - i);\n                if (piece == string(piece.rbegin(), piece.rend())) {   // only cut off palindromes\n                    path.push_back(piece);\n                    dfs(j);\n                    path.pop_back();\n                }\n            }\n        };\n        dfs(0);\n        return out;\n    }\n};",
 "palindrome-partitioning-ii": "class Solution {\npublic:\n    int minCut(string s) {\n        int n = s.size();\n        vector<int> cut(n + 1);                          // cut[i]: fewest cuts for s[0..i), with cut[0] = -1\n        iota(cut.begin(), cut.end(), -1);\n        for (int c = 0; c < n; c++)\n            for (auto [l, r] : {pair{c, c}, pair{c, c + 1}})   // grow each palindrome from its centre\n                while (l >= 0 && r < n && s[l] == s[r]) {\n                    cut[r + 1] = min(cut[r + 1], cut[l] + 1);\n                    l--; r++;\n                }\n        return cut[n];\n    }\n};",
 "palindrome-partitioning-iii": "class Solution {\npublic:\n    int palindromePartition(string s, int k) {\n        int n = s.size();\n        vector<vector<int>> cost(n, vector<int>(n, 0));   // changes to make s[i..j] a palindrome\n        for (int len = 2; len <= n; len++)\n            for (int i = 0; i + len - 1 < n; i++) {\n                int j = i + len - 1;\n                cost[i][j] = (len > 2 ? cost[i + 1][j - 1] : 0) + (s[i] != s[j]);\n            }\n        const int INF = INT_MAX / 2;\n        vector<vector<int>> dp(n + 1, vector<int>(k + 1, INF));\n        dp[0][0] = 0;\n        for (int i = 1; i <= n; i++)\n            for (int p = 1; p <= min(k, i); p++)\n                for (int j = p - 1; j < i; j++)               // the last part is s[j..i-1]\n                    dp[i][p] = min(dp[i][p], dp[j][p - 1] + cost[j][i - 1]);\n        return dp[n][k];\n    }\n};",
 "palindromic-substrings": "class Solution {\npublic:\n    int countSubstrings(string s) {\n        int count = 0, n = s.size();\n        for (int c = 0; c < 2 * n - 1; c++) {       // 2n - 1 centres: on a letter or between two\n            int l = c / 2, r = c / 2 + c % 2;\n            while (l >= 0 && r < n && s[l] == s[r]) {\n                count++;\n                l--; r++;\n            }\n        }\n        return count;\n    }\n};",
 "partition-array-into-disjoint-intervals": "class Solution {\npublic:\n    int partitionDisjoint(vector<int>& nums) {\n        int leftMax = nums[0], curMax = nums[0], cut = 0;\n        for (int i = 1; i < (int)nums.size(); i++) {\n            curMax = max(curMax, nums[i]);\n            if (nums[i] < leftMax) {   // nums[i] must join the left part\n                cut = i;\n                leftMax = curMax;\n            }\n        }\n        return cut + 1;\n    }\n};",
 "partition-equal-subset-sum": "class Solution {\npublic:\n    bool canPartition(vector<int>& nums) {\n        int total = accumulate(nums.begin(), nums.end(), 0);\n        if (total % 2) return false;\n        int half = total / 2;\n        vector<bool> can(half + 1, false);                   // can[s]: some subset sums to s\n        can[0] = true;\n        for (int x : nums)\n            for (int s = half; s >= x; s--)                  // backwards so x is used once\n                can[s] = can[s] || can[s - x];\n        return can[half];\n    }\n};",
 "partition-labels": "class Solution {\npublic:\n    vector<int> partitionLabels(string s) {\n        int last[26] = {};\n        for (int i = 0; i < (int)s.size(); i++) last[s[i] - 'a'] = i;\n        vector<int> out;\n        int start = 0, end = 0;\n        for (int i = 0; i < (int)s.size(); i++) {\n            end = max(end, last[s[i] - 'a']);            // the part must reach every copy of s[i]\n            if (i == end) { out.push_back(end - start + 1); start = i + 1; }\n        }\n        return out;\n    }\n};",
 "partition-list": "class Solution {\npublic:\n    ListNode* partition(ListNode* head, int x) {\n        ListNode small, big;                          // dummy heads of the two lists\n        ListNode *s = &small, *b = &big;\n        while (head) {\n            if (head->val < x) { s->next = head; s = s->next; }\n            else { b->next = head; b = b->next; }\n            head = head->next;\n        }\n        b->next = nullptr;                            // end the big list\n        s->next = big.next;                           // small list, then big list\n        return small.next;\n    }\n};",
 "partition-to-k-equal-sum-subsets": "class Solution {\n    vector<int> nums, buckets;\n    int target = 0;\n    bool place(size_t i) {\n        if (i == nums.size()) return true;\n        for (int& b : buckets) {\n            if (b + nums[i] <= target) {\n                b += nums[i];\n                if (place(i + 1)) return true;\n                b -= nums[i];\n            }\n            if (b == 0) break;                               // empty buckets are all alike: try one\n        }\n        return false;\n    }\npublic:\n    bool canPartitionKSubsets(vector<int>& nums, int k) {\n        int total = accumulate(nums.begin(), nums.end(), 0);\n        if (total % k) return false;\n        target = total / k;\n        this->nums = nums;\n        sort(this->nums.rbegin(), this->nums.rend());        // big numbers first fail faster\n        if (this->nums[0] > target) return false;\n        buckets.assign(k, 0);\n        return place(0);\n    }\n};",
 "pascals-triangle": "class Solution {\npublic:\n    vector<vector<int>> generate(int numRows) {\n        vector<vector<int>> rows{{1}};\n        for (int r = 1; r < numRows; r++) {\n            auto& prev = rows.back();\n            vector<int> row{1};\n            for (size_t i = 0; i + 1 < prev.size(); i++) row.push_back(prev[i] + prev[i + 1]);   // sum of the two above\n            row.push_back(1);\n            rows.push_back(row);\n        }\n        return rows;\n    }\n};",
 "patching-array": "class Solution {\npublic:\n    int minPatches(vector<int>& nums, int n) {\n        long long miss = 1;            // every sum below miss can be made\n        int i = 0, patches = 0;\n        while (miss <= n) {\n            if (i < (int)nums.size() && nums[i] <= miss) miss += nums[i++];\n            else {\n                miss += miss;          // patch with miss itself\n                patches++;\n            }\n        }\n        return patches;\n    }\n};",
 "path-sum": "class Solution {\npublic:\n    bool hasPathSum(TreeNode* root, int targetSum) {\n        if (!root) return false;\n        if (!root->left && !root->right) return root->val == targetSum;   // a leaf must finish the sum\n        int rem = targetSum - root->val;\n        return hasPathSum(root->left, rem) || hasPathSum(root->right, rem);\n    }\n};",
 "path-sum-ii": "class Solution {\npublic:\n    vector<vector<int>> pathSum(TreeNode* root, int targetSum) {\n        vector<vector<int>> out;\n        vector<int> path;\n        function<void(TreeNode*, int)> dfs = [&](TreeNode* node, int rem) {\n            if (!node) return;\n            path.push_back(node->val);\n            rem -= node->val;\n            if (!node->left && !node->right && rem == 0) out.push_back(path);\n            dfs(node->left, rem);\n            dfs(node->right, rem);\n            path.pop_back();                           // backtrack\n        };\n        dfs(root, targetSum);\n        return out;\n    }\n};",
 "path-sum-iii": "class Solution {\n    unordered_map<long long, int> seen;                    // prefix sums on the current root path\n    int dfs(TreeNode* node, long long run, int target) {\n        if (!node) return 0;\n        run += node->val;\n        int count = seen.count(run - target) ? seen[run - target] : 0;\n        seen[run]++;\n        count += dfs(node->left, run, target) + dfs(node->right, run, target);\n        seen[run]--;                                       // leave this node: no longer an ancestor\n        return count;\n    }\npublic:\n    int pathSum(TreeNode* root, int targetSum) {\n        seen[0] = 1;\n        return dfs(root, 0, targetSum);\n    }\n};",
 "path-with-maximum-probability": "class Solution {\npublic:\n    double maxProbability(int n, vector<vector<int>>& edges, vector<double>& succProb, int start_node, int end_node) {\n        vector<vector<pair<int, double>>> adj(n);\n        for (size_t i = 0; i < edges.size(); i++) {\n            adj[edges[i][0]].push_back({edges[i][1], succProb[i]});\n            adj[edges[i][1]].push_back({edges[i][0], succProb[i]});\n        }\n        vector<double> best(n, 0.0);\n        best[start_node] = 1.0;\n        priority_queue<pair<double, int>> heap;          // max-heap on probability\n        heap.push({1.0, start_node});\n        while (!heap.empty()) {\n            auto [p, u] = heap.top(); heap.pop();\n            if (u == end_node) return p;\n            if (p < best[u]) continue;                   // stale entry\n            for (auto [v, q] : adj[u])\n                if (p * q > best[v]) { best[v] = p * q; heap.push({best[v], v}); }\n        }\n        return 0.0;\n    }\n};",
 "path-with-minimum-effort": "class Solution {\npublic:\n    int minimumEffortPath(vector<vector<int>>& heights) {\n        int R = heights.size(), C = heights[0].size();\n        vector<vector<int>> best(R, vector<int>(C, INT_MAX));\n        best[0][0] = 0;\n        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> heap;\n        heap.push({0, 0, 0});\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        while (!heap.empty()) {\n            auto [e, r, c] = heap.top(); heap.pop();\n            if (r == R - 1 && c == C - 1) return e;\n            if (e > best[r][c]) continue;\n            for (int d = 0; d < 4; d++) {\n                int nr = r + dr[d], nc = c + dc[d];\n                if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;\n                int ne = max(e, abs(heights[nr][nc] - heights[r][c]));   // effort is the largest single step\n                if (ne < best[nr][nc]) { best[nr][nc] = ne; heap.push({ne, nr, nc}); }\n            }\n        }\n        return 0;\n    }\n};",
 "perfect-squares": "class Solution {\npublic:\n    int numSquares(int n) {\n        vector<int> dp(n + 1, n);                            // n ones is always enough\n        dp[0] = 0;\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j * j <= i; j++) dp[i] = min(dp[i], dp[i - j * j] + 1);\n        return dp[n];\n    }\n};",
 "permutation-in-string": "class Solution {\npublic:\n    bool checkInclusion(string s1, string s2) {\n        int k = s1.size();\n        if (k > (int)s2.size()) return false;\n        array<int, 26> need{}, win{};\n        for (int i = 0; i < k; i++) { need[s1[i] - 'a']++; win[s2[i] - 'a']++; }\n        for (int i = k; i < (int)s2.size(); i++) {\n            if (win == need) return true;\n            win[s2[i] - 'a']++;                       // slide: add the new char, drop the old one\n            win[s2[i - k] - 'a']--;\n        }\n        return win == need;\n    }\n};",
 "permutations": "class Solution {\npublic:\n    vector<vector<int>> permute(vector<int>& nums) {\n        vector<vector<int>> out;\n        vector<int> path;\n        vector<bool> used(nums.size(), false);\n        function<void()> dfs = [&]() {\n            if (path.size() == nums.size()) { out.push_back(path); return; }\n            for (size_t i = 0; i < nums.size(); i++) {\n                if (used[i]) continue;\n                used[i] = true;\n                path.push_back(nums[i]);\n                dfs();\n                path.pop_back();                       // undo the choice\n                used[i] = false;\n            }\n        };\n        dfs();\n        return out;\n    }\n};",
 "plus-one": "class Solution {\npublic:\n    vector<int> plusOne(vector<int>& digits) {\n        for (int i = digits.size() - 1; i >= 0; i--) {\n            if (digits[i] < 9) { digits[i]++; return digits; }\n            digits[i] = 0;                                 // 9 becomes 0 and carries\n        }\n        digits.insert(digits.begin(), 1);\n        return digits;\n    }\n};",
 "populating-next-right-pointers-in-each-node": "class Node {\npublic:\n    int val;\n    Node* left;\n    Node* right;\n    Node* next;\n\n    Node() : val(0), left(NULL), right(NULL), next(NULL) {}\n\n    Node(int _val) : val(_val), left(NULL), right(NULL), next(NULL) {}\n\n    Node(int _val, Node* _left, Node* _right, Node* _next)\n        : val(_val), left(_left), right(_right), next(_next) {}\n};\n\nclass Solution {\npublic:\n    Node* connect(Node* root) {\n        Node* leftmost = root;\n        while (leftmost && leftmost->left) {                 // wire the level below this one\n            for (Node* node = leftmost; node; node = node->next) {\n                node->left->next = node->right;              // siblings\n                if (node->next) node->right->next = node->next->left;   // across to the next parent\n            }\n            leftmost = leftmost->left;\n        }\n        return root;\n    }\n};",
 "populating-next-right-pointers-in-each-node-ii": "class Node {\npublic:\n    int val;\n    Node* left;\n    Node* right;\n    Node* next;\n\n    Node() : val(0), left(NULL), right(NULL), next(NULL) {}\n\n    Node(int _val) : val(_val), left(NULL), right(NULL), next(NULL) {}\n\n    Node(int _val, Node* _left, Node* _right, Node* _next)\n        : val(_val), left(_left), right(_right), next(_next) {}\n};\n\nclass Solution {\npublic:\n    Node* connect(Node* root) {\n        Node* head = root;   // leftmost node of the current level\n        while (head) {\n            Node dummy(0), *tail = &dummy;   // builds the next level's chain\n            for (Node* node = head; node; node = node->next)\n                for (Node* child : {node->left, node->right})\n                    if (child) { tail->next = child; tail = child; }\n            head = dummy.next;\n        }\n        return root;\n    }\n};",
 "possible-bipartition": "class Solution {\npublic:\n    bool possibleBipartition(int n, vector<vector<int>>& dislikes) {\n        vector<vector<int>> g(n + 1);\n        for (auto& d : dislikes) { g[d[0]].push_back(d[1]); g[d[1]].push_back(d[0]); }\n        vector<int> color(n + 1, 0);                   // 0 unseen, 1 or -1 the two groups\n        for (int s = 1; s <= n; s++) {\n            if (color[s]) continue;\n            color[s] = 1;\n            queue<int> q;\n            q.push(s);\n            while (!q.empty()) {\n                int u = q.front(); q.pop();\n                for (int v : g[u]) {\n                    if (color[v] == color[u]) return false;   // two people who dislike each other, same group\n                    if (!color[v]) { color[v] = -color[u]; q.push(v); }\n                }\n            }\n        }\n        return true;\n    }\n};",
 "power-of-four": "class Solution {\npublic:\n    bool isPowerOfFour(int n) {\n        // one set bit, and it sits on an even position\n        return n > 0 && (n & (n - 1)) == 0 && (n & 0x55555555) != 0;\n    }\n};",
 "power-of-three": "class Solution {\npublic:\n    bool isPowerOfThree(int n) {\n        if (n < 1) return false;\n        while (n % 3 == 0) n /= 3;\n        return n == 1;\n    }\n};",
 "power-of-two": "class Solution {\npublic:\n    bool isPowerOfTwo(int n) {\n        return n > 0 && (n & (n - 1)) == 0;                  // exactly one set bit\n    }\n};",
 "powx-n": "class Solution {\npublic:\n    double myPow(double x, int n) {\n        long long e = n;                                     // -INT_MIN does not fit in int\n        if (e < 0) { x = 1 / x; e = -e; }\n        double res = 1.0;\n        while (e) {                                          // square and multiply\n            if (e & 1) res *= x;\n            x *= x;\n            e >>= 1;\n        }\n        return res;\n    }\n};",
 "prefix-and-suffix-search": "class WordFilter {\n    unordered_map<string, int> index;          // \"prefix#suffix\" -> latest word index\npublic:\n    WordFilter(vector<string>& words) {\n        for (int i = 0; i < (int)words.size(); i++) {\n            const string& w = words[i];\n            for (size_t p = 0; p <= w.size(); p++)\n                for (size_t s = 0; s <= w.size(); s++)\n                    index[w.substr(0, p) + \"#\" + w.substr(s)] = i;   // later words overwrite earlier ones\n        }\n    }\n\n    int f(string pref, string suff) {\n        auto it = index.find(pref + \"#\" + suff);\n        return it == index.end() ? -1 : it->second;\n    }\n};",
 "prime-arrangements": "class Solution {\npublic:\n    int numPrimeArrangements(int n) {\n        const long long MOD = 1'000'000'007;\n        int p = 0;\n        for (int k = 2; k <= n; k++) {\n            bool prime = true;\n            for (int d = 2; d * d <= k; d++) if (k % d == 0) { prime = false; break; }\n            p += prime;\n        }\n        long long ans = 1;\n        for (int k = 2; k <= p; k++) ans = ans * k % MOD;        // primes on prime spots: p!\n        for (int k = 2; k <= n - p; k++) ans = ans * k % MOD;    // the rest: (n - p)!\n        return (int)ans;\n    }\n};",
 "prime-number-of-set-bits-in-binary-representation": "class Solution {\npublic:\n    int countPrimeSetBits(int left, int right) {\n        unordered_set<int> primes{2, 3, 5, 7, 11, 13, 17, 19};   // at most 20 bits below 10^6\n        int count = 0;\n        for (int x = left; x <= right; x++) count += primes.count(__builtin_popcount(x));\n        return count;\n    }\n};",
 "product-of-array-except-self": "class Solution {\npublic:\n    vector<int> productExceptSelf(vector<int>& nums) {\n        int n = nums.size();\n        vector<int> out(n, 1);\n        int left = 1;\n        for (int i = 0; i < n; i++) { out[i] = left; left *= nums[i]; }        // product of everything to the left\n        int right = 1;\n        for (int i = n - 1; i >= 0; i--) { out[i] *= right; right *= nums[i]; }   // times everything to the right\n        return out;\n    }\n};",
 "pseudo-palindromic-paths-in-a-binary-tree": "class Solution {\n    int dfs(TreeNode* node, int mask) {\n        if (!node) return 0;\n        mask ^= 1 << node->val;                                  // parity of each digit\n        if (!node->left && !node->right) return (mask & (mask - 1)) == 0;   // at most one odd\n        return dfs(node->left, mask) + dfs(node->right, mask);\n    }\npublic:\n    int pseudoPalindromicPaths(TreeNode* root) { return dfs(root, 0); }\n};",
 "put-marbles-in-bags": "class Solution {\npublic:\n    long long putMarbles(vector<int>& weights, int k) {\n        vector<long long> pairs;       // cost of cutting between i and i + 1\n        for (size_t i = 0; i + 1 < weights.size(); i++) pairs.push_back((long long)weights[i] + weights[i + 1]);\n        sort(pairs.begin(), pairs.end());\n        long long ans = 0;\n        int m = pairs.size();\n        for (int i = 0; i < k - 1; i++) ans += pairs[m - 1 - i] - pairs[i];   // k - 1 biggest minus k - 1 smallest\n        return ans;\n    }\n};",
 "queens-that-can-attack-the-king": "class Solution {\npublic:\n    vector<vector<int>> queensAttacktheKing(vector<vector<int>>& queens, vector<int>& king) {\n        set<pair<int, int>> qs;\n        for (auto& q : queens) qs.insert({q[0], q[1]});\n        vector<vector<int>> out;\n        for (int dr = -1; dr <= 1; dr++)\n            for (int dc = -1; dc <= 1; dc++) {\n                if (dr == 0 && dc == 0) continue;\n                int r = king[0] + dr, c = king[1] + dc;\n                while (0 <= r && r < 8 && 0 <= c && c < 8) {\n                    if (qs.count({r, c})) { out.push_back({r, c}); break; }   // first queen in this direction\n                    r += dr; c += dc;\n                }\n            }\n        return out;\n    }\n};",
 "queue-reconstruction-by-height": "class Solution {\npublic:\n    vector<vector<int>> reconstructQueue(vector<vector<int>>& people) {\n        // tallest first; among equal heights, fewer people in front first\n        sort(people.begin(), people.end(), [](auto& a, auto& b) { return a[0] != b[0] ? a[0] > b[0] : a[1] < b[1]; });\n        vector<vector<int>> out;\n        for (auto& p : people) out.insert(out.begin() + p[1], p);   // everyone already placed is at least as tall\n        return out;\n    }\n};",
 "race-car": "class Solution {\npublic:\n    int racecar(int target) {\n        vector<int> dp(target + 1, INT_MAX);\n        dp[0] = 0;\n        for (int t = 1; t <= target; t++) {\n            int k = bit_width((unsigned)t);                // k A's from rest reach 2^k - 1\n            if (t == (1 << k) - 1) { dp[t] = k; continue; }\n            dp[t] = k + 1 + dp[(1 << k) - 1 - t];          // overshoot, reverse, come back\n            for (int j = 0; j < k - 1; j++)                // stop short, back up j, reverse again\n                dp[t] = min(dp[t], k - 1 + j + 2 + dp[t - (1 << (k - 1)) + (1 << j)]);\n        }\n        return dp[target];\n    }\n};",
 "range-module": "class RangeModule {\n    vector<int> pts;                           // sorted ends: [pts[0], pts[1]), [pts[2], pts[3]), ...\n\n    // replace pts[i..j) with the given ends\n    void splice(int i, int j, vector<int> ends) {\n        pts.erase(pts.begin() + i, pts.begin() + j);\n        pts.insert(pts.begin() + i, ends.begin(), ends.end());\n    }\npublic:\n    RangeModule() {}\n\n    void addRange(int left, int right) {\n        int i = lower_bound(pts.begin(), pts.end(), left) - pts.begin();\n        int j = upper_bound(pts.begin(), pts.end(), right) - pts.begin();\n        vector<int> ends;\n        if (i % 2 == 0) ends.push_back(left);       // left falls outside a range: it starts one\n        if (j % 2 == 0) ends.push_back(right);      // right falls outside a range: it ends one\n        splice(i, j, ends);\n    }\n\n    bool queryRange(int left, int right) {\n        int i = upper_bound(pts.begin(), pts.end(), left) - pts.begin();\n        int j = lower_bound(pts.begin(), pts.end(), right) - pts.begin();\n        return i == j && i % 2 == 1;                 // both inside the same range\n    }\n\n    void removeRange(int left, int right) {\n        int i = lower_bound(pts.begin(), pts.end(), left) - pts.begin();\n        int j = upper_bound(pts.begin(), pts.end(), right) - pts.begin();\n        vector<int> ends;\n        if (i % 2 == 1) ends.push_back(left);       // left is inside a range: cut it there\n        if (j % 2 == 1) ends.push_back(right);\n        splice(i, j, ends);\n    }\n};",
 "range-sum-of-sorted-subarray-sums": "class Solution {\npublic:\n    int rangeSum(vector<int>& nums, int n, int left, int right) {\n        vector<long long> sums;   // every subarray sum\n        for (int i = 0; i < n; i++) {\n            long long s = 0;\n            for (int j = i; j < n; j++) sums.push_back(s += nums[j]);\n        }\n        sort(sums.begin(), sums.end());\n        long long total = 0;\n        for (int k = left - 1; k < right; k++) total = (total + sums[k]) % 1000000007;\n        return total;\n    }\n};",
 "range-sum-query-2d-immutable": "class NumMatrix {\n    vector<vector<int>> P;                                 // P[i][j] = sum of the top-left i x j block\npublic:\n    NumMatrix(vector<vector<int>>& matrix) {\n        int m = matrix.size(), n = matrix[0].size();\n        P.assign(m + 1, vector<int>(n + 1, 0));\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++)\n                P[i + 1][j + 1] = matrix[i][j] + P[i][j + 1] + P[i + 1][j] - P[i][j];\n    }\n\n    int sumRegion(int row1, int col1, int row2, int col2) {\n        return P[row2 + 1][col2 + 1] - P[row1][col2 + 1] - P[row2 + 1][col1] + P[row1][col1];\n    }\n};",
 "range-sum-query-immutable": "class NumArray {\n    vector<int> pre{0};                                    // pre[i] = sum of the first i numbers\npublic:\n    NumArray(vector<int>& nums) {\n        for (int x : nums) pre.push_back(pre.back() + x);\n    }\n\n    int sumRange(int left, int right) { return pre[right + 1] - pre[left]; }\n};",
 "range-sum-query-mutable": "class NumArray {\n    int n;\n    vector<int> a;\n    vector<int> t;   // Fenwick tree, 1-indexed\n\n    void add(int i, int d) {\n        for (; i <= n; i += i & -i) t[i] += d;\n    }\n    int prefix(int i) {\n        int s = 0;\n        for (; i; i -= i & -i) s += t[i];\n        return s;\n    }\n\npublic:\n    NumArray(vector<int>& nums) : n(nums.size()), a(nums), t(n + 1, 0) {\n        for (int i = 0; i < n; i++) add(i + 1, nums[i]);\n    }\n\n    void update(int index, int val) {\n        add(index + 1, val - a[index]);   // push only the change\n        a[index] = val;\n    }\n\n    int sumRange(int left, int right) {\n        return prefix(right + 1) - prefix(left);\n    }\n};",
 "rank-teams-by-votes": "class Solution {\npublic:\n    string rankTeams(vector<string>& votes) {\n        int n = votes[0].size();\n        vector<vector<int>> count(26, vector<int>(n, 0));  // count[team][position]\n        for (auto& v : votes)\n            for (int i = 0; i < n; i++) count[v[i] - 'A'][i]++;\n        string teams = votes[0];\n        sort(teams.begin(), teams.end(), [&](char a, char b) {\n            if (count[a - 'A'] != count[b - 'A']) return count[a - 'A'] > count[b - 'A'];   // more top places first\n            return a < b;\n        });\n        return teams;\n    }\n};",
 "reachable-nodes-with-restrictions": "class Solution {\npublic:\n    int reachableNodes(int n, vector<vector<int>>& edges, vector<int>& restricted) {\n        vector<vector<int>> g(n);\n        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }\n        vector<bool> seen(n, false);\n        for (int r : restricted) seen[r] = true;           // restricted nodes act as walls\n        seen[0] = true;\n        vector<int> stack{0};\n        int count = 0;\n        while (!stack.empty()) {\n            int u = stack.back(); stack.pop_back();\n            count++;\n            for (int v : g[u])\n                if (!seen[v]) { seen[v] = true; stack.push_back(v); }\n        }\n        return count;\n    }\n};",
 "rearrange-array-elements-by-sign": "class Solution {\npublic:\n    vector<int> rearrangeArray(vector<int>& nums) {\n        vector<int> out(nums.size());\n        int pos = 0, neg = 1;   // positives at even slots, negatives at odd\n        for (int x : nums) {\n            if (x > 0) { out[pos] = x; pos += 2; }\n            else { out[neg] = x; neg += 2; }\n        }\n        return out;\n    }\n};",
 "reconstruct-itinerary": "class Solution {\npublic:\n    vector<string> findItinerary(vector<vector<string>>& tickets) {\n        unordered_map<string, vector<string>> g;\n        sort(tickets.rbegin(), tickets.rend());\n        for (auto& t : tickets) g[t[0]].push_back(t[1]);     // reverse sorted, so back() is the smallest\n        vector<string> route, st = {\"JFK\"};\n        while (!st.empty()) {\n            while (!g[st.back()].empty()) {\n                string next = g[st.back()].back();\n                g[st.back()].pop_back();\n                st.push_back(next);\n            }\n            route.push_back(st.back());\n            st.pop_back();\n        }\n        reverse(route.begin(), route.end());\n        return route;\n    }\n};",
 "recover-binary-search-tree": "class Solution {\npublic:\n    void recoverTree(TreeNode* root) {\n        TreeNode *first = nullptr, *second = nullptr, *prev = nullptr;\n        vector<TreeNode*> st;\n        TreeNode* node = root;\n        while (!st.empty() || node) {                  // iterative inorder\n            while (node) { st.push_back(node); node = node->left; }\n            node = st.back(); st.pop_back();\n            if (prev && prev->val > node->val) {       // a drop in the sorted order\n                if (!first) first = prev;\n                second = node;\n            }\n            prev = node;\n            node = node->right;\n        }\n        swap(first->val, second->val);\n    }\n};",
 "reduce-array-size-to-the-half": "class Solution {\npublic:\n    int minSetSize(vector<int>& arr) {\n        unordered_map<int, int> freq;\n        for (int x : arr) freq[x]++;\n        vector<int> counts;\n        for (auto& [v, c] : freq) counts.push_back(c);\n        sort(counts.rbegin(), counts.rend());   // most common first\n        int removed = 0;\n        for (int i = 0; i < (int)counts.size(); i++) {\n            removed += counts[i];\n            if (removed * 2 >= (int)arr.size()) return i + 1;\n        }\n        return counts.size();\n    }\n};",
 "reduction-operations-to-make-the-array-elements-equal": "class Solution {\npublic:\n    int reductionOperations(vector<int>& nums) {\n        sort(nums.begin(), nums.end());\n        int ops = 0, steps = 0;\n        for (int i = 1; i < (int)nums.size(); i++) {\n            if (nums[i] != nums[i - 1]) steps++;   // one more distinct value below this one\n            ops += steps;\n        }\n        return ops;\n    }\n};",
 "redundant-connection": "class Solution {\npublic:\n    vector<int> findRedundantConnection(vector<vector<int>>& edges) {\n        vector<int> parent(edges.size() + 1);\n        iota(parent.begin(), parent.end(), 0);\n        auto find = [&](int x) {\n            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }\n            return x;\n        };\n        for (auto& e : edges) {\n            int ra = find(e[0]), rb = find(e[1]);\n            if (ra == rb) return e;                      // already connected: this edge closes a cycle\n            parent[ra] = rb;\n        }\n        return {};\n    }\n};",
 "redundant-connection-ii": "class Solution {\npublic:\n    vector<int> findRedundantDirectedConnection(vector<vector<int>>& edges) {\n        int n = edges.size();\n        vector<int> parent(n + 1, 0), cand1, cand2;\n        for (auto& e : edges) {\n            if (parent[e[1]]) {   // second parent: one of these two edges must go\n                cand1 = {parent[e[1]], e[1]};\n                cand2 = {e[0], e[1]};\n            } else {\n                parent[e[1]] = e[0];\n            }\n        }\n        vector<int> uf(n + 1);\n        iota(uf.begin(), uf.end(), 0);\n        auto find = [&](int x) {\n            while (uf[x] != x) {\n                uf[x] = uf[uf[x]];\n                x = uf[x];\n            }\n            return x;\n        };\n        for (auto& e : edges) {\n            if (e == cand2) continue;   // try the tree without the later candidate\n            int ru = find(e[0]), rv = find(e[1]);\n            if (ru == rv) return cand1.empty() ? e : cand1;   // still a cycle\n            uf[rv] = ru;\n        }\n        return cand2;\n    }\n};",
 "regular-expression-matching": "class Solution {\npublic:\n    bool isMatch(string s, string p) {\n        int m = s.size(), n = p.size();\n        vector<vector<bool>> dp(m + 1, vector<bool>(n + 1, false));   // dp[i][j]: s[:i] matches p[:j]\n        dp[0][0] = true;\n        for (int j = 2; j <= n; j++) dp[0][j] = p[j - 1] == '*' && dp[0][j - 2];\n        for (int i = 1; i <= m; i++)\n            for (int j = 1; j <= n; j++) {\n                if (p[j - 1] == '*')                     // zero copies, or one more copy of p[j - 2]\n                    dp[i][j] = dp[i][j - 2] || ((p[j - 2] == s[i - 1] || p[j - 2] == '.') && dp[i - 1][j]);\n                else\n                    dp[i][j] = (p[j - 1] == s[i - 1] || p[j - 1] == '.') && dp[i - 1][j - 1];\n            }\n        return dp[m][n];\n    }\n};",
 "remove-all-occurrences-of-a-substring": "class Solution {\npublic:\n    string removeOccurrences(string s, string part) {\n        string st;   // the string works as a stack\n        size_t m = part.size();\n        for (char c : s) {\n            st.push_back(c);\n            if (st.size() >= m && st.compare(st.size() - m, m, part) == 0)\n                st.resize(st.size() - m);   // the top m chars spell part: drop them\n        }\n        return st;\n    }\n};",
 "remove-colored-pieces-if-both-neighbors-are-the-same-color": "class Solution {\npublic:\n    bool winnerOfGame(string colors) {\n        int a = 0, b = 0;   // moves each player has\n        for (int i = 1; i + 1 < (int)colors.size(); i++)\n            if (colors[i - 1] == colors[i] && colors[i] == colors[i + 1]) {\n                if (colors[i] == 'A') a++;\n                else b++;\n            }\n        return a > b;\n    }\n};",
 "remove-covered-intervals": "class Solution {\npublic:\n    int removeCoveredIntervals(vector<vector<int>>& intervals) {\n        // by start, and the longer one first when starts tie\n        sort(intervals.begin(), intervals.end(), [](auto& x, auto& y) { return x[0] != y[0] ? x[0] < y[0] : x[1] > y[1]; });\n        int count = 0, right = 0;\n        for (auto& iv : intervals)\n            if (iv[1] > right) { count++; right = iv[1]; }   // not inside an earlier interval\n        return count;\n    }\n};",
 "remove-duplicate-letters": "class Solution {\npublic:\n    string removeDuplicateLetters(string s) {\n        int last[26];\n        for (int i = 0; i < (int)s.size(); i++) last[s[i] - 'a'] = i;\n        string st;\n        bool used[26] = {};\n        for (int i = 0; i < (int)s.size(); i++) {\n            char c = s[i];\n            if (used[c - 'a']) continue;\n            // pop a bigger letter if it appears again later\n            while (!st.empty() && c < st.back() && last[st.back() - 'a'] > i) {\n                used[st.back() - 'a'] = false;\n                st.pop_back();\n            }\n            st.push_back(c);\n            used[c - 'a'] = true;\n        }\n        return st;\n    }\n};",
 "remove-duplicates-from-sorted-list": "class Solution {\npublic:\n    ListNode* deleteDuplicates(ListNode* head) {\n        ListNode* cur = head;\n        while (cur && cur->next) {\n            if (cur->val == cur->next->val) cur->next = cur->next->next;   // skip the copy\n            else cur = cur->next;\n        }\n        return head;\n    }\n};",
 "remove-duplicates-from-sorted-list-ii": "class Solution {\npublic:\n    ListNode* deleteDuplicates(ListNode* head) {\n        ListNode dummy(0, head);\n        ListNode* prev = &dummy;                       // last node kept\n        while (head) {\n            if (head->next && head->val == head->next->val) {\n                while (head->next && head->val == head->next->val) head = head->next;\n                prev->next = head->next;               // cut out the whole run\n            } else {\n                prev = prev->next;\n            }\n            head = head->next;\n        }\n        return dummy.next;\n    }\n};",
 "remove-invalid-parentheses": "class Solution {\n    static bool valid(const string& t) {\n        int bal = 0;\n        for (char c : t) {\n            if (c == '(') bal++;\n            else if (c == ')' && --bal < 0) return false;\n        }\n        return bal == 0;\n    }\n\npublic:\n    vector<string> removeInvalidParentheses(string s) {\n        unordered_set<string> level{s};   // BFS: every string with the same number of removals\n        while (true) {\n            vector<string> good;\n            for (auto& t : level)\n                if (valid(t)) good.push_back(t);\n            if (!good.empty()) return good;   // the first level with a valid string has the fewest removals\n            unordered_set<string> next;\n            for (auto& t : level)\n                for (size_t i = 0; i < t.size(); i++)\n                    if (t[i] == '(' || t[i] == ')') next.insert(t.substr(0, i) + t.substr(i + 1));\n            level = next;\n        }\n    }\n};",
 "remove-k-digits": "class Solution {\npublic:\n    string removeKdigits(string num, int k) {\n        string st;                                     // digits kept, never falling\n        for (char d : num) {\n            while (k && !st.empty() && st.back() > d) { st.pop_back(); k--; }\n            st.push_back(d);\n        }\n        st.resize(st.size() - k);                      // still owed removals come off the end\n        size_t start = st.find_first_not_of('0');\n        return start == string::npos ? \"0\" : st.substr(start);\n    }\n};",
 "remove-max-number-of-edges-to-keep-graph-fully-traversable": "class Solution {\n    int find(vector<int>& p, int x) {\n        while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; }\n        return x;\n    }\n    int unite(vector<int>& p, int a, int b) {            // 1 if it joined two parts\n        int ra = find(p, a), rb = find(p, b);\n        if (ra == rb) return 0;\n        p[ra] = rb;\n        return 1;\n    }\n\npublic:\n    int maxNumEdgesToRemove(int n, vector<vector<int>>& edges) {\n        vector<int> alice(n + 1), bob(n + 1);\n        iota(alice.begin(), alice.end(), 0);\n        iota(bob.begin(), bob.end(), 0);\n        sort(edges.rbegin(), edges.rend());              // shared (type 3) edges first\n        int used = 0, ja = 0, jb = 0;\n        for (auto& e : edges) {\n            int t = e[0], u = e[1], v = e[2];\n            if (t == 3) {\n                int got = unite(alice, u, v);\n                unite(bob, u, v);\n                used += got; ja += got; jb += got;\n            } else if (t == 1) {\n                int got = unite(alice, u, v);\n                used += got; ja += got;\n            } else {\n                int got = unite(bob, u, v);\n                used += got; jb += got;\n            }\n        }\n        return ja == n - 1 && jb == n - 1 ? (int)edges.size() - used : -1;\n    }\n};",
 "remove-nodes-from-linked-list": "class Solution {\npublic:\n    ListNode* removeNodes(ListNode* head) {\n        vector<ListNode*> st;                          // values never rising\n        for (; head; head = head->next) {\n            while (!st.empty() && st.back()->val < head->val) st.pop_back();\n            st.push_back(head);\n        }\n        for (size_t i = 0; i + 1 < st.size(); i++) st[i]->next = st[i + 1];   // relink what is left\n        st.back()->next = nullptr;\n        return st[0];\n    }\n};",
 "remove-nth-node-from-end-of-list": "class Solution {\npublic:\n    ListNode* removeNthFromEnd(ListNode* head, int n) {\n        ListNode dummy(0, head);\n        ListNode *fast = &dummy, *slow = &dummy;\n        for (int i = 0; i < n; i++) fast = fast->next;     // open a gap of n nodes\n        while (fast->next) { fast = fast->next; slow = slow->next; }\n        slow->next = slow->next->next;                     // slow sits just before the target\n        return dummy.next;\n    }\n};",
 "remove-sub-folders-from-the-filesystem": "class Solution {\npublic:\n    vector<string> removeSubfolders(vector<string>& folder) {\n        sort(folder.begin(), folder.end());            // a parent sorts right before its subfolders\n        vector<string> out;\n        for (const string& f : folder)\n            if (out.empty() || !f.starts_with(out.back() + \"/\")) out.push_back(f);\n        return out;\n    }\n};",
 "remove-zero-sum-consecutive-nodes-from-linked-list": "class Solution {\npublic:\n    ListNode* removeZeroSumSublists(ListNode* head) {\n        ListNode dummy(0, head);\n        unordered_map<int, ListNode*> last;            // prefix sum -> last node with that sum\n        int s = 0;\n        for (ListNode* node = &dummy; node; node = node->next) { s += node->val; last[s] = node; }\n        s = 0;\n        for (ListNode* node = &dummy; node; node = node->next) {\n            s += node->val;\n            node->next = last[s]->next;                // skip everything that sums to zero\n        }\n        return dummy.next;\n    }\n};",
 "reorder-data-in-log-files": "class Solution {\npublic:\n    vector<string> reorderLogFiles(vector<string>& logs) {\n        auto key = [](const string& log) {\n            size_t sp = log.find(' ');\n            string ident = log.substr(0, sp), rest = log.substr(sp + 1);\n            // letter logs first, by content then identifier; digit logs keep their order\n            return isalpha(rest[0]) ? make_tuple(0, rest, ident) : make_tuple(1, string(), string());\n        };\n        vector<string> out = logs;\n        stable_sort(out.begin(), out.end(), [&](const string& a, const string& b) { return key(a) < key(b); });\n        return out;\n    }\n};",
 "reorder-list": "class Solution {\npublic:\n    void reorderList(ListNode* head) {\n        ListNode *slow = head, *fast = head;\n        while (fast->next && fast->next->next) { slow = slow->next; fast = fast->next->next; }\n        ListNode* second = slow->next;\n        slow->next = nullptr;                          // split after the middle\n        ListNode* prev = nullptr;\n        while (second) {                               // reverse the second half\n            ListNode* nxt = second->next;\n            second->next = prev;\n            prev = second;\n            second = nxt;\n        }\n        ListNode* first = head;\n        second = prev;\n        while (second) {                               // weave: one from each half\n            ListNode *n1 = first->next, *n2 = second->next;\n            first->next = second;\n            second->next = n1;\n            first = n1;\n            second = n2;\n        }\n    }\n};",
 "reorganize-string": "class Solution {\npublic:\n    string reorganizeString(string s) {\n        int cnt[26] = {};\n        for (char ch : s) cnt[ch - 'a']++;\n        vector<int> order;                               // letters, most frequent first\n        for (int c = 0; c < 26; c++) if (cnt[c]) order.push_back(c);\n        stable_sort(order.begin(), order.end(), [&](int a, int b) { return cnt[a] > cnt[b]; });\n        int n = s.size(), half = (n + 1) / 2;\n        if (cnt[order[0]] > half) return \"\";             // too many of one letter to keep them apart\n        string chars;\n        for (int c : order) chars += string(cnt[c], 'a' + c);\n        string out(n, ' ');\n        for (int i = 0; i < n; i++)                      // first half on even slots, the rest on odd ones\n            out[i < half ? 2 * i : 2 * (i - half) + 1] = chars[i];\n        return out;\n    }\n};",
 "repeated-dna-sequences": "class Solution {\npublic:\n    vector<string> findRepeatedDnaSequences(string s) {\n        unordered_map<string, int> seen;\n        vector<string> out;\n        for (int i = 0; i + 10 <= (int)s.size(); i++) {\n            string w = s.substr(i, 10);\n            if (++seen[w] == 2) out.push_back(w);            // report on the second sighting only\n        }\n        return out;\n    }\n};",
 "repeated-string-match": "class Solution {\npublic:\n    int repeatedStringMatch(string a, string b) {\n        int q = (b.size() + a.size() - 1) / a.size();   // fewest copies long enough to hold b\n        for (int times : {q, q + 1}) {\n            string rep;\n            for (int i = 0; i < times; i++) rep += a;\n            if (rep.find(b) != string::npos) return times;\n        }\n        return -1;\n    }\n};",
 "repeated-substring-pattern": "class Solution {\npublic:\n    bool repeatedSubstringPattern(string s) {\n        string doubled = s + s;\n        // drop the first and last char so s cannot match at the trivial positions\n        return doubled.substr(1, doubled.size() - 2).find(s) != string::npos;\n    }\n};",
 "replace-words": "class Solution {\n    struct Trie {\n        Trie* next[26] = {};\n        bool end = false;\n    };\n\npublic:\n    string replaceWords(vector<string>& dictionary, string sentence) {\n        Trie* trie = new Trie();\n        for (auto& w : dictionary) {\n            Trie* node = trie;\n            for (char c : w) {\n                if (!node->next[c - 'a']) node->next[c - 'a'] = new Trie();\n                node = node->next[c - 'a'];\n            }\n            node->end = true;\n        }\n        auto root = [&](const string& word) {\n            Trie* node = trie;\n            for (int i = 0; i < (int)word.size(); i++) {\n                node = node->next[word[i] - 'a'];\n                if (!node) return word;\n                if (node->end) return word.substr(0, i + 1);   // shortest root wins\n            }\n            return word;\n        };\n        istringstream in(sentence);\n        string w, out;\n        while (in >> w) out += (out.empty() ? \"\" : \" \") + root(w);\n        return out;\n    }\n};",
 "restore-the-array-from-adjacent-pairs": "class Solution {\npublic:\n    vector<int> restoreArray(vector<vector<int>>& adjacentPairs) {\n        unordered_map<int, vector<int>> g;\n        for (auto& p : adjacentPairs) { g[p[0]].push_back(p[1]); g[p[1]].push_back(p[0]); }\n        int start = 0;\n        for (auto& [x, nb] : g) if (nb.size() == 1) { start = x; break; }   // an end has one neighbour\n        vector<int> out{start};\n        optional<int> prev;\n        while (out.size() < g.size()) {\n            int cur = out.back();\n            int nxt = g[cur][0] != prev ? g[cur][0] : g[cur].back();   // the neighbour we did not come from\n            prev = cur;\n            out.push_back(nxt);\n        }\n        return out;\n    }\n};",
 "reverse-bits": "class Solution {\npublic:\n    uint32_t reverseBits(uint32_t n) {\n        uint32_t out = 0;\n        for (int i = 0; i < 32; i++) {\n            out = (out << 1) | (n & 1);                      // move n's last bit onto out's end\n            n >>= 1;\n        }\n        return out;\n    }\n};",
 "reverse-integer": "class Solution {\npublic:\n    int reverse(int x) {\n        int sign = x < 0 ? -1 : 1;\n        long long v = llabs((long long)x), rev = 0;          // long long: the reverse can overflow int\n        while (v) {\n            rev = rev * 10 + v % 10;\n            v /= 10;\n        }\n        rev *= sign;\n        return rev >= INT_MIN && rev <= INT_MAX ? (int)rev : 0;\n    }\n};",
 "reverse-linked-list": "class Solution {\npublic:\n    ListNode* reverseList(ListNode* head) {\n        ListNode* prev = nullptr;\n        while (head) {\n            ListNode* nxt = head->next;\n            head->next = prev;                         // point back\n            prev = head;\n            head = nxt;\n        }\n        return prev;\n    }\n};",
 "reverse-linked-list-ii": "class Solution {\npublic:\n    ListNode* reverseBetween(ListNode* head, int left, int right) {\n        ListNode dummy(0, head);\n        ListNode* prev = &dummy;\n        for (int i = 0; i < left - 1; i++) prev = prev->next;   // node before the range\n        ListNode* cur = prev->next;\n        for (int i = 0; i < right - left; i++) {                // move cur's next to the front of the range\n            ListNode* nxt = cur->next;\n            cur->next = nxt->next;\n            nxt->next = prev->next;\n            prev->next = nxt;\n        }\n        return dummy.next;\n    }\n};",
 "reverse-nodes-in-k-group": "class Solution {\npublic:\n    ListNode* reverseKGroup(ListNode* head, int k) {\n        ListNode dummy(0, head);\n        ListNode* groupPrev = &dummy;\n        while (true) {\n            ListNode* kth = groupPrev;\n            for (int i = 0; i < k; i++) {\n                kth = kth->next;\n                if (!kth) return dummy.next;               // fewer than k left: keep them as they are\n            }\n            ListNode* groupNext = kth->next;\n            ListNode *prev = groupNext, *cur = groupPrev->next;\n            while (cur != groupNext) {                     // reverse the group onto groupNext\n                ListNode* nxt = cur->next;\n                cur->next = prev;\n                prev = cur;\n                cur = nxt;\n            }\n            ListNode* first = groupPrev->next;             // now the group's last node\n            groupPrev->next = kth;\n            groupPrev = first;\n        }\n    }\n};",
 "reverse-odd-levels-of-binary-tree": "class Solution {\npublic:\n    TreeNode* reverseOddLevels(TreeNode* root) {\n        vector<TreeNode*> level{root};\n        int depth = 0;\n        while (level[0]->left) {   // the tree is perfect, so one check is enough\n            vector<TreeNode*> next;\n            for (auto* n : level) { next.push_back(n->left); next.push_back(n->right); }\n            level = next;\n            if (++depth % 2) {\n                // swap values from both ends inward\n                for (int i = 0, j = level.size() - 1; i < j; i++, j--) swap(level[i]->val, level[j]->val);\n            }\n        }\n        return root;\n    }\n};",
 "reverse-pairs": "class Solution {\n    // sorts a[lo, hi) and returns the reverse pairs inside it\n    int sortCount(vector<int>& a, int lo, int hi) {\n        if (hi - lo <= 1) return 0;\n        int mid = (lo + hi) / 2;\n        int cnt = sortCount(a, lo, mid) + sortCount(a, mid, hi);\n        int j = mid;\n        for (int i = lo; i < mid; i++) {   // both halves sorted: j only moves forward\n            while (j < hi && a[i] > 2LL * a[j]) j++;\n            cnt += j - mid;\n        }\n        inplace_merge(a.begin() + lo, a.begin() + mid, a.begin() + hi);\n        return cnt;\n    }\n\npublic:\n    int reversePairs(vector<int>& nums) {\n        return sortCount(nums, 0, nums.size());\n    }\n};",
 "reverse-string": "class Solution {\npublic:\n    void reverseString(vector<char>& s) {\n        int l = 0, r = (int)s.size() - 1;\n        while (l < r) swap(s[l++], s[r--]);            // swap the ends and move inward\n    }\n};",
 "reverse-substrings-between-each-pair-of-parentheses": "class Solution {\npublic:\n    string reverseParentheses(string s) {\n        vector<string> st{\"\"};                         // text built at each open depth\n        for (char ch : s) {\n            if (ch == '(') st.push_back(\"\");\n            else if (ch == ')') {\n                string top = st.back(); st.pop_back();\n                st.back() += string(top.rbegin(), top.rend());   // closing a pair reverses its text\n            } else {\n                st.back() += ch;\n            }\n        }\n        return st[0];\n    }\n};",
 "reverse-words-in-a-string": "class Solution {\npublic:\n    string reverseWords(string s) {\n        istringstream in(s);\n        vector<string> words;\n        for (string w; in >> w; ) words.push_back(w);      // splits on any run of spaces\n        string out;\n        for (int i = words.size() - 1; i >= 0; i--) out += words[i] + (i ? \" \" : \"\");\n        return out;\n    }\n};",
 "robot-collisions": "class Solution {\npublic:\n    vector<int> survivedRobotsHealths(vector<int>& positions, vector<int>& healths, string directions) {\n        int n = positions.size();\n        vector<int> h = healths, order(n);\n        iota(order.begin(), order.end(), 0);\n        sort(order.begin(), order.end(), [&](int a, int b) { return positions[a] < positions[b]; });\n        vector<int> st;   // robots moving right, waiting to meet one moving left\n        for (int i : order) {\n            if (directions[i] == 'R') { st.push_back(i); continue; }\n            while (!st.empty() && h[i]) {\n                int j = st.back();\n                if (h[j] < h[i]) { st.pop_back(); h[j] = 0; h[i]--; }\n                else if (h[j] > h[i]) { h[j]--; h[i] = 0; }\n                else { st.pop_back(); h[j] = h[i] = 0; }\n            }\n        }\n        vector<int> out;\n        for (int x : h) if (x) out.push_back(x);   // survivors in input order\n        return out;\n    }\n};",
 "roman-to-integer": "class Solution {\npublic:\n    int romanToInt(string s) {\n        unordered_map<char, int> val{{'I', 1}, {'V', 5}, {'X', 10}, {'L', 50}, {'C', 100}, {'D', 500}, {'M', 1000}};\n        int total = 0;\n        for (size_t i = 0; i < s.size(); i++) {\n            if (i + 1 < s.size() && val[s[i]] < val[s[i + 1]]) total -= val[s[i]];   // a smaller one before a bigger one subtracts\n            else total += val[s[i]];\n        }\n        return total;\n    }\n};",
 "rotate-array": "class Solution {\npublic:\n    void rotate(vector<int>& nums, int k) {\n        int n = nums.size();\n        k %= n;\n        reverse(nums.begin(), nums.end());                 // reverse all, then each part\n        reverse(nums.begin(), nums.begin() + k);\n        reverse(nums.begin() + k, nums.end());\n    }\n};",
 "rotate-image": "class Solution {\npublic:\n    void rotate(vector<vector<int>>& matrix) {\n        int n = matrix.size();\n        for (int i = 0; i < n; i++)\n            for (int j = i + 1; j < n; j++) swap(matrix[i][j], matrix[j][i]);   // transpose\n        for (auto& row : matrix) reverse(row.begin(), row.end());               // then mirror each row\n    }\n};",
 "rotate-string": "class Solution {\npublic:\n    bool rotateString(string s, string goal) {\n        return s.size() == goal.size() && (s + s).find(goal) != string::npos;   // every rotation sits in s + s\n    }\n};",
 "rotating-the-box": "class Solution {\npublic:\n    vector<vector<char>> rotateTheBox(vector<vector<char>>& boxGrid) {\n        int m = boxGrid.size(), n = boxGrid[0].size();\n        for (auto& row : boxGrid) {\n            int empty = n - 1;                             // lowest free slot on the right\n            for (int j = n - 1; j >= 0; j--) {\n                if (row[j] == '*') empty = j - 1;\n                else if (row[j] == '#') { row[j] = '.'; row[empty] = '#'; empty--; }\n            }\n        }\n        vector<vector<char>> out(n, vector<char>(m));\n        for (int j = 0; j < n; j++)\n            for (int i = 0; i < m; i++) out[j][i] = boxGrid[m - 1 - i][j];   // rotate clockwise\n        return out;\n    }\n};",
 "rotting-oranges": "class Solution {\npublic:\n    int orangesRotting(vector<vector<int>>& grid) {\n        int R = grid.size(), C = grid[0].size(), fresh = 0, minutes = 0;\n        queue<pair<int, int>> q;\n        for (int r = 0; r < R; r++)\n            for (int c = 0; c < C; c++) {\n                if (grid[r][c] == 2) q.push({r, c});\n                else if (grid[r][c] == 1) fresh++;\n            }\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        while (!q.empty() && fresh) {\n            minutes++;\n            for (int k = q.size(); k > 0; k--) {         // one minute: every rotten orange spreads once\n                auto [r, c] = q.front(); q.pop();\n                for (int d = 0; d < 4; d++) {\n                    int nr = r + dr[d], nc = c + dc[d];\n                    if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] == 1) {\n                        grid[nr][nc] = 2; fresh--; q.push({nr, nc});\n                    }\n                }\n            }\n        }\n        return fresh ? -1 : minutes;\n    }\n};",
 "russian-doll-envelopes": "class Solution {\npublic:\n    int maxEnvelopes(vector<vector<int>>& envelopes) {\n        // width ascending, height descending for equal widths\n        sort(envelopes.begin(), envelopes.end(), [](auto& a, auto& b) {\n            return a[0] != b[0] ? a[0] < b[0] : a[1] > b[1];\n        });\n        vector<int> tails;                                 // LIS of heights\n        for (auto& e : envelopes) {\n            auto it = lower_bound(tails.begin(), tails.end(), e[1]);\n            if (it == tails.end()) tails.push_back(e[1]);\n            else *it = e[1];\n        }\n        return tails.size();\n    }\n};",
 "same-tree": "class Solution {\npublic:\n    bool isSameTree(TreeNode* p, TreeNode* q) {\n        if (!p || !q) return p == q;                       // both empty, or only one is\n        return p->val == q->val && isSameTree(p->left, q->left) && isSameTree(p->right, q->right);\n    }\n};",
 "satisfiability-of-equality-equations": "class Solution {\npublic:\n    bool equationsPossible(vector<string>& equations) {\n        int parent[26];\n        iota(parent, parent + 26, 0);\n        auto find = [&](int x) {\n            while (parent[x] != x) {\n                parent[x] = parent[parent[x]];   // path halving\n                x = parent[x];\n            }\n            return x;\n        };\n        for (auto& e : equations)\n            if (e[1] == '=') parent[find(e[0] - 'a')] = find(e[3] - 'a');\n        for (auto& e : equations)\n            if (e[1] == '!' && find(e[0] - 'a') == find(e[3] - 'a')) return false;\n        return true;\n    }\n};",
 "score-after-flipping-matrix": "class Solution {\npublic:\n    int matrixScore(vector<vector<int>>& grid) {\n        int R = grid.size(), C = grid[0].size(), total = 0;\n        for (int c = 0; c < C; c++) {\n            // every row is flipped to start with 1, so a cell is 1 when it equals its row's first cell\n            int ones = 0;\n            for (int r = 0; r < R; r++) ones += grid[r][c] == grid[r][0];\n            total += max(ones, R - ones) << (C - 1 - c);   // then flip the column if that gives more ones\n        }\n        return total;\n    }\n};",
 "score-of-parentheses": "class Solution {\npublic:\n    int scoreOfParentheses(string s) {\n        int depth = 0, score = 0;\n        for (size_t i = 0; i < s.size(); i++) {\n            if (s[i] == '(') depth++;\n            else {\n                depth--;\n                if (s[i - 1] == '(') score += 1 << depth;   // each \"()\" is worth 2^depth\n            }\n        }\n        return score;\n    }\n};",
 "search-a-2d-matrix-ii": "class Solution {\npublic:\n    bool searchMatrix(vector<vector<int>>& matrix, int target) {\n        int r = 0, c = matrix[0].size() - 1;   // start at the top right corner\n        while (r < (int)matrix.size() && c >= 0) {\n            int v = matrix[r][c];\n            if (v == target) return true;\n            if (v > target) c--;   // the whole column below is bigger\n            else r++;              // the whole row to the left is smaller\n        }\n        return false;\n    }\n};",
 "search-in-rotated-sorted-array": "class Solution {\npublic:\n    int search(vector<int>& nums, int target) {\n        int lo = 0, hi = nums.size() - 1;\n        while (lo <= hi) {\n            int mid = (lo + hi) / 2;\n            if (nums[mid] == target) return mid;\n            if (nums[lo] <= nums[mid]) {                   // left half is sorted\n                if (nums[lo] <= target && target < nums[mid]) hi = mid - 1;\n                else lo = mid + 1;\n            } else {                                       // right half is sorted\n                if (nums[mid] < target && target <= nums[hi]) lo = mid + 1;\n                else hi = mid - 1;\n            }\n        }\n        return -1;\n    }\n};",
 "search-insert-position": "class Solution {\npublic:\n    int searchInsert(vector<int>& nums, int target) {\n        int lo = 0, hi = nums.size();                      // first index with nums[i] >= target\n        while (lo < hi) {\n            int mid = (lo + hi) / 2;\n            if (nums[mid] < target) lo = mid + 1;\n            else hi = mid;\n        }\n        return lo;\n    }\n};",
 "search-suggestions-system": "class Solution {\npublic:\n    vector<vector<string>> suggestedProducts(vector<string>& products, string searchWord) {\n        sort(products.begin(), products.end());\n        vector<vector<string>> out;\n        string prefix;\n        for (char ch : searchWord) {\n            prefix += ch;\n            auto it = lower_bound(products.begin(), products.end(), prefix);   // first product >= prefix\n            vector<string> row;\n            for (int k = 0; k < 3 && it != products.end() && it->starts_with(prefix); k++, it++) row.push_back(*it);\n            out.push_back(row);\n        }\n        return out;\n    }\n};",
 "separate-black-and-white-balls": "class Solution {\npublic:\n    long long minimumSteps(string s) {\n        long long ones = 0, steps = 0;\n        for (char ch : s) {\n            if (ch == '1') ones++;\n            else steps += ones;                            // this 0 passes every 1 to its left\n        }\n        return steps;\n    }\n};",
 "serialize-and-deserialize-binary-tree": "class Codec {\n    void write(TreeNode* node, string& out) {                // preorder, # for null\n        if (!out.empty()) out += ',';\n        if (!node) { out += '#'; return; }\n        out += to_string(node->val);\n        write(node->left, out);\n        write(node->right, out);\n    }\n    TreeNode* read(istringstream& in) {\n        string v;\n        getline(in, v, ',');\n        if (v == \"#\") return nullptr;\n        TreeNode* node = new TreeNode(stoi(v));\n        node->left = read(in);\n        node->right = read(in);\n        return node;\n    }\npublic:\n    string serialize(TreeNode* root) {\n        string out;\n        write(root, out);\n        return out;\n    }\n\n    TreeNode* deserialize(string data) {\n        istringstream in(data);\n        return read(in);\n    }\n};",
 "serialize-and-deserialize-bst": "class Codec {\npublic:\n    // Encodes a tree to a single string: preorder values, comma separated.\n    string serialize(TreeNode* root) {\n        string out;\n        function<void(TreeNode*)> pre = [&](TreeNode* n) {\n            if (!n) return;\n            out += (out.empty() ? \"\" : \",\") + to_string(n->val);\n            pre(n->left);\n            pre(n->right);\n        };\n        pre(root);\n        return out;\n    }\n\n    // Decodes your encoded data to tree.\n    TreeNode* deserialize(string data) {\n        vector<int> vals;\n        stringstream ss(data);\n        for (string x; getline(ss, x, ',');) vals.push_back(stoi(x));\n        size_t i = 0;\n        // the BST bounds tell where each preorder value belongs, so no null markers are needed\n        function<TreeNode*(long long, long long)> build = [&](long long lo, long long hi) -> TreeNode* {\n            if (i == vals.size() || !(lo < vals[i] && vals[i] < hi)) return nullptr;\n            int v = vals[i++];\n            TreeNode* left = build(lo, v);\n            TreeNode* right = build(v, hi);\n            return new TreeNode(v, left, right);\n        };\n        return build(LLONG_MIN, LLONG_MAX);\n    }\n};",
 "set-matrix-zeroes": "class Solution {\npublic:\n    void setZeroes(vector<vector<int>>& matrix) {\n        int m = matrix.size(), n = matrix[0].size();\n        bool firstRow = false, firstCol = false;\n        for (int j = 0; j < n; j++) if (matrix[0][j] == 0) firstRow = true;\n        for (int i = 0; i < m; i++) if (matrix[i][0] == 0) firstCol = true;\n        for (int i = 1; i < m; i++)\n            for (int j = 1; j < n; j++)\n                if (matrix[i][j] == 0) matrix[i][0] = matrix[0][j] = 0;   // first row and column hold the marks\n        for (int i = 1; i < m; i++)\n            for (int j = 1; j < n; j++)\n                if (matrix[i][0] == 0 || matrix[0][j] == 0) matrix[i][j] = 0;\n        if (firstRow) for (int j = 0; j < n; j++) matrix[0][j] = 0;\n        if (firstCol) for (int i = 0; i < m; i++) matrix[i][0] = 0;\n    }\n};",
 "shifting-letters": "class Solution {\npublic:\n    string shiftingLetters(string s, vector<int>& shifts) {\n        long long total = 0;\n        for (int i = s.size() - 1; i >= 0; i--) {   // letter i moves by the sum of shifts[i..]\n            total = (total + shifts[i]) % 26;\n            s[i] = 'a' + (s[i] - 'a' + total) % 26;\n        }\n        return s;\n    }\n};",
 "shifting-letters-ii": "class Solution {\npublic:\n    string shiftingLetters(string s, vector<vector<int>>& shifts) {\n        vector<int> diff(s.size() + 1, 0);\n        for (auto& sh : shifts) {\n            int v = sh[2] ? 1 : -1;\n            diff[sh[0]] += v;\n            diff[sh[1] + 1] -= v;\n        }\n        int run = 0;\n        for (size_t i = 0; i < s.size(); i++) {\n            run += diff[i];                                // total shift at i\n            s[i] = 'a' + ((s[i] - 'a' + run) % 26 + 26) % 26;   // keep the remainder non-negative\n        }\n        return s;\n    }\n};",
 "shortest-common-supersequence": "class Solution {\npublic:\n    string shortestCommonSupersequence(string str1, string str2) {\n        int m = str1.size(), n = str2.size();\n        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));   // LCS table\n        for (int i = 0; i < m; i++)\n            for (int j = 0; j < n; j++)\n                dp[i + 1][j + 1] = str1[i] == str2[j] ? dp[i][j] + 1 : max(dp[i][j + 1], dp[i + 1][j]);\n        string out;\n        int i = m, j = n;\n        while (i && j) {                                     // walk back, writing each char once\n            if (str1[i - 1] == str2[j - 1]) { out += str1[i - 1]; i--; j--; }\n            else if (dp[i - 1][j] >= dp[i][j - 1]) out += str1[--i];\n            else out += str2[--j];\n        }\n        while (i) out += str1[--i];                          // leftovers of either string\n        while (j) out += str2[--j];\n        reverse(out.begin(), out.end());\n        return out;\n    }\n};",
 "shortest-palindrome": "class Solution {\npublic:\n    string shortestPalindrome(string s) {\n        string t = s + \"#\" + string(s.rbegin(), s.rend());\n        vector<int> lps(t.size(), 0);   // KMP prefix function\n        for (size_t i = 1; i < t.size(); i++) {\n            int k = lps[i - 1];\n            while (k && t[i] != t[k]) k = lps[k - 1];\n            if (t[i] == t[k]) k++;\n            lps[i] = k;\n        }\n        // lps.back() is the longest palindrome prefix of s; mirror the rest in front\n        string rest = s.substr(lps.back());\n        return string(rest.rbegin(), rest.rend()) + s;\n    }\n};",
 "shortest-path-in-a-grid-with-obstacles-elimination": "class Solution {\npublic:\n    int shortestPath(vector<vector<int>>& grid, int k) {\n        int R = grid.size(), C = grid[0].size();\n        if (k >= R + C - 2) return R + C - 2;   // enough to walk straight through anything\n        vector<vector<int>> best(R, vector<int>(C, -1));   // most eliminations left on arrival\n        best[0][0] = k;\n        queue<array<int, 3>> q;\n        q.push({0, 0, k});\n        const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        for (int steps = 0; !q.empty(); steps++) {\n            for (int s = q.size(); s > 0; s--) {\n                auto [r, c, left] = q.front();\n                q.pop();\n                if (r == R - 1 && c == C - 1) return steps;\n                for (int d = 0; d < 4; d++) {\n                    int nr = r + dr[d], nc = c + dc[d];\n                    if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;\n                    int nl = left - grid[nr][nc];\n                    if (nl > best[nr][nc]) {   // only revisit with more eliminations left\n                        best[nr][nc] = nl;\n                        q.push({nr, nc, nl});\n                    }\n                }\n            }\n        }\n        return -1;\n    }\n};",
 "shortest-path-in-binary-matrix": "class Solution {\npublic:\n    int shortestPathBinaryMatrix(vector<vector<int>>& grid) {\n        int n = grid.size();\n        if (grid[0][0] || grid[n - 1][n - 1]) return -1;\n        queue<tuple<int, int, int>> q;\n        q.push({0, 0, 1});\n        grid[0][0] = 1;                                  // mark visited\n        while (!q.empty()) {\n            auto [r, c, d] = q.front(); q.pop();\n            if (r == n - 1 && c == n - 1) return d;\n            for (int dr = -1; dr <= 1; dr++)\n                for (int dc = -1; dc <= 1; dc++) {       // all 8 directions\n                    int nr = r + dr, nc = c + dc;\n                    if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 0) {\n                        grid[nr][nc] = 1;\n                        q.push({nr, nc, d + 1});\n                    }\n                }\n        }\n        return -1;\n    }\n};",
 "shortest-path-visiting-all-nodes": "class Solution {\npublic:\n    int shortestPathLength(vector<vector<int>>& graph) {\n        int n = graph.size(), full = (1 << n) - 1;\n        queue<tuple<int, int, int>> q;                   // (node, visited mask, distance)\n        vector<vector<bool>> seen(n, vector<bool>(1 << n, false));\n        for (int i = 0; i < n; i++) { q.push({i, 1 << i, 0}); seen[i][1 << i] = true; }   // start anywhere\n        while (!q.empty()) {\n            auto [u, mask, d] = q.front(); q.pop();\n            if (mask == full) return d;\n            for (int v : graph[u]) {\n                int m2 = mask | 1 << v;\n                if (!seen[v][m2]) { seen[v][m2] = true; q.push({v, m2, d + 1}); }\n            }\n        }\n        return 0;\n    }\n};",
 "shortest-path-with-alternating-colors": "class Solution {\npublic:\n    vector<int> shortestAlternatingPaths(int n, vector<vector<int>>& redEdges, vector<vector<int>>& blueEdges) {\n        vector<vector<int>> adj[2] = {vector<vector<int>>(n), vector<vector<int>>(n)};   // 0 red, 1 blue\n        for (auto& e : redEdges) adj[0][e[0]].push_back(e[1]);\n        for (auto& e : blueEdges) adj[1][e[0]].push_back(e[1]);\n        vector<int> ans(n, -1);\n        vector<array<bool, 2>> seen(n, {false, false});  // (node, colour of the edge that got us here)\n        seen[0] = {true, true};\n        queue<tuple<int, int, int>> q;\n        q.push({0, 0, 0}); q.push({0, 1, 0});\n        while (!q.empty()) {\n            auto [u, c, d] = q.front(); q.pop();\n            if (ans[u] == -1) ans[u] = d;\n            for (int v : adj[1 - c][u])                  // next edge must be the other colour\n                if (!seen[v][1 - c]) { seen[v][1 - c] = true; q.push({v, 1 - c, d + 1}); }\n        }\n        return ans;\n    }\n};",
 "shortest-subarray-to-be-removed-to-make-array-sorted": "class Solution {\npublic:\n    int findLengthOfShortestSubarray(vector<int>& arr) {\n        int n = arr.size(), r = n - 1;\n        while (r > 0 && arr[r - 1] <= arr[r]) r--;   // sorted suffix starts at r\n        if (r == 0) return 0;\n        int best = r;                                // remove arr[0..r-1]\n        for (int l = 0; l < r && (l == 0 || arr[l - 1] <= arr[l]); l++) {\n            while (r < n && arr[r] < arr[l]) r++;    // first suffix element that can follow arr[l]\n            best = min(best, r - l - 1);\n        }\n        return best;\n    }\n};",
 "shortest-subarray-with-sum-at-least-k": "class Solution {\npublic:\n    int shortestSubarray(vector<int>& nums, int k) {\n        int n = nums.size();\n        vector<long long> pre(n + 1, 0);\n        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];\n        int best = n + 1;\n        deque<int> dq;                                  // indexes with increasing prefix sums\n        for (int j = 0; j <= n; j++) {\n            while (!dq.empty() && pre[j] - pre[dq.front()] >= k) {\n                best = min(best, j - dq.front());\n                dq.pop_front();\n            }\n            while (!dq.empty() && pre[dq.back()] >= pre[j]) dq.pop_back();   // never a better start\n            dq.push_back(j);\n        }\n        return best <= n ? best : -1;\n    }\n};",
 "shortest-unsorted-continuous-subarray": "class Solution {\npublic:\n    int findUnsortedSubarray(vector<int>& nums) {\n        int n = nums.size(), start = 0, end = -1;\n        int mx = nums[0], mn = nums[n - 1];\n        for (int i = 0; i < n; i++) {\n            mx = max(mx, nums[i]);\n            if (nums[i] < mx) end = i;     // smaller than something before it\n            int j = n - 1 - i;\n            mn = min(mn, nums[j]);\n            if (nums[j] > mn) start = j;   // bigger than something after it\n        }\n        return end - start + 1;\n    }\n};",
 "simplify-path": "class Solution {\npublic:\n    string simplifyPath(string path) {\n        vector<string> st;\n        stringstream ss(path);\n        string part;\n        while (getline(ss, part, '/')) {\n            if (part == \"..\") { if (!st.empty()) st.pop_back(); }   // go up, never above root\n            else if (!part.empty() && part != \".\") st.push_back(part);\n        }\n        string out;\n        for (const string& p : st) out += \"/\" + p;\n        return out.empty() ? \"/\" : out;\n    }\n};",
 "single-number": "class Solution {\npublic:\n    int singleNumber(vector<int>& nums) {\n        int x = 0;\n        for (int v : nums) x ^= v;                           // pairs cancel out\n        return x;\n    }\n};",
 "single-number-ii": "class Solution {\npublic:\n    int singleNumber(vector<int>& nums) {\n        int ones = 0, twos = 0;    // bits seen once and twice (mod 3)\n        for (int x : nums) {\n            ones = (ones ^ x) & ~twos;\n            twos = (twos ^ x) & ~ones;\n        }\n        return ones;\n    }\n};",
 "single-number-iii": "class Solution {\npublic:\n    vector<int> singleNumber(vector<int>& nums) {\n        unsigned x = 0;   // unsigned so x & -x never overflows\n        for (int v : nums) x ^= v;\n        unsigned low = x & -x;   // a bit where the two answers differ\n        int a = 0;\n        for (int v : nums)\n            if (v & low) a ^= v;\n        return {a, (int)(x ^ a)};\n    }\n};",
 "sliding-window-maximum": "class Solution {\npublic:\n    vector<int> maxSlidingWindow(vector<int>& nums, int k) {\n        deque<int> dq;                                // indices, values decreasing from front to back\n        vector<int> out;\n        for (int i = 0; i < (int)nums.size(); i++) {\n            if (!dq.empty() && dq.front() <= i - k) dq.pop_front();    // front fell out of the window\n            while (!dq.empty() && nums[dq.back()] <= nums[i]) dq.pop_back();  // smaller ones can never win\n            dq.push_back(i);\n            if (i >= k - 1) out.push_back(nums[dq.front()]);\n        }\n        return out;\n    }\n};",
 "sliding-window-median": "class Solution {\npublic:\n    vector<double> medianSlidingWindow(vector<int>& nums, int k) {\n        vector<int> win(nums.begin(), nums.begin() + k);   // the window, kept sorted\n        sort(win.begin(), win.end());\n        vector<double> out;\n        for (int i = k; i <= (int)nums.size(); i++) {\n            if (k % 2) out.push_back(win[k / 2]);\n            else out.push_back(((double)win[k / 2 - 1] + win[k / 2]) / 2);\n            if (i == (int)nums.size()) break;\n            win.erase(lower_bound(win.begin(), win.end(), nums[i - k]));\n            win.insert(upper_bound(win.begin(), win.end(), nums[i]), nums[i]);\n        }\n        return out;\n    }\n};",
 "smallest-number-in-infinite-set": "class SmallestInfiniteSet {\n    int next = 1;                                          // every number >= next is still in the set\n    priority_queue<int, vector<int>, greater<int>> heap;   // numbers added back below next\n    unordered_set<int> back;\npublic:\n    SmallestInfiniteSet() {}\n\n    int popSmallest() {\n        if (!heap.empty()) {\n            int x = heap.top(); heap.pop();\n            back.erase(x);\n            return x;\n        }\n        return next++;\n    }\n\n    void addBack(int num) {\n        if (num < next && !back.count(num)) { back.insert(num); heap.push(num); }\n    }\n};",
 "smallest-range-covering-elements-from-k-lists": "class Solution {\npublic:\n    vector<int> smallestRange(vector<vector<int>>& nums) {\n        // (value, list, index in list): the smallest current value of every list\n        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> heap;\n        int hi = INT_MIN;\n        for (int i = 0; i < (int)nums.size(); i++) {\n            heap.push({nums[i][0], i, 0});\n            hi = max(hi, nums[i][0]);\n        }\n        vector<int> best{get<0>(heap.top()), hi};\n        while (true) {\n            auto [lo, i, j] = heap.top();\n            heap.pop();\n            if ((long long)hi - lo < (long long)best[1] - best[0]) best = {lo, hi};\n            if (j + 1 == (int)nums[i].size()) return best;   // a list ran out\n            int nxt = nums[i][j + 1];\n            hi = max(hi, nxt);\n            heap.push({nxt, i, j + 1});\n        }\n    }\n};",
 "smallest-string-with-a-given-numeric-value": "class Solution {\npublic:\n    string getSmallestString(int n, int k) {\n        string out(n, 'a');\n        for (int i = n; i >= 1; i--) {\n            int v = min(26, k - (i - 1));                  // leave at least an 'a' for each earlier spot\n            out[i - 1] = 'a' + v - 1;\n            k -= v;\n        }\n        return out;\n    }\n};",
 "smallest-string-with-swaps": "class Solution {\npublic:\n    string smallestStringWithSwaps(string s, vector<vector<int>>& pairs) {\n        int n = s.size();\n        vector<int> parent(n);\n        iota(parent.begin(), parent.end(), 0);\n        auto find = [&](int x) {\n            while (parent[x] != x) {\n                parent[x] = parent[parent[x]];\n                x = parent[x];\n            }\n            return x;\n        };\n        for (auto& p : pairs) parent[find(p[0])] = find(p[1]);\n        unordered_map<int, vector<int>> groups;   // root -> indices, in increasing order\n        for (int i = 0; i < n; i++) groups[find(i)].push_back(i);\n        string out = s;\n        for (auto& [r, idx] : groups) {\n            string chars;\n            for (int i : idx) chars += s[i];\n            sort(chars.begin(), chars.end());\n            for (int k = 0; k < (int)idx.size(); k++) out[idx[k]] = chars[k];   // smallest letters to the earliest slots\n        }\n        return out;\n    }\n};",
 "smallest-subarrays-with-maximum-bitwise-or": "class Solution {\npublic:\n    vector<int> smallestSubarrays(vector<int>& nums) {\n        int n = nums.size();\n        vector<int> last(32, 0), out(n, 1);                // last[b]: nearest index >= i with bit b\n        for (int i = n - 1; i >= 0; i--) {\n            for (int b = 0; b < 32; b++)\n                if (nums[i] >> b & 1) last[b] = i;\n            out[i] = max(1, *max_element(last.begin(), last.end()) - i + 1);\n        }\n        return out;\n    }\n};",
 "smallest-subsequence-of-distinct-characters": "class Solution {\npublic:\n    string smallestSubsequence(string s) {\n        int last[26];\n        for (int i = 0; i < (int)s.size(); i++) last[s[i] - 'a'] = i;\n        string st;\n        bool inside[26] = {};\n        for (int i = 0; i < (int)s.size(); i++) {\n            char c = s[i];\n            if (inside[c - 'a']) continue;\n            while (!st.empty() && st.back() > c && last[st.back() - 'a'] > i) {   // it comes again later\n                inside[st.back() - 'a'] = false;\n                st.pop_back();\n            }\n            st.push_back(c);\n            inside[c - 'a'] = true;\n        }\n        return st;\n    }\n};",
 "smallest-subtree-with-all-the-deepest-nodes": "class Solution {\n    // returns {depth, answer}\n    pair<int, TreeNode*> go(TreeNode* node) {\n        if (!node) return {0, nullptr};\n        auto [ld, ln] = go(node->left);\n        auto [rd, rn] = go(node->right);\n        if (ld > rd) return {ld + 1, ln};\n        if (rd > ld) return {rd + 1, rn};\n        return {ld + 1, node};   // deepest nodes on both sides: this node holds them all\n    }\n\npublic:\n    TreeNode* subtreeWithAllDeepest(TreeNode* root) {\n        return go(root).second;\n    }\n};",
 "snapshot-array": "class SnapshotArray {\n    vector<vector<pair<int, int>>> h;                  // per index: (snap id, value) in snap order\n    int snapId = 0;\npublic:\n    SnapshotArray(int length) : h(length, {{-1, 0}}) {}\n\n    void set(int index, int val) {\n        auto& hist = h[index];\n        if (hist.back().first == snapId) hist.back().second = val;   // overwrite within the same snap\n        else hist.push_back({snapId, val});\n    }\n\n    int snap() { return snapId++; }\n\n    int get(int index, int snap_id) {\n        auto& hist = h[index];\n        // last change made at or before snap_id\n        return prev(upper_bound(hist.begin(), hist.end(), pair{snap_id, INT_MAX}))->second;\n    }\n};",
 "sort-an-array": "class Solution {\npublic:\n    vector<int> sortArray(vector<int>& nums) {\n        if (nums.size() <= 1) return nums;\n        size_t mid = nums.size() / 2;\n        vector<int> left(nums.begin(), nums.begin() + mid), right(nums.begin() + mid, nums.end());\n        vector<int> a = sortArray(left), b = sortArray(right);\n        vector<int> out;\n        size_t i = 0, j = 0;\n        while (i < a.size() && j < b.size()) {\n            if (a[i] <= b[j]) out.push_back(a[i++]);    // <= keeps the sort stable\n            else out.push_back(b[j++]);\n        }\n        out.insert(out.end(), a.begin() + i, a.end());\n        out.insert(out.end(), b.begin() + j, b.end());\n        return out;\n    }\n};",
 "sort-characters-by-frequency": "class Solution {\npublic:\n    string frequencySort(string s) {\n        unordered_map<char, int> cnt;\n        for (char c : s) cnt[c]++;\n        vector<pair<int, char>> order;\n        for (auto [c, k] : cnt) order.push_back({k, c});\n        sort(order.rbegin(), order.rend());   // most common first\n        string out;\n        for (auto [k, c] : order) out.append(k, c);\n        return out;\n    }\n};",
 "sort-colors": "class Solution {\npublic:\n    void sortColors(vector<int>& nums) {\n        int lo = 0, mid = 0, hi = (int)nums.size() - 1;\n        while (mid <= hi) {\n            if (nums[mid] == 0) swap(nums[lo++], nums[mid++]);   // 0 goes to the front block\n            else if (nums[mid] == 1) mid++;\n            else swap(nums[mid], nums[hi--]);                    // 2 goes to the back; recheck nums[mid]\n        }\n    }\n};",
 "sort-integers-by-the-number-of-1-bits": "class Solution {\npublic:\n    vector<int> sortByBits(vector<int>& arr) {\n        vector<int> out = arr;\n        sort(out.begin(), out.end(), [](int a, int b) {\n            int pa = __builtin_popcount(a), pb = __builtin_popcount(b);\n            return pa != pb ? pa < pb : a < b;               // by bit count, then by value\n        });\n        return out;\n    }\n};",
 "sort-items-by-groups-respecting-dependencies": "class Solution {\n    // Kahn's algorithm; empty when there is a cycle\n    vector<int> topo(int count, vector<vector<int>>& edges) {\n        vector<int> indeg(count, 0), out;\n        for (auto& to : edges) for (int b : to) indeg[b]++;\n        queue<int> q;\n        for (int x = 0; x < count; x++) if (indeg[x] == 0) q.push(x);\n        while (!q.empty()) {\n            int x = q.front(); q.pop();\n            out.push_back(x);\n            for (int y : edges[x]) if (--indeg[y] == 0) q.push(y);\n        }\n        return (int)out.size() == count ? out : vector<int>{};\n    }\npublic:\n    vector<int> sortItems(int n, int m, vector<int>& group, vector<vector<int>>& beforeItems) {\n        for (int i = 0; i < n; i++)\n            if (group[i] == -1) group[i] = m++;            // an ungrouped item gets its own group\n        vector<vector<int>> itemEdges(n), groupEdges(m);\n        for (int a = 0; a < n; a++)\n            for (int b : beforeItems[a]) {\n                itemEdges[b].push_back(a);\n                if (group[a] != group[b]) groupEdges[group[b]].push_back(group[a]);\n            }\n        vector<int> items = topo(n, itemEdges), groups = topo(m, groupEdges);\n        if (items.empty() || groups.empty()) return {};\n        vector<vector<int>> byGroup(m);\n        for (int x : items) byGroup[group[x]].push_back(x);\n        vector<int> out;\n        for (int g : groups) for (int x : byGroup[g]) out.push_back(x);\n        return out;\n    }\n};",
 "sort-list": "class Solution {\npublic:\n    ListNode* sortList(ListNode* head) {\n        if (!head || !head->next) return head;\n        ListNode *slow = head, *fast = head->next;\n        while (fast && fast->next) { slow = slow->next; fast = fast->next->next; }\n        ListNode* mid = slow->next;\n        slow->next = nullptr;                                // cut the list in two halves\n        ListNode *a = sortList(head), *b = sortList(mid);\n        ListNode dummy, *tail = &dummy;\n        while (a && b) {\n            if (a->val <= b->val) { tail->next = a; a = a->next; }\n            else { tail->next = b; b = b->next; }\n            tail = tail->next;\n        }\n        tail->next = a ? a : b;\n        return dummy.next;\n    }\n};",
 "sort-the-jumbled-numbers": "class Solution {\npublic:\n    vector<int> sortJumbled(vector<int>& mapping, vector<int>& nums) {\n        auto key = [&](int x) {   // map each digit, read the result as a number\n            string d = to_string(x);\n            int v = 0;\n            for (char c : d) v = v * 10 + mapping[c - '0'];\n            return v;\n        };\n        vector<pair<int, int>> keyed;\n        for (int x : nums) keyed.push_back({key(x), x});\n        stable_sort(keyed.begin(), keyed.end(), [](auto& a, auto& b) { return a.first < b.first; });   // ties keep input order\n        vector<int> out;\n        for (auto& [k, x] : keyed) out.push_back(x);\n        return out;\n    }\n};",
 "sort-the-matrix-diagonally": "class Solution {\npublic:\n    vector<vector<int>> diagonalSort(vector<vector<int>>& mat) {\n        unordered_map<int, vector<int>> d;   // i - j names a diagonal\n        for (int i = 0; i < (int)mat.size(); i++)\n            for (int j = 0; j < (int)mat[i].size(); j++) d[i - j].push_back(mat[i][j]);\n        for (auto& [k, v] : d) sort(v.rbegin(), v.rend());   // descending, so pop_back gives the smallest\n        for (int i = 0; i < (int)mat.size(); i++)\n            for (int j = 0; j < (int)mat[i].size(); j++) {\n                mat[i][j] = d[i - j].back();\n                d[i - j].pop_back();\n            }\n        return mat;\n    }\n};",
 "sort-the-students-by-their-kth-score": "class Solution {\npublic:\n    vector<vector<int>> sortTheStudents(vector<vector<int>>& score, int k) {\n        sort(score.begin(), score.end(), [k](auto& a, auto& b) { return a[k] > b[k]; });   // highest kth score first\n        return score;\n    }\n};",
 "sort-vowels-in-a-string": "class Solution {\npublic:\n    string sortVowels(string s) {\n        auto isVowel = [](char c) { return string(\"aeiouAEIOU\").find(c) != string::npos; };\n        string vowels;\n        for (char c : s)\n            if (isVowel(c)) vowels += c;\n        sort(vowels.begin(), vowels.end());   // uppercase sorts before lowercase in ASCII\n        int k = 0;\n        for (char& c : s)\n            if (isVowel(c)) c = vowels[k++];\n        return s;\n    }\n};",
 "spiral-matrix": "class Solution {\npublic:\n    vector<int> spiralOrder(vector<vector<int>>& matrix) {\n        vector<int> out;\n        int top = 0, bottom = (int)matrix.size() - 1, left = 0, right = (int)matrix[0].size() - 1;\n        while (top <= bottom && left <= right) {\n            for (int j = left; j <= right; j++) out.push_back(matrix[top][j]);\n            top++;\n            for (int i = top; i <= bottom; i++) out.push_back(matrix[i][right]);\n            right--;\n            if (top <= bottom) {                             // a row is still left\n                for (int j = right; j >= left; j--) out.push_back(matrix[bottom][j]);\n                bottom--;\n            }\n            if (left <= right) {                             // a column is still left\n                for (int i = bottom; i >= top; i--) out.push_back(matrix[i][left]);\n                left++;\n            }\n        }\n        return out;\n    }\n};",
 "stickers-to-spell-word": "class Solution {\n    vector<array<int, 26>> packs;\n    unordered_map<string, int> memo;\n    static constexpr int INF = INT_MAX / 2;\n\n    int solve(const string& left) {                      // left is sorted, so equal states share one key\n        if (left.empty()) return 0;\n        if (auto it = memo.find(left); it != memo.end()) return it->second;\n        array<int, 26> need{};\n        for (char ch : left) need[ch - 'a']++;\n        int best = INF;\n        for (auto& p : packs) {\n            if (p[left[0] - 'a'] == 0) continue;         // only stickers that cover the first letter\n            string rest;\n            for (int ch = 0; ch < 26; ch++) rest += string(max(0, need[ch] - p[ch]), 'a' + ch);\n            best = min(best, 1 + solve(rest));\n        }\n        return memo[left] = best;\n    }\n\npublic:\n    int minStickers(vector<string>& stickers, string target) {\n        for (auto& s : stickers) {\n            array<int, 26> c{};\n            for (char ch : s) c[ch - 'a']++;\n            packs.push_back(c);\n        }\n        sort(target.begin(), target.end());\n        int ans = solve(target);\n        return ans >= INF ? -1 : ans;\n    }\n};",
 "stock-price-fluctuation": "class StockPrice {\n    unordered_map<int, int> price;                         // true price per timestamp\n    int latest = 0;\n    priority_queue<pair<int, int>> hi;                                          // (price, time), max on top\n    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> lo;       // min on top\npublic:\n    StockPrice() {}\n\n    void update(int timestamp, int price) {\n        this->price[timestamp] = price;\n        latest = max(latest, timestamp);\n        hi.push({price, timestamp});\n        lo.push({price, timestamp});\n    }\n\n    int current() { return price[latest]; }\n\n    int maximum() {\n        while (price[hi.top().second] != hi.top().first) hi.pop();   // drop stale entries\n        return hi.top().first;\n    }\n\n    int minimum() {\n        while (price[lo.top().second] != lo.top().first) lo.pop();\n        return lo.top().first;\n    }\n};",
 "stone-game-vi": "class Solution {\npublic:\n    int stoneGameVI(vector<int>& aliceValues, vector<int>& bobValues) {\n        int n = aliceValues.size();\n        vector<int> order(n);\n        iota(order.begin(), order.end(), 0);\n        // a stone is worth its value to you plus what it denies the other player\n        sort(order.begin(), order.end(), [&](int a, int b) { return aliceValues[a] + bobValues[a] > aliceValues[b] + bobValues[b]; });\n        int diff = 0;\n        for (int turn = 0; turn < n; turn++) {\n            int i = order[turn];\n            diff += turn % 2 == 0 ? aliceValues[i] : -bobValues[i];\n        }\n        return (diff > 0) - (diff < 0);\n    }\n};",
 "stream-of-characters": "class StreamChecker {\n    struct Node { Node* next[26] = {}; bool end = false; };\n    Node* root = new Node();\n    int longest = 0;\n    string stream;\npublic:\n    StreamChecker(vector<string>& words) {\n        for (auto& w : words) {\n            longest = max(longest, (int)w.size());\n            Node* node = root;\n            for (int i = w.size() - 1; i >= 0; i--) {      // store each word reversed\n                int c = w[i] - 'a';\n                if (!node->next[c]) node->next[c] = new Node();\n                node = node->next[c];\n            }\n            node->end = true;\n        }\n    }\n\n    bool query(char letter) {\n        stream.push_back(letter);\n        Node* node = root;\n        // walk the stream newest to oldest, at most `longest` letters\n        for (int i = stream.size() - 1; i >= 0 && i >= (int)stream.size() - longest; i--) {\n            node = node->next[stream[i] - 'a'];\n            if (!node) return false;\n            if (node->end) return true;\n        }\n        return false;\n    }\n};",
 "string-to-integer-atoi": "class Solution {\npublic:\n    int myAtoi(string s) {\n        size_t i = 0, n = s.size();\n        while (i < n && s[i] == ' ') i++;\n        int sign = 1;\n        if (i < n && (s[i] == '+' || s[i] == '-')) sign = s[i++] == '-' ? -1 : 1;\n        long long num = 0;\n        while (i < n && isdigit((unsigned char)s[i])) {\n            num = min(num * 10 + (s[i++] - '0'), (long long)INT_MAX + 1);   // stop growing once past int range\n        }\n        return (int)max((long long)INT_MIN, min((long long)INT_MAX, sign * num));\n    }\n};",
 "subarray-product-less-than-k": "class Solution {\npublic:\n    int numSubarrayProductLessThanK(vector<int>& nums, int k) {\n        if (k <= 1) return 0;\n        long long prod = 1;\n        int L = 0, ans = 0;\n        for (int R = 0; R < (int)nums.size(); R++) {\n            prod *= nums[R];\n            while (prod >= k) prod /= nums[L++];   // shrink until the product fits\n            ans += R - L + 1;                       // subarrays ending at R\n        }\n        return ans;\n    }\n};",
 "subarray-sum-equals-k": "class Solution {\npublic:\n    int subarraySum(vector<int>& nums, int k) {\n        unordered_map<int, int> seen{{0, 1}};                // prefix sum -> how many times seen\n        int run = 0, count = 0;\n        for (int x : nums) {\n            run += x;\n            auto it = seen.find(run - k);                    // earlier prefixes that leave sum k\n            if (it != seen.end()) count += it->second;\n            seen[run]++;\n        }\n        return count;\n    }\n};",
 "subarray-sums-divisible-by-k": "class Solution {\npublic:\n    int subarraysDivByK(vector<int>& nums, int k) {\n        unordered_map<int, int> count{{0, 1}};   // prefix remainder -> how often seen\n        int s = 0, ans = 0;\n        for (int x : nums) {\n            s = ((s + x) % k + k) % k;   // keep the remainder non-negative\n            ans += count[s]++;\n        }\n        return ans;\n    }\n};",
 "subarrays-with-k-different-integers": "class Solution {\n    // subarrays with at most k distinct values\n    int atMost(vector<int>& nums, int k) {\n        unordered_map<int, int> cnt;\n        int left = 0, res = 0;\n        for (int right = 0; right < (int)nums.size(); right++) {\n            cnt[nums[right]]++;\n            while ((int)cnt.size() > k) {\n                int y = nums[left++];\n                if (--cnt[y] == 0) cnt.erase(y);\n            }\n            res += right - left + 1;\n        }\n        return res;\n    }\n\npublic:\n    int subarraysWithKDistinct(vector<int>& nums, int k) {\n        return atMost(nums, k) - atMost(nums, k - 1);   // exactly k\n    }\n};",
 "subsets": "class Solution {\npublic:\n    vector<vector<int>> subsets(vector<int>& nums) {\n        vector<vector<int>> out{{}};\n        for (int x : nums) {\n            size_t size = out.size();\n            for (size_t i = 0; i < size; i++) {              // every subset so far, now with x too\n                vector<int> s = out[i];\n                s.push_back(x);\n                out.push_back(s);\n            }\n        }\n        return out;\n    }\n};",
 "substring-with-concatenation-of-all-words": "class Solution {\npublic:\n    vector<int> findSubstring(string s, vector<string>& words) {\n        int L = words[0].size(), k = words.size(), n = s.size();\n        unordered_map<string, int> need;\n        for (auto& w : words) need[w]++;\n        vector<int> out;\n        for (int off = 0; off < L; off++) {           // one sliding window per offset\n            unordered_map<string, int> seen;\n            int left = off, used = 0;\n            for (int right = off; right + L <= n; right += L) {\n                string w = s.substr(right, L);\n                if (!need.count(w)) {                 // a foreign word: restart after it\n                    seen.clear();\n                    used = 0;\n                    left = right + L;\n                    continue;\n                }\n                seen[w]++;\n                used++;\n                while (seen[w] > need[w]) {           // too many copies: shrink from the left\n                    seen[s.substr(left, L)]--;\n                    used--;\n                    left += L;\n                }\n                if (used == k) {\n                    out.push_back(left);\n                    seen[s.substr(left, L)]--;\n                    used--;\n                    left += L;\n                }\n            }\n        }\n        sort(out.begin(), out.end());\n        return out;\n    }\n};",
 "substrings-of-size-three-with-distinct-characters": "class Solution {\npublic:\n    int countGoodSubstrings(string s) {\n        int count = 0;\n        for (size_t i = 0; i + 2 < s.size(); i++) {      // every window of three\n            char a = s[i], b = s[i + 1], c = s[i + 2];\n            if (a != b && b != c && a != c) count++;\n        }\n        return count;\n    }\n};",
 "subtree-of-another-tree": "class Solution {\n    bool same(TreeNode* a, TreeNode* b) {\n        if (!a || !b) return a == b;\n        return a->val == b->val && same(a->left, b->left) && same(a->right, b->right);\n    }\npublic:\n    bool isSubtree(TreeNode* root, TreeNode* subRoot) {\n        return root && (same(root, subRoot) || isSubtree(root->left, subRoot) || isSubtree(root->right, subRoot));\n    }\n};",
 "sudoku-solver": "class Solution {\n    // used[r][v]: digit v + 1 is already in row r (and the same for columns and boxes)\n    bool rows[9][9] = {}, cols[9][9] = {}, boxes[9][9] = {};\n    vector<pair<int, int>> empty;\n    bool go(vector<vector<char>>& board, size_t k) {\n        if (k == empty.size()) return true;\n        auto [r, c] = empty[k];\n        int b = r / 3 * 3 + c / 3;\n        for (int v = 0; v < 9; v++) {\n            if (rows[r][v] || cols[c][v] || boxes[b][v]) continue;\n            board[r][c] = '1' + v;\n            rows[r][v] = cols[c][v] = boxes[b][v] = true;\n            if (go(board, k + 1)) return true;\n            rows[r][v] = cols[c][v] = boxes[b][v] = false;   // undo and try the next digit\n        }\n        board[r][c] = '.';\n        return false;\n    }\npublic:\n    void solveSudoku(vector<vector<char>>& board) {\n        for (int r = 0; r < 9; r++)\n            for (int c = 0; c < 9; c++) {\n                char v = board[r][c];\n                if (v == '.') empty.push_back({r, c});\n                else rows[r][v - '1'] = cols[c][v - '1'] = boxes[r / 3 * 3 + c / 3][v - '1'] = true;\n            }\n        go(board, 0);\n    }\n};",
 "sum-of-beauty-of-all-substrings": "class Solution {\npublic:\n    int beautySum(string s) {\n        int total = 0;\n        for (int i = 0; i < (int)s.size(); i++) {\n            int cnt[26] = {};\n            for (int j = i; j < (int)s.size(); j++) {\n                cnt[s[j] - 'a']++;\n                int hi = 0, lo = INT_MAX;\n                for (int c : cnt)\n                    if (c) { hi = max(hi, c); lo = min(lo, c); }   // min over letters that appear\n                total += hi - lo;\n            }\n        }\n        return total;\n    }\n};",
 "sum-of-distances-in-tree": "class Solution {\npublic:\n    vector<int> sumOfDistancesInTree(int n, vector<vector<int>>& edges) {\n        vector<vector<int>> adj(n);\n        for (auto& e : edges) {\n            adj[e[0]].push_back(e[1]);\n            adj[e[1]].push_back(e[0]);\n        }\n        vector<int> order{0}, parent(n, -1);       // BFS order from root 0\n        for (size_t i = 0; i < order.size(); i++) {\n            int u = order[i];\n            for (int v : adj[u])\n                if (v != parent[u]) {\n                    parent[v] = u;\n                    order.push_back(v);\n                }\n        }\n        vector<int> count(n, 1), sub(n, 0);        // subtree size and distance sum inside it\n        for (int i = n - 1; i >= 0; i--) {\n            int u = order[i], p = parent[u];\n            if (p >= 0) {\n                count[p] += count[u];\n                sub[p] += sub[u] + count[u];\n            }\n        }\n        vector<int> ans(n, 0);\n        ans[0] = sub[0];\n        // moving the root to u: count[u] nodes get 1 closer, the rest 1 further\n        for (int i = 1; i < n; i++) {\n            int u = order[i];\n            ans[u] = ans[parent[u]] - count[u] + (n - count[u]);\n        }\n        return ans;\n    }\n};",
 "sum-of-even-numbers-after-queries": "class Solution {\npublic:\n    vector<int> sumEvenAfterQueries(vector<int>& nums, vector<vector<int>>& queries) {\n        int even = 0;\n        for (int x : nums) if (x % 2 == 0) even += x;\n        vector<int> out;\n        for (auto& q : queries) {\n            int val = q[0], i = q[1];\n            if (nums[i] % 2 == 0) even -= nums[i];         // remove the old value\n            nums[i] += val;\n            if (nums[i] % 2 == 0) even += nums[i];         // add the new one\n            out.push_back(even);\n        }\n        return out;\n    }\n};",
 "sum-of-nodes-with-even-valued-grandparent": "class Solution {\n    int dfs(TreeNode* node, int parent, int grand) {\n        if (!node) return 0;\n        int here = grand % 2 == 0 ? node->val : 0;\n        return here + dfs(node->left, node->val, parent) + dfs(node->right, node->val, parent);\n    }\n\npublic:\n    int sumEvenGrandparent(TreeNode* root) {\n        return dfs(root, 1, 1);   // odd placeholders for the missing ancestors\n    }\n};",
 "sum-of-prefix-scores-of-strings": "class Solution {\npublic:\n    vector<int> sumPrefixScores(vector<string>& words) {\n        // trie as arrays: next[node][letter], and how many words pass through each node\n        vector<array<int, 26>> next(1);\n        vector<int> pass(1, 0);\n        for (auto& w : words) {\n            int node = 0;\n            for (char ch : w) {\n                int c = ch - 'a';\n                if (!next[node][c]) {\n                    next[node][c] = next.size();\n                    next.push_back({});\n                    pass.push_back(0);\n                }\n                node = next[node][c];\n                pass[node]++;\n            }\n        }\n        vector<int> out;\n        for (auto& w : words) {\n            int node = 0, s = 0;\n            for (char ch : w) {\n                node = next[node][ch - 'a'];\n                s += pass[node];\n            }\n            out.push_back(s);\n        }\n        return out;\n    }\n};",
 "sum-of-subarray-minimums": "class Solution {\npublic:\n    int sumSubarrayMins(vector<int>& arr) {\n        const long long MOD = 1e9 + 7;\n        int n = arr.size();\n        vector<int> st;                                   // indexes with rising values\n        long long total = 0;\n        for (int i = 0; i <= n; i++) {\n            int x = i < n ? arr[i] : 0;                   // a final 0 flushes the stack\n            while (!st.empty() && arr[st.back()] >= x) {\n                int j = st.back(); st.pop_back();\n                int left = st.empty() ? -1 : st.back();\n                // arr[j] is the minimum of (j - left) * (i - j) subarrays\n                total = (total + (long long)arr[j] * (j - left) % MOD * (i - j)) % MOD;\n            }\n            st.push_back(i);\n        }\n        return total;\n    }\n};",
 "sum-of-total-strength-of-wizards": "class Solution {\npublic:\n    int totalStrength(vector<int>& strength) {\n        const long long MOD = 1'000'000'007;\n        int n = strength.size();\n        vector<int> left(n, -1), right(n, n), st;\n        for (int i = 0; i < n; i++) {\n            while (!st.empty() && strength[st.back()] >= strength[i]) { right[st.back()] = i; st.pop_back(); }\n            left[i] = st.empty() ? -1 : st.back();\n            st.push_back(i);\n        }\n        vector<long long> P{0}, PP{0};                     // prefix sums and prefix of prefix sums, mod MOD\n        for (int x : strength) P.push_back((P.back() + x) % MOD);\n        for (long long p : P) PP.push_back((PP.back() + p) % MOD);\n        long long ans = 0;\n        for (int i = 0; i < n; i++) {\n            long long L = left[i], R = right[i];\n            long long total = ((i - L) * ((PP[R + 1] - PP[i + 1] + MOD) % MOD) % MOD\n                             - (R - i) * ((PP[i + 1] - PP[L + 1] + MOD) % MOD) % MOD + MOD) % MOD;\n            ans = (ans + strength[i] * total) % MOD;\n        }\n        return ans;\n    }\n};",
 "sum-of-two-integers": "class Solution {\npublic:\n    int getSum(int a, int b) {\n        // unsigned so the carry shift never overflows; it wraps like 32-bit hardware\n        unsigned x = a, y = b;\n        while (y) {\n            unsigned carry = (x & y) << 1;\n            x ^= y;                                          // sum without carries\n            y = carry;\n        }\n        return (int)x;\n    }\n};",
 "summary-ranges": "class Solution {\npublic:\n    vector<string> summaryRanges(vector<int>& nums) {\n        vector<string> out;\n        size_t i = 0;\n        while (i < nums.size()) {\n            size_t j = i;\n            while (j + 1 < nums.size() && (long long)nums[j + 1] == (long long)nums[j] + 1) j++;   // extend the run\n            out.push_back(i == j ? to_string(nums[i]) : to_string(nums[i]) + \"->\" + to_string(nums[j]));\n            i = j + 1;\n        }\n        return out;\n    }\n};",
 "super-egg-drop": "class Solution {\npublic:\n    int superEggDrop(int k, int n) {\n        vector<int> dp(k + 1, 0);                        // dp[e]: floors we can settle with e eggs in m moves\n        int m = 0;\n        while (dp[k] < n) {\n            m++;\n            for (int e = k; e > 0; e--) dp[e] = dp[e - 1] + dp[e] + 1;   // breaks: below; survives: above\n        }\n        return m;\n    }\n};",
 "super-pow": "class Solution {\n    int power(int b, int e) {                                // b^e mod 1337, b already below 1337\n        int r = 1;\n        for (int i = 0; i < e; i++) r = r * b % 1337;\n        return r;\n    }\npublic:\n    int superPow(int a, vector<int>& b) {\n        int res = 1;\n        a %= 1337;\n        for (int d : b) res = power(res, 10) * power(a, d) % 1337;   // a^(10x+d) = (a^x)^10 * a^d\n        return res;\n    }\n};",
 "surrounded-regions": "class Solution {\n    void keep(vector<vector<char>>& board, int r, int c) {   // mark an O connected to the border\n        if (r < 0 || r >= (int)board.size() || c < 0 || c >= (int)board[0].size() || board[r][c] != 'O') return;\n        board[r][c] = '#';\n        keep(board, r + 1, c); keep(board, r - 1, c); keep(board, r, c + 1); keep(board, r, c - 1);\n    }\n\npublic:\n    void solve(vector<vector<char>>& board) {\n        int R = board.size(), C = board[0].size();\n        for (int r = 0; r < R; r++) { keep(board, r, 0); keep(board, r, C - 1); }\n        for (int c = 0; c < C; c++) { keep(board, 0, c); keep(board, R - 1, c); }\n        for (auto& row : board)\n            for (char& x : row) x = x == '#' ? 'O' : 'X';  // marked ones stay, every other O is captured\n    }\n};",
 "swap-nodes-in-pairs": "class Solution {\npublic:\n    ListNode* swapPairs(ListNode* head) {\n        ListNode dummy(0, head);\n        ListNode* prev = &dummy;\n        while (prev->next && prev->next->next) {\n            ListNode *a = prev->next, *b = a->next;\n            prev->next = b;                                // prev -> b -> a -> rest\n            a->next = b->next;\n            b->next = a;\n            prev = a;\n        }\n        return dummy.next;\n    }\n};",
 "swim-in-rising-water": "class Solution {\npublic:\n    int swimInWater(vector<vector<int>>& grid) {\n        int n = grid.size();\n        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> heap;\n        vector<vector<bool>> seen(n, vector<bool>(n, false));\n        heap.push({grid[0][0], 0, 0});\n        seen[0][0] = true;\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        while (!heap.empty()) {\n            auto [t, r, c] = heap.top(); heap.pop();     // lowest water level that reaches a new cell\n            if (r == n - 1 && c == n - 1) return t;\n            for (int d = 0; d < 4; d++) {\n                int nr = r + dr[d], nc = c + dc[d];\n                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !seen[nr][nc]) {\n                    seen[nr][nc] = true;\n                    heap.push({max(t, grid[nr][nc]), nr, nc});\n                }\n            }\n        }\n        return -1;\n    }\n};",
 "symmetric-tree": "class Solution {\n    bool mirror(TreeNode* a, TreeNode* b) {\n        if (!a || !b) return a == b;\n        return a->val == b->val && mirror(a->left, b->right) && mirror(a->right, b->left);\n    }\npublic:\n    bool isSymmetric(TreeNode* root) {\n        return mirror(root->left, root->right);\n    }\n};",
 "tag-validator": "class Solution {\npublic:\n    bool isValid(string code) {\n        vector<string> st;                                 // open tag names\n        size_t i = 0, n = code.size();\n        while (i < n) {\n            if (i > 0 && st.empty()) return false;         // everything must sit inside one closed tag\n            if (code.compare(i, 9, \"<![CDATA[\") == 0) {\n                size_t j = code.find(\"]]>\", i + 9);\n                if (st.empty() || j == string::npos) return false;\n                i = j + 3;                                 // skip the CDATA body untouched\n            } else if (code.compare(i, 2, \"</\") == 0) {\n                size_t j = code.find('>', i + 2);\n                if (j == string::npos || st.empty() || st.back() != code.substr(i + 2, j - i - 2)) return false;\n                st.pop_back();\n                i = j + 1;\n            } else if (code[i] == '<') {\n                size_t j = code.find('>', i + 1);\n                if (j == string::npos) return false;\n                string name = code.substr(i + 1, j - i - 1);\n                bool upper = all_of(name.begin(), name.end(), [](char c) { return c >= 'A' && c <= 'Z'; });\n                if (name.size() < 1 || name.size() > 9 || !upper) return false;\n                st.push_back(name);\n                i = j + 1;\n            } else {\n                i++;\n            }\n        }\n        return st.empty();\n    }\n};",
 "target-sum": "class Solution {\npublic:\n    int findTargetSumWays(vector<int>& nums, int target) {\n        int total = accumulate(nums.begin(), nums.end(), 0);\n        if (abs(target) > total || (total + target) % 2) return 0;\n        int P = (total + target) / 2;                        // sum of the numbers given a plus sign\n        vector<int> dp(P + 1, 0);\n        dp[0] = 1;\n        for (int x : nums)\n            for (int s = P; s >= x; s--) dp[s] += dp[s - x];  // count subsets summing to P\n        return dp[P];\n    }\n};",
 "task-scheduler": "class Solution {\npublic:\n    int leastInterval(vector<char>& tasks, int n) {\n        int cnt[26] = {};\n        for (char t : tasks) cnt[t - 'A']++;\n        int top = *max_element(cnt, cnt + 26);\n        int ties = count(cnt, cnt + 26, top);            // tasks that share the top count fill the last row\n        return max((int)tasks.size(), (top - 1) * (n + 1) + ties);\n    }\n};",
 "text-justification": "class Solution {\npublic:\n    vector<string> fullJustify(vector<string>& words, int maxWidth) {\n        vector<string> out, line;\n        int width = 0;                                     // letters on the line, without spaces\n        for (const string& w : words) {\n            if (width + (int)w.size() + (int)line.size() > maxWidth) {\n                int gaps = max((int)line.size() - 1, 1);\n                for (int k = 0; k < maxWidth - width; k++) line[k % gaps] += ' ';   // spread spaces left first\n                string row;\n                for (const string& x : line) row += x;\n                out.push_back(row);\n                line.clear();\n                width = 0;\n            }\n            line.push_back(w);\n            width += w.size();\n        }\n        string last;                                       // last line: single spaces, padded on the right\n        for (size_t i = 0; i < line.size(); i++) last += (i ? \" \" : \"\") + line[i];\n        last.resize(maxWidth, ' ');\n        out.push_back(last);\n        return out;\n    }\n};",
 "the-k-th-lexicographical-string-of-all-happy-strings-of-length-n": "class Solution {\npublic:\n    string getHappyString(int n, int k) {\n        if (k > 3 * (1 << (n - 1))) return \"\";\n        k--;\n        string out;\n        for (int i = 0; i < n; i++) {\n            int block = 1 << (n - 1 - i);       // strings that share each choice here\n            string opts;\n            for (char c : string(\"abc\"))\n                if (out.empty() || c != out.back()) opts += c;\n            out += opts[k / block];\n            k %= block;\n        }\n        return out;\n    }\n};",
 "the-kth-factor-of-n": "class Solution {\npublic:\n    int kthFactor(int n, int k) {\n        vector<int> small, large;\n        for (int i = 1; i * i <= n; i++)\n            if (n % i == 0) {\n                small.push_back(i);\n                if (i != n / i) large.push_back(n / i);    // its partner above sqrt(n)\n            }\n        small.insert(small.end(), large.rbegin(), large.rend());\n        return k <= (int)small.size() ? small[k - 1] : -1;\n    }\n};",
 "the-number-of-weak-characters-in-the-game": "class Solution {\npublic:\n    int numberOfWeakCharacters(vector<vector<int>>& properties) {\n        // attack descending, defense ascending within one attack\n        sort(properties.begin(), properties.end(), [](auto& a, auto& b) {\n            return a[0] != b[0] ? a[0] > b[0] : a[1] < b[1];\n        });\n        int best = 0, weak = 0;\n        for (auto& p : properties) {\n            if (p[1] < best) weak++;\n            best = max(best, p[1]);\n        }\n        return weak;\n    }\n};",
 "the-skyline-problem": "class Solution {\npublic:\n    vector<vector<int>> getSkyline(vector<vector<int>>& buildings) {\n        // (x, -height, right) for a start, (x, 0, 0) for an end: starts first, taller first\n        vector<tuple<int, int, int>> events;\n        for (auto& b : buildings) {\n            events.push_back({b[0], -b[2], b[1]});\n            events.push_back({b[1], 0, 0});\n        }\n        sort(events.begin(), events.end());\n        vector<vector<int>> res{{0, 0}};\n        priority_queue<pair<int, int>> heap;   // (height, right edge), tallest on top\n        heap.push({0, INT_MAX});               // the ground never ends\n        for (auto [x, negH, r] : events) {\n            while (heap.top().second <= x) heap.pop();   // drop buildings that ended\n            if (negH) heap.push({-negH, r});\n            if (res.back()[1] != heap.top().first) res.push_back({x, heap.top().first});   // the height changed\n        }\n        res.erase(res.begin());\n        return res;\n    }\n};",
 "three-equal-parts": "class Solution {\npublic:\n    vector<int> threeEqualParts(vector<int>& arr) {\n        int n = arr.size();\n        vector<int> ones;\n        for (int i = 0; i < n; i++)\n            if (arr[i]) ones.push_back(i);\n        if (ones.empty()) return {0, n - 1};\n        if (ones.size() % 3) return {-1, -1};\n        int k = ones.size() / 3;\n        int a = ones[0], b = ones[k], c = ones[2 * k];   // first 1 of each part\n        int tail = n - c;                                // the last part fixes the length\n        if (equal(arr.begin() + a, arr.begin() + a + tail, arr.begin() + c) &&\n            equal(arr.begin() + b, arr.begin() + b + tail, arr.begin() + c))\n            return {a + tail - 1, b + tail};\n        return {-1, -1};\n    }\n};",
 "top-k-frequent-elements": "class Solution {\npublic:\n    vector<int> topKFrequent(vector<int>& nums, int k) {\n        unordered_map<int, int> cnt;\n        for (int x : nums) cnt[x]++;\n        vector<int> keys;\n        for (auto& [v, c] : cnt) keys.push_back(v);\n        // only the k most frequent need to be in order\n        partial_sort(keys.begin(), keys.begin() + k, keys.end(), [&](int a, int b) { return cnt[a] > cnt[b]; });\n        return vector<int>(keys.begin(), keys.begin() + k);\n    }\n};",
 "top-k-frequent-words": "class Solution {\npublic:\n    vector<string> topKFrequent(vector<string>& words, int k) {\n        unordered_map<string, int> cnt;\n        for (auto& w : words) cnt[w]++;\n        vector<string> keys;\n        for (auto& [w, c] : cnt) keys.push_back(w);\n        // most frequent first, ties in alphabetical order\n        partial_sort(keys.begin(), keys.begin() + k, keys.end(), [&](auto& a, auto& b) {\n            return cnt[a] != cnt[b] ? cnt[a] > cnt[b] : a < b;\n        });\n        keys.resize(k);\n        return keys;\n    }\n};",
 "total-hamming-distance": "class Solution {\npublic:\n    int totalHammingDistance(vector<int>& nums) {\n        int n = nums.size(), total = 0;\n        for (int b = 0; b < 32; b++) {\n            int ones = 0;\n            for (int x : nums) ones += x >> b & 1;\n            total += ones * (n - ones);   // each (one, zero) pair differs at this bit\n        }\n        return total;\n    }\n};",
 "trapping-rain-water": "class Solution {\npublic:\n    int trap(vector<int>& height) {\n        int l = 0, r = (int)height.size() - 1, lmax = 0, rmax = 0, water = 0;\n        while (l < r) {\n            if (height[l] < height[r]) {                     // the left wall is the limit\n                lmax = max(lmax, height[l]);\n                water += lmax - height[l++];\n            } else {\n                rmax = max(rmax, height[r]);\n                water += rmax - height[r--];\n            }\n        }\n        return water;\n    }\n};",
 "trapping-rain-water-ii": "class Solution {\npublic:\n    int trapRainWater(vector<vector<int>>& heightMap) {\n        int m = heightMap.size(), n = heightMap[0].size();\n        vector<vector<bool>> seen(m, vector<bool>(n, false));\n        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> pq;   // (wall, r, c)\n        for (int r = 0; r < m; r++)\n            for (int c = 0; c < n; c++)\n                if (r == 0 || r == m - 1 || c == 0 || c == n - 1) { pq.push({heightMap[r][c], r, c}); seen[r][c] = true; }\n        int water = 0;\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        while (!pq.empty()) {\n            auto [h, r, c] = pq.top(); pq.pop();\n            for (int d = 0; d < 4; d++) {\n                int nr = r + dr[d], nc = c + dc[d];\n                if (nr < 0 || nr >= m || nc < 0 || nc >= n || seen[nr][nc]) continue;\n                seen[nr][nc] = true;\n                water += max(0, h - heightMap[nr][nc]);    // the lowest wall decides the fill\n                pq.push({max(h, heightMap[nr][nc]), nr, nc});\n            }\n        }\n        return water;\n    }\n};",
 "triangle": "class Solution {\npublic:\n    int minimumTotal(vector<vector<int>>& triangle) {\n        vector<int> dp = triangle.back();                // best path from each cell of the bottom row\n        for (int i = (int)triangle.size() - 2; i >= 0; i--)\n            for (int j = 0; j < (int)triangle[i].size(); j++) dp[j] = triangle[i][j] + min(dp[j], dp[j + 1]);\n        return dp[0];\n    }\n};",
 "trim-a-binary-search-tree": "class Solution {\npublic:\n    TreeNode* trimBST(TreeNode* root, int low, int high) {\n        if (!root) return nullptr;\n        if (root->val < low) return trimBST(root->right, low, high);    // root and its left are too small\n        if (root->val > high) return trimBST(root->left, low, high);    // root and its right are too big\n        root->left = trimBST(root->left, low, high);\n        root->right = trimBST(root->right, low, high);\n        return root;\n    }\n};",
 "two-city-scheduling": "class Solution {\npublic:\n    int twoCitySchedCost(vector<vector<int>>& costs) {\n        // those who save most by going to A come first\n        sort(costs.begin(), costs.end(), [](auto& x, auto& y) { return x[0] - x[1] < y[0] - y[1]; });\n        int n = costs.size() / 2, total = 0;\n        for (int i = 0; i < n; i++) total += costs[i][0];\n        for (int i = n; i < 2 * n; i++) total += costs[i][1];\n        return total;\n    }\n};",
 "two-sum": "class Solution {\npublic:\n    vector<int> twoSum(vector<int>& nums, int target) {\n        unordered_map<int, int> seen;                        // value -> index\n        for (int i = 0; i < (int)nums.size(); i++) {\n            auto it = seen.find(target - nums[i]);\n            if (it != seen.end()) return {it->second, i};\n            seen[nums[i]] = i;\n        }\n        return {};\n    }\n};",
 "two-sum-iv-input-is-a-bst": "class Solution {\n    unordered_set<int> seen;\npublic:\n    bool findTarget(TreeNode* root, int k) {\n        if (!root) return false;\n        if (seen.count(k - root->val)) return true;          // its partner was visited already\n        seen.insert(root->val);\n        return findTarget(root->left, k) || findTarget(root->right, k);\n    }\n};",
 "ugly-number": "class Solution {\npublic:\n    bool isUgly(int n) {\n        if (n <= 0) return false;\n        for (int p : {2, 3, 5})\n            while (n % p == 0) n /= p;                       // strip every allowed factor\n        return n == 1;\n    }\n};",
 "ugly-number-ii": "class Solution {\npublic:\n    int nthUglyNumber(int n) {\n        vector<long long> ugly{1};                           // long long: candidates can pass int range\n        size_t i2 = 0, i3 = 0, i5 = 0;\n        while ((int)ugly.size() < n) {\n            long long a = ugly[i2] * 2, b = ugly[i3] * 3, c = ugly[i5] * 5;\n            long long nxt = min({a, b, c});\n            ugly.push_back(nxt);\n            if (nxt == a) i2++;                              // advance every pointer that made it,\n            if (nxt == b) i3++;                              // so duplicates like 6 appear once\n            if (nxt == c) i5++;\n        }\n        return (int)ugly.back();\n    }\n};",
 "unique-binary-search-trees": "class Solution {\npublic:\n    int numTrees(int n) {\n        vector<long long> G(n + 1, 0);                   // G[m]: trees with m nodes\n        G[0] = 1;\n        if (n >= 1) G[1] = 1;\n        for (int m = 2; m <= n; m++)\n            for (int root = 1; root <= m; root++) G[m] += G[root - 1] * G[m - root];   // left times right\n        return G[n];\n    }\n};",
 "unique-binary-search-trees-ii": "class Solution {\npublic:\n    vector<TreeNode*> generateTrees(int n) {\n        map<pair<int, int>, vector<TreeNode*>> memo;       // subtrees are shared, as with lru_cache\n        function<vector<TreeNode*>(int, int)> build = [&](int lo, int hi) -> vector<TreeNode*> {\n            if (lo > hi) return {nullptr};\n            auto it = memo.find({lo, hi});\n            if (it != memo.end()) return it->second;\n            vector<TreeNode*> out;\n            for (int root = lo; root <= hi; root++)\n                for (TreeNode* left : build(lo, root - 1))\n                    for (TreeNode* right : build(root + 1, hi))\n                        out.push_back(new TreeNode(root, left, right));\n            return memo[{lo, hi}] = out;\n        };\n        return build(1, n);\n    }\n};",
 "unique-paths": "class Solution {\npublic:\n    int uniquePaths(int m, int n) {\n        vector<int> row(n, 1);                               // paths into each cell of the current row\n        for (int r = 0; r < m - 1; r++)\n            for (int c = 1; c < n; c++) row[c] += row[c - 1];   // from above plus from the left\n        return row.back();\n    }\n};",
 "unique-paths-ii": "class Solution {\npublic:\n    int uniquePathsWithObstacles(vector<vector<int>>& obstacleGrid) {\n        int C = obstacleGrid[0].size();\n        vector<long long> dp(C, 0);                      // paths to each cell of the current row\n        dp[0] = 1;\n        for (auto& row : obstacleGrid)\n            for (int j = 0; j < C; j++) {\n                if (row[j]) dp[j] = 0;                   // blocked\n                else if (j) dp[j] += dp[j - 1];\n            }\n        return dp[C - 1];\n    }\n};",
 "unique-paths-iii": "class Solution {\n    int R, C;\n\n    int dfs(vector<vector<int>>& grid, int r, int c, int left) {\n        if (r < 0 || r >= R || c < 0 || c >= C || grid[r][c] < 0) return 0;\n        if (grid[r][c] == 2) return left == 0;   // reached the end having walked every square\n        grid[r][c] = -1;   // mark visited\n        int total = dfs(grid, r + 1, c, left - 1) + dfs(grid, r - 1, c, left - 1) + dfs(grid, r, c + 1, left - 1) + dfs(grid, r, c - 1, left - 1);\n        grid[r][c] = 0;    // undo\n        return total;\n    }\n\npublic:\n    int uniquePathsIII(vector<vector<int>>& grid) {\n        R = grid.size();\n        C = grid[0].size();\n        int need = 1, sr = 0, sc = 0;   // empty squares plus the end square\n        for (int r = 0; r < R; r++)\n            for (int c = 0; c < C; c++) {\n                if (grid[r][c] == 0) need++;\n                if (grid[r][c] == 1) { sr = r; sc = c; }\n            }\n        return dfs(grid, sr, sc, need);\n    }\n};",
 "valid-anagram": "class Solution {\npublic:\n    bool isAnagram(string s, string t) {\n        if (s.size() != t.size()) return false;\n        unordered_map<char, int> count;\n        for (char c : s) count[c]++;\n        for (char c : t) if (--count[c] < 0) return false;   // t uses a letter s does not have\n        return true;\n    }\n};",
 "valid-arrangement-of-pairs": "class Solution {\npublic:\n    vector<vector<int>> validArrangement(vector<vector<int>>& pairs) {\n        unordered_map<int, vector<int>> g;\n        unordered_map<int, int> bal;                         // out-degree - in-degree\n        for (auto& p : pairs) { g[p[0]].push_back(p[1]); bal[p[0]]++; bal[p[1]]--; }\n        int start = pairs[0][0];\n        for (auto& [x, b] : bal) if (b == 1) { start = x; break; }\n        vector<int> path, st = {start};\n        while (!st.empty()) {\n            int u = st.back();\n            if (!g[u].empty()) { st.push_back(g[u].back()); g[u].pop_back(); }\n            else { path.push_back(u); st.pop_back(); }\n        }\n        reverse(path.begin(), path.end());\n        vector<vector<int>> out;\n        for (size_t i = 0; i + 1 < path.size(); i++) out.push_back({path[i], path[i + 1]});\n        return out;\n    }\n};",
 "valid-palindrome": "class Solution {\npublic:\n    bool isPalindrome(string s) {\n        int l = 0, r = (int)s.size() - 1;\n        while (l < r) {\n            if (!isalnum((unsigned char)s[l])) l++;\n            else if (!isalnum((unsigned char)s[r])) r--;\n            else if (tolower((unsigned char)s[l]) != tolower((unsigned char)s[r])) return false;\n            else { l++; r--; }\n        }\n        return true;\n    }\n};",
 "valid-palindrome-ii": "class Solution {\npublic:\n    bool validPalindrome(string s) {\n        auto isPal = [&](int l, int r) {\n            while (l < r) if (s[l++] != s[r--]) return false;\n            return true;\n        };\n        int l = 0, r = (int)s.size() - 1;\n        while (l < r) {\n            if (s[l] != s[r]) return isPal(l + 1, r) || isPal(l, r - 1);   // one deletion: skip either side\n            l++; r--;\n        }\n        return true;\n    }\n};",
 "valid-parentheses": "class Solution {\npublic:\n    bool isValid(string s) {\n        unordered_map<char, char> opener{{')', '('}, {']', '['}, {'}', '{'}};\n        vector<char> st;\n        for (char ch : s) {\n            if (opener.count(ch)) {\n                if (st.empty() || st.back() != opener[ch]) return false;   // must close the latest opener\n                st.pop_back();\n            } else {\n                st.push_back(ch);\n            }\n        }\n        return st.empty();\n    }\n};",
 "valid-triangle-number": "class Solution {\npublic:\n    int triangleNumber(vector<int>& a) {\n        sort(a.begin(), a.end());\n        int ans = 0;\n        for (int k = a.size() - 1; k > 1; k--) {   // a[k] is the longest side\n            int L = 0, R = k - 1;\n            while (L < R) {\n                if (a[L] + a[R] > a[k]) {\n                    ans += R - L;   // every L..R-1 also works with R\n                    R--;\n                } else L++;\n            }\n        }\n        return ans;\n    }\n};",
 "validate-binary-search-tree": "class Solution {\n    bool ok(TreeNode* node, long long lo, long long hi) {    // long long bounds fit every int value\n        if (!node) return true;\n        if (!(lo < node->val && node->val < hi)) return false;\n        return ok(node->left, lo, node->val) && ok(node->right, node->val, hi);\n    }\npublic:\n    bool isValidBST(TreeNode* root) {\n        return ok(root, LLONG_MIN, LLONG_MAX);\n    }\n};",
 "vertical-order-traversal-of-a-binary-tree": "class Solution {\n    vector<tuple<int, int, int>> cells;                      // (column, row, value)\n    void dfs(TreeNode* node, int r, int c) {\n        if (!node) return;\n        cells.push_back({c, r, node->val});\n        dfs(node->left, r + 1, c - 1);\n        dfs(node->right, r + 1, c + 1);\n    }\npublic:\n    vector<vector<int>> verticalTraversal(TreeNode* root) {\n        dfs(root, 0, 0);\n        sort(cells.begin(), cells.end());                    // by column, then row, then value\n        vector<vector<int>> out;\n        int prev = INT_MIN;\n        for (auto [c, r, v] : cells) {\n            if (out.empty() || c != prev) { out.push_back({}); prev = c; }\n            out.back().push_back(v);\n        }\n        return out;\n    }\n};",
 "video-stitching": "class Solution {\npublic:\n    int videoStitching(vector<vector<int>>& clips, int time) {\n        vector<int> furthest(time, 0);                     // furthest end of a clip starting at each second\n        for (auto& c : clips)\n            if (c[0] < time) furthest[c[0]] = max(furthest[c[0]], c[1]);\n        int count = 0, end = 0, far = 0;\n        for (int t = 0; t < time; t++) {\n            far = max(far, furthest[t]);\n            if (t == end) {                                // current clip runs out: take the best next one\n                if (far <= t) return -1;\n                count++;\n                end = far;\n            }\n        }\n        return count;\n    }\n};",
 "vowels-of-all-substrings": "class Solution {\npublic:\n    long long countVowels(string word) {\n        long long n = word.size(), total = 0;\n        for (long long i = 0; i < n; i++)\n            if (string(\"aeiou\").find(word[i]) != string::npos)\n                total += (i + 1) * (n - i);                // substrings that contain index i\n        return total;\n    }\n};",
 "watering-plants": "class Solution {\npublic:\n    int wateringPlants(vector<int>& plants, int capacity) {\n        int steps = 0, water = capacity;\n        for (int i = 0; i < (int)plants.size(); i++) {\n            if (water < plants[i]) {   // walk back to the river and return\n                steps += 2 * i;\n                water = capacity;\n            }\n            water -= plants[i];\n            steps++;\n        }\n        return steps;\n    }\n};",
 "where-will-the-ball-fall": "class Solution {\npublic:\n    vector<int> findBall(vector<vector<int>>& grid) {\n        int R = grid.size(), C = grid[0].size();\n        vector<int> out;\n        for (int c = 0; c < C; c++) {\n            int col = c;\n            for (int r = 0; r < R; r++) {\n                int d = grid[r][col], nc = col + d;    // the board pushes the ball one column\n                if (nc < 0 || nc >= C || grid[r][nc] != d) { col = -1; break; }   // wall or V shape: stuck\n                col = nc;\n            }\n            out.push_back(col);\n        }\n        return out;\n    }\n};",
 "wiggle-subsequence": "class Solution {\npublic:\n    int wiggleMaxLength(vector<int>& nums) {\n        int up = 1, down = 1;                            // longest wiggle ending with a rise / a fall\n        for (size_t i = 1; i < nums.size(); i++) {\n            if (nums[i] > nums[i - 1]) up = down + 1;\n            else if (nums[i] < nums[i - 1]) down = up + 1;\n        }\n        return max(up, down);\n    }\n};",
 "wildcard-matching": "class Solution {\npublic:\n    bool isMatch(string s, string p) {\n        int m = s.size(), n = p.size();\n        // dp[i][j]: the first i letters of s match the first j of p\n        vector<vector<bool>> dp(m + 1, vector<bool>(n + 1, false));\n        dp[0][0] = true;\n        for (int j = 1; j <= n; j++) dp[0][j] = dp[0][j - 1] && p[j - 1] == '*';\n        for (int i = 1; i <= m; i++)\n            for (int j = 1; j <= n; j++) {\n                if (p[j - 1] == '*') dp[i][j] = dp[i][j - 1] || dp[i - 1][j];   // empty, or eat one more\n                else dp[i][j] = dp[i - 1][j - 1] && (p[j - 1] == s[i - 1] || p[j - 1] == '?');\n            }\n        return dp[m][n];\n    }\n};",
 "word-break": "class Solution {\npublic:\n    bool wordBreak(string s, vector<string>& wordDict) {\n        unordered_set<string> words(wordDict.begin(), wordDict.end());\n        int n = s.size();\n        vector<bool> dp(n + 1, false);                   // dp[i]: s[:i] splits into words\n        dp[0] = true;\n        for (int i = 1; i <= n; i++)\n            for (int j = 0; j < i && !dp[i]; j++)\n                if (dp[j] && words.count(s.substr(j, i - j))) dp[i] = true;\n        return dp[n];\n    }\n};",
 "word-ladder": "class Solution {\npublic:\n    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {\n        unordered_set<string> words(wordList.begin(), wordList.end());\n        if (!words.count(endWord)) return 0;\n        queue<pair<string, int>> q;\n        unordered_set<string> seen = {beginWord};\n        q.push({beginWord, 1});\n        while (!q.empty()) {\n            auto [w, d] = q.front(); q.pop();\n            if (w == endWord) return d;\n            for (size_t i = 0; i < w.size(); i++)\n                for (char ch = 'a'; ch <= 'z'; ch++) {   // every word one letter away\n                    string n = w;\n                    n[i] = ch;\n                    if (words.count(n) && !seen.count(n)) { seen.insert(n); q.push({n, d + 1}); }\n                }\n        }\n        return 0;\n    }\n};",
 "word-ladder-ii": "class Solution {\n    unordered_map<string, vector<string>> parents;\n    vector<vector<string>> out;\n    void build(const string& w, const string& begin, vector<string>& path) {\n        if (w == begin) { out.emplace_back(path.rbegin(), path.rend()); return; }\n        for (auto& p : parents[w]) {\n            path.push_back(p);\n            build(p, begin, path);\n            path.pop_back();\n        }\n    }\npublic:\n    vector<vector<string>> findLadders(string beginWord, string endWord, vector<string>& wordList) {\n        unordered_set<string> words(wordList.begin(), wordList.end());\n        if (!words.count(endWord)) return {};\n        unordered_set<string> level{beginWord};\n        bool found = false;\n        words.erase(beginWord);\n        while (!level.empty() && !found) {\n            unordered_map<string, vector<string>> nxt;\n            for (auto& w : level)\n                for (size_t i = 0; i < w.size(); i++)\n                    for (char ch = 'a'; ch <= 'z'; ch++) {\n                        string t = w;\n                        t[i] = ch;\n                        if (words.count(t)) nxt[t].push_back(w);\n                    }\n            level.clear();\n            for (auto& [t, ps] : nxt) {\n                words.erase(t);                            // remove only after the whole level\n                auto& dst = parents[t];\n                dst.insert(dst.end(), ps.begin(), ps.end());\n                level.insert(t);\n            }\n            found = nxt.count(endWord);\n        }\n        if (found) { vector<string> path{endWord}; build(endWord, beginWord, path); }\n        return out;\n    }\n};",
 "word-search": "class Solution {\n    bool dfs(vector<vector<char>>& board, const string& word, int r, int c, int i) {\n        if (i == (int)word.size()) return true;\n        if (r < 0 || r >= (int)board.size() || c < 0 || c >= (int)board[0].size() || board[r][c] != word[i]) return false;\n        board[r][c] = '#';                               // mark the cell as used on this path\n        bool found = dfs(board, word, r + 1, c, i + 1) || dfs(board, word, r - 1, c, i + 1) ||\n                     dfs(board, word, r, c + 1, i + 1) || dfs(board, word, r, c - 1, i + 1);\n        board[r][c] = word[i];                           // undo\n        return found;\n    }\n\npublic:\n    bool exist(vector<vector<char>>& board, string word) {\n        for (int r = 0; r < (int)board.size(); r++)\n            for (int c = 0; c < (int)board[0].size(); c++)\n                if (dfs(board, word, r, c, 0)) return true;\n        return false;\n    }\n};",
 "word-search-ii": "class Solution {\n    struct Trie {\n        unordered_map<char, unique_ptr<Trie>> kids;\n        string word;                                       // set at the end of a word, cleared once found\n    };\n    vector<string> out;\n\n    void dfs(vector<vector<char>>& board, int r, int c, Trie* parent) {\n        char ch = board[r][c];\n        Trie* node = parent->kids[ch].get();\n        if (!node->word.empty()) { out.push_back(node->word); node->word.clear(); }   // report each word once\n        board[r][c] = '#';                                 // mark the cell used on this path\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        for (int d = 0; d < 4; d++) {\n            int nr = r + dr[d], nc = c + dc[d];\n            if (nr >= 0 && nr < (int)board.size() && nc >= 0 && nc < (int)board[0].size() && node->kids.count(board[nr][nc]))\n                dfs(board, nr, nc, node);\n        }\n        board[r][c] = ch;\n        if (node->kids.empty() && node->word.empty()) parent->kids.erase(ch);   // prune a finished branch\n    }\npublic:\n    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {\n        Trie root;\n        for (const string& w : words) {\n            Trie* node = &root;\n            for (char ch : w) {\n                auto& next = node->kids[ch];\n                if (!next) next = make_unique<Trie>();\n                node = next.get();\n            }\n            node->word = w;\n        }\n        out.clear();\n        for (int r = 0; r < (int)board.size(); r++)\n            for (int c = 0; c < (int)board[0].size(); c++)\n                if (root.kids.count(board[r][c])) dfs(board, r, c, &root);\n        return out;\n    }\n};",
 "word-subsets": "class Solution {\npublic:\n    vector<string> wordSubsets(vector<string>& words1, vector<string>& words2) {\n        array<int, 26> need{};   // most of each letter any word in words2 needs\n        for (auto& b : words2) {\n            array<int, 26> c{};\n            for (char ch : b) c[ch - 'a']++;\n            for (int i = 0; i < 26; i++) need[i] = max(need[i], c[i]);\n        }\n        vector<string> out;\n        for (auto& a : words1) {\n            array<int, 26> c{};\n            for (char ch : a) c[ch - 'a']++;\n            bool ok = true;\n            for (int i = 0; i < 26; i++) ok &= c[i] >= need[i];\n            if (ok) out.push_back(a);\n        }\n        return out;\n    }\n};",
 "x-of-a-kind-in-a-deck-of-cards": "class Solution {\npublic:\n    bool hasGroupsSizeX(vector<int>& deck) {\n        unordered_map<int, int> cnt;\n        for (int x : deck) cnt[x]++;\n        int g = 0;\n        for (auto& [card, c] : cnt) g = gcd(g, c);           // group size must divide every count\n        return g >= 2;\n    }\n};",
 "xor-operation-in-an-array": "class Solution {\npublic:\n    int xorOperation(int n, int start) {\n        int x = 0;\n        for (int i = 0; i < n; i++) x ^= start + 2 * i;\n        return x;\n    }\n};",
 "xor-queries-of-a-subarray": "class Solution {\npublic:\n    vector<int> xorQueries(vector<int>& arr, vector<vector<int>>& queries) {\n        vector<int> X{0};                                    // prefix XORs\n        for (int v : arr) X.push_back(X.back() ^ v);\n        vector<int> out;\n        for (auto& q : queries) out.push_back(X[q[1] + 1] ^ X[q[0]]);   // the shared prefix cancels\n        return out;\n    }\n};"
};
